function [success, sim_hist] = sim_run(case_name, body_case, varargin)
% function success = sim_run(case_name, body_case, varargin)
%SIM_RUN  Execute a simulation using the previously prepared sim_setup bundle.
%
% Usage (auto-pick latest setup):
%   sharpy_root = '/path/to/TestBenchPazy';              % SHARPy root
%   matlab_root = '/path/to/MatlabFlex';                 % MATLAB project root
%   success = sim_run(sharpy_root, matlab_root, 'pazy_ROM', 'wingOnly');
%
% Usage (explicit setup dir):
%   success = sim_run(sharpy_root, matlab_root, 'pazy_ROM','wingOnly', ...
%                     'setup_dir', '/.../sim_setup/pazy_ROM/wing_only/20251110');
%
% Name-Value:
%   'setup_dir'       : explicit sim_setup run directory to read from
%   'date_only_runs'  : true  -> sim_run/<date>, false -> <date_time> (default: true)
%   'overwrite'       : whether to reuse an existing run dir (default: true)
%   'structured_outer_audit_request' : hash-bound audit-only outer-wing
%                                      selection; omitted by default. Set its
%                                      coordinateNmpcHorizon field true only
%                                      for the approved coordination audit.
%                                      A source-specific selection carries its
%                                      matching exact-source gainBank request.
%   'simple_pd_rigid_path_audit_request' : default-disabled Case-A
%                                      elevator PD discriminator.
%   'nmhe_health_gate_audit_request' : default-disabled audit-only nMHE
%                                      health gate for nMPC bypass testing.
%   'nmhe_preparation_feedback_audit_request' : default-disabled audit-only
%                                      nMHE preparation/feedback RTI study.
%   'runtime_checkpoint_audit_request' : default-disabled audit-only capture
%                                      of exact post-scheduling runtime state.
%   'runtime_segment_audit_request' : default-disabled audit-only stop/resume
%                                      checkpoint for the exact integrated
%                                      approved Case-A or Case-B/C execution.
%   'coupled_rti_allocator_audit_request' : default-disabled persistent
%                                      rigid-flexible allocation study.
%   'rigid_attitude_chi_audit_request' : default-disabled discriminator
%                                      for plant-only versus plant-and-nMHE
%                                      package-relative chi ownership.
%   'wing_actuator_bypass_audit_request' : default-disabled nonphysical
%                                      identity realization discriminator for
%                                      the named formal Case-A audit only.
%   'outer_wing_fusion_bypass_audit_request' : default-disabled nonphysical
%                                      direct outer-wing request discriminator.
%                                      It retains the wing actuator and limits.
%   'symmetric_wing_authority_discriminator_audit_request' : default-disabled
%                                      Case-A nominal outer-wing authority audit.
%   'benchmark_control_profile' : source-bound production benchmark profile;
%                                      omitted by default.
%   'audit_mpc_solver_override' : default-empty audit-only solver override
%                                      for a named shared-wing audit.
%   'audit_mpc_sqp_options_override' : default-empty audit-only custom-SQP
%                                      option override for a named shared-wing audit.
%   'structured_virtual_pitch_runtime_audit_request' : default-disabled,
%                                      hash-bound Case-A integration of the
%                                      certified virtual pitch-demand law.
%   'fixed_basis_intrinsic_port_audit_request' : default-disabled exact
%                                      Case-A aerodynamic/structural port
%                                      coordinate integration audit.
%   'reciprocal_tangent_audit_request' : compatibility name for the exact
%                                      Case-A reciprocal-reaction selector.
%                                      The named formal profile supplies the
%                                      promoted request; enable=false selects
%                                      its fixed-root rollback comparator.
%   'reciprocal_controller_model_provider_audit_request' : default-inactive,
%                                      exact Case-A causal nMHE process-model
%                                      provider for the reciprocal plant.
%   'corrected_model_rigid_residual_allocation_audit_request' :
%                                      default-disabled 100 Hz algebraic
%                                      tail/thrust realization of the rigid
%                                      demand displaced by the nMPC wing target.
%   'source_coordinate_outer_feedback_request' : default-inactive exact
%                                      Case-A dynamic output-feedback selector.
%   'scheduled_equilibrium_feedforward_audit_request' : default-inactive
%                                      Case-B scheduled trim handoff audit.
%
% Notes
%   • Reads sim_bundle.mat, run_settings.mat, base/beam/aero bundles, sim_for_sharpy.h5
%   • Supports runner families: 'SimRunner' and 'PlantROM'
%   • Supports sim_case: 'openloop' and 'nmhe_nmpc'
%   • Minimal outputs now; post-processing will follow later

% ------------------- parse args -------------------
p = inputParser;
p.addParameter('setup_dir','',@(s)ischar(s)||isstring(s));
p.addParameter('date_only_runs', true, @(b)islogical(b)||isnumeric(b));
p.addParameter('overwrite',      true, @(b)islogical(b)||isnumeric(b));
p.addParameter('structured_outer_audit_request', struct(), @isstruct);
p.addParameter('simple_pd_rigid_path_audit_request', struct(), @isstruct);
p.addParameter('shared_wing_daisy_chain_audit_request', struct(), @isstruct);
p.addParameter('outer_audit_reference_provider', struct(), @isstruct);
p.addParameter('outer_reference_provider', struct(), @isstruct);
p.addParameter('nmhe_health_gate_audit_request', struct(), @isstruct);
p.addParameter('nmpc_solver_rejection_safe_endpoint_audit_request', ...
    struct(), @isstruct);
p.addParameter('nmhe_preparation_feedback_audit_request', struct(), @isstruct);
p.addParameter('runtime_checkpoint_audit_request', struct(), @isstruct);
p.addParameter('runtime_segment_audit_request', struct(), @isstruct);
p.addParameter('coupled_rti_allocator_audit_request', struct(), @isstruct);
p.addParameter('rigid_attitude_chi_audit_request', struct(), @isstruct);
p.addParameter('wing_actuator_bypass_audit_request', struct(), @isstruct);
p.addParameter('outer_wing_fusion_bypass_audit_request', struct(), @isstruct);
p.addParameter('symmetric_wing_authority_discriminator_audit_request', struct(), @isstruct);
p.addParameter('gust_rigid_response_domain_audit_request', struct(), @isstruct);
p.addParameter('realized_constrained_outer_allocation_audit_request', struct(), @isstruct);
p.addParameter('lexicographic_shared_wing_allocation_audit_request', struct(), @isstruct);
p.addParameter('full_channel_lexicographic_trajectory_allocation_audit_request', struct(), @isstruct);
p.addParameter('virtual_demand_shared_surface_realization_audit_request', struct(), @isstruct);
p.addParameter('structured_virtual_pitch_runtime_audit_request', struct(), @isstruct);
p.addParameter('fixed_basis_intrinsic_port_audit_request', struct(), @isstruct);
p.addParameter('reciprocal_tangent_audit_request', struct(), @isstruct);
p.addParameter('reciprocal_controller_model_provider_audit_request', ...
    struct(), @isstruct);
p.addParameter('corrected_model_rigid_residual_allocation_audit_request', ...
    struct(), @isstruct);
p.addParameter('source_coordinate_outer_feedback_request',struct(),@isstruct);
p.addParameter('scheduled_equilibrium_feedforward_audit_request', ...
    struct(),@isstruct);
p.addParameter('benchmark_control_profile', "", ...
    @(s)ischar(s)||isstring(s));
p.addParameter('audit_mpc_solver_override', "", ...
    @(s)ischar(s)||isstring(s));
p.addParameter('audit_mpc_sqp_options_override', struct(), @isstruct);
p.addParameter('phase18_trace_path', "", @(s)ischar(s)||isstring(s));
p.parse(varargin{:});
setup_dir      = char(p.Results.setup_dir);
date_only_runs = logical(p.Results.date_only_runs);
overwrite      = logical(p.Results.overwrite);
structuredOuterAuditRequest = p.Results.structured_outer_audit_request;
simplePdRigidPathAuditRequest = p.Results.simple_pd_rigid_path_audit_request;
sharedWingDaisyChainAuditRequest = p.Results.shared_wing_daisy_chain_audit_request;
outerAuditReferenceProvider = p.Results.outer_audit_reference_provider;
outerReferenceProvider = localProductionOuterReferenceProvider( ...
    p.Results.outer_reference_provider);
assert(isempty(fieldnames(outerAuditReferenceProvider)) || ...
    isempty(fieldnames(outerReferenceProvider)), ...
    'sim_run:OuterReferenceProviderConflict', ...
    ['Specify either the retained audit reference provider or the ', ...
    'production reference provider, never both.']);
nMheHealthGateAuditRequest = localNmpcMheHealthGateRequest( ...
    p.Results.nmhe_health_gate_audit_request);
nMpcSolverRejectionSafeEndpointRequest = ...
    localNmpcSolverRejectionSafeEndpointRequest( ...
    p.Results.nmpc_solver_rejection_safe_endpoint_audit_request);
nMhePreparationFeedbackAuditRequest = ...
    localNmpcMhePreparationFeedbackRequest( ...
    p.Results.nmhe_preparation_feedback_audit_request);
runtimeCheckpointAuditRequest = localRuntimeCheckpointAuditRequest( ...
    p.Results.runtime_checkpoint_audit_request);
runtimeSegmentAuditRequest = localRuntimeSegmentAuditRequest( ...
    p.Results.runtime_segment_audit_request);
coupledRtiAllocatorAuditRequest = localCoupledRtiAllocatorAuditRequest( ...
    p.Results.coupled_rti_allocator_audit_request);
rigidAttitudeChiAuditRequest = localRigidAttitudeChiAuditRequest( ...
    p.Results.rigid_attitude_chi_audit_request);
wingActuatorBypassAuditRequest = localWingActuatorBypassAuditRequest( ...
    p.Results.wing_actuator_bypass_audit_request);
outerWingFusionBypassAuditRequest = localOuterWingFusionBypassAuditRequest( ...
    p.Results.outer_wing_fusion_bypass_audit_request);
symmetricWingAuthorityDiscriminatorAuditRequest = ...
    localSymmetricWingAuthorityDiscriminatorAuditRequest( ...
    p.Results.symmetric_wing_authority_discriminator_audit_request);
gustRigidResponseDomainAuditRequest = ...
    localGustRigidResponseDomainAuditRequest( ...
    p.Results.gust_rigid_response_domain_audit_request);
realizedConstrainedOuterAllocationRequest = ...
    localRealizedConstrainedOuterAllocationRequest( ...
    p.Results.realized_constrained_outer_allocation_audit_request);
lexicographicSharedWingAllocationRequest = ...
    localLexicographicSharedWingAllocationRequest( ...
    p.Results.lexicographic_shared_wing_allocation_audit_request);
fullChannelLexicographicAllocationRequest = ...
    localFullChannelLexicographicTrajectoryAllocationRequest( ...
    p.Results.full_channel_lexicographic_trajectory_allocation_audit_request);
virtualDemandSharedSurfaceRealizationRequest = ...
    localVirtualDemandSharedSurfaceRealizationAuditRequest( ...
    p.Results.virtual_demand_shared_surface_realization_audit_request);
structuredVirtualPitchRuntimeRequest = ...
    localStructuredVirtualPitchRuntimeAuditRequest( ...
    p.Results.structured_virtual_pitch_runtime_audit_request);
fixedBasisIntrinsicPortRequest = localFixedBasisIntrinsicPortAuditRequest( ...
    p.Results.fixed_basis_intrinsic_port_audit_request);
reciprocalTangentAuditRequest = localReciprocalTangentAuditRequest( ...
    p.Results.reciprocal_tangent_audit_request);
reciprocalControllerModelProviderRawRequest = ...
    p.Results.reciprocal_controller_model_provider_audit_request;
correctedModelRigidResidualAllocationRequest = ...
    localCorrectedModelRigidResidualAllocationRequest( ...
    p.Results.corrected_model_rigid_residual_allocation_audit_request);
sourceCoordinateOuterRequest = ...
    p.Results.source_coordinate_outer_feedback_request;
scheduledEquilibriumFeedforwardRequest = ...
    localScheduledEquilibriumFeedforwardAuditRequest( ...
    p.Results.scheduled_equilibrium_feedforward_audit_request);
benchmarkControlProfileName = strtrim(string( ...
    p.Results.benchmark_control_profile));
auditMpcSolverOverride = lower(strtrim(string( ...
    p.Results.audit_mpc_solver_override)));
auditMpcSqpOptionsOverride = p.Results.audit_mpc_sqp_options_override;
phase18TracePath = string(p.Results.phase18_trace_path);
body_case = lower(string(body_case));
sourceCoordinateOuterEnabled = isfield(sourceCoordinateOuterRequest,'enable') && ...
    logical(sourceCoordinateOuterRequest.enable);
if sourceCoordinateOuterEnabled
    sourceCoordinateInnerHold = ...
        isfield(structuredOuterAuditRequest,'holdInnerAtTrim') && ...
        logical(structuredOuterAuditRequest.holdInnerAtTrim) && ...
        numel(fieldnames(structuredOuterAuditRequest))==1;
    assert(body_case=="coupledfull" && benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1", ...
        'sim_run:SourceCoordinateOuterScope', ...
        'The source-coordinate outer controller is restricted to formal Case A.');
    assert((isempty(fieldnames(structuredOuterAuditRequest)) || ...
        sourceCoordinateInnerHold) && ...
        isempty(fieldnames(simplePdRigidPathAuditRequest)) && ...
        isempty(fieldnames(sharedWingDaisyChainAuditRequest)) && ...
        ~coupledRtiAllocatorAuditRequest.enabled && ...
        ~wingActuatorBypassAuditRequest.enabled && ...
        ~outerWingFusionBypassAuditRequest.enabled && ...
        ~symmetricWingAuthorityDiscriminatorAuditRequest.enabled && ...
        ~realizedConstrainedOuterAllocationRequest.enabled && ...
        ~lexicographicSharedWingAllocationRequest.enabled && ...
        ~fullChannelLexicographicAllocationRequest.enabled && ...
        ~virtualDemandSharedSurfaceRealizationRequest.enabled && ...
        ~structuredVirtualPitchRuntimeRequest.enabled && ...
        ~correctedModelRigidResidualAllocationRequest.enabled && ...
        strlength(auditMpcSolverOverride)==0 && ...
        isempty(fieldnames(auditMpcSqpOptionsOverride)), ...
        'sim_run:SourceCoordinateOuterIsolation', ...
        ['The source-coordinate outer controller cannot inherit a historical ', ...
        'allocator, bypass, controller, or solver override.']);
end
if runtimeSegmentAuditRequest.enabled
    caseASegment = runtimeSegmentAuditRequest.source== ...
        "phase18c-v17a-formal-casea-integrated-resumable-execution-v1" && ...
        benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1" && ...
        sourceCoordinateOuterEnabled && ...
        isfield(reciprocalControllerModelProviderRawRequest,'enabled') && ...
        logical(reciprocalControllerModelProviderRawRequest.enabled);
    caseBcSegment = runtimeSegmentAuditRequest.source== ...
        "phase18c-v17a-casebc-integrated-resumable-execution-v1" && ...
        benchmarkControlProfileName== ...
        "phase18c_v17a_caseb_corrected_output_retained_soc_v1" && ...
        ~sourceCoordinateOuterEnabled;
    caseBSourceRootSegment = caseBcSegment && ...
        fullChannelLexicographicAllocationRequest.enabled && ...
        fullChannelLexicographicAllocationRequest. ...
        sourceRootCondensedMultiInputCoordination && ...
        any(fullChannelLexicographicAllocationRequest.source==[ ...
        "phase18c-v17a-caseb-source-root-condensed-multi-input-coordination-discriminator-v1", ...
        "phase18c-v17a-caseb-trajectory-metric-shared-allocation-persistent-integration-v1"]);
    assert(body_case=="coupledfull" && (caseASegment || caseBcSegment), ...
        'sim_run:RuntimeSegmentScope', ...
        ['Runtime segmentation is restricted to the exact integrated ', ...
        'Case-A or scheduled reciprocal Case-B/C path.']);
    assert(~runtimeCheckpointAuditRequest.enabled && ...
        ~coupledRtiAllocatorAuditRequest.enabled && ...
        ~wingActuatorBypassAuditRequest.enabled && ...
        ~outerWingFusionBypassAuditRequest.enabled && ...
        ~symmetricWingAuthorityDiscriminatorAuditRequest.enabled && ...
        ~realizedConstrainedOuterAllocationRequest.enabled && ...
        ~lexicographicSharedWingAllocationRequest.enabled && ...
        (~fullChannelLexicographicAllocationRequest.enabled || ...
        caseBSourceRootSegment) && ...
        ~virtualDemandSharedSurfaceRealizationRequest.enabled && ...
        ~structuredVirtualPitchRuntimeRequest.enabled && ...
        ~correctedModelRigidResidualAllocationRequest.enabled, ...
        'sim_run:RuntimeSegmentIsolation', ...
        ['The resumable integrated path cannot inherit an unrelated ', ...
        'allocator, bypass, or runtime checkpoint audit.']);
end
assert(isscalar(benchmarkControlProfileName), ...
    'sim_run:BenchmarkControlProfile', ...
    'benchmark_control_profile must be a scalar string.');
if fixedBasisIntrinsicPortRequest.enabled
    assert(body_case=="coupledfull" && benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1", ...
        'sim_run:IntrinsicPortAuditScope', ...
        ['The fixed-basis/intrinsic-port integration is restricted to ', ...
        'the named formal Case-A coupled-full profile.']);
    assert(isempty(fieldnames(structuredOuterAuditRequest)) && ...
        isempty(fieldnames(simplePdRigidPathAuditRequest)) && ...
        isempty(fieldnames(sharedWingDaisyChainAuditRequest)) && ...
        ~nMheHealthGateAuditRequest.enabled && ...
        ~nMhePreparationFeedbackAuditRequest.enabled && ...
        ~runtimeCheckpointAuditRequest.enabled && ...
        ~coupledRtiAllocatorAuditRequest.enabled && ...
        ~rigidAttitudeChiAuditRequest.enable && ...
        ~wingActuatorBypassAuditRequest.enabled && ...
        ~outerWingFusionBypassAuditRequest.enabled && ...
        ~symmetricWingAuthorityDiscriminatorAuditRequest.enabled && ...
        ~gustRigidResponseDomainAuditRequest.enabled && ...
        ~realizedConstrainedOuterAllocationRequest.enabled && ...
        ~lexicographicSharedWingAllocationRequest.enabled && ...
        ~fullChannelLexicographicAllocationRequest.enabled && ...
        ~virtualDemandSharedSurfaceRealizationRequest.enabled && ...
        ~structuredVirtualPitchRuntimeRequest.enabled && ...
        strlength(auditMpcSolverOverride)==0 && ...
        isempty(fieldnames(auditMpcSqpOptionsOverride)), ...
        'sim_run:IntrinsicPortAuditIsolation', ...
        ['The fixed-basis/intrinsic-port audit cannot inherit a historical ', ...
        'allocator, bypass, estimator, solver, or controller override.']);
end
if reciprocalTangentAuditRequest.enabled
    assert(body_case=="coupledfull" && benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1", ...
        'sim_run:ReciprocalTangentAuditScope', ...
        ['The reciprocal-tangent integration is restricted to the named ', ...
        'formal Case-A coupled-full profile.']);
    assert(~fixedBasisIntrinsicPortRequest.enabled && ...
        ~wingActuatorBypassAuditRequest.enabled && ...
        ~outerWingFusionBypassAuditRequest.enabled, ...
        'sim_run:ReciprocalTangentAuditIsolation', ...
        ['The reciprocal-tangent audit cannot inherit another plant-path ', ...
        'candidate or a command-path bypass.']);
end
if wingActuatorBypassAuditRequest.enabled
    assert(body_case=="coupledfull" && ...
        benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1", ...
        'sim_run:WingActuatorBypassScope', ...
        ['The wing-actuator bypass is limited to the named formal ', ...
        'Case-A coupled-full audit profile.']);
end
if outerWingFusionBypassAuditRequest.enabled
    assert(body_case=="coupledfull" && ...
        benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1", ...
        'sim_run:OuterWingFusionBypassScope', ...
        ['The outer-wing fusion bypass is limited to the named formal ', ...
        'Case-A coupled-full audit profile.']);
    assert(~wingActuatorBypassAuditRequest.enabled, ...
        'sim_run:AuditBypassConflict', ...
        ['The fusion-bypass discriminator retains actuator dynamics and ', ...
        'cannot be combined with the actuator-bypass discriminator.']);
end
if symmetricWingAuthorityDiscriminatorAuditRequest.enabled
    assert(body_case=="coupledfull" && benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1", ...
        'sim_run:SymmetricWingAuthorityDiscriminatorScope', ...
        ['The symmetric-wing authority discriminator is limited to the ', ...
        'named formal Case-A coupled-full audit profile.']);
    assert(~wingActuatorBypassAuditRequest.enabled && ...
        ~outerWingFusionBypassAuditRequest.enabled && ...
        fullChannelLexicographicAllocationRequest.enabled && ...
        fullChannelLexicographicAllocationRequest. ...
        offlineFminconReferenceGovernor && ...
        auditMpcSolverOverride=="fmincon", ...
        'sim_run:SymmetricWingAuthorityDiscriminatorIsolation', ...
        ['The authority discriminator requires only the approved ', ...
        'full-channel fmincon reference governor and no bypass.']);
end
if gustRigidResponseDomainAuditRequest.enabled
    assert(body_case=="coupledfull" && ...
        benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1", ...
        'sim_run:GustRigidResponseDomainScope', ...
        ['The gust rigid-response domain diagnostic is limited to the ', ...
        'named formal Case-A coupled-full audit profile.']);
end
if realizedConstrainedOuterAllocationRequest.enabled
    assert(body_case=="coupledfull" && benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1", ...
        'sim_run:RealizedOuterAllocationScope', ...
        ['The realized constrained outer allocation is limited to the ', ...
        'named formal Case-A coupled-full audit profile.']);
    % Keep this audit attribution-clean: it may exercise the active shared
    % wing path, but it must not inherit a prior bypass, RTI, or solver study.
    assert(~coupledRtiAllocatorAuditRequest.enabled && ...
        ~wingActuatorBypassAuditRequest.enabled && ...
        ~outerWingFusionBypassAuditRequest.enabled && ...
        strlength(auditMpcSolverOverride)==0 && ...
        isempty(fieldnames(auditMpcSqpOptionsOverride)), ...
        'sim_run:RealizedOuterAllocationIsolation', ...
        ['The realized outer-allocation audit cannot be combined with ', ...
        'coupled-RTI, bypass, or MPC-solver override requests.']);
end
if lexicographicSharedWingAllocationRequest.enabled
    assert(body_case=="coupledfull" && benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1", ...
        'sim_run:LexicographicSharedWingScope', ...
        ['The lexicographic shared-wing allocator is limited to the named ', ...
        'formal Case-A coupled-full audit profile.']);
    assert(~coupledRtiAllocatorAuditRequest.enabled && ...
        ~realizedConstrainedOuterAllocationRequest.enabled && ...
        ~wingActuatorBypassAuditRequest.enabled && ...
        ~outerWingFusionBypassAuditRequest.enabled && ...
        strlength(auditMpcSolverOverride)==0 && ...
        isempty(fieldnames(auditMpcSqpOptionsOverride)), ...
        'sim_run:LexicographicSharedWingIsolation', ...
        ['The lexicographic shared-wing allocator cannot inherit coupled-RTI, ', ...
        'prior outer-guard, bypass, or MPC-solver override requests.']);
end

if fullChannelLexicographicAllocationRequest.enabled
    caseBSourceRootCoordination = ...
        fullChannelLexicographicAllocationRequest. ...
        sourceRootCondensedMultiInputCoordination;
    fullChannelSqpAuditOnly = isfield(auditMpcSqpOptionsOverride, ...
        "AuditCapture") && logical(auditMpcSqpOptionsOverride.AuditCapture) && ...
        all(ismember(string(fieldnames(auditMpcSqpOptionsOverride)), ...
        ["AuditCapture","MaxIterations"]));
    fullChannelFminconReferenceGovernor = ...
        fullChannelLexicographicAllocationRequest. ...
        offlineFminconReferenceGovernor;
    caseAFullChannelScope = benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1" && ...
        ~caseBSourceRootCoordination;
    caseBFullChannelScope = benchmarkControlProfileName== ...
        "phase18c_v17a_caseb_corrected_output_retained_soc_v1" && ...
        caseBSourceRootCoordination;
    assert(body_case=="coupledfull" && ...
        (caseAFullChannelScope || caseBFullChannelScope), ...
        'sim_run:FullChannelLexicographicScope', ...
        ['The full-channel allocator requires its named Case-A profile or ', ...
        'the exact persistent source-root Case-B profile.']);
    assert(~coupledRtiAllocatorAuditRequest.enabled && ...
        ~realizedConstrainedOuterAllocationRequest.enabled && ...
        ~lexicographicSharedWingAllocationRequest.enabled && ...
        ~wingActuatorBypassAuditRequest.enabled && ...
        ~outerWingFusionBypassAuditRequest.enabled && ...
        (strlength(auditMpcSolverOverride)==0 || ...
        fullChannelFminconReferenceGovernor) && ...
        (isempty(fieldnames(auditMpcSqpOptionsOverride)) || ...
        fullChannelSqpAuditOnly), ...
        'sim_run:FullChannelLexicographicIsolation', ...
        ['The full-channel allocator cannot inherit another allocator, ', ...
        'bypass, solver override, or numerical change.']);
end
if virtualDemandSharedSurfaceRealizationRequest.enabled
    assert(body_case=="coupledfull" && benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1", ...
        'sim_run:VirtualDemandSharedSurfaceScope', ...
        ['The virtual-demand realization is limited to the named formal ', ...
        'Case-A coupled-full audit profile.']);
    assert(~coupledRtiAllocatorAuditRequest.enabled && ...
        ~realizedConstrainedOuterAllocationRequest.enabled && ...
        ~lexicographicSharedWingAllocationRequest.enabled && ...
        ~fullChannelLexicographicAllocationRequest.enabled && ...
        ~wingActuatorBypassAuditRequest.enabled && ...
        ~outerWingFusionBypassAuditRequest.enabled, ...
        'sim_run:VirtualDemandSharedSurfaceIsolation', ...
        ['The virtual-demand realization cannot inherit another allocator ', ...
        'or a bypass discriminator.']);
end
if structuredVirtualPitchRuntimeRequest.enabled
    assert(body_case=="coupledfull" && benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1", ...
        'sim_run:StructuredVirtualPitchRuntimeScope', ...
        ['The structured virtual-pitch runtime integration is limited to ', ...
        'the named formal Case-A coupled-full audit profile.']);
    assert(~coupledRtiAllocatorAuditRequest.enabled && ...
        ~realizedConstrainedOuterAllocationRequest.enabled && ...
        ~lexicographicSharedWingAllocationRequest.enabled && ...
        ~fullChannelLexicographicAllocationRequest.enabled && ...
        ~virtualDemandSharedSurfaceRealizationRequest.enabled && ...
        ~wingActuatorBypassAuditRequest.enabled && ...
        ~outerWingFusionBypassAuditRequest.enabled && ...
        ~symmetricWingAuthorityDiscriminatorAuditRequest.enabled && ...
        strlength(auditMpcSolverOverride)==0 && ...
        isempty(fieldnames(auditMpcSqpOptionsOverride)), ...
        'sim_run:StructuredVirtualPitchRuntimeIsolation', ...
        ['The structured virtual-pitch integration cannot inherit a ', ...
        'historical allocator, bypass, authority scale, or solver override.']);
end
if correctedModelRigidResidualAllocationRequest.enabled
    assert(body_case=="coupledfull" && benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1" && ...
        structuredVirtualPitchRuntimeRequest.enabled, ...
        'sim_run:CorrectedRigidResidualScope', ...
        ['The corrected-model residual allocator requires the named ', ...
        'formal Case-A profile and corrected structured outer controller.']);
    assert(~coupledRtiAllocatorAuditRequest.enabled && ...
        ~realizedConstrainedOuterAllocationRequest.enabled && ...
        ~lexicographicSharedWingAllocationRequest.enabled && ...
        ~fullChannelLexicographicAllocationRequest.enabled && ...
        ~virtualDemandSharedSurfaceRealizationRequest.enabled && ...
        ~wingActuatorBypassAuditRequest.enabled && ...
        ~outerWingFusionBypassAuditRequest.enabled && ...
        ~symmetricWingAuthorityDiscriminatorAuditRequest.enabled && ...
        strlength(auditMpcSolverOverride)==0 && ...
        isempty(fieldnames(auditMpcSqpOptionsOverride)), ...
        'sim_run:CorrectedRigidResidualIsolation', ...
        ['The corrected-model residual allocator cannot inherit a ', ...
        'historical allocator, bypass, authority scale, or solver override.']);
end
if coupledRtiAllocatorAuditRequest.dynamicNullspaceWingOnly
    dynamicFminconComparator = coupledRtiAllocatorAuditRequest. ...
        offlineFminconComparator.enabled;
    assert(body_case=="coupledfull" && benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1", ...
        'sim_run:DynamicNullspaceFormalCaseAScope', ...
        ['The baseline-relative rigid-tube allocator is restricted to the ', ...
        'named formal Case-A coupled-full audit profile.']);
    assert(~lexicographicSharedWingAllocationRequest.enabled && ...
        ~fullChannelLexicographicAllocationRequest.enabled && ...
        ~realizedConstrainedOuterAllocationRequest.enabled && ...
        ~wingActuatorBypassAuditRequest.enabled && ...
        ~outerWingFusionBypassAuditRequest.enabled && ...
        (strlength(auditMpcSolverOverride)==0 || ...
        (dynamicFminconComparator && auditMpcSolverOverride=="fmincon")) && ...
        isempty(fieldnames(auditMpcSqpOptionsOverride)), ...
        'sim_run:DynamicNullspaceFormalCaseAIsolation', ...
        ['The baseline-relative rigid-tube allocator cannot inherit a ', ...
        'second allocation path, bypass, or solver override outside its ', ...
        'named offline fmincon comparator.']);
end
assert(isscalar(auditMpcSolverOverride) && ...
    (strlength(auditMpcSolverOverride)==0 || ...
    any(auditMpcSolverOverride==["fmincon","custom_sqp"])), ...
    'sim_run:AuditMpcSolverOverride', ...
    'audit_mpc_solver_override must be empty, fmincon, or custom_sqp.');
benchmarkControlProfile = struct('enabled',false,'name',"");
benchmarkMeasurement = struct();
benchmarkMeasurementContext = zeros(0,1);
benchmarkSignedWingtipContract = [];
structuredVirtualPitchRuntime = struct('enabled',false);
sourceCoordinateOuter = [];
sourceCoordinateOuterBaseline = struct();
sourceCoordinateOuterLatestGust = 0;
sourceCoordinateOuterHeldGust = 0;
body_case_dir  = sanitize_bodycase(body_case);

%% ---- locate setup_dir and roots without explicit args ----
% We try, in order:
%   (A) user-provided 'setup_dir'
%   (B) roots.mat in CWD (rare)
%   (C) scan Research/*/sim_setup/<case>/<body>/ to find the latest dated run
%   (D) if we find a setup, also load for_matlab/roots.mat to reconstruct roots
%
% Everything here is path-agnostic and should work under .../Research/<anything>/

here         = fileparts(mfilename('fullpath'));       % .../MatlabFlex/configs
matlab_root  = fileparts(here);                         % .../MatlabFlex
research_root= fileparts(matlab_root);                  % .../Research
reciprocalControllerModelProviderRequest = ...
    localReciprocalControllerModelProviderAuditRequest( ...
    reciprocalControllerModelProviderRawRequest,matlab_root);
scheduledReciprocalRuntimeEnabled = false;
scheduledReciprocalPacket = struct();
scheduledReciprocalPacketCache = struct();
p1PlantIntervalAuditEnabled = false;
p1PlantIntervalAuditRequest = struct();
reciprocalControllerRuntimeEnabled = ...
    reciprocalControllerModelProviderRequest.enabled;
if reciprocalControllerModelProviderRequest.enabled
    assert(body_case=="coupledfull" && benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1" && ...
        reciprocalTangentAuditRequest.enabled, ...
        'sim_run:ReciprocalControllerProviderScope', ...
        ['The reciprocal controller-model provider requires the named ', ...
        'formal Case-A coupled-full profile and reciprocal plant owner.']);
end

% record places we checked for better error messages
checked_msgs = {};

% --- (A) explicit setup_dir wins ---
if ~isempty(setup_dir)
    setup_dir = char(setup_dir);
    if exist(setup_dir,'dir')~=7
        error('Provided setup_dir does not exist: %s', setup_dir);
    end
end

roots = [];  % will hold sharpy_root/matlab_root/sim_setup_root/sim_run_root if found

% --- (B) roots.mat in current working dir (rare but cheap) ---
if isempty(setup_dir) && exist('roots.mat','file')==2
    try
        Sroots = load('roots.mat'); roots = Sroots.roots;
        checked_msgs{end+1} = sprintf('Loaded roots.mat from CWD -> %s', pwd);
    catch
        % ignore, continue
    end
end


% Body case
cfg.sim.body_case = body_case;



% --- (C) scan Research/* for any folder that contains a sim_setup ---
if isempty(setup_dir)
    % build list of candidate sim_setup roots
    sim_setup_candidates = discover_sim_setup_roots(research_root);
    if isempty(sim_setup_candidates)
        checked_msgs{end+1} = sprintf('No sim_setup found under %s', research_root);
    else
        checked_msgs{end+1} = sprintf('Found %d sim_setup roots under %s', numel(sim_setup_candidates), research_root);
        % try each candidate for latest <case>/<body> folder
        best_dir = '';
        best_dn  = -inf;
        for c = 1:numel(sim_setup_candidates)
            base = sim_setup_candidates{c};
            if exist(fullfile(base,case_name,body_case_dir),'dir')==7
                dd = dir(fullfile(base,case_name,body_case_dir));
                dd = dd([dd.isdir]);
                for k = 1:numel(dd)
                    nm = dd(k).name;
                    if strcmp(nm,'.')||strcmp(nm,'..'), continue; end
                    this_dir = fullfile(base,case_name,body_case_dir,nm);
                    if dd(k).datenum > best_dn
                        best_dn = dd(k).datenum;
                        best_dir = this_dir;
                    end
                end
            end
        end
        if ~isempty(best_dir)
            setup_dir = best_dir;
            checked_msgs{end+1} = sprintf('Selected latest setup: %s', setup_dir);
        else
            checked_msgs{end+1} = sprintf('No dated runs under any sim_setup/<case>/<body> for %s/%s', case_name, body_case_dir);
        end
    end
end

% --- If found a setup_dir, see if it has for_matlab/roots.mat ---
if ~isempty(setup_dir) && isempty(roots)
    fm = fullfile(setup_dir,'for_matlab');
    if exist(fullfile(fm,'roots.mat'),'file')==2
        try
            Sroots = load(fullfile(fm,'roots.mat')); roots = Sroots.roots;
            checked_msgs{end+1} = sprintf('Loaded roots.mat from %s', fullfile(fm,'roots.mat'));
        catch
            checked_msgs{end+1} = sprintf('Failed loading roots.mat in %s', fm);
        end
    end
end

% --- If still no setup_dir, do a last-ditch try using any sim_bundle to reconstruct roots
if isempty(setup_dir)
    % search for any sim_bundle.mat under discovered sim_setup roots to infer a valid setup
    sim_setup_candidates = discover_sim_setup_roots(research_root);
    found_bundle = '';
    for c = 1:numel(sim_setup_candidates)
        base = sim_setup_candidates{c};
        pattern = fullfile(base,'**','for_matlab','sim_bundle.mat');
        L = dir(pattern);
        if ~isempty(L)
            % pick newest
            [~,ix] = max([L.datenum]);
            found_bundle = fullfile(L(ix).folder, L(ix).name);
            setup_dir = fileparts(L(ix).folder);  % remove /for_matlab
            checked_msgs{end+1} = sprintf('Guessed setup_dir via sim_bundle: %s', setup_dir);
            break
        end
    end
end

% --- If we still don't have setup_dir, error with diagnostics ---
if isempty(setup_dir)
    fprintf(2,'[sim_run] Could not locate a valid sim_setup folder for case="%s", body="%s".\n', case_name, body_case);
    if ~isempty(checked_msgs)
        fprintf(2,'Checked:\n');
        for i=1:numel(checked_msgs), fprintf(2,'  - %s\n', checked_msgs{i}); end
    end
    fprintf(2,'Hints:\n  • Run sim_init first (it creates sim_setup/... and roots.mat)\n  • Or call sim_run with ''setup_dir'',''/path/to/sim_setup/<case>/<body>/<date>''\n');
    error('sim_run:setup_not_found','Auto-discovery failed.');
end

% --- If we had no roots, reconstruct them from sim_bundle paths
fm_setup = fullfile(setup_dir,'for_matlab');
Ssim_setup = load(fullfile(fm_setup,'sim_bundle.mat'));    % has sim_config.paths.run_dir
if isempty(roots)
    run_dir = Ssim_setup.sim_config.paths.run_dir;
    p1 = fileparts(run_dir);    % .../sim_setup/<case>/<body>
    p2 = fileparts(p1);         % .../sim_setup/<case>
    p3 = fileparts(p2);         % .../sim_setup
    sharpy_root = fileparts(p3);
    roots.sharpy_root     = sharpy_root;
    roots.sim_setup_root  = p3;
    roots.sim_run_root    = fullfile(sharpy_root,'sim_run');
    roots.matlab_root     = matlab_root;                  % from our file location
    checked_msgs{end+1}   = sprintf('Reconstructed roots from sim_bundle at %s', fm_setup);
else
    sharpy_root = roots.sharpy_root;
end

% Finally, create the sim_run folder structure and expose only the package
% parent. Recursively adding MatlabFlex would also expose superseded MEX
% caches and package internals, making runtime function ownership depend on
% path order rather than the source-signature check in setupProject.
sim_run_root = fullfile(roots.sharpy_root,'sim_run');
[run_dir, paths] = create_run_dirs(sim_run_root, case_name, sanitize_bodycase(body_case), overwrite, date_only_runs);
addpath(roots.matlab_root,'-begin');


% ------------------- global console log -------------------
if ~exist(paths.logs,'dir'), mkdir(paths.logs); end
log_name = sprintf('run_%s_%s_%s.log', case_name, body_case_dir, datestr(now,'yyyymmdd'));
console_log = fullfile(paths.logs, log_name);
diary off; diary(console_log); diary on;
cleanupLog = onCleanup(@() diary('off')); %#ok<NASGU>

fprintf('=== sim_run started %s ===\n', datestr(now,'yyyy-mm-dd HH:MM:SS'));
fprintf('setup_dir: %s\n', setup_dir);
fprintf('run_dir  : %s\n', run_dir);

% ------------------- load setup artifacts -------------------
fm = fullfile(setup_dir,'for_matlab');
fs = fullfile(setup_dir,'for_sharpy');
assert(exist(fm,'dir')==7 && exist(fs,'dir')==7, 'Setup dir missing for_matlab/for_sharpy.');

% Core bundles
Ssim = load(fullfile(fm,'sim_bundle.mat'));         % sim_config, state_space_system, input_settings, ...
Saer = load(fullfile(fm,'aero_bundle.mat'));        % aero
Sbem = load(fullfile(fm,'beam_bundle.mat'));        % beam
Sbas = load(fullfile(fm,'base_bundle.mat'));        % base
Srun = load(fullfile(fm,'run_settings.mat'));       % run_settings

% Optional L
if exist(fullfile(fm,'L_bundle.mat'),'file')
    SL = load(fullfile(fm,'L_bundle.mat')); L = SL.L; blk = SL.blk; %#ok<NASGU>
else
    L = []; blk = [];
end

% Gust/time H5
h5 = fullfile(fs,'sim_for_sharpy.h5');
assert(exist(h5,'file')==2, 'Missing sim_for_sharpy.h5 in setup.');
t_vec       = h5read(h5,'/time');                   % nsamp×1
gust_series = h5read(h5,'/gust');                   % nsamp×1
% deflection  = h5read(h5,'/deflection');             % nsamp×Nc
% defl_rate   = h5read(h5,'/deflection_rate');        % nsamp×Nc



% Rehydrate objects/config
cfg  = Ssim.sim_config.cfg;
aero = Saer.aero;
beam = Sbem.beam;
base = Sbas.base;
trim = Ssim.sim_config.trim;
idx  = Ssim.sim_config.idx;
% Runtime products belong to this invocation, not to the reusable setup.
% Preserve setup provenance separately while redirecting plots, logs, and
% post-processing products to the unique run directory.
if ~isfield(cfg,'paths') || ~isstruct(cfg.paths)
    cfg.paths = struct();
end
cfg.paths.setup_dir = setup_dir;
runPathFields = fieldnames(paths);
for runPathIndex = 1:numel(runPathFields)
    runPathField = runPathFields{runPathIndex};
    cfg.paths.(runPathField) = paths.(runPathField);
end
if isfield(Ssim.sim_config,'x0')
    x0 = Ssim.sim_config.x0;
else
    x0 = [];
end
if ~isempty(fieldnames(structuredOuterAuditRequest))
    if ~isfield(cfg, 'outerLQR')
        cfg.outerLQR = struct();
    end
    cfg.outerLQR.structuredOuter = structuredOuterAuditRequest;
    if isfield(structuredOuterAuditRequest, 'gainBank')
        cfg.outerLQR.gainBank = structuredOuterAuditRequest.gainBank;
    end
end
if ~isempty(fieldnames(simplePdRigidPathAuditRequest))
    assert(body_case=="coupledfull" && benchmarkControlProfileName== ...
        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1", ...
        'sim_run:SimplePdRigidPathScope', ...
        ['The simple PD rigid-path discriminator is limited to the named ', ...
        'formal Case-A coupled-full profile.']);
    if ~isfield(cfg,'outerLQR')
        cfg.outerLQR = struct();
    end
    cfg.outerLQR.simplePdRigidPath = simplePdRigidPathAuditRequest;
end
if ~isempty(fieldnames(sharedWingDaisyChainAuditRequest))
    if ~isfield(cfg,'outerLQR')
        cfg.outerLQR = struct();
    end
    cfg.outerLQR.sharedWingDaisyChain = sharedWingDaisyChainAuditRequest;
end
if ~isempty(fieldnames(outerAuditReferenceProvider))
    if ~isfield(cfg,'outerLQR')
        cfg.outerLQR = struct();
    end
    cfg.outerLQR.auditReferenceProvider = outerAuditReferenceProvider;
end
if ~isempty(fieldnames(outerReferenceProvider))
    if ~isfield(cfg,'outerLQR')
        cfg.outerLQR = struct();
    end
    cfg.outerLQR.referenceProvider = outerReferenceProvider;
end
if scheduledEquilibriumFeedforwardRequest.enable
    if ~isfield(cfg,'outerLQR')
        cfg.outerLQR = struct();
    end
    cfg.outerLQR.scheduledEquilibriumFeedforward = ...
        scheduledEquilibriumFeedforwardRequest;
end
% GLAConfig is re-run by the PlantROM path. Preserve the explicitly
% opt-in audit reference request across that configuration refresh; the
% request remains absent unless the audit setup supplied it.
auditReferenceRequest = struct();
if isfield(cfg,'outerLQR') && isfield(cfg.outerLQR,'auditReferenceProvider')
    auditReferenceRequest = cfg.outerLQR.auditReferenceProvider;
end
referenceRequest = struct();
if isfield(cfg,'outerLQR') && isfield(cfg.outerLQR,'referenceProvider')
    referenceRequest = cfg.outerLQR.referenceProvider;
end
sharedWingDaisyChainRequest = struct();
if isfield(cfg,'outerLQR') && isfield(cfg.outerLQR,'sharedWingDaisyChain')
    sharedWingDaisyChainRequest = cfg.outerLQR.sharedWingDaisyChain;
end
scheduledEquilibriumFeedforwardSaved = struct();
if isfield(cfg,'outerLQR') && ...
        isfield(cfg.outerLQR,'scheduledEquilibriumFeedforward')
    scheduledEquilibriumFeedforwardSaved = ...
        cfg.outerLQR.scheduledEquilibriumFeedforward;
end
%

deflection  = safe_h5read(h5, '/deflection',    zeros(numel(t_vec), getOr(cfg.ctrl,'n_surf',2)));
defl_rate   = safe_h5read(h5, '/deflection_rate', zeros(numel(t_vec), getOr(cfg.ctrl,'n_surf',2)));
% % Make sure gust pipe is consistent for SimRunner path
% if isprop(aero, 'gust_input')
%     aero.gust_input = gust_series(:);   % guarantee column
% end

% Keep gust external; AeroROM.gust_input is read-only.
gust_series = gust_series(:);  % used in Plant/ROM loops below
if isfield(cfg.gust,'scaleMag')
    gust_series = gust_series*cfg.gust.scaleMag;
end

% AeroFlex.sched.defaultLibraryConfig;
% cfg = AeroFlex.sched.defaultLibraryConfig;
% cfg = AeroFlex.sched.defaultLibraryConfig(cfg);
ROMlib = [];
if isfield(cfg,'library') && cfg.library.enable
    AeroFlex.sched.defaultLibraryConfig;

    if isfield(Ssim.sim_config,'ROMlib')
        ROMlib = Ssim.sim_config.ROMlib;
    elseif exist(cfg.library.path,'file') == 2
        ROMlib = AeroFlex.sched.loadLibrary(cfg.library.path);
    else
        error('cfg.library.enable=true, but no ROM library was found.');
    end
end

% Optional sanity check for SimRunner path (just warn; do not set)
try
    gi = aero.gust_input;  % will throw if not readable; that's fine
    if ~isempty(gi) && numel(gi) ~= numel(gust_series)
        warning(['sim_run:gust_length_mismatch'], ...
            'Setup gust length = %d, H5 gust length = %d. SimRunner will use its setup gust.', ...
            numel(gi), numel(gust_series));
    end
catch
    % property exists but read-only; ignore
end

% Runner preferences
run_settings = Srun.run_settings;
sim_case     = lower(char(run_settings.sim_case));
runner       = lower(char(run_settings.runner));

% ------------------- prep outputs & metadata -------------------
copyfile(setup_dir, fullfile(paths.run_dir,'_setup_snapshot'));  % helpful provenance

% Save a small meta for the run
meta_fn = fullfile(paths.run_dir,'meta_run.yaml');
fid = fopen(meta_fn,'w');
if fid~=-1
    fprintf(fid,'case_name: %s\n', Ssim.sim_config.case_name);
    fprintf(fid,'body_case: %s\n', body_case_dir);
    fprintf(fid,'setup_dir: %s\n', setup_dir);
    fprintf(fid,'created:   %s\n', datestr(now,'yyyy-mm-dd'));
    fprintf(fid,'sim_case:  %s\n', sim_case);
    fprintf(fid,'runner:    %s\n', runner);
    fclose(fid);
end

% ------------------- RUN DISPATCH ----------------------------------------
results = struct(); hadError = false; MEout = [];
cfg.sim.bodyCase = body_case;
cfg.sim.body_case= body_case;
if strlength(phase18TracePath) > 0
    if ~isfield(cfg,'debug') || ~isstruct(cfg.debug)
        cfg.debug = struct();
    end
    cfg.debug.phase18TracePath = char(phase18TracePath);
end
if isfield(fullChannelLexicographicAllocationRequest, ...
        'centeredRootWrenchGustRecovery') && ~isempty(fieldnames( ...
        fullChannelLexicographicAllocationRequest.centeredRootWrenchGustRecovery))
    cfg.sim.centeredRootWrenchGustRecoveryAudit = ...
        fullChannelLexicographicAllocationRequest.centeredRootWrenchGustRecovery;
end
% try
% Optional symmetry handling if using one semi-wing to represent both wings.
% cfg.sim.symmetricWingPair = true;
cfg.sim.symmetricWingPair = false;
cfg.sim.wingMultiplicity  = 1;

% Conservative default: do not overwrite chi unless you explicitly want
% rigid-body alpha injected into the ROM attitude states.
% cfg.sim.coupleRigidAttitudeIntoWingChi = false;
% cfg.sim.coupleRigidAttitudeIntoWingChi = false;
if structuredVirtualPitchRuntimeRequest.enabled && ...
        string(structuredVirtualPitchRuntimeRequest.source)== ...
        "phase18c-v17a-corrected-nonwing-trim-lqr-owner-integration-v1"
    [cfg,trim,x0] = localInstallCorrectedNonwingTrimOwner( ...
        cfg,trim,x0,structuredVirtualPitchRuntimeRequest,matlab_root);
end

% Rigid-body parameters
rParams = RigidBody.methods.paramsRigid_PazyUAV();
explicitNonwingOwner = isfield(cfg,'rigidEOMset') && ...
    isstruct(cfg.rigidEOMset) && ...
    isfield(cfg.rigidEOMset,'massOwnership') && ...
    string(cfg.rigidEOMset.massOwnership.owner)== ...
    "nonwing_source_owned_wing_reaction";
if explicitNonwingOwner
    [cfg,~] = RigidBody.methods.applyRuntimeMassOwner(cfg, ...
        "nonwing_source_owned_wing_reaction");
else
    cfg.rigidEOMset.mass = rParams.mass;
    if isfield(rParams,'J')
        cfg.rigidEOMset.I_B = rParams.J;
    else
        error('Could not find inertia in rParams.');
    end
end

% Thrust line offset, body frame, from CG to thrust application point.
cfg.rigidEOMset.rThrust_B = [0;0;0];

% initial rigid state.
% cfg.rigidEOMset.euler0 = [0; deg2rad(cfg.flight.aoa_deg); 0];
% Rigid initial condition from coupled trim.
alphaTrim = 0;
if isstruct(trim) && isfield(trim,'alphaDeg') && isfinite(trim.alphaDeg)
    alphaTrim = deg2rad(trim.alphaDeg);
elseif isfield(cfg.flight,'aoa_deg')
    alphaTrim = deg2rad(cfg.flight.aoa_deg);
end

cfg.rigidEOMset.euler0 = [0; alphaTrim; 0];
cfg.rigidEOMset.vB0    = [cfg.flight.U_inf*cos(alphaTrim);
    0;
    cfg.flight.U_inf*sin(alphaTrim)];

% Commands are increments about trim. PlantRunTime adds trim internally.
cfg.sim.commandsAreTrimIncrements = true;

% First validation mode. Change to "perPlantStep" only after trim replay works.
if isfield(cfg,'library') && cfg.library.enable
    % cfg.library.updateMode = 'frozenTrim';
    cfg.library.noExtrapolate = true;
end

alphaTrim = deg2rad(trim.alphaDeg);

cfg.rigidEOMset.euler0 = [0; alphaTrim; 0];
cfg.rigidEOMset.vB0 = [cfg.flight.U_inf*cos(alphaTrim);
    0;
    cfg.flight.U_inf*sin(alphaTrim)];

% ---------------------------------------------------------------------
% State-history allocation
% ---------------------------------------------------------------------
nxFlex = length(trim.states);   % flexible ROM state length
if isempty(x0)
    x0 = trim.states(:);
end
validateattributes(x0,{'numeric'}, {'real','vector','finite'}, ...
    mfilename,'sim_config.x0');
x0 = x0(:);
assert(numel(x0) == nxFlex, 'sim_run:InitialConditionDimension', ...
    ['sim_config.x0 has length %d, but this control path requires the ', ...
    'flexible ROM state length %d.'], numel(x0), nxFlex);

% Use Nt+1 because plant states include the initial condition and each step.
t = t_vec(:);                       % column
Nt = numel(t) - 1;                  % number of s
x = zeros(nxFlex,Nt+1);
x(:,1) = x0(1:nxFlex);

% Rigid-body appended state:
%   rb = [r_I(3); v_B(3); euler(3); omega_B(3)]
rbHist = nan(12,Nt+1);

% Coupled-load logs:
Clamp6Hist   = nan(6,Nt);
FwingHist    = nan(3,Nt);
MwingHist    = nan(3,Nt);
FtotHist     = nan(3,Nt);
MtotHist     = nan(3,Nt);
FgravHist    = nan(3,Nt);
FthrustHist  = nan(3,Nt);

%

if isfield(cfg,'debug') && isstruct(cfg.debug) && ...
        isfield(cfg.debug,'plotTrueGust') && logical(cfg.debug.plotTrueGust)
    figure; plot(t_vec, gust_series); title('True Gust Series');
    xlabel('t (sec)'); ylabel('w true');
end

switch sim_case

    % ================= OPENLOOP =================
    case 'openloop'
        switch runner
            case 'simrunner'
                % Fresh SimRunner (don’t reuse any stale handles from MAT)
                simObj = AeroFlex.sim.SimRunner(cfg, beam, aero, base, trim);
                cfg.sim.storeSens = true;               % mirror setup
                u_ctrl = zeros(cfg.ctrl.n_surf*cfg.ctrl.var_per,1); % open-loop
                [t, x, log, sensEq] = simObj.run(x0, Ssim.sim_config.cfg.sim.t_end, u_ctrl, cfg.sim.storeSens);

            case 'plantrom'
                % Plant integrator path (ROMIntegrator + PlantRunTime)
                modelFcn      = str2func(run_settings.modelFcn);
                sensorFcn     = str2func(run_settings.sensorFcn);
                estimatorFcn  = str2func(run_settings.estimatorFcn);
                controllerFcn = @(cfg_in) [];   % not used in open-loop


                % Time grid from setup H5
                t = t_vec(:);                       % column
                Nt = numel(t) - 1;                  % number of steps between samples
                x  = zeros(length(x0), Nt+1); x(:,1) = x0;
                switch lower(string(body_case))
                    case "wingonly"
                        cfg.sim.rigidToWingMode = "fixed";

                    case "coupledfull"
                        cfg.sim.rigidToWingMode = "alpha_gust";

                    otherwise
                        error('Unknown cfg.sim.body_case = "%s".', cfg.sim.body_case);
                end
                rom   = modelFcn(cfg, beam, aero, base);
                % cfg.sim.mirrorWingClamp = true;
                % cfg.sim.symmetricWingPair = false;
                % cfg.sim.wingMultiplicity = 1;
                %
                % cfg.sim.commandsAreTrimIncrements = true;
                % cfg.sim.coupleRigidAttitudeIntoWingChi = false;
                % cfg.sim.shiftWingMomentToCG = false;

                if nMhePreparationFeedbackAuditRequest.enabled
                    cfg.ctrl.mhePreparationFeedbackAudit = ...
                        nMhePreparationFeedbackAuditRequest;
                end
                plant = AeroFlex.sim.PlantRunTime(cfg, beam, aero, base, x0, trim);

                % Lookup
                if ~isempty(ROMlib) & cfg.library.enable
                    plant.attachROMLibrary(ROMlib);
                end
                if plant.useRigidBody
                    rbHist(:,1) = localRigidStateVector(plant);
                end

                % Read-only local load derivatives at the trimmed state.
                % This should be checked before trusting any open-loop divergence.
                if ~isfield(cfg,'debug') || ~isfield(cfg.debug,'trimDerivatives')
                    cfg.debug.trimDerivatives = true;
                end

                if cfg.sim.body_case ~= "wingonly"
                    if cfg.debug.trimDerivatives
                        trimDeriv = plant.diagnoseTrimLocalDerivatives();
                        results.trimDerivativeDiagnostic = trimDeriv;
                        % return
                    end
                end
                log = struct(); sensEq = [];

                for k = 1:Nt
                    % gk = gust_series(k+1);          % align with sample k
                    gk = gust_series(k);          % align with sample k
                    uk = zeros(cfg.ctrl.n_surf*cfg.ctrl.var_per,1);

                    switch lower(string(body_case))
                        case "wingonly"
                            cfg.sim.rigidToWingMode = "fixed";
                            assert(cfg.sim.commandsAreTrimIncrements, ...
                                'sim_run:WingOnlyOpenLoopCommandFrame', ...
                                ['Wing-only open-loop propagation requires ', ...
                                 'the trim-relative command contract.']);
                            xk = plant.step( ...
                                plant.trimWingControl+uk,gk,"ROM");

                        case "coupledfull"
                            cfg.sim.rigidToWingMode = "alpha_gust";
                            xk = plant.stepCoupled(uk, gk);

                        otherwise
                            error('Unknown cfg.sim.body_case = "%s".', cfg.sim.body_case);
                    end
                    % x(:,k+1) = plant.step(uk, gk, "ROM");
                    xk_full = xk;
                    % ---------------------------------------------------------------------
                    % Split plant state into flexible and rigid-body parts.
                    % ---------------------------------------------------------------------
                    [xFlex_k, rb_k] = splitFlexibleRigidState(xk_full,nxFlex);

                    % Store flexible part for legacy postProcess reconstruction.
                    x(:,k+1) = xFlex_k;

                    % Store appended rigid-body states separately.
                    if ~isempty(rb_k)
                        rbHist(:,k+1) = rb_k;
                    end

                    % ---------------------------------------------------------------------
                    % Store coupled force/moment terms if PlantRunTime.stepCoupled populated
                    % plant.last.
                    % ---------------------------------------------------------------------
                    if isprop(plant,'last') && isstruct(plant.last)

                        if isfield(plant.last,'Clamp6')
                            Clamp6Hist(:,k) = plant.last.Clamp6(:);
                        end

                        if isfield(plant.last,'Fwing_B')
                            FwingHist(:,k) = plant.last.Fwing_B(:);
                        end

                        if isfield(plant.last,'Mwing_B')
                            MwingHist(:,k) = plant.last.Mwing_B(:);
                        end

                        if isfield(plant.last,'Ftot_B')
                            FtotHist(:,k) = plant.last.Ftot_B(:);
                        end

                        if isfield(plant.last,'Mtot_B')
                            MtotHist(:,k) = plant.last.Mtot_B(:);
                        end

                        if isfield(plant.last,'Fgrav_B')
                            FgravHist(:,k) = plant.last.Fgrav_B(:);
                        end

                        if isfield(plant.last,'Fthrust_B')
                            FthrustHist(:,k) = plant.last.Fthrust_B(:);
                        end
                    end
                end


            otherwise
                error('Unknown runner="%s".', runner);
        end

        % ================= NMHE/NMPC =================
    case 'nmhe_nmpc'
        % A serialized setup owns its solver selection and options.
        % Retain SQPconfig only as a legacy fallback for incomplete setup
        % bundles, rather than overwriting a declared runtime contract.
        if ~isfield(cfg,'ctrl') || ~isstruct(cfg.ctrl) || ...
                ~isfield(cfg.ctrl,'mpcSolver') || ...
                ~isfield(cfg.ctrl,'mheSolver') || ...
                ~isfield(cfg.ctrl,'sqp') || ...
                ~isfield(cfg.ctrl,'mheSqp')
            SQPconfig;
        end
        switch runner
            case 'simrunner'
                % Let SimRunner own the inner loop (if your SimRunner supports control hooks)
                % Here we just call it; user’s SimRunner implementation applies control inside.
                simObj = AeroFlex.sim.SimRunner(cfg, beam, aero, base, trim);
                cfg.sim.storeSens = false;
                [t, x, log, sensEq] = simObj.run(x0, Ssim.sim_config.cfg.sim.t_end, cfg.sim.storeSens);

            case 'plantrom'
                % Full loop: Plant + Estimator + Controller
                GLAConfig;
                if strlength(phase18TracePath) > 0
                    if ~isfield(cfg,'debug') || ~isstruct(cfg.debug)
                        cfg.debug = struct();
                    end
                    cfg.debug.phase18TracePath = char(phase18TracePath);
                end
                if ~isempty(fieldnames(auditReferenceRequest))
                    if ~isfield(cfg,'outerLQR')
                        cfg.outerLQR = struct();
                    end
                    cfg.outerLQR.auditReferenceProvider = auditReferenceRequest;
                end
                if ~isempty(fieldnames(referenceRequest))
                    if ~isfield(cfg,'outerLQR')
                        cfg.outerLQR = struct();
                    end
                    cfg.outerLQR.referenceProvider = referenceRequest;
                end
                if ~isempty(fieldnames(sharedWingDaisyChainRequest))
                    if ~isfield(cfg,'outerLQR')
                        cfg.outerLQR = struct();
                    end
                    cfg.outerLQR.sharedWingDaisyChain = ...
                        sharedWingDaisyChainRequest;
                end
                % bodyCase = lower(string(cfg.sim.bodyCase));

                switch body_case
                    case "wingonly"
                        useRigidBody = false;
                        useOuterLQR  = false;

                    case "coupledfull"
                        useRigidBody = true;
                        useOuterLQR  = true;

                        if benchmarkControlProfileName ~= ...
                                "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1"
                            LQRConfig;
                        end
                        % LQRConfig refreshes cfg.outerLQR.  Restore the
                        % explicitly supplied audit-only reference after
                        % that refresh so its scheduler fields reach the
                        % active control-sample package.
                        if ~isempty(fieldnames(auditReferenceRequest))
                            cfg.outerLQR.auditReferenceProvider = ...
                                auditReferenceRequest;
                        end
                        if ~isempty(fieldnames(referenceRequest))
                            cfg.outerLQR.referenceProvider = ...
                                referenceRequest;
                        end
                        if ~isempty(fieldnames( ...
                                scheduledEquilibriumFeedforwardSaved))
                            cfg.outerLQR.scheduledEquilibriumFeedforward = ...
                                scheduledEquilibriumFeedforwardSaved;
                        end
                        cfg.trim.useRateProjection = true;

                    otherwise
                        error('Unknown cfg.sim.bodyCase = "%s".', body_case);
                end

                if useOuterLQR && isfield(structuredOuterAuditRequest, ...
                        'holdInnerAtTrim') && ...
                        logical(structuredOuterAuditRequest.holdInnerAtTrim)
                    cfg.ctrl.skipMPC = true;
                    if isfield(structuredOuterAuditRequest, ...
                            'holdEstimatorAtTrim') && ...
                            logical(structuredOuterAuditRequest. ...
                            holdEstimatorAtTrim)
                        cfg.ctrl.skipMHE = true;
                    end
                end

                if useOuterLQR && benchmarkControlProfileName ~= ...
                        "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1"
                    outerCtrl = AeroFlex.ctrl.OuterLQR(cfg, trim);
                else
                    outerCtrl = [];
                end

                sharedIncrementActuatorFrame = ...
                    isfield(cfg,'sharedModelWorkflow') && ...
                    isstruct(cfg.sharedModelWorkflow) && ...
                    isfield(cfg.sharedModelWorkflow,'enabled') && ...
                    logical(cfg.sharedModelWorkflow.enabled) && ...
                    isfield(cfg.sharedModelWorkflow,'actuatorCommandFrame') && ...
                    string(cfg.sharedModelWorkflow.actuatorCommandFrame) == ...
                    "trim_relative_increment";
                if sharedIncrementActuatorFrame
                    assert(strlength(benchmarkControlProfileName)==0, ...
                        'sim_run:SharedActuatorFormalProfile', ...
                        ['The shared actuator-frame owner cannot replace ', ...
                         'a formal benchmark profile owner.']);
                    assert(isfield(cfg,'sim') && ...
                        isfield(cfg.sim,'commandsAreTrimIncrements') && ...
                        logical(cfg.sim.commandsAreTrimIncrements), ...
                        'sim_run:SharedActuatorCommandFrame', ...
                        ['The shared actuator-frame owner requires the ', ...
                         'trim-relative command contract.']);
                    cfg.trim.Uinpt = zeros( ...
                        cfg.ctrl.n_surf*cfg.ctrl.var_per,1);
                end


                if isfield(cfg,'fusion') && isfield(cfg.fusion,'enable') && cfg.fusion.enable
                    fuser = AeroFlex.ctrl.ComplementaryCommandFusion(cfg, trim);
                else
                    fuser = [];
                end
                coordinateNmpcHorizon = useOuterLQR && ~isempty(fuser) && ...
                    ((isfield(structuredOuterAuditRequest, ...
                    'coordinateNmpcHorizon') && ...
                    logical(structuredOuterAuditRequest.coordinateNmpcHorizon)) || ...
                    (isfield(sharedWingDaisyChainAuditRequest, ...
                    'coordinateNmpcHorizon') && ...
                    logical(sharedWingDaisyChainAuditRequest.coordinateNmpcHorizon)) || ...
                    lexicographicSharedWingAllocationRequest.enabled || ...
                    fullChannelLexicographicAllocationRequest.enabled || ...
                    structuredVirtualPitchRuntimeRequest.enabled || ...
                    (sourceCoordinateOuterEnabled && ~cfg.ctrl.skipMPC) || ...
                    (coupledRtiAllocatorAuditRequest.enabled && ...
                    coupledRtiAllocatorAuditRequest. ...
                    daisyChainOuterEndpointIntegration));
                priorityNmpcReference = useOuterLQR && ~isempty(fuser) && ...
                    isfield(structuredOuterAuditRequest, ...
                    'priorityNmpcReference') && ...
                    logical(structuredOuterAuditRequest.priorityNmpcReference);
                realizeNmpcEndpoint = useOuterLQR && ~isempty(fuser) && ...
                    isfield(structuredOuterAuditRequest, ...
                    'realizeNmpcEndpoint') && ...
                    logical(structuredOuterAuditRequest.realizeNmpcEndpoint);
                if lexicographicSharedWingAllocationRequest.enabled
                    % This request owns a realised endpoint handoff after
                    % nMPC; it is an explicit third coordination contract.
                    coordinateNmpcHorizon = true;
                end
                if fullChannelLexicographicAllocationRequest.enabled
                    coordinateNmpcHorizon = true;
                end
                assert(~coordinateNmpcHorizon || ...
                    ((isfield(cfg.outerLQR,'structuredOuter') && ...
                    cfg.outerLQR.structuredOuter.enable) || ...
                    (isfield(cfg.outerLQR,'sharedWingDaisyChain') && ...
                    cfg.outerLQR.sharedWingDaisyChain.enable) || ...
                    structuredVirtualPitchRuntimeRequest.enabled || ...
                    sourceCoordinateOuterEnabled || ...
                    fullChannelLexicographicAllocationRequest. ...
                    sourceRootCondensedMultiInputCoordination), ...
                    'sim_run:CoordinationAuditRequest', ...
                    ['Shared-command horizon coordination requires the ', ...
                    'explicit structured outer audit request.']);
                assert(~(coordinateNmpcHorizon && priorityNmpcReference), ...
                    'sim_run:PriorityReferenceContract', ...
                    ['The forced-base and priority-reference shared-wing ', ...
                    'contracts are mutually exclusive.']);
                assert(~(coordinateNmpcHorizon && realizeNmpcEndpoint), ...
                    'sim_run:EndpointRealizationContract', ...
                    ['The forced-base and endpoint-realization audit ', ...
                    'contracts are mutually exclusive.']);
                assert(~(nMheHealthGateAuditRequest.enabled && ...
                    useOuterLQR && isempty(fuser)), ...
                    'sim_run:nMheHealthGateFusion', ...
                    ['The coupled nMHE-health audit requires the existing ', ...
                    'fusion owner to preserve the preceding wing endpoint ', ...
                    'while the outer rigid LQR remains active.']);

                if isfield(cfg,'actuator') && isfield(cfg.actuator,'enable') && cfg.actuator.enable
                    actuator = AeroFlex.ctrl.ActuatorChain(cfg, trim);
                else
                    actuator = [];
                end

                outerEvery = 1;
                if isfield(cfg,'ctrl') && isfield(cfg.ctrl,'outerEvery')
                    outerEvery = cfg.ctrl.outerEvery;
                end
                cfg.nu        = size(aero.forceMap.B_delta,2) ...
                    + size(aero.forceMap.B_ddelta,2);
                u_outer_hold = zeros(cfg.nu,1);
                u_outer_raw_hold = u_outer_hold;
                rbCmd_hold = struct('delta_e',0,'delta_a',0,'delta_r',0,'thrust',0);
                rigidIncrementHold = zeros(4,1);
                rigidTotalHold = zeros(4,1);
                rigidStateHold = zeros(9,1);
                rigidReferenceHold = zeros(9,1);
                structuredVirtualPitchReferenceHold = zeros(9,1);
                structuredVirtualPitchStateHold = zeros(9,1);
                structuredVirtualPitchPrevious = struct( ...
                    'uOuter',u_outer_hold,'rigidIncrement',rigidIncrementHold, ...
                    'rigidTotal',rigidTotalHold,'rbCmd',rbCmd_hold, ...
                    'accepted',false,'sample',0);
                fullChannelTrimReference = zeros(9,1);
                fullChannelTrimReferenceCaptured = false;
                fullChannelFeasibilityTailAllocatorCalls = 0;
                virtualDemandModel = struct();
                virtualDemandContextHold = struct('valid',false);
                virtualDemandRealizationHold = struct('accepted',false);
                if virtualDemandSharedSurfaceRealizationRequest.enabled
                    virtualDemandModel = localLoadVirtualDemandSharedSurfaceModel( ...
                        virtualDemandSharedSurfaceRealizationRequest);
                end
                correctedRigidResidualModel = struct();
                correctedRigidResidualPreview = [];
                correctedRigidResidualNominalHold = struct( ...
                    'valid',false,'wing',0,'elevator',0,'thrust',0);
                correctedRigidResidualPreviousTailThrust = zeros(2,1);
                correctedRigidResidualRealizationHold = struct( ...
                    'accepted',false,'reason',"not_evaluated");
                if correctedModelRigidResidualAllocationRequest.enabled
                    correctedRigidResidualModel = ...
                        localLoadCorrectedModelRigidResidualModel( ...
                        correctedModelRigidResidualAllocationRequest);
                    assert(abs(correctedRigidResidualModel.sampleTimeSeconds- ...
                        cfg.ctrl.Ts)<=10*eps(cfg.ctrl.Ts), ...
                        'sim_run:CorrectedRigidResidualCadence', ...
                        ['The residual input map and active inner-loop ', ...
                        'sample times differ.']);
                    residualPreviewRequest = struct('enabled',true, ...
                        'auditOnly',true,'predictionIntervals',3, ...
                        'finiteDifferenceStep',2.5e-3);
                    correctedRigidResidualPreview = ...
                        AeroFlex.ctrl.CoupledRtiAllocatorAudit( ...
                        cfg,beam,aero,base,residualPreviewRequest);
                end


                modelFcn      = str2func(run_settings.modelFcn);
                sensorFcn     = str2func(run_settings.sensorFcn);
                estimatorFcn  = str2func(run_settings.estimatorFcn);
                controllerFcn = str2func(run_settings.controllerFcn);
                cfg.sim.storeSens = true;           % true if also want ∂x/∂x0
                % cfg.trim.useRateProjection = false;
                cfg.trim.Uinpt = zeros(4,1);

                % Instantiate
                sharedExactPackagePrediction = ...
                    isfield(cfg,'sharedModelWorkflow') && ...
                    isstruct(cfg.sharedModelWorkflow) && ...
                    isfield(cfg.sharedModelWorkflow,'enabled') && ...
                    logical(cfg.sharedModelWorkflow.enabled) && ...
                    isfield(cfg.sharedModelWorkflow, ...
                        'exactPackagePrediction') && ...
                    logical(cfg.sharedModelWorkflow. ...
                        exactPackagePrediction);
                if sharedExactPackagePrediction
                    assert(strlength(benchmarkControlProfileName)==0, ...
                        'sim_run:SharedExactPackageFormalProfile', ...
                        ['The shared exact-package predictor owner cannot ', ...
                         'replace a formal benchmark profile owner.']);
                    assert(isfield(cfg,'library') && cfg.library.enable && ...
                        isfield(cfg.library,'frozenPackage') && ...
                        ~isempty(cfg.library.frozenPackage), ...
                        'sim_run:SharedExactPackageMissing', ...
                        ['The shared prediction owner requires the exact ', ...
                         'package already attached to the plant.']);
                    predictionPackage = cfg.library.frozenPackage;
                    assert(isfield(predictionPackage,'name') && ...
                        string(predictionPackage.name)== ...
                        string(cfg.sharedModelWorkflow.sourceId), ...
                        'sim_run:SharedExactPackageSource', ...
                        ['The shared prediction package and declared source ', ...
                         'identity differ.']);
                    cfg.modelHandle = @(runtimeCfg,beamModel,aeroModel,baseModel) ...
                        modelFcn(runtimeCfg,beamModel,aeroModel,baseModel, ...
                            predictionPackage);
                else
                    cfg.modelHandle = @(runtimeCfg,beamModel,aeroModel,baseModel) ...
                        modelFcn(runtimeCfg,beamModel,aeroModel,baseModel);
                end
                % -------------- 1.  SENSOR / DIMENSIONS ----------------------------
                sensor = sensorFcn(beam, cfg);
                cfg.ny        = size(sensor.PhiY,1);
                cfg.nu        = size(aero.forceMap.B_delta,2) ...
                    + size(aero.forceMap.B_ddelta,2);
                cfg.nw        = size(aero.forceMap.Bw,2);
                switch lower(string(body_case))
                    case "wingonly"
                        cfg.sim.rigidToWingMode = "fixed";

                    case "coupledfull"
                        cfg.sim.rigidToWingMode = "alpha_gust";

                    otherwise
                        error('Unknown cfg.sim.body_case = "%s".', cfg.sim.body_case);
                end

                % cfg.sim.mirrorWingClamp = true;
                % cfg.sim.symmetricWingPair = false;
                % cfg.sim.wingMultiplicity = 1;
                %
                % cfg.sim.commandsAreTrimIncrements = true;
                % cfg.sim.coupleRigidAttitudeIntoWingChi = false;
                % cfg.sim.shiftWingMomentToCG = false;
                plant = AeroFlex.sim.PlantRunTime(cfg, beam, aero, base, x0, trim);
                % Lookup
                if ~isempty(ROMlib) & cfg.library.enable
                    plant.attachROMLibrary(ROMlib);
                end
                if plant.useRigidBody
                    rbHist(:,1) = localRigidStateVector(plant);
                end
                if strlength(benchmarkControlProfileName) > 0
                    cfg.sim.dt = plant.dt;
                    switch benchmarkControlProfileName
                        case "phase18c_v17a_casea_integrated_control_v1"
                            profileSource = localCaseAProfileSource( ...
                                matlab_root,beam,base,trim,plant);
                            [cfg,benchmarkMeasurement,profileDetail] = ...
                                phase18c_v17a_casea_integrated_control_v1( ...
                                cfg,profileSource);
                        case "phase18c_v17a_casea_corrected_output_retained_soc_v1"
                            cfg = localCorrectedOutputRetainedSocRequest(cfg);
                            profileSource = localCaseAProfileSource( ...
                                matlab_root,beam,base,trim,plant);
                            [cfg,benchmarkMeasurement,profileDetail] = ...
                                phase18c_v17a_casea_integrated_control_v1( ...
                                cfg,profileSource);
                            [cfg,profileDetail] = ...
                                localFinalizeCorrectedOutputRetainedSocProfile( ...
                                cfg,profileDetail, ...
                                benchmarkControlProfileName);
                        case "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1"
                            if sourceCoordinateOuterEnabled
                                if ~isfield(cfg,'outerLQR') || ...
                                        ~isstruct(cfg.outerLQR)
                                    cfg.outerLQR = struct();
                                end
                                cfg.outerLQR. ...
                                    sourceCoordinateDynamicOutputFeedback = ...
                                    sourceCoordinateOuterRequest;
                            end
                            profileSource = localCaseAProfileSource( ...
                                matlab_root,beam,base,trim,plant, ...
                                fixedBasisIntrinsicPortRequest, ...
                                structuredVirtualPitchRuntimeRequest);
                            if fixedBasisIntrinsicPortRequest.enabled
                                [plant,cfg,trim,profileSource] = ...
                                    localInstallCaseAIntrinsicPortPackage( ...
                                    plant,cfg,trim,profileSource);
                                x0 = plant.x;
                                assert(norm(x0(1:plant.nx)- ...
                                    profileSource.p5.x_eq(:),inf)==0, ...
                                    'sim_run:IntrinsicPortInitialState', ...
                                    ['The simulation initial state and ', ...
                                    'candidate equilibrium must be identical.']);
                            end
                            if reciprocalTangentAuditRequest.enabled
                                [plant,profileSource] = ...
                                    localInstallCaseAReciprocalTangent( ...
                                    plant,profileSource,matlab_root, ...
                                    reciprocalTangentAuditRequest);
                            end
                            [cfg,benchmarkMeasurement,profileDetail] = ...
                                phase18c_v17a_formal_casea_freeflight_attitude_hold_v1( ...
                                cfg,profileSource);
                            LQRConfig;
                            outerCtrl = AeroFlex.ctrl.OuterLQR(cfg,trim);
                        case "phase18c_v17a_caseb_integrated_control_v1"
                            profileSource = localCaseBProfileSource( ...
                                matlab_root,beam,base,trim,plant);
                            [cfg,benchmarkMeasurement,profileDetail] = ...
                                phase18c_v17a_caseb_integrated_control_v1( ...
                                cfg,profileSource);
                            LQRConfig;
                            outerCtrl = AeroFlex.ctrl.OuterLQR(cfg,trim);
                        case "phase18c_v17a_caseb_corrected_output_retained_soc_v1"
                            cfg = localCorrectedOutputRetainedSocRequest(cfg);
                            profileSource = localCaseBProfileSource( ...
                                matlab_root,beam,base,trim,plant);
                            [cfg,benchmarkMeasurement,profileDetail] = ...
                                phase18c_v17a_caseb_integrated_control_v1( ...
                                cfg,profileSource);
                            [cfg,profileDetail] = ...
                                localFinalizeCorrectedOutputRetainedSocProfile( ...
                                cfg,profileDetail, ...
                                benchmarkControlProfileName);
                            LQRConfig;
                            outerCtrl = AeroFlex.ctrl.OuterLQR(cfg,trim);
                        otherwise
                            error('sim_run:BenchmarkControlProfile', ...
                                'Unknown benchmark control profile: %s.', ...
                                benchmarkControlProfileName);
                    end
                    if ~isempty(fieldnames(referenceRequest))
                        % The Case-B profile installs its frozen formal
                        % provider. An explicit production custom request
                        % owns this run instead, so retain the field for
                        % rollback visibility but disable its selector.
                        cfg.outerLQR.auditReferenceProvider = ...
                            struct('enable',false);
                        cfg.outerLQR.referenceProvider = referenceRequest;
                    end
                    benchmarkControlProfile = profileDetail;
                    benchmarkControlProfile.enabled = true;
                    if isfield(structuredOuterAuditRequest, ...
                            'holdInnerAtTrim') && ...
                            logical(structuredOuterAuditRequest.holdInnerAtTrim)
                        cfg.ctrl.skipMPC = true;
                        if isfield(structuredOuterAuditRequest, ...
                                'holdEstimatorAtTrim') && ...
                                logical(structuredOuterAuditRequest. ...
                                holdEstimatorAtTrim)
                            cfg.ctrl.skipMHE = true;
                        end
                    end
                    if reciprocalTangentAuditRequest.enabled
                        benchmarkControlProfile. ...
                            reciprocalTangentRuntimeIntegration = ...
                            profileSource. ...
                            reciprocalTangentRuntimeIntegration;
                    end
                    if rigidAttitudeChiAuditRequest.enable
                        assert(body_case == "coupledfull", ...
                            'sim_run:RigidAttitudeChiAuditBodyCase', ...
                            ['The rigid-attitude chi discriminator is ', ...
                            'restricted to coupled-full execution.']);
                        switch rigidAttitudeChiAuditRequest.mode
                            case "disabled"
                                cfg.sim.packageRelativeRigidAttitudeChi.enable = false;
                                cfg.ctrl.mheKnownRigidAttitudeChi.enable = false;
                            case "plant_only"
                                cfg.sim.packageRelativeRigidAttitudeChi.enable = true;
                                cfg.ctrl.mheKnownRigidAttitudeChi.enable = false;
                            otherwise
                                error('sim_run:RigidAttitudeChiAuditMode', ...
                                    'Unsupported rigid-attitude chi audit mode.');
                        end
                        benchmarkControlProfile. ...
                            rigidAttitudeChiAuditMode = ...
                            rigidAttitudeChiAuditRequest.mode;
                        benchmarkControlProfile. ...
                            knownMheRigidAttitudeChiEnabled = ...
                            logical(cfg.ctrl. ...
                            mheKnownRigidAttitudeChi.enable);
                    end
                    if isfield(cfg.sim,'packageRelativeRigidAttitudeChi')
                        % PlantRunTime is constructed before the named
                        % benchmark profile is finalized. Transfer only
                        % this approved default-inactive request into the
                        % existing owner before the first control sample.
                        plant.cfg.sim.packageRelativeRigidAttitudeChi = ...
                            cfg.sim.packageRelativeRigidAttitudeChi;
                    end
                    if isfield(profileDetail, ...
                            'scheduleOutOfCorridorPolicy')
                        assert(string(profileDetail. ...
                            scheduleOutOfCorridorPolicy) == ...
                            "hold_last_accepted_package" && ...
                            isfield(cfg,'library') && ...
                            isfield(cfg.library, ...
                            'holdLastOnExtrapolate') && ...
                            logical(cfg.library. ...
                            holdLastOnExtrapolate), ...
                            'sim_run:BenchmarkScheduleFallback', ...
                            ['The benchmark profile requires the named ', ...
                            'hold-last scheduler fallback.']);
                        % The profile is finalized after PlantRunTime is
                        % constructed. Propagate only this approved
                        % scheduling policy into the existing plant
                        % configuration; no plant equation is changed.
                        plant.cfg.library.holdLastOnExtrapolate = true;
                    end
                    if profileDetail.physicalOutputOwnerPolicy == ...
                            "package_owned_signed_mirrored_tip"
                        signedTipSource = profileSource;
                        if isfield(profileSource, ...
                                'packageOwnedScheduleStateCoordinate')
                            signedTipSource.scheduleStateCoordinate = ...
                                profileSource.packageOwnedScheduleStateCoordinate;
                        end
                        benchmarkSignedWingtipContract = ...
                            AeroFlex.sensor.buildSignedWingtipOutput( ...
                            signedTipSource);
                    end
                    if structuredVirtualPitchRuntimeRequest.enabled
                        [structuredVirtualPitchRuntime,cfg] = ...
                            localLoadStructuredVirtualPitchRuntime( ...
                            structuredVirtualPitchRuntimeRequest, ...
                            matlab_root,cfg,profileSource,plant,trim);
                        benchmarkControlProfile.structuredVirtualPitchRuntime = ...
                            localStructuredVirtualPitchRuntimeProvenance( ...
                            structuredVirtualPitchRuntime);
                    end
                    assert(isfield(cfg,'fusion') && ...
                        isfield(cfg.fusion,'enable') && ...
                        logical(cfg.fusion.enable), ...
                        'sim_run:CaseAProfileFusion', ...
                        'The Case-A profile requires command fusion.');
                    assert(isfield(cfg,'actuator') && ...
                        isfield(cfg.actuator,'enable') && ...
                        logical(cfg.actuator.enable), ...
                        'sim_run:CaseAProfileActuator', ...
                        'The Case-A profile requires the actuator chain.');
                    % Reconstruct these stateless-at-entry owners from the
                    % qualified profile before the first control sample.
                    fuser = AeroFlex.ctrl.ComplementaryCommandFusion(cfg,trim);
                    actuator = AeroFlex.ctrl.ActuatorChain(cfg,trim);
                    if sourceCoordinateOuterEnabled
                        % A coordinated base horizon exists only when nMPC
                        % owns a fresh desired applied endpoint.  In an
                        % outer-only discriminator the inner signal stays
                        % at trim and must not recycle the preceding
                        % fusion-inverse value as a new endpoint target.
                        coordinateNmpcHorizon = ~cfg.ctrl.skipMPC;
                        assert(~priorityNmpcReference && ...
                            ~realizeNmpcEndpoint, ...
                            'sim_run:SourceCoordinateOuterCoordination', ...
                            ['The source-coordinate outer base horizon ', ...
                            'cannot coexist with a second fusion owner.']);
                    end
                    sourceCoordinateOuter = [];
                    sourceCoordinateOuterBaseline = struct();
                    sourceCoordinateOuterLatestGust = 0;
                    sourceCoordinateOuterHeldGust = 0;
                    if sourceCoordinateOuterEnabled
                        sourceSelection = cfg.outerLQR. ...
                            sourceCoordinateDynamicOutputFeedback;
                        assert(sourceSelection.enable && ...
                            sourceSelection.exactCaseAOnly && ...
                            abs(sourceSelection.design.sampleTimeSeconds- ...
                            cfg.ctrl.outerTs)<=10*eps(cfg.ctrl.outerTs), ...
                            'sim_run:SourceCoordinateOuterConfiguration', ...
                            ['The exact Case-A source-coordinate ', ...
                            'controller is not configured.']);
                        sourceCoordinateOuter = ...
                            AeroFlex.ctrl.SourceCoordinateOuterFeedback( ...
                            sourceSelection.design,plant.trimThrust);
                        sourceCoordinateOuterBaseline = struct( ...
                            'velocity',plant.rb.v_B(:), ...
                            'theta',plant.rb.euler(2));
                        benchmarkControlProfile. ...
                            sourceCoordinateDynamicOutputFeedback = struct( ...
                            'enabled',true,'defaultActive',false, ...
                            'sourceId',string(sourceSelection.sourceId), ...
                            'artifactPath',string(sourceSelection.artifactPath), ...
                            'artifactSha256',string(sourceSelection.artifactSha256), ...
                            'measurementOrder', ...
                            {sourceSelection.design.measurementOrder}, ...
                            'demandOrder',{sourceSelection.design.demandOrder});
                    end
                    if structuredVirtualPitchRuntimeRequest.enabled
                        % The formal profile finalizes fusion after the
                        % initial shared-command owner is captured.  The
                        % corrected structured runtime therefore refreshes
                        % the existing nMPC base-horizon contract here,
                        % after the final fusion/actuator owners exist.
                        assert(useOuterLQR && ~isempty(fuser) && ...
                            ~isempty(actuator), ...
                            'sim_run:PostProfileSharedCommandOwners', ...
                            ['The post-profile shared-command horizon ', ...
                            'requires active outer, fusion, and actuator ', ...
                            'owners.']);
                        attributionInnerHeld = cfg.ctrl.skipMPC && ...
                            isfield(structuredVirtualPitchRuntimeRequest, ...
                            'attributionSource') && ...
                            string(structuredVirtualPitchRuntimeRequest. ...
                            attributionSource)== ...
                            "phase18c-v17a-casea-corrected-model-rigid-residual-allocation-integration-v1";
                        assert(~cfg.ctrl.skipMPC || attributionInnerHeld, ...
                            'sim_run:PostProfileSharedCommandInnerOwner', ...
                            ['Holding nMPC at trim requires the approved ', ...
                            'corrected-model attribution contract.']);
                        coordinateNmpcHorizon = ~cfg.ctrl.skipMPC;
                        assert(~priorityNmpcReference && ...
                            ~realizeNmpcEndpoint, ...
                            'sim_run:PostProfileSharedCommandConflict', ...
                            ['The post-profile base-horizon contract is ', ...
                            'mutually exclusive with priority-reference ', ...
                            'and endpoint-realization contracts.']);
                        if attributionInnerHeld
                            sharedOwner = "inner_held_at_trim_attribution";
                        else
                            sharedOwner = "post_profile_fusion_preview";
                        end
                        benchmarkControlProfile. ...
                            structuredVirtualPitchRuntime. ...
                            sharedCommandHorizonOwner = sharedOwner;
                        benchmarkControlProfile. ...
                            structuredVirtualPitchRuntime. ...
                            coordinateNmpcHorizon = true;
                        rigidTotalHold = outerCtrl.uTrimRB(:);
                        rigidStateHold = outerCtrl.xTrim(:);
                        rigidReferenceHold = outerCtrl.xTrim(:);
                        structuredVirtualPitchReferenceHold = ...
                            outerCtrl.xTrim(:);
                        structuredVirtualPitchStateHold = ...
                            outerCtrl.xTrim(:);
                        structuredVirtualPitchPrevious.rigidTotal = ...
                            rigidTotalHold;
                        structuredVirtualPitchPrevious.rigidIncrement = ...
                            zeros(4,1);
                        structuredVirtualPitchPrevious.rbCmd = ...
                            struct('delta_e',0,'delta_a',0, ...
                            'delta_r',0,'thrust',0);
                    end
                    benchmarkMeasurementContext = ...
                        benchmarkMeasurement.linearizationAtTrim.context(:);
                end
                % LQRConfig can be invoked by a benchmark profile after
                % the initial cadence capture above.  Refresh the local
                % runtime owner only after that profile is final, so the
                % discrete gain is evaluated at its certified hold rate.
                if useOuterLQR
                    assert(isfield(cfg,'ctrl') && isfield(cfg.ctrl, ...
                        'outerEvery') && isnumeric(cfg.ctrl.outerEvery) && ...
                        isscalar(cfg.ctrl.outerEvery) && ...
                        isfinite(cfg.ctrl.outerEvery) && ...
                        cfg.ctrl.outerEvery >= 1 && ...
                        cfg.ctrl.outerEvery == round(cfg.ctrl.outerEvery), ...
                        'sim_run:OuterLqrCadenceOwner', ...
                        'The outer-LQR cadence owner must be a positive integer.');
                    assert(isfield(cfg.ctrl,'Ts') && isfield(cfg.ctrl,'outerTs') && ...
                        isnumeric(cfg.ctrl.Ts) && isnumeric(cfg.ctrl.outerTs) && ...
                        isscalar(cfg.ctrl.Ts) && isscalar(cfg.ctrl.outerTs) && ...
                        isfinite(cfg.ctrl.Ts) && isfinite(cfg.ctrl.outerTs), ...
                        'sim_run:OuterLqrCadenceTimes', ...
                        'The outer-LQR sample times must be finite scalars.');
                    outerEvery = double(cfg.ctrl.outerEvery);
                    cadenceTolerance = 32*eps(max([1,abs(cfg.ctrl.outerTs), ...
                        abs(outerEvery*cfg.ctrl.Ts)]));
                    assert(abs(outerEvery*cfg.ctrl.Ts-cfg.ctrl.outerTs) <= ...
                        cadenceTolerance, 'sim_run:OuterLqrCadenceMismatch', ...
                        ['outerEvery*cfg.ctrl.Ts must equal cfg.ctrl.outerTs ', ...
                        'after final benchmark-profile configuration.']);
                    assert(~isempty(outerCtrl) && isprop(outerCtrl,'Ts') && ...
                        isfinite(outerCtrl.Ts) && ...
                        abs(outerCtrl.Ts-cfg.ctrl.outerTs) <= cadenceTolerance, ...
                        'sim_run:OuterLqrObjectCadenceMismatch', ...
                        'OuterLQR.Ts must equal the finalized cfg.ctrl.outerTs.');
                end
                if strlength(auditMpcSolverOverride) > 0
                    assert((isfield(sharedWingDaisyChainAuditRequest,'enable') && ...
                        logical(sharedWingDaisyChainAuditRequest.enable) && ...
                        isfield(sharedWingDaisyChainAuditRequest,'auditOnly') && ...
                        logical(sharedWingDaisyChainAuditRequest.auditOnly)) || ...
                        (coupledRtiAllocatorAuditRequest. ...
                        offlineFminconComparator.enabled && ...
                        auditMpcSolverOverride=="fmincon"), ...
                        'sim_run:AuditMpcSolverOverrideScope', ...
                        ['The solver override is restricted to an explicit ', ...
                        'audit-only shared-wing request or the named ', ...
                        'baseline-relative rigid-tube fmincon comparator.']);
                    cfg.ctrl.mpcSolver = auditMpcSolverOverride;
                    benchmarkControlProfile.auditMpcSolverOverride = ...
                        auditMpcSolverOverride;
                end
                if ~isempty(fieldnames(auditMpcSqpOptionsOverride))
                    assert(isfield(sharedWingDaisyChainAuditRequest,'enable') && ...
                        logical(sharedWingDaisyChainAuditRequest.enable) && ...
                        isfield(sharedWingDaisyChainAuditRequest,'auditOnly') && ...
                        logical(sharedWingDaisyChainAuditRequest.auditOnly), ...
                        'sim_run:AuditMpcSqpOptionsScope', ...
                        ['The custom-SQP option override is restricted to an ', ...
                        'explicit audit-only shared-wing request.']);
                    allowedSqpFields = ["MaxIterations","AuditCapture", ...
                        "CollectTiming","LineSearchUpdate", ...
                        "LineSearchStrategy","UseValueOnlyMeritEvaluation", ...
                        "QpFeasibilityTolerance"];
                    overrideFields = string(fieldnames( ...
                        auditMpcSqpOptionsOverride));
                    assert(all(ismember(overrideFields,allowedSqpFields)), ...
                        'sim_run:AuditMpcSqpOptionsFields', ...
                        ['Only MaxIterations, AuditCapture, CollectTiming, ', ...
                        'LineSearchUpdate, LineSearchStrategy, ', ...
                        'UseValueOnlyMeritEvaluation, and ', ...
                        'QpFeasibilityTolerance may be overridden.']);
                    if isfield(auditMpcSqpOptionsOverride,'MaxIterations')
                        maxIterations = auditMpcSqpOptionsOverride.MaxIterations;
                        validateattributes(maxIterations,{'numeric'}, ...
                            {'scalar','integer','positive','<=',100});
                        cfg.ctrl.sqp.MaxIterations = maxIterations;
                    end
                    if isfield(auditMpcSqpOptionsOverride,'AuditCapture')
                        validateattributes(auditMpcSqpOptionsOverride. ...
                            AuditCapture,{'logical','numeric'},{'scalar'});
                        cfg.ctrl.sqp.AuditCapture = logical( ...
                            auditMpcSqpOptionsOverride.AuditCapture);
                    end
                    if isfield(auditMpcSqpOptionsOverride,'CollectTiming')
                        validateattributes(auditMpcSqpOptionsOverride. ...
                            CollectTiming,{'logical','numeric'},{'scalar'});
                        cfg.ctrl.sqp.CollectTiming = logical( ...
                            auditMpcSqpOptionsOverride.CollectTiming);
                    end
                    if isfield(auditMpcSqpOptionsOverride,'LineSearchUpdate')
                        lineSearchUpdate = lower(string( ...
                            auditMpcSqpOptionsOverride.LineSearchUpdate));
                        assert(isscalar(lineSearchUpdate) && ismember( ...
                            lineSearchUpdate,["fixed_beta", ...
                            "quadratic_safeguarded"]), ...
                            'sim_run:AuditMpcSqpLineSearchUpdate', ...
                            ['LineSearchUpdate must be fixed_beta or ', ...
                            'quadratic_safeguarded.']);
                        cfg.ctrl.sqp.LineSearchUpdate = lineSearchUpdate;
                    end
                    if isfield(auditMpcSqpOptionsOverride,'LineSearchStrategy')
                        lineSearchStrategy = lower(string( ...
                            auditMpcSqpOptionsOverride.LineSearchStrategy));
                        assert(isscalar(lineSearchStrategy) && ismember( ...
                            lineSearchStrategy,["l1_merit","filter", ...
                            "safeguarded_hybrid"]), ...
                            'sim_run:AuditMpcSqpLineSearchStrategy', ...
                            ['LineSearchStrategy must be l1_merit, filter, ', ...
                            'or safeguarded_hybrid.']);
                        cfg.ctrl.sqp.LineSearchStrategy = lineSearchStrategy;
                    end
                    if isfield(auditMpcSqpOptionsOverride, ...
                            'UseValueOnlyMeritEvaluation')
                        validateattributes(auditMpcSqpOptionsOverride. ...
                            UseValueOnlyMeritEvaluation,{'logical','numeric'}, ...
                            {'scalar'});
                        cfg.ctrl.sqp.UseValueOnlyMeritEvaluation = logical( ...
                            auditMpcSqpOptionsOverride. ...
                            UseValueOnlyMeritEvaluation);
                    end
                    if isfield(auditMpcSqpOptionsOverride, ...
                            'QpFeasibilityTolerance')
                        qpTolerance = auditMpcSqpOptionsOverride. ...
                            QpFeasibilityTolerance;
                        validateattributes(qpTolerance,{'numeric'}, ...
                            {'scalar','finite','>=',1e-11,'<=',1e-8});
                        cfg.ctrl.sqp.QPOptions = optimoptions( ...
                            cfg.ctrl.sqp.QPOptions, ...
                            'ConstraintTolerance',qpTolerance, ...
                            'OptimalityTolerance',qpTolerance, ...
                            'StepTolerance',min(1e-10,qpTolerance/10));
                    end
                    benchmarkControlProfile.auditMpcSqpOptionsOverride = ...
                        auditMpcSqpOptionsOverride;
                end
                reciprocalMheContext = struct();
                scheduledRequest = struct();
                symmetricReciprocalRequest = struct();
                if isfield(cfg.ctrl, ...
                        'scheduledReciprocalControllerModelProviderAudit')
                    scheduledRequest = cfg.ctrl. ...
                        scheduledReciprocalControllerModelProviderAudit;
                    if isfield(scheduledRequest, ...
                            'symmetricLongitudinalRuntimeDomainOwner')
                        symmetricReciprocalRequest = scheduledRequest. ...
                            symmetricLongitudinalRuntimeDomainOwner;
                    end
                end
                scheduledReciprocalRuntimeEnabled = ...
                    isstruct(scheduledRequest) && ...
                    isfield(scheduledRequest,'enabled') && ...
                    logical(scheduledRequest.enabled);
                if scheduledReciprocalRuntimeEnabled
                    assert(~reciprocalControllerModelProviderRequest.enabled && ...
                        body_case=="coupledfull" && ...
                        startsWith(benchmarkControlProfileName, ...
                        "phase18c_v17a_caseb_") && ...
                        isfield(cfg.ctrl,'mheScheduledPackageHistoryAudit') && ...
                        logical(cfg.ctrl.mheScheduledPackageHistoryAudit.enabled), ...
                        'sim_run:ScheduledReciprocalProviderScope', ...
                        ['The scheduled reciprocal runtime requires the ', ...
                        'approved Case-B profile and package history.']);
                    manifestPath = fullfile(matlab_root,'context', ...
                        'audits','phase18c-control-validation','plant', ...
                        'v17a-casebc-scheduled-reciprocal-bank-v1', ...
                        ['PHASE18C_V17A_CASEBC_SCHEDULED_QUERY_', ...
                        'RECIPROCAL_RUNTIME_BANK_V2.json']);
                    assert(isfile(manifestPath) && ...
                        localIntrinsicPortFileHash(manifestPath)== ...
                        "05f6a5ed782abf4de2a49cef9f3684c66d0a0360f8adb40b36794d15772a687d", ...
                        'sim_run:ScheduledReciprocalManifest', ...
                        ['The approved scheduled reciprocal runtime-bank ', ...
                        'manifest is unavailable or changed.']);
                    initialPackage = plant.activePredictionPackage();
                    [scheduledReciprocalPacket, ...
                        scheduledReciprocalPacketCache] = ...
                        AeroFlex.sched.buildScheduledReciprocalPacket( ...
                        initialPackage,string(manifestPath), ...
                        scheduledReciprocalPacketCache, ...
                        symmetricReciprocalRequest);
                    scheduledReciprocalPacket = ...
                        AeroFlex.sched. ...
                        applySymmetricLongitudinalReciprocalAudit( ...
                        scheduledReciprocalPacket, ...
                        symmetricReciprocalRequest);
                    plant.applyScheduledReciprocalPacket( ...
                        scheduledReciprocalPacket);
                    reciprocalSubstepCount = round( ...
                        cfg.ctrl.Ts/plant.dt);
                    reciprocalMheContext = ...
                        localReciprocalControllerIntervalContext( ...
                        plant,zeros(cfg.nu,1),rbCmd_hold, ...
                        reciprocalSubstepCount, ...
                        scheduledReciprocalPacket,initialPackage);
                    scheduledRequest.initialPacket = ...
                        scheduledReciprocalPacket;
                    scheduledRequest.initialContext = ...
                        reciprocalMheContext;
                    scheduledRequest.formulation = ...
                        "condensed_internal_memory";
                    cfg.ctrl. ...
                        scheduledReciprocalControllerModelProviderAudit = ...
                        scheduledRequest;
                    cfg.ctrl.mheColdStartStrategy = "trim";
                    if isfield(scheduledRequest,'runtimeAcceleration') && ...
                            isstruct(scheduledRequest.runtimeAcceleration) && ...
                            isscalar(scheduledRequest.runtimeAcceleration) && ...
                            isfield(scheduledRequest.runtimeAcceleration, ...
                            'enabled') && ...
                            logical(scheduledRequest. ...
                            runtimeAcceleration.enabled)
                        acceleration = scheduledRequest.runtimeAcceleration;
                        assert(all(isfield(acceleration,{ ...
                            'nmheIterationCount','nmpcIterationCount', ...
                            'compiledKernel', ...
                            'compiledEstimatorKernel', ...
                            'compiledControllerKernel'})) && ...
                            isscalar(acceleration.compiledKernel), ...
                            'sim_run:ScheduledReciprocalAcceleration', ...
                            ['The scheduled reciprocal acceleration ', ...
                            'request is incomplete.']);
                        cfg.ctrl.mheSolver = "fmincon";
                        cfg.ctrl.mpcSolver = "fmincon";
                        cfg.ctrl.condensedRtiRuntimeOwner = struct( ...
                            'enabled',true,'auditOnly',false, ...
                            'changeId', ...
                            "phase18c-v17a-condensed-rti-compiled-runtime-owner-promotion-v1", ...
                            'condensingMode',"full_state", ...
                            'chartMode',"auto_rate", ...
                            'solutionOwner',"qualified_rti", ...
                            'nmheIterationCount',double( ...
                            acceleration.nmheIterationCount), ...
                            'nmpcIterationCount',double( ...
                            acceleration.nmpcIterationCount), ...
                            'qpMode',string(safeField(acceleration, ...
                            'condensedRtiQpMode', ...
                            "configured_quadprog")), ...
                            'fallbackPolicy',"hold_previous");
                        cfg.ctrl.compiledReciprocalIntervalProvider = ...
                            struct('enabled',logical( ...
                            acceleration.compiledKernel), ...
                            'auditOnly',true, ...
                            'estimatorEnabled',logical( ...
                            acceleration.compiledEstimatorKernel), ...
                            'controllerEnabled',logical( ...
                            acceleration.compiledControllerKernel), ...
                            'changeId', ...
                            "phase18c-v17a-casebc-scheduled-compiled-interval-kernel-audit-v1", ...
                            'activeStencilSensitivityEnabled', ...
                            isfield(acceleration, ...
                            'activeStencilSensitivityEnabled') && ...
                            logical(acceleration. ...
                            activeStencilSensitivityEnabled), ...
                            'sensitivityChangeId', ...
                            "phase18c-v17a-casebc-active-stencil-scheduled-sensitivity-condensation-v1");
                    end
                    correctnessSolver = "";
                    if isfield(scheduledRequest,'correctnessSolver') && ...
                            ~isempty(scheduledRequest.correctnessSolver)
                        correctnessSolver = lower(string( ...
                            scheduledRequest.correctnessSolver));
                    end
                    assert(isscalar(correctnessSolver) && ...
                        any(correctnessSolver==["","fmincon"]), ...
                        'sim_run:ScheduledReciprocalCorrectnessSolver', ...
                        'The scheduled correctness solver is invalid.');
                    if correctnessSolver=="fmincon"
                        assert(~(isfield(scheduledRequest, ...
                            'runtimeAcceleration') && ...
                            isstruct(scheduledRequest. ...
                            runtimeAcceleration) && ...
                            isfield(scheduledRequest. ...
                            runtimeAcceleration,'enabled') && ...
                            logical(scheduledRequest. ...
                            runtimeAcceleration.enabled)), ...
                            'sim_run:ScheduledReciprocalSolverConflict', ...
                            ['The fmincon oracle and condensed RTI ', ...
                            'cannot own the same scheduled run.']);
                        cfg.ctrl.mheSolver = "fmincon";
                        cfg.ctrl.mpcSolver = "fmincon";
                    end
                    reciprocalControllerRuntimeEnabled = ~cfg.ctrl.skipMHE;
                    benchmarkControlProfile. ...
                        scheduledReciprocalRuntime = struct( ...
                        'enabled',true,'auditOnly',true, ...
                        'changeId',string(scheduledRequest.changeId), ...
                        'sourceCount',numel( ...
                        scheduledReciprocalPacket.sourceIds), ...
                        'hiddenStateCount',scheduledReciprocalPacket. ...
                        hiddenStateCount, ...
                        'fallback','native scheduled provider disabled');
                end
                if isfield(cfg,'sim') && isfield(cfg.sim, ...
                        'scheduledReciprocalPlantIntervalAudit')
                    p1PlantIntervalAuditRequest = cfg.sim. ...
                        scheduledReciprocalPlantIntervalAudit;
                    assert(isstruct(p1PlantIntervalAuditRequest) && ...
                        isscalar(p1PlantIntervalAuditRequest) && ...
                        all(isfield(p1PlantIntervalAuditRequest,{ ...
                        'enabled','auditOnly','changeId','caseId', ...
                        'expectedSubstepCount','fallbackPolicy'})), ...
                        'sim_run:P1PlantIntervalRequest', ...
                        'The P1 plant-interval request is incomplete.');
                    p1PlantIntervalAuditEnabled = logical( ...
                        p1PlantIntervalAuditRequest.enabled);
                end
                if p1PlantIntervalAuditEnabled
                    assert(logical(p1PlantIntervalAuditRequest.auditOnly) && ...
                        string(p1PlantIntervalAuditRequest.changeId)== ...
                        "phase18c-v17a-casebc-p1-plant-interval-runtime-integration-v1" && ...
                        string(p1PlantIntervalAuditRequest.caseId)== ...
                        "formal_case_b" && ...
                        double(p1PlantIntervalAuditRequest. ...
                        expectedSubstepCount)==14 && ...
                        string(p1PlantIntervalAuditRequest.fallbackPolicy)== ...
                        "exact_fourteen_stepcoupled_calls" && ...
                        scheduledReciprocalRuntimeEnabled && ...
                        reciprocalControllerRuntimeEnabled && ...
                        body_case=="coupledfull" && ...
                        startsWith(benchmarkControlProfileName, ...
                        "phase18c_v17a_caseb_"), ...
                        'sim_run:P1PlantIntervalScope', ...
                        ['P1 is restricted to the approved scheduled ', ...
                        'Case-B audit owner with exact fallback.']);
                    benchmarkControlProfile.p1PlantInterval = struct( ...
                        'enabled',true,'auditOnly',true, ...
                        'changeId',string( ...
                        p1PlantIntervalAuditRequest.changeId), ...
                        'fallback','fourteen PlantRunTime.stepCoupled calls');
                end
                if reciprocalControllerModelProviderRequest.enabled
                    assert(~cfg.ctrl.skipMHE && ...
                        cfg.library.updateMode=="frozenTrim" && ...
                        (~isfield(cfg.ctrl, ...
                        'mheScheduledPackageHistoryAudit') || ...
                        ~logical(safeField(cfg.ctrl. ...
                        mheScheduledPackageHistoryAudit, ...
                        'enabled',false))), ...
                        'sim_run:ReciprocalControllerProviderOwners', ...
                        ['The exact reciprocal nMHE provider requires ', ...
                        'active estimation and the frozen exact source.']);
                    reciprocalSubstepCount = round( ...
                        cfg.ctrl.Ts/plant.dt);
                    assert(reciprocalSubstepCount>=1 && ...
                        abs(reciprocalSubstepCount*plant.dt- ...
                        cfg.ctrl.Ts)<=100*eps(max( ...
                        [1,cfg.ctrl.Ts,plant.dt])), ...
                        'sim_run:ReciprocalControllerProviderCadence', ...
                        ['The reciprocal nMHE interval must contain an ', ...
                        'integer number of plant substeps.']);
                    reciprocalMheContext = ...
                        localReciprocalControllerIntervalContext( ...
                        plant,zeros(cfg.nu,1),rbCmd_hold, ...
                        reciprocalSubstepCount);
                    reciprocalControllerModelProviderRequest. ...
                        initialContext = reciprocalMheContext;
                    cfg.ctrl.reciprocalControllerModelProviderAudit = ...
                        reciprocalControllerModelProviderRequest;
                    acceleration = ...
                        reciprocalControllerModelProviderRequest. ...
                        runtimeAcceleration;
                    if acceleration.enabled
                        cfg.ctrl.condensedRtiRuntimeOwner = struct( ...
                            'enabled',true,'auditOnly',false, ...
                            'changeId',string(acceleration.changeId), ...
                            'condensingMode',"full_state", ...
                            'chartMode',"auto_rate", ...
                            'solutionOwner',"qualified_rti", ...
                            'nmheIterationCount',double( ...
                            acceleration.nmheIterationCount), ...
                            'nmpcIterationCount',double( ...
                            acceleration.nmpcIterationCount), ...
                            'fallbackPolicy',"hold_previous");
                        cfg.ctrl.compiledReciprocalIntervalProvider = ...
                            struct('enabled',logical( ...
                            acceleration.compiledKernel), ...
                            'auditOnly',false, ...
                            'changeId',string(acceleration.changeId));
                    end
                    % Offline correctness is the approved first solver
                    % gate for this larger, changed process model.
                    cfg.ctrl.mheColdStartStrategy = "trim";
                    cfg.ctrl.mheSolver = ...
                        reciprocalControllerModelProviderRequest.mheSolver;
                    if strlength(reciprocalControllerModelProviderRequest. ...
                            mpcSolver)>0
                        cfg.ctrl.mpcSolver = ...
                            reciprocalControllerModelProviderRequest. ...
                            mpcSolver;
                    end
                    benchmarkControlProfile. ...
                        reciprocalControllerModelProvider = struct( ...
                        'enabled',true,'auditOnly',true, ...
                        'changeId',string( ...
                        reciprocalControllerModelProviderRequest. ...
                        changeId), ...
                        'candidateSha256',string( ...
                        reciprocalControllerModelProviderRequest. ...
                        candidateSha256), ...
                        'formulation',string( ...
                        reciprocalControllerModelProviderRequest. ...
                        formulation), ...
                        'nativeStateCount',74,'latentStateCount',47, ...
                        'estimatorActivationSeconds',double( ...
                        reciprocalControllerModelProviderRequest. ...
                        estimatorActivationSeconds), ...
                        'mheSolver',string(cfg.ctrl.mheSolver), ...
                        'mpcSolver',string(cfg.ctrl.mpcSolver), ...
                        'runtimeAcceleration',acceleration, ...
                        'fallback',"native_74_state_provider_disabled");
                end
                est    = estimatorFcn(cfg, beam, aero, base, trim);
                ctrl   = controllerFcn(cfg, beam, aero, base, trim);
                if reciprocalControllerModelProviderRequest.enabled && ...
                        reciprocalControllerModelProviderRequest. ...
                        estimatorActivationSeconds > 0
                    assert(reciprocalControllerModelProviderRequest. ...
                        formulation=="condensed_internal_memory", ...
                        'sim_run:ReciprocalEstimatorActivationScope', ...
                        ['Deferred estimator activation is restricted ', ...
                        'to the condensed reciprocal audit.']);
                    xhat = trim.states(:);
                    what = zeros(cfg.ctrl.Ne*cfg.nw,1);
                    Ehe = struct('cost',0,'continuity',0,'exitflag',0, ...
                        'solveAttempted',false,'accepted',false, ...
                        'fallback',false, ...
                        'status',"deferred_preallocation");
                end
                if cfg.ctrl.skipMHE
                    xhat = trim.states(:);
                    what = zeros(cfg.ctrl.Ne*cfg.nw,1);
                    Ehe = struct('cost',nan,'continuity',0,'exitflag',1, ...
                        'constraintViolationInf',0, ...
                        'solveAttempted',false,'accepted',true, ...
                        'fallback',false,'solverUsed',"held", ...
                        'status',"held_at_trim_outer_only");
                end
                coupledRtiAllocator = [];
                if coupledRtiAllocatorAuditRequest.enabled
                    coupledRtiDaisyChainIntegration = ...
                        coupledRtiAllocatorAuditRequest. ...
                        daisyChainOuterEndpointIntegration;
                    if coupledRtiDaisyChainIntegration
                        assert(isfield(sharedWingDaisyChainAuditRequest, ...
                            'enable') && logical( ...
                            sharedWingDaisyChainAuditRequest.enable) && ...
                            isfield(sharedWingDaisyChainAuditRequest, ...
                            'auditOnly') && logical( ...
                            sharedWingDaisyChainAuditRequest.auditOnly), ...
                            'sim_run:CoupledRtiDaisyChainRequest', ...
                            ['The coupled RTI daisy-chain integration ', ...
                            'requires the explicit audit-only shared-wing ', ...
                            'request.']);
                        % The specialized request is the authoritative
                        % opt-in for its applied-endpoint coordination path.
                        coordinateNmpcHorizon = true;
                    end
                    coupledRtiOwnerContract = useRigidBody && ...
                        ~isempty(fuser) && ~isempty(actuator) && ...
                        ~priorityNmpcReference && ...
                        ((realizeNmpcEndpoint && ...
                        ~coordinateNmpcHorizon) || ...
                        (coupledRtiDaisyChainIntegration && ...
                        coordinateNmpcHorizon && ...
                        isfield(cfg.outerLQR,'sharedWingDaisyChain') && ...
                        cfg.outerLQR.sharedWingDaisyChain.enable));
                    assert(coupledRtiOwnerContract, ...
                        'sim_run:CoupledRtiAllocatorOwners', ...
                        ['Coupled RTI owner contract failed: rigid=%d ', ...
                        'fusion=%d actuator=%d priority=%d endpoint=%d ', ...
                        'coordinate=%d daisyIntegration=%d daisyCfg=%d.'], ...
                        useRigidBody,~isempty(fuser),~isempty(actuator), ...
                        priorityNmpcReference,realizeNmpcEndpoint, ...
                        coordinateNmpcHorizon, ...
                        coupledRtiDaisyChainIntegration, ...
                        isfield(cfg.outerLQR,'sharedWingDaisyChain') && ...
                        cfg.outerLQR.sharedWingDaisyChain.enable);
                    coupledRtiAllocator = ...
                        AeroFlex.ctrl.CoupledRtiAllocatorAudit( ...
                        cfg,beam,aero,base, ...
                        coupledRtiAllocatorAuditRequest);
                end
                gustRigidResponseDomainPreview = [];
                if gustRigidResponseDomainAuditRequest.enabled
                    assert(useRigidBody && ~isempty(fuser) && ~isempty(actuator), ...
                        'sim_run:GustRigidResponseDomainOwners', ...
                        ['The gust rigid-response diagnostic requires active ', ...
                        'rigid-body, fusion, and actuator owners.']);
                    previewRequest = struct('enabled',true,'auditOnly',true, ...
                        'predictionIntervals',3,'finiteDifferenceStep', ...
                        gustRigidResponseDomainAuditRequest.finiteDifferenceStep);
                    gustRigidResponseDomainPreview = ...
                        AeroFlex.ctrl.CoupledRtiAllocatorAudit( ...
                        cfg,beam,aero,base,previewRequest);
                end
                outerAllocationPreview = [];
                if realizedConstrainedOuterAllocationRequest.enabled
                    assert(useOuterLQR && ~isempty(fuser) && ~isempty(actuator), ...
                        'sim_run:RealizedOuterAllocationOwners', ...
                        ['The realized outer allocation requires active outer ', ...
                        'LQR, fusion, and actuator owners.']);
                    previewRequest = struct('enabled',true,'auditOnly',true, ...
                        'predictionIntervals',3,'finiteDifferenceStep',2.5e-3);
                    outerAllocationPreview = AeroFlex.ctrl.CoupledRtiAllocatorAudit( ...
                        cfg,beam,aero,base,previewRequest);
                end
                lexicographicSharedWingAllocator = [];
                if lexicographicSharedWingAllocationRequest.enabled
                    assert(useOuterLQR && ~isempty(fuser) && ~isempty(actuator) && ...
                        coordinateNmpcHorizon && ~priorityNmpcReference, ...
                        'sim_run:LexicographicSharedWingOwners', ...
                        ['The lexicographic allocator requires active outer ', ...
                        'LQR, fusion, actuator, and endpoint coordination ', ...
                        '(outer=%d, fusion=%d, actuator=%d, coordinate=%d, ', ...
                        'priority=%d).'],useOuterLQR,~isempty(fuser), ...
                        ~isempty(actuator),coordinateNmpcHorizon, ...
                        priorityNmpcReference);
                    lexicographicRequest = struct('enabled',true, ...
                        'auditOnly',true,'predictionIntervals',3, ...
                        'finiteDifferenceStep',2.5e-3);
                    lexicographicSharedWingAllocator = ...
                        AeroFlex.ctrl.CoupledRtiAllocatorAudit( ...
                        cfg,beam,aero,base,lexicographicRequest);
                end
                fullChannelLexicographicAllocator = [];
                if fullChannelLexicographicAllocationRequest.enabled
                    caseBSourceRootCoordination = ...
                        fullChannelLexicographicAllocationRequest. ...
                        sourceRootCondensedMultiInputCoordination;
                    packageOwnerQualified = ...
                        cfg.library.updateMode=="frozenTrim" || ...
                        (caseBSourceRootCoordination && ...
                        isfield(cfg.library,'runtimeCaseViewOwner') && ...
                        logical(cfg.library.runtimeCaseViewOwner.enabled));
                    assert(useOuterLQR && ~isempty(fuser) && ~isempty(actuator) && ...
                        coordinateNmpcHorizon && ~priorityNmpcReference && ...
                        packageOwnerQualified, ...
                        'sim_run:FullChannelLexicographicOwners', ...
                        ['The full-channel allocator requires active outer LQR, ', ...
                        'fusion, actuator, endpoint coordination, and the ', ...
                        'qualified frozen or scheduled package owner.']);
                    fullChannelRequest = struct('enabled',true, ...
                        'auditOnly',true,'predictionIntervals',10, ...
                        'finiteDifferenceStep',2.5e-3, ...
                        'fullChannelLexicographic',true, ...
                        'source',fullChannelLexicographicAllocationRequest.source, ...
