                    if caseBSourceRootCoordination
                        fullChannelRequest.coupledNmpcPredictor = ...
                            fullChannelLexicographicAllocationRequest. ...
                            coupledNmpcPredictor;
                        fullChannelRequest.futureScheduledPackageSequence = ...
                            fullChannelLexicographicAllocationRequest. ...
                            futureScheduledPackageSequence;
                        fullChannelRequest. ...
                            sourceRootCondensedMultiInputCoordination = ...
