                                trajectoryMetricSharedAllocation))
                            fullChannelRequest. ...
                                trajectoryMetricSharedAllocation = ...
                                fullChannelLexicographicAllocationRequest. ...
                                trajectoryMetricSharedAllocation;
                        end
                    end
                    if isfield(fullChannelLexicographicAllocationRequest,'debug')
                        fullChannelRequest.debug = ...
                            fullChannelLexicographicAllocationRequest.debug;
                    end
                    if isfield(fullChannelLexicographicAllocationRequest, ...
