                end
                dynamicEquilibriumRecenteringAuditRequest = ...
                    localDynamicEquilibriumRecenteringAuditRequest(cfg);
                runtimeSolverSelection = struct( ...
                    'requestedMpc',string(cfg.ctrl.mpcSolver), ...
                    'actualMpc',string(ctrl.solverName), ...
                    'requestedMhe',string(cfg.ctrl.mheSolver), ...
                    'actualMhe',string(est.solverName));
                assert(runtimeSolverSelection.requestedMpc == ...
                    runtimeSolverSelection.actualMpc && ...
                    runtimeSolverSelection.requestedMhe == ...
                    runtimeSolverSelection.actualMhe, ...
                    'sim_run:SolverSelectionMismatch', ...
                    'The instantiated solver differs from the setup solver selection.');

                xk = x0;
                uMhePreviousInterval = zeros(cfg.nu,1);
                mhePreviousReciprocalContext = reciprocalMheContext;
                uMpcPreviousEndpoint = zeros(cfg.nu,1);
                % Audit-only full-channel ownership: retain the last
                % allocator endpoint actually realized by the servo as
                % the inner nMPC input-cost reference between 25 Hz
                % outer updates.  It is intentionally distinct from the
                % previous endpoint used by nMPC rate constraints.
                fullChannelOuterEndpointReference = zeros(cfg.nu,1);
                outerAllocationPrevious = struct('uOuter',zeros(cfg.nu,1), ...
