                coupledRtiEstimatorGateLatched = false;
                coupledRtiEstimatorGateHealthyCount = 0;
                benchmarkPreviousState = xk(1:plant.nx);
                benchmarkPreviousAppliedGust = zeros(cfg.nw,1);
                mhePreviousIntervalPackage = plant.activePredictionPackage();
                dynamicEquilibriumReference = plant.trimWingControl(:);
                %======================================================================
                % Runtime / closed-loop diagnostic setup
                %======================================================================
                simWallTimer = tic;

                % Main integration setup. Rename these if your variables differ.
                dtSim     = cfg.sim.dt;
                TsCtrl    = cfg.ctrl.Ts;
                ctrlEvery = max(1, round(TsCtrl/dtSim)); % controller update interval in sim steps
                coupledPlantStepsPerControlSample = 1;
                coupledSampleTimeTolerance = ...
                    100 * eps(max([1, abs(TsCtrl), abs(plant.dt)]));
                if lower(string(body_case)) == "coupledfull"
                    coupledPlantStepsPerControlSample = round(TsCtrl/plant.dt);
                    assert(coupledPlantStepsPerControlSample >= 1 && ...
                        abs(coupledPlantStepsPerControlSample * plant.dt - TsCtrl) <= ...
                        coupledSampleTimeTolerance, ...
