                        ['The controller sample time %.16g s is not an integer ', ...
                        'multiple of the coupled plant step %.16g s.'], ...
                        TsCtrl, plant.dt);
                end
                Nsim = size(Ssim.y,1) - 1;          % because log has samples 0...Nsim
                tEnd = Nsim * dtSim;

                Ninterval = round(tEnd/TsCtrl);
                assert(Ninterval >= 1 && ...
                    abs(Ninterval*TsCtrl - tEnd) <= coupledSampleTimeTolerance, ...
                    'sim_run:ControllerDurationAlignment', ...
                    ['The requested duration %.16g s is not an integer ', ...
                    'number of controller intervals %.16g s.'], ...
                    tEnd, TsCtrl);

                % A control command owns each interval; states include both endpoints.
                Nctrl = Ninterval;
                benchmarkMeasurementContextHist = nan( ...
                    numel(benchmarkMeasurementContext),Nctrl+5);
                knownMheChiContextHist = nan(3,Nctrl+5);
                tCtrlVec = (0:Nctrl-1) * TsCtrl;
                t = (0:Nctrl) * TsCtrl;
