                uOuterRigidReferenceHist = zeros(9,Nctrl);
                uFusedRequestedHist = zeros(cfg.nu,Nctrl);
                uActuatorEndpointHist = zeros(cfg.nu,Nctrl);
                uMhePreviousIntervalHist = zeros(cfg.nu,Nctrl);
                uMpcPreviousEndpointHist = zeros(cfg.nu,Nctrl);
