                    signedWingtipHist = segmentLog.signedWingtip;
                    estimatedSignedWingtipHist = ...
                        segmentLog.estimatedSignedWingtip;
                    rbHist = segmentLog.rigidState;
                    Clamp6Hist = segmentLog.clamp6;
                    sourceRootWrenchHist = segmentLog.sourceRootWrench;
                    sourceRootLoadQualifiedHist = ...
                        segmentLog.sourceRootLoadQualified;
                    FwingHist = segmentLog.wingForce;
                    MwingHist = segmentLog.wingMoment;
                    FtotHist = segmentLog.totalForce;
                    MtotHist = segmentLog.totalMoment;
                    FgravHist = segmentLog.gravityForce;
                    FthrustHist = segmentLog.thrustForce;
                    xhat_hist = segmentLog.estimatedState;
                    Uhist = segmentLog.appliedInterval;
                    uInnerHist = segmentLog.innerRequest;
                    uMpcAppliedTargetHist = segmentLog.mpcAppliedTarget;
                    uKnownOuterBaseHist = segmentLog.knownOuterBase;
                    uMpcAppliedHorizonHist = segmentLog.mpcAppliedHorizon;
                    uKnownOuterBaseHorizonHist = ...
                        segmentLog.knownOuterBaseHorizon;
                    uOuterHist = segmentLog.outerRequest;
                    uOuterRawHist = segmentLog.outerRawRequest;
                    uOuterRigidIncrementHist = ...
                        segmentLog.outerRigidIncrement;
                    uOuterRigidTotalHist = segmentLog.outerRigidTotal;
                    uOuterRigidPositionHist = ...
                        segmentLog.outerRigidPosition;
                    uOuterRigidStateHist = segmentLog.outerRigidState;
                    uOuterRigidReferenceHist = ...
                        segmentLog.outerRigidReference;
                    uFusedRequestedHist = segmentLog.fusedRequest;
                    uActuatorEndpointHist = segmentLog.actuatorEndpoint;
                    uMhePreviousIntervalHist = ...
                        segmentLog.mhePreviousInterval;
                    uMpcPreviousEndpointHist = ...
                        segmentLog.mpcPreviousEndpoint;
                    scheduleMuHist = segmentLog.scheduleMu;
                    schedulePointIds = segmentLog.schedulePointIds;
                    wHorizon = segmentLog.disturbanceHorizon;
                    trueGust = segmentLog.trueGust;
                    estimatorTruthGust = segmentLog.estimatorTruthGust;
                    nMheMeasurementHist = segmentLog.mheMeasurement;
                    reciprocalMheCompletedContextHist = ...
                        segmentLog.reciprocalMheCompletedContext;
                    benchmarkMeasurementContextHist = ...
                        segmentLog.benchmarkMeasurementContext;
                    knownMheChiContextHist = ...
                        segmentLog.knownMheChiContext;
                    diag = segmentLog.diagnostics;
                    runtimeSegmentStartSample = ...
                        runtimeSegmentCheckpoint.completedSample+1;
                    runtimeSegmentResumed = true;
                end

                fprintf('\n');
                fprintf('======================================================================\n');
                fprintf(' SIMULATION START\n');
                fprintf('======================================================================\n');
                fprintf('  Nt              : %d samples\n', Nt);
                fprintf('  dtSim           : %.6g s\n', dtSim);
                fprintf('  TsCtrl          : %.6g s\n', TsCtrl);
                fprintf('  ctrlEvery       : %d sim steps/control update\n', ctrlEvery);
                fprintf('  coupled substeps: %d plant steps/control update\n', ...
                    coupledPlantStepsPerControlSample);
                fprintf('  MHE horizon Ne  : %d slots, tau_e = %.6g s\n', cfg.ctrl.Ne, cfg.ctrl.Ne*TsCtrl);
                fprintf('  MPC horizon Nc  : %d slots, tau_c = %.6g s\n', cfg.ctrl.Nc, cfg.ctrl.Nc*TsCtrl);
                fprintf('  nx, nu, nw      : %d, %d, %d\n', length(trim.states), cfg.nu, cfg.nw);
                fprintf('  nMHE health gate: %s\n', ternary( ...
                    nMheHealthGateAuditRequest.enabled,"audit-only enabled","disabled"));
                fprintf('----------------------------------------------------------------------\n');
                fprintf(['  %7s | %9s | %9s | %7s | %8s | %8s | %8s | %8s | %7s | %8s | %8s | %8s\n'], ...
                    'Prog[%]', 't_sim[s]', 'wall', 'RTx', ...
                    'MHE[ms]', 'MPC[ms]', 'MHEceq', 'MPCceq', ...
                    'flags', '|w|inf', '|u|inf', '|du|inf');
                fprintf('----------------------------------------------------------------------\n');

                % for k = 1:Nt
                for k = runtimeSegmentStartSample:Nctrl
                    io = AeroFlex.sim.readPlantIO_case(plant, cfg, Ssim, body_case);
                    io.rb = plant.rb;
                    t_k = io.t;
                    z_k = io.yWing;       % wing sensors for nMHE
                    yRB = io.yRB;         % rigid-body sensors for LQR, empty in wing_only
                    rb_k = io.rb;



                    % True gust from prepared profile
                    gk = gust_series( min(round(t_k/cfg.sim.dt)+1, numel(gust_series)) );
                    trueGust(k) = gk;
                    iCtrl = k;

                    t_k = tCtrlVec(iCtrl);

                    % Safe sensor index into the sim-rate sensor log.
                    iSense = round(t_k/dtSim) + 1;
                    iSense = min(max(iSense,1), size(Ssim.y,1));

                    % z_k = Ssim.y(iSense,:).';

                    % True gust, safely indexed.
                    iGust = min(max(iSense,1), numel(gust_series));
                    gk = gust_series(iGust);

                    trueGust(iCtrl) = gk;
                    estimatorTruthGust(iCtrl) = ...
                        benchmarkPreviousAppliedGust(1);
                    if benchmarkControlProfile.enabled
                        currentBenchmarkState = xk(1:plant.nx);
                        totalPreviousInput = plant.trimWingControl + ...
                            uMhePreviousInterval;
                        if benchmarkControlProfile.enabled && ...
                                benchmarkMeasurement.contextWidth > 0
                            benchmarkMeasurementContext = ...
                                localBenchmarkMeasurementContext( ...
                                benchmarkMeasurement,rb_k);
                            intervalMeasurement = ...
                                benchmarkMeasurement.measureIntervalWithContext( ...
                                benchmarkPreviousState,currentBenchmarkState, ...
                                benchmarkPreviousAppliedGust, ...
                                totalPreviousInput,TsCtrl, ...
                                benchmarkMeasurementContext);
                        else
                            intervalMeasurement = ...
                                benchmarkMeasurement.measureInterval( ...
                                benchmarkPreviousState,currentBenchmarkState, ...
                                benchmarkPreviousAppliedGust, ...
                                totalPreviousInput,TsCtrl);
                        end
                        z_k = benchmarkMeasurement.measure( ...
                            currentBenchmarkState) + intervalMeasurement;
                        assert(numel(z_k) == cfg.ny && all(isfinite(z_k)), ...
                            'sim_run:BenchmarkProfileMeasurement', ...
                            ['The benchmark physical measurement must contain ', ...
                            '%d finite values.'],cfg.ny);
                    end
                    nMheMeasurementHist(:,k) = z_k(:);
                    % ==============================================================
                    % 2. Outer rigid-body controller
                    % ==============================================================
                    isOuterUpdate = useOuterLQR && ...
                        (mod(k-1,outerEvery) == 0);
                    switch body_case
                        case "wingonly"
                            u_outer = zeros(cfg.nu,1);

                        case "coupledfull"
                            if isOuterUpdate

                                ref = localOuterAuditReference(cfg,t_k,rb_k);

                                if sourceCoordinateOuterEnabled
                                    sourceMeasurement = ...
                                        localSourceCoordinateOuterMeasurement( ...
                                        benchmarkMeasurement, ...
                                        currentBenchmarkState,rb_k, ...
                                        sourceCoordinateOuterBaseline);
                                    referencePitch = ref.euler_ref(2)- ...
                                        sourceCoordinateOuterBaseline.theta;
                                    [sourceDemand,sourceInfo] = ...
                                        sourceCoordinateOuter.update( ...
                                        sourceMeasurement,referencePitch, ...
                                        sourceCoordinateOuterLatestGust);
                                    sourceCoordinateOuterHeldGust = ...
                                        sourceCoordinateOuterLatestGust;
                                    u_outer_hold = zeros(cfg.nu,1);
                                    u_outer_hold(1:cfg.ctrl.n_surf) = ...
                                        sourceDemand(1);
                                    u_outer_raw_hold = u_outer_hold;
                                    rigidIncrement = [sourceDemand(2);0;0; ...
                                        sourceDemand(3)];
                                    assert(plant.trimThrust+rigidIncrement(4)>=0, ...
                                        'sim_run:SourceCoordinateOuterThrust', ...
                                        ['The source-coordinate outer ', ...
                                        'controller violated T >= 0.']);
                                    rbCmd_hold = struct( ...
                                        'delta_e',rigidIncrement(1), ...
                                        'delta_a',0,'delta_r',0, ...
                                        'thrust',rigidIncrement(4));
                                    rigidIncrementHold = rigidIncrement;
                                    rigidTotalHold = outerCtrl.uTrimRB(:)+ ...
                                        rigidIncrement;
                                    rigidStateHold = [rb_k.v_B(:); ...
                                        rb_k.euler(:);rb_k.omega_B(:)];
                                    sourceVelocityReference = rb_k.v_B(:);
                                    if isfield(ref,'v_B_ref') && ...
                                            ~isempty(ref.v_B_ref)
                                        sourceVelocityReference = ...
                                            ref.v_B_ref(:);
                                    end
                                    sourceRateReference = zeros(3,1);
                                    if isfield(ref,'omega_B_ref') && ...
                                            ~isempty(ref.omega_B_ref)
                                        sourceRateReference = ...
                                            ref.omega_B_ref(:);
                                    end
                                    rigidReferenceHold = [ ...
                                        sourceVelocityReference; ...
                                        ref.euler_ref(:); ...
                                        sourceRateReference];
                                    u_outer = u_outer_hold;
                                    outerInfo = struct( ...
                                        'sourceCoordinateDynamicOutputFeedback', ...
                                        sourceInfo, ...
                                        'legacyCommandDiscarded',true, ...
                                        'uRB',rigidTotalHold,'x',rigidStateHold, ...
                                        'xRef',rigidReferenceHold);
                                else
                                    realizedWingState = struct();
                                    if ~isempty(fuser) && ~isempty(actuator)
                                        realizedWingState = struct( ...
                                            'fusionOuterLP',fuser.yOuterLP(:), ...
                                            'actuatorDelta',actuator.delta(:));
                                    end
                                    if isstruct(plant.reciprocalTangentCorrection) && ...
                                            isfield(plant.reciprocalTangentCorrection, ...
                                            'scheduledQueryTrim')
                                        realizedWingState.scheduledQueryTrim = ...
                                            plant.reciprocalTangentCorrection. ...
                                            scheduledQueryTrim;
                                    end
                                    speedGuidanceEnabled = ...
                                        scheduledEquilibriumFeedforwardRequest.enable && ...
                                        isfield(scheduledEquilibriumFeedforwardRequest, ...
                                        'speedGuidance') && ...
                                        isstruct(scheduledEquilibriumFeedforwardRequest. ...
                                        speedGuidance) && ...
                                        isfield(scheduledEquilibriumFeedforwardRequest. ...
                                        speedGuidance,'enable') && ...
                                        logical(scheduledEquilibriumFeedforwardRequest. ...
                                        speedGuidance.enable);
                                    if speedGuidanceEnabled
                                        assert(scheduledReciprocalRuntimeEnabled && ...
                                            isfield(ref,'v_B_ref') && ...
                                            isfield(ref,'euler_ref'), ...
                                            'sim_run:ScheduledSpeedGuidanceScope', ...
                                            ['Virtual-speed guidance requires ', ...
                                            'the scheduled reciprocal runtime ', ...
                                            'and a complete rigid reference.']);
                                        referenceQuery = [norm(ref.v_B_ref(:)), ...
                                            rad2deg(ref.euler_ref(2))];
                                        [realizedWingState.referenceQueryTrim, ...
                                            referenceTrimInfo] = AeroFlex.ctrl. ...
                                            interpolateScheduledEquilibriumTrimAudit( ...
                                            cfg.ROMlib,referenceQuery, ...
                                            cfg.library, ...
                                            scheduledReciprocalPacketCache);
                                        realizedWingState.referenceQueryTrimInfo = ...
                                            referenceTrimInfo;
                                    end
                                    [u_outer_hold, ~, outerInfo] = ...
                                        outerCtrl.computeControl(rb_k,ref,t_k, ...
                                        realizedWingState);
                                    u_outer_raw_hold = u_outer_hold;
                                    if scheduledEquilibriumFeedforwardRequest.enable && ...
                                            isfield(outerInfo, ...
                                            'scheduledEquilibriumFeedforward') && ...
                                            logical(outerInfo. ...
                                            scheduledEquilibriumFeedforward.enabled)
                                        % The scheduled packet supplies a physical wing
                                        % equilibrium.  The active coupled actuator contract
                                        % is trim-increment based, and PlantRunTime adds the
                                        % active packet trim exactly once.
                                        assert(cfg.sim.commandsAreTrimIncrements && ...
                                            ~isempty(fuser) && ...
                                            numel(plant.trimWingControl) >= ...
                                            cfg.ctrl.n_surf, ...
                                            'sim_run:ScheduledEquilibriumWingChart', ...
                                            ['Scheduled physical wing trim requires the ', ...
                                            'active trim-increment actuator contract.']);
                                        scheduledWingPhysical = ...
                                            u_outer_hold(1:cfg.ctrl.n_surf);
                                        scheduledWingTrim = ...
                                            plant.trimWingControl(1:cfg.ctrl.n_surf);
                                        u_outer_hold(1:cfg.ctrl.n_surf) = ...
                                            scheduledWingPhysical-scheduledWingTrim;
                                        assert(all(isfinite(u_outer_hold)) && ...
                                            norm(u_outer_hold(cfg.ctrl.n_surf+1:end),inf) <= ...
                                            100*eps(1), ...
                                            'sim_run:ScheduledEquilibriumWingRateChart', ...
                                            ['Scheduled equilibrium must retain zero wing ', ...
                                            'rate coordinates before actuator realization.']);
                                        outerInfo.scheduledEquilibriumFeedforward. ...
                                            physicalWingCommand = scheduledWingPhysical;
                                        outerInfo.scheduledEquilibriumFeedforward. ...
                                            activePlantWingTrim = scheduledWingTrim;
                                        outerInfo.scheduledEquilibriumFeedforward. ...
                                            incrementWingCommand = ...
                                            u_outer_hold(1:cfg.ctrl.n_surf);
                                    end
                                    if symmetricWingAuthorityDiscriminatorAuditRequest.enabled
                                        u_outer_hold = localScaleSymmetricOuterWingReference( ...
                                            u_outer_hold,fuser, ...
                                            symmetricWingAuthorityDiscriminatorAuditRequest, ...
                                            cfg.ctrl.n_surf,cfg.ctrl.var_per);
                                        localPhaseTrace(cfg,"after_symmetric_wing_authority_scale", ...
                                            struct('timeSeconds',t_k, ...
                                            'rawOuterWingRequest', ...
                                            u_outer_raw_hold(1:cfg.ctrl.n_surf), ...
                                            'scaledOuterWingRequest', ...
                                            u_outer_hold(1:cfg.ctrl.n_surf), ...
                                            'scale',symmetricWingAuthorityDiscriminatorAuditRequest.scale));
                                    end
                                    rigidIncrement = outerInfo.uRB(:) - outerCtrl.uTrimRB(:);
                                    assert(numel(rigidIncrement) == 4 && all(isfinite(rigidIncrement)), ...
                                        'sim_run:InvalidOuterRigidIncrement', ...
                                        'Outer LQR rigid increment must contain four finite values.');
                                    assert(outerInfo.uRB(4) >= 0, ...
                                        'sim_run:NegativeOuterThrust', ...
                                        'Outer LQR produced a negative total thrust command.');
                                    rbCmd_hold = struct( ...
                                        'delta_e', rigidIncrement(1), ...
                                        'delta_a', rigidIncrement(2), ...
                                        'delta_r', rigidIncrement(3), ...
                                        'thrust', rigidIncrement(4));
                                    if isfield(ref,'scheduleUInfMps')
                                        rbCmd_hold.scheduleUInfMps = ...
                                            ref.scheduleUInfMps;
                                    end
                                    if isfield(ref,'scheduleAlphaDeg')
                                        rbCmd_hold.alphaScheduleDeg = ...
                                            ref.scheduleAlphaDeg;
                                    end
                                    rigidIncrementHold = rigidIncrement;
                                    rigidTotalHold = outerInfo.uRB(:);
                                    rigidStateHold = outerInfo.x(:);
                                    rigidReferenceHold = outerInfo.xRef(:);
                                    if isfield(outerInfo,'sharedWingDaisyChain') && ...
                                            isstruct(outerInfo.sharedWingDaisyChain)
                                        localPhaseTrace(cfg,"after_outer_lqr",struct( ...
                                            'timeSeconds',t_k,'rigidState', ...
                                            rigidStateHold,'rigidReference', ...
                                            rigidReferenceHold,'rigidIncrement', ...
                                            rigidIncrementHold,'outerWingRequest', ...
                                            u_outer_hold(:),'sharedWing', ...
                                            outerInfo.sharedWingDaisyChain));
                                    end
                                    if virtualDemandSharedSurfaceRealizationRequest.enabled
                                        assert(isfield(outerInfo,'sharedWingDaisyChain') && ...
                                            outerInfo.sharedWingDaisyChain.enabled && ...
                                            isfield(outerInfo.sharedWingDaisyChain,'commandState'), ...
                                            'sim_run:VirtualDemandSharedSurfaceOuter', ...
                                            ['The virtual-demand realization requires the ', ...
                                            'source-bound realized shared-wing outer state.']);
                                        virtualDemandContextHold = struct('valid',true, ...
                                            'zDeviation',outerInfo.sharedWingDaisyChain.commandState(:), ...
                                            'nominalCommand',[mean(u_outer_hold(1:cfg.ctrl.n_surf)); ...
                                            rbCmd_hold.delta_e;rbCmd_hold.thrust]);
                                    end
                                    if fullChannelLexicographicAllocationRequest.enabled && ...
                                            ~fullChannelTrimReferenceCaptured
                                        % Capture the actual trim-reference owner once.
                                        % Ordinary estimator/plant drift must not trigger
                                        % an expensive full allocation before a command or
                                        % declared gust disturbance exists.
                                        fullChannelTrimReference = rigidReferenceHold;
                                        fullChannelTrimReferenceCaptured = true;
                                    end
                                    u_outer = u_outer_hold;
                                    if realizedConstrainedOuterAllocationRequest.enabled
                                        assert(cfg.library.updateMode=="frozenTrim" && ...
                                            ~cfg.ctrl.skipMPC, ...
                                            'sim_run:RealizedOuterAllocationContract', ...
                                            ['The first realized outer allocation audit ', ...
                                            'requires the frozen exact package and active ', ...
                                            'controller owner.']);
                                        package = plant.activePredictionPackage();
                                        [u_outer_hold,rigidIncrement,allocationInfo] = ...
                                            localRealizedOuterAllocation( ...
                                            outerAllocationPreview,plant,package,fuser, ...
                                            actuator,ctrl,xk(1:plant.nx), ...
                                            uMhePreviousInterval,u_outer_hold, ...
                                            rigidIncrement,rigidReferenceHold,gk, ...
                                            outerAllocationPrevious);
                                        rbCmd_hold.delta_e = rigidIncrement(1);
                                        rbCmd_hold.delta_a = rigidIncrement(2);
                                        rbCmd_hold.delta_r = rigidIncrement(3);
                                        rbCmd_hold.thrust = rigidIncrement(4);
                                        rigidIncrementHold = rigidIncrement;
                                        rigidTotalHold = outerCtrl.uTrimRB(:)+rigidIncrement;
                                        u_outer = u_outer_hold;
                                        outerAllocationPrevious = struct( ...
                                            'uOuter',u_outer_hold, ...
                                            'rigidIncrement',rigidIncrement);
                                        diag.realizedOuterAllocation{iCtrl} = allocationInfo;
                                    end
                                    if structuredVirtualPitchRuntimeRequest.enabled
                                        % The legacy controller is evaluated only to recover
                                        % the current benchmark reference/state contract. Its
                                        % actuator commands are discarded before scheduling,
                                        % fusion, or plant propagation. The certified structured
                                        % law is evaluated after the current nMHE result exists.
                                        structuredVirtualPitchReferenceHold = ...
                                            outerInfo.xRef(:);
                                        structuredVirtualPitchStateHold = ...
                                            outerInfo.x(:);
                                        u_outer_hold = ...
                                            structuredVirtualPitchPrevious.uOuter;
                                        u_outer_raw_hold = u_outer_hold;
                                        rigidIncrementHold = ...
                                            structuredVirtualPitchPrevious.rigidIncrement;
                                        rigidTotalHold = ...
                                            structuredVirtualPitchPrevious.rigidTotal;
                                        rbCmd_hold = ...
                                            structuredVirtualPitchPrevious.rbCmd;
                                        rigidStateHold = ...
                                            structuredVirtualPitchStateHold;
                                        rigidReferenceHold = ...
                                            structuredVirtualPitchReferenceHold;
                                        u_outer = u_outer_hold;
                                        outerInfo.legacyCommandDiscarded = true;
                                    end
                                end
                            else
                                outerInfo = struct();
                            end
                    end

                    %======================================================================
                    % Control / estimation update
                    %======================================================================
                    % if mod(k-1,ctrlEvery) == 0

                    diag.iCtrl = diag.iCtrl + 1;
                    iCtrl = diag.iCtrl;

                    tCtrlTimer = tic;

                    % One admissible V17 package owns this complete
                    % controller interval and all coupled plant substeps.
                    localPhaseTrace(cfg, "before_prepare_control_sample", ...
                        struct('timeSeconds',t_k,'hasScheduleSpeed', ...
                        isfield(rbCmd_hold,'scheduleUInfMps'), ...
                        'hasScheduleAlpha',isfield(rbCmd_hold,'alphaScheduleDeg'), ...
                        'scheduleSpeed',safeField(rbCmd_hold, ...
                        'scheduleUInfMps',nan),'scheduleAlpha', ...
                        safeField(rbCmd_hold,'alphaScheduleDeg',nan)));
                    p1PlantIntervalPacket = struct();
                    p1PlantIntervalPacketReady = false;
                    p1PlantIntervalPacketBuildTime = 0;
                    p1PlantIntervalFallbackReason = "";
                    scheduleTimer = tic;
                    schedulePrepareTimer = tic;
                    [predictionPackage,scheduleInfo] = ...
                        plant.prepareControlSample( ...
                        gk,uMhePreviousInterval,rbCmd_hold, ...
                        coupledPlantStepsPerControlSample);
                    schedulePrepareTime = toc(schedulePrepareTimer);
                    schedulePacketBuildTime = 0;
                    schedulePacketAuditTime = 0;
                    schedulePacketInstallTime = 0;
                    if scheduledReciprocalRuntimeEnabled
                        schedulePacketBuildTimer = tic;
                        [scheduledReciprocalPacket, ...
                            scheduledReciprocalPacketCache] = ...
                            AeroFlex.sched.buildScheduledReciprocalPacket( ...
                            predictionPackage,string(manifestPath), ...
                            scheduledReciprocalPacketCache, ...
                            symmetricReciprocalRequest);
                        schedulePacketBuildTime = toc(schedulePacketBuildTimer);
                        schedulePacketAuditTimer = tic;
                        scheduledReciprocalPacket = ...
                            AeroFlex.sched. ...
                            applySymmetricLongitudinalReciprocalAudit( ...
                            scheduledReciprocalPacket, ...
                            symmetricReciprocalRequest);
                        schedulePacketAuditTime = toc(schedulePacketAuditTimer);
                        schedulePacketInstallTimer = tic;
                        plant.applyScheduledReciprocalPacket( ...
                            scheduledReciprocalPacket);
                        schedulePacketInstallTime = toc(schedulePacketInstallTimer);
                        if p1PlantIntervalAuditEnabled
                            p1PacketBuildTimer = tic;
                            try
                                p1PlantIntervalPacket = AeroFlex.sim. ...
                                    buildScheduledReciprocalPlantIntervalPacketAudit( ...
                                    plant);
                                p1PlantIntervalPacketReady = true;
                            catch p1PacketException
                                p1PlantIntervalFallbackReason = ...
                                    "packet:"+string( ...
                                    p1PacketException.identifier);
                            end
                            p1PlantIntervalPacketBuildTime = ...
                                toc(p1PacketBuildTimer);
                        end
                    end
                    scheduleModelSyncTimer = tic;
                    modelIdentity = synchronizePredictionModels( ...
                        est,ctrl,predictionPackage,cfg,plant.model, ...
                        scheduledReciprocalPacket,body_case);
                    scheduleModelSyncTime = toc(scheduleModelSyncTimer);
                    if isfield(scheduleInfo,'stateTransport') && ...
                            isstruct(scheduleInfo.stateTransport) && ...
                            isfield(scheduleInfo.stateTransport,'enabled') && ...
                            scheduleInfo.stateTransport.enabled
                        [transportInfo,benchmarkPreviousState, ...
                            benchmarkMeasurement, ...
                            benchmarkSignedWingtipContract] = ...
                            localTransportScheduledControlState( ...
                            scheduleInfo.stateTransport,predictionPackage, ...
                            cfg,est,ctrl,benchmarkPreviousState, ...
                            benchmarkMeasurement, ...
                            dynamicEquilibriumRecenteringAuditRequest);
                        xk(1:plant.nx) = plant.xFlex;
                        scheduleInfo.controlStateTransport = transportInfo;
                    end
                    equilibriumRebaseRequest = ...
                        dynamicEquilibriumRecenteringAuditRequest;
                    if isfield(scheduleInfo,'stateTransport') && ...
                            isstruct(scheduleInfo.stateTransport) && ...
                            isfield(scheduleInfo.stateTransport,'enabled') && ...
                            scheduleInfo.stateTransport.enabled
                        % The approved atomic physical-chart transition
                        % also changes the package-owned equilibrium input.
                        % Rebase every local command owner in the same
                        % transaction so the applied total endpoint is
                        % invariant across the package switch.
                        equilibriumRebaseRequest.enabled = true;
                        equilibriumRebaseRequest.auditOnly = true;
                        equilibriumRebaseRequest.origin = ...
                            "atomic_scheduled_state_transport";
                    end
                    [dynamicEquilibriumReference,uMhePreviousInterval, ...
                        uMpcPreviousEndpoint,recenterInfo] = ...
                        localRebaseDynamicEquilibriumReference( ...
                        equilibriumRebaseRequest,plant, ...
                        est,ctrl,fuser,actuator,predictionPackage, ...
                        dynamicEquilibriumReference,uMhePreviousInterval, ...
                        uMpcPreviousEndpoint);
                    scheduleTime = toc(scheduleTimer);
                    localPhaseTrace(cfg, "after_prepare_control_sample");
                    scheduleMuHist(:,iCtrl) = ...
                        scheduleInfo.activeMu(:);
                    if isfield(scheduleInfo,'scheduleMuRaw') && ...
                            numel(scheduleInfo.scheduleMuRaw)==2
                        diag.scheduleMuRaw(:,iCtrl) = ...
                            scheduleInfo.scheduleMuRaw(:);
                    end
                    if isfield(scheduleInfo,'scheduleMuFiltered') && ...
                            numel(scheduleInfo.scheduleMuFiltered)==2
                        diag.scheduleMuFiltered(:,iCtrl) = ...
                            scheduleInfo.scheduleMuFiltered(:);
                    end
                    if isfield(scheduleInfo,'requestedScheduleUInfMps') && ...
                            isscalar(scheduleInfo.requestedScheduleUInfMps)
                        diag.scheduleRequestedUInfMps(iCtrl) = ...
                            scheduleInfo.requestedScheduleUInfMps;
                    end
                    if isfield(scheduleInfo,'schedulerGate') && ...
                            isstruct(scheduleInfo.schedulerGate)
                        diag.scheduleGate{iCtrl} = scheduleInfo.schedulerGate;
                    end
                    diag.scheduleChanged(iCtrl) = scheduleInfo.scheduleChanged;
                    if isfield(plant.last,'schedLastReject')
                        diag.scheduleLastReject{iCtrl} = plant.last.schedLastReject;
                    end
                    if isfield(predictionPackage,'pointIds')
                        schedulePointIds{iCtrl} = ...
                            predictionPackage.pointIds(:).';
                    end
                    uMhePreviousIntervalHist(:,iCtrl) = ...
                        uMhePreviousInterval;
                    uMpcPreviousEndpointHist(:,iCtrl) = ...
                        uMpcPreviousEndpoint;
                    diag.dynamicEquilibriumRecenteringAttempted(iCtrl) = ...
                        recenterInfo.attempted;
                    diag.dynamicEquilibriumRecenteringAccepted(iCtrl) = ...
                        recenterInfo.accepted;
                    diag.dynamicEquilibriumReferenceChangeInf(iCtrl) = ...
                        recenterInfo.referenceChangeInfinityNorm;
                    diag.dynamicEquilibriumEndpointPreservationInf(iCtrl) = ...
                        recenterInfo.endpointPreservationInfinityNorm;
                    diag.nmpcStateTargetPreservationInf(iCtrl) = ...
                        recenterInfo.stateTargetPreservationInfinityNorm;
                    diag.nmpcInputTargetPreservationInf(iCtrl) = ...
                        recenterInfo.inputTargetPreservationInfinityNorm;
                    diag.nmpcControlTargetHeld(iCtrl) = ...
                        recenterInfo.controlTargetHeld;
                    diag.dynamicEquilibriumRecenteringReason{iCtrl} = ...
                        char(recenterInfo.reason);
                    if runtimeCheckpointAuditRequest.enabled && ...
                            any(iCtrl == runtimeCheckpointAuditRequest.sampleIndices)
                        diag.runtimeCheckpoint{iCtrl} = ...
                            localCaptureRuntimeCheckpoint( ...
                            plant,predictionPackage,scheduleInfo, ...
                            modelIdentity,scheduledReciprocalPacket, ...
                            fuser,actuator,ctrl, ...
                            uMhePreviousInterval,uMpcPreviousEndpoint, ...
                            u_outer_hold,rbCmd_hold,gk,iCtrl,t_k);
                    end

                    %--------------------------------------------------------------
                    % 1. nMHE solve
                    %--------------------------------------------------------------
                    mheTimer = tic;
                    knownMheChiContext = [];
                    if isfield(cfg.ctrl,'mheKnownRigidAttitudeChi') && ...
                            isstruct(cfg.ctrl.mheKnownRigidAttitudeChi) && ...
                            isfield(cfg.ctrl.mheKnownRigidAttitudeChi,'enable') && ...
                            logical(cfg.ctrl.mheKnownRigidAttitudeChi.enable)
                        assert(isfield(plant.last,'rigidAttitudeChiOwner') && ...
                            plant.last.rigidAttitudeChiOwner.enabled, ...
                            'sim_run:KnownRigidAttitudeChiOwner', ...
                            ['The estimator requested known chi before ', ...
                            'the plant established its physical owner.']);
                        knownMheChiContext = ...
                            plant.last.rigidAttitudeChiOwner.chiRad(:);
                        assert(numel(knownMheChiContext) == 3 && ...
                            all(isfinite(knownMheChiContext)) && ...
                            norm(knownMheChiContext([1 3]),inf) <= 1e-12, ...
                            'sim_run:KnownRigidAttitudeChiContext', ...
                            'The known chi context violates its declared scope.');
                        knownMheChiContextHist(:,iCtrl) = knownMheChiContext;
                    end

                    % Estimate
                    skipMheSolve = cfg.ctrl.skipMHE || ...
                        (dynamicEquilibriumRecenteringAuditRequest. ...
                        suppressSolvesAfterInitialization && iCtrl > 1);
                    deferReciprocalMhe = ...
                        reciprocalControllerModelProviderRequest.enabled && ...
                        reciprocalControllerModelProviderRequest. ...
                        estimatorActivationSeconds > 0 && ...
                        t_k+100*eps(max(1,t_k)) < ...
                        reciprocalControllerModelProviderRequest. ...
                        estimatorActivationSeconds;
                    if reciprocalControllerRuntimeEnabled
                        assert(~skipMheSolve && ...
                            isstruct(mhePreviousReciprocalContext) && ...
                            ~isempty(fieldnames( ...
                            mhePreviousReciprocalContext)), ...
                            'sim_run:ReciprocalControllerProviderContext', ...
                            ['The active reciprocal nMHE requires one ', ...
                            'completed causal interval at every sample.']);
                        est.setReciprocalCompletedIntervalContext( ...
                            mhePreviousReciprocalContext);
                        reciprocalMheCompletedContextHist{iCtrl} = ...
                            localReciprocalContextLogRecord( ...
                            mhePreviousReciprocalContext);
                    end
                    if ~skipMheSolve && ~deferReciprocalMhe
                        localPhaseTrace(cfg, "before_nmhe_estimate");
                        [xhat,what,Ehe] = localEstimateWithContexts( ...
                            est,z_k,uMhePreviousInterval,t_k, ...
                            benchmarkMeasurementContext, ...
                            knownMheChiContext, ...
                            mhePreviousIntervalPackage);
                        localPhaseTrace(cfg, "after_nmhe_estimate", ...
                            localSolverTracePayload(Ehe,t_k,toc(mheTimer)));
                    elseif skipMheSolve
                        if k == 1 && ~cfg.ctrl.skipMHE
                            [xhat,what,Ehe] = localEstimateWithContexts( ...
                                est,z_k,uMhePreviousInterval,t_k, ...
                                benchmarkMeasurementContext, ...
                                knownMheChiContext, ...
                                mhePreviousIntervalPackage);
                        else
                            Ehe = struct('status', ...
                                "held_at_last_estimate_outer_only", ...
                                'solveAttempted',false,'accepted',true, ...
                                'exitflag',1,'continuity',0, ...
                                'constraintViolationInf',0, ...
                                'cost',nan,'solverUsed',"held");
                        end
                    else
                        % Audit-only preallocation: retain the exact trim
                        % estimate until one contiguous horizon remains
                        % before gust onset. The latest completed context
                        % is still validated and replaces the pending one.
                        Ehe.status = "deferred_preallocation";
                    end
                    if ~isempty(benchmarkMeasurementContext)
                        benchmarkMeasurementContextHist(:,iCtrl) = ...
                            benchmarkMeasurementContext;
                    end

                    mheSolveTime = toc(mheTimer);
                    mheHealthy = localNmpcMheHealth(Ehe,xhat,what);
                    mpcSkippedByMheHealth = ...
                        nMheHealthGateAuditRequest.enabled && ~mheHealthy;

                    % The audit-only structured wing path uses the
                    % current flexible estimate and existing rigid
                    % measurement after nMHE. It cannot alter the
                    % established trim-relative rigid command boundary.
                    if useOuterLQR && isOuterUpdate && ...
                            isfield(cfg.outerLQR,'structuredOuter') && ...
                            cfg.outerLQR.structuredOuter.enable
                        [u_outer_hold, structuredOuterInfo] = ...
                            outerCtrl.computeStructuredWingIncrement( ...
                            xhat, rb_k, t_k);
                        outerInfo.structured = structuredOuterInfo;
                    end

                    if structuredVirtualPitchRuntimeRequest.enabled && ...
                            isOuterUpdate
                        [structuredCandidate,structuredInfo] = ...
                            localEvaluateStructuredVirtualPitchRuntime( ...
                            structuredVirtualPitchRuntime,xhat,mheHealthy, ...
                            plant.rb,fuser,actuator, ...
                            structuredVirtualPitchReferenceHold, ...
                            structuredVirtualPitchStateHold, ...
                            structuredVirtualPitchPrevious,outerCtrl,iCtrl,t_k);
                        structuredVirtualPitchPrevious = structuredCandidate;
                        u_outer_hold = structuredCandidate.uOuter;
                        u_outer_raw_hold = u_outer_hold;
                        rigidIncrementHold = ...
                            structuredCandidate.rigidIncrement;
                        rigidTotalHold = structuredCandidate.rigidTotal;
                        rbCmd_hold = structuredCandidate.rbCmd;
                        rigidStateHold = structuredVirtualPitchStateHold;
                        rigidReferenceHold = ...
                            structuredVirtualPitchReferenceHold;
                        u_outer = u_outer_hold;
                        diag.structuredVirtualPitchRuntime{iCtrl} = ...
                            structuredInfo;
                    end
                    if correctedModelRigidResidualAllocationRequest.enabled && ...
                            isOuterUpdate
                        correctedRigidResidualNominalHold = struct( ...
                            'valid',true, ...
                            'wing',mean(u_outer_hold(1:cfg.ctrl.n_surf)), ...
                            'elevator',rbCmd_hold.delta_e, ...
                            'thrust',rbCmd_hold.thrust);
                        assert(all(isfinite([ ...
                            correctedRigidResidualNominalHold.wing; ...
                            correctedRigidResidualNominalHold.elevator; ...
                            correctedRigidResidualNominalHold.thrust])), ...
                            'sim_run:CorrectedRigidResidualNominal', ...
                            'The held nominal physical command is nonfinite.');
                    end

                    % The estimator owns fallback and always returns its
                    % retained newest disturbance estimate.
                    wMPC = what(end-cfg.nw+1:end);
                    if sourceCoordinateOuterEnabled && mheHealthy
                        sourceCoordinateOuterLatestGust = wMPC(end);
                    end

                    if cfg.forceRealGust
                        wForMPC = gk;
                    else
                        wForMPC = wMPC;
                    end

                    coupledPreviewIntervalCount = ...
                        coupledRtiAllocatorAuditRequest.predictionIntervals;
                    if fullChannelLexicographicAllocationRequest. ...
                            sourceRootCondensedMultiInputCoordination
                        assert(~isempty(fullChannelLexicographicAllocator) && ...
                            fullChannelLexicographicAllocator.nInterval==10, ...
                            'sim_run:SourceRootGustHorizonOwner', ...
                            ['The persistent source-root coordinator ', ...
                            'requires its native ten-interval owner.']);
                        coupledPreviewIntervalCount = ...
                            fullChannelLexicographicAllocator.nInterval;
                    end
                    coupledRtiGustHorizon = repmat(wForMPC(:),1, ...
                        coupledPreviewIntervalCount);
                    if coupledRtiAllocatorAuditRequest.knownGustPreview.enabled
                        assert(benchmarkControlProfile.enabled && ...
                            benchmarkControlProfileName == ...
                            "phase18c_v17a_formal_casea_freeflight_attitude_hold_v1", ...
                            'sim_run:CoupledRtiKnownGustProfile', ...
                            ['Known gust preview is restricted to the ', ...
                            'explicit formal Case-A audit profile.']);
                        assert(cfg.nw == 1, ...
                            'sim_run:CoupledRtiKnownGustContract', ...
                            ['The formal Case-A known preview requires ', ...
                            'the declared scalar gust input.']);
                        previewTime = t_k+(0:coupledRtiAllocatorAuditRequest. ...
                            predictionIntervals-1)*TsCtrl;
                        previewIndex = min(max(round(previewTime/ ...
                            cfg.sim.dt)+1,1),numel(gust_series));
                        coupledRtiGustHorizon = reshape( ...
                            gust_series(previewIndex),1,[]);
                    end

                    coupledRtiInWindow = ...
                        coupledRtiAllocatorAuditRequest.enabled && ...
                        iCtrl >= coupledRtiAllocatorAuditRequest.startSample && ...
                        iCtrl <= coupledRtiAllocatorAuditRequest.endSample;
                    coupledRtiEstimatorGateEnabled = coupledRtiInWindow && ...
                        coupledRtiAllocatorAuditRequest. ...
                        estimatorConditionedSafetyGate;
                    coupledRtiGateGustEstimate = wMPC(end);
                    if coupledRtiEstimatorGateEnabled && ~ ...
                            coupledRtiEstimatorGateLatched
                        if mheHealthy && ...
                                abs(coupledRtiGateGustEstimate) >= ...
                                coupledRtiAllocatorAuditRequest. ...
                                gustActivationThreshold
                            coupledRtiEstimatorGateHealthyCount = ...
                                coupledRtiEstimatorGateHealthyCount+1;
                        else
                            coupledRtiEstimatorGateHealthyCount = 0;
                        end
                    end
                    if coupledRtiEstimatorGateEnabled && mheHealthy && ...
                            coupledRtiEstimatorGateHealthyCount >= ...
                            coupledRtiAllocatorAuditRequest. ...
                            minimumHealthyAboveThresholdSamples
                        coupledRtiEstimatorGateLatched = true;
                    end
                    coupledRtiSkippedByEstimatorGate = ...
                        coupledRtiEstimatorGateEnabled && ...
                        ~(mheHealthy && coupledRtiEstimatorGateLatched);
                    mpcHeldByEstimatorGate = mpcSkippedByMheHealth || ...
                        coupledRtiSkippedByEstimatorGate;

                    %--------------------------------------------------------------
                    % 2. nMPC solve
                    %--------------------------------------------------------------
                    mpcTimer = tic;
                    if coordinateNmpcHorizon || priorityNmpcReference
                        uBaseHorizon = fuser.previewOuterBaseHorizon( ...
                            u_outer_hold,ctrl.Nc);
                        assert(isequal(size(uBaseHorizon),[cfg.nu,ctrl.Nc]) && ...
                            all(isfinite(uBaseHorizon),'all'), ...
                            'sim_run:OuterBaseHorizonContract', ...
                            ['The fusion-owned nMPC base horizon must contain ', ...
                            'one finite command per prediction interval.']);
                    else
                        uBaseHorizon = [];
                    end
                    fullChannelPersistentInWindow = ...
                        ~fullChannelLexicographicAllocationRequest. ...
                        sourceRootCondensedMultiInputCoordination || ...
                        (iCtrl >= fullChannelLexicographicAllocationRequest. ...
                        persistentSampleWindow(1) && ...
                        iCtrl <= fullChannelLexicographicAllocationRequest. ...
                        persistentSampleWindow(2));
                    if fullChannelLexicographicAllocationRequest.enabled && ...
                            fullChannelPersistentInWindow
                        assert(isequal(size(fullChannelOuterEndpointReference), ...
                            [cfg.nu,1]) && all(isfinite( ...
                            fullChannelOuterEndpointReference)), ...
                            'sim_run:FullChannelReferenceEndpoint', ...
                            ['The full-channel inner reference must be the ', ...
                            'finite realized servo endpoint.']);
                        uBaseHorizon = repmat( ...
                            fullChannelOuterEndpointReference,1,ctrl.Nc);
                    end
                    if priorityNmpcReference
                        priorityCostTolerance = 1e-12;
                        if isfield(structuredOuterAuditRequest, ...
                                'priorityNmpcPrimaryCostTolerance')
                            priorityCostTolerance = structuredOuterAuditRequest. ...
                                priorityNmpcPrimaryCostTolerance;
                        end
                        validateattributes(priorityCostTolerance,{'numeric'}, ...
                            {'scalar','real','finite','nonnegative'});
                        priorityReference = struct('enabled',true, ...
                            'auditOnly',true, ...
                            'referenceHorizon',uBaseHorizon, ...
                            'primaryCostTolerance',priorityCostTolerance);
                    else
                        priorityReference = struct('enabled',false);
                    end
                    if structuredVirtualPitchRuntimeRequest.enabled && ...
                            ~cfg.ctrl.skipMPC
                        assert(coordinateNmpcHorizon && ...
                            isequal(size(uBaseHorizon),[cfg.nu,ctrl.Nc]) && ...
                            all(isfinite(uBaseHorizon),'all'), ...
                            'sim_run:PostProfileSharedCommandHorizon', ...
                            ['The corrected structured runtime requires ', ...
                            'one finite fusion-owned base command per ', ...
                            'nMPC horizon interval.']);
                    end
                    if reciprocalControllerRuntimeEnabled && ...
                            ~cfg.ctrl.skipMPC
                        assert(string( ...
                            reciprocalControllerModelProviderRequest. ...
                            futureRigidPolicy)=="held_measured", ...
                            'sim_run:ReciprocalNmpcFutureRigidPolicy', ...
                            'The active reciprocal nMPC policy changed.');
                        reciprocalNmpcLatent = ...
                            est.reciprocalInternalMemoryEndpoint();
                        reciprocalNmpcFutureContext = ...
                            localReciprocalControllerFutureContextHorizon( ...
                            plant,rbCmd_hold,ctrl.Nc, ...
                            coupledPlantStepsPerControlSample, ...
                            scheduledReciprocalPacket, ...
                            predictionPackage);
                        ctrl.setReciprocalPredictionContext( ...
                            reciprocalNmpcLatent, ...
                            reciprocalNmpcFutureContext);
                    end
                    if cfg.ctrl.skipMPC
                        if sourceCoordinateOuterEnabled
                            assert(~coordinateNmpcHorizon, ...
                                'sim_run:SourceCoordinateOuterOnlyCoordination', ...
                                ['An outer-only source-coordinate member ', ...
                                'must not activate nMPC endpoint coordination.']);
                        end
                        u_inner = fuser.uTrim;
                        Uinfo = struct('accepted',false,'solveAttempted',false, ...
                            'exitflag',0,'flag',0,'continuity',0, ...
                            'constraintViolationInf',0, ...
                            'status',"held_at_trim_outer_only");
                    elseif mpcHeldByEstimatorGate
                        [u_inner,Uinfo] = localNmpcMheHealthHold( ...
                            uMpcPreviousEndpoint,cfg.ctrl.n_surf);
                        if coupledRtiSkippedByEstimatorGate
                            Uinfo.status = ...
                                "skipped_estimator_conditioned_rti_gate";
                        end
                    elseif coupledRtiInWindow && ~ ...
                            coupledRtiAllocatorAuditRequest. ...
                            dynamicNullspaceWingOnly
                        assert(~isempty(coupledRtiAllocator), ...
                            'sim_run:CoupledRtiAllocator', ...
                            'The coupled RTI audit owner is unavailable.');
                        coupledFlexibleInitialState = xhat;
                        if coupledRtiAllocatorAuditRequest. ...
                                usePlantFlexibleStateOracle
                            coupledFlexibleInitialState = plant.xFlex;
                            diag.coupledRtiPlantStateOracle(iCtrl) = true;
                        elseif coupledRtiAllocatorAuditRequest. ...
                                usePlantChiStateOracle
                            coupledFlexibleInitialState(plant.idx.chi) = ...
                                plant.xFlex(plant.idx.chi);
                            diag.coupledRtiPlantChiStateOracle(iCtrl) = true;
                        end
                        [u_inner,Uinfo] = coupledRtiAllocator.compute( ...
                            plant,predictionPackage,fuser,actuator,ctrl, ...
                            coupledFlexibleInitialState, ...
                            uMpcPreviousEndpoint,u_outer_hold, ...
                            rbCmd_hold,rigidReferenceHold, ...
                            coupledRtiGustHorizon,t_k);
                        diag.coupledRtiActive(iCtrl) = true;
                        if coupledRtiAllocatorAuditRequest. ...
                                usePlantFlexibleStateOracle
                            flexibleStateOwner = "plant-state-oracle";
                        elseif coupledRtiAllocatorAuditRequest. ...
                                usePlantChiStateOracle
                            flexibleStateOwner = "nmhe-with-plant-chi-oracle";
                        else
                            flexibleStateOwner = "nmhe-estimate";
                        end
                        Uinfo.output.auditCapture.flexibleStateOwner = ...
                            flexibleStateOwner;
                        Uinfo.output.auditCapture.gustHorizonOwner = ...
                            coupledRtiAllocatorAuditRequest. ...
                            knownGustPreview.source;
                    elseif ~(cfg.ctrl.skipMPC || ...
                            (dynamicEquilibriumRecenteringAuditRequest. ...
                            suppressSolvesAfterInitialization && iCtrl > 1))
                        localCaseBInnerFixedPointTrace(cfg,plant,ctrl,est, ...
                            xhat,wForMPC,iCtrl,t_k);
                        localPhaseTrace(cfg, "before_nmpc_compute_control", ...
                            struct('timeSeconds',t_k,'xhatTrimInf', ...
                            norm(xhat-ctrl.xTrim,inf),'trimStateInf', ...
                            norm(trim.states,inf),'controllerTrimVsRunTrimInf', ...
                            norm(ctrl.xTrim-trim.states,inf),'gustInf', ...
                            norm(wForMPC,inf),'previousEndpointInf', ...
                            norm(uMpcPreviousEndpoint,inf),'baseHorizonInf', ...
                            norm(uBaseHorizon,inf),'scheduleUInfMps', ...
                            scheduleMuHist(1,iCtrl),'scheduleAlphaDeg', ...
                            scheduleMuHist(2,iCtrl), ...
                            'coordinateNmpcHorizon', ...
                            coordinateNmpcHorizon,'outerHoldInf', ...
                            norm(u_outer_hold,inf), ...
                            'fusionOuterLowPassInf', ...
                            localFusionOuterLowPassInf(fuser), ...
                            'baseHorizonFirstInf', ...
                            localFirstColumnNorm(uBaseHorizon)));
                        [u_inner, Uinfo] = ctrl.computeControl( ...
                            xhat,wForMPC,uMpcPreviousEndpoint,t_k, ...
                            uBaseHorizon,priorityReference);
                        localCaseBPostNmpcSourceDomainTrace( ...
                            cfg,ctrl,xhat,wForMPC,Uinfo,iCtrl,t_k);
                        if structuredVirtualPitchRuntimeRequest.enabled
                            assert(isfield(Uinfo,'uBaseHorizon') && ...
                                isequal(size(Uinfo.uBaseHorizon), ...
                                size(uBaseHorizon)) && ...
                                norm(Uinfo.uBaseHorizon- ...
                                uBaseHorizon,inf)==0, ...
                                'sim_run:PostProfileSharedCommandPassThrough', ...
                                ['The nMPC-reported base horizon differs ', ...
                                'from the fusion preview passed to it.']);
                        end
                        localPhaseTrace(cfg, "after_nmpc_compute_control", ...
                            localNmpcTracePayload(Uinfo,t_k,toc(mpcTimer)));
                    else
                        if k == 1 % Need to init the vals
                            [u_inner, Uinfo] = ctrl.computeControl( ...
                                xhat,wForMPC,uMpcPreviousEndpoint,t_k, ...
                                uBaseHorizon,priorityReference);
                        end
                    end

                    mpcSolveTime = toc(mpcTimer);
                    uMpcAppliedTarget = u_inner;
                    if virtualDemandSharedSurfaceRealizationRequest.enabled && ...
                            isOuterUpdate && virtualDemandContextHold.valid
                        nmpcAcceptedForRealization = logical(safeField( ...
                            Uinfo,'accepted',safeField(Uinfo,'exitflag',-1)>0));
                        if nmpcAcceptedForRealization
                            nSurface = cfg.ctrl.n_surf;
                            assert(numel(uMpcAppliedTarget)>=nSurface && ...
                                all(isfinite(uMpcAppliedTarget(1:nSurface)),"all"), ...
                                'sim_run:VirtualDemandSharedSurfaceNmpc', ...
                                'The accepted nMPC endpoint lacks a finite wing target.');
                            wingRealized = mean(uMpcAppliedTarget(1:nSurface));
                            bounds = struct('elevatorLower',-deg2rad(10), ...
                                'elevatorUpper',deg2rad(10), ...
                                'thrustLower',-double(trim.thrust), ...
                                'thrustUpper',0.5,'trimThrust',double(trim.thrust));
                            virtualDemandRealizationHold = ...
                                AeroFlex.ctrl.realizeVirtualDemandAudit( ...
                                virtualDemandModel, ...
                                virtualDemandContextHold.zDeviation, ...
                                virtualDemandContextHold.nominalCommand, ...
                                wingRealized,bounds);
                            assert(virtualDemandRealizationHold. ...
                                totalThrustLowerSatisfied, ...
                                'sim_run:VirtualDemandSharedSurfaceThrust', ...
                                'The virtual-demand realization would violate T >= 0.');
                            rbCmd_hold.delta_e = virtualDemandRealizationHold. ...
                                realizedCommand(2);
                            rbCmd_hold.thrust = virtualDemandRealizationHold. ...
                                realizedCommand(3);
                            rigidIncrementHold(1) = rbCmd_hold.delta_e;
                            rigidIncrementHold(4) = rbCmd_hold.thrust;
                            rigidTotalHold = outerCtrl.uTrimRB(:)+rigidIncrementHold;
                        else
                            virtualDemandRealizationHold = struct( ...
                                'accepted',false,'reason', ...
                                "nmpc_candidate_unavailable");
                        end
                        diag.virtualDemandSharedSurfaceRealization{iCtrl} = ...
                            virtualDemandRealizationHold;
                    end
                    if coupledRtiInWindow && ...
                            coupledRtiAllocatorAuditRequest. ...
                            dynamicNullspaceWingOnly
                        assert(~isempty(coupledRtiAllocator), ...
                            'sim_run:DynamicNullspaceAllocator', ...
                            'The baseline-relative rigid-tube allocator is unavailable.');
                        nmpcAcceptedForAllocation = logical(safeField( ...
                            Uinfo,'accepted',safeField(Uinfo,'exitflag',-1)>0));
                        if nmpcAcceptedForAllocation && ...
                                isfield(Uinfo,'uHorizon') && ...
                                size(Uinfo.uHorizon,1)==cfg.nu && ...
                                ~isempty(Uinfo.uHorizon) && ...
                                all(isfinite(Uinfo.uHorizon),"all")
                            nmpcCandidateHorizon = Uinfo.uHorizon;
                            candidateColumns = size(nmpcCandidateHorizon,2);
                            if candidateColumns < ...
                                    coupledRtiAllocatorAuditRequest. ...
                                    predictionIntervals
                                % The native nMPC horizon is shorter than
                                % the allocation preview.  Preserve every
                                % optimized node and hold its terminal
                                % command for the extra preview nodes.
                                nmpcCandidateHorizon = [ ...
                                    nmpcCandidateHorizon,repmat( ...
                                    nmpcCandidateHorizon(:,end),1, ...
                                    coupledRtiAllocatorAuditRequest. ...
                                    predictionIntervals-candidateColumns)];
                            end
                            [uMpcAppliedTarget,dynamicNullspaceInfo] = ...
                                coupledRtiAllocator.computeDynamicNullspaceWing( ...
                                plant,predictionPackage,fuser,actuator,ctrl,xhat, ...
                                uMpcPreviousEndpoint,u_outer_hold,rbCmd_hold, ...
                                rigidReferenceHold,coupledRtiGustHorizon,t_k, ...
                                nmpcCandidateHorizon);
                            dynamicNullspaceInfo.output.auditCapture. ...
                                nativeNmpcHorizonColumns = candidateColumns;
                            u_inner = uMpcAppliedTarget;
                        else
                            uMpcAppliedTarget = uMpcPreviousEndpoint;
                            u_inner = uMpcAppliedTarget;
                            dynamicNullspaceInfo = struct('accepted',false, ...
                                'solveAttempted',false,'exitflag',0, ...
                                'output',struct('auditCapture',struct( ...
                                'schemaVersion', ...
                                'phase18c-v17a-casea-baseline-relative-rigid-tube-formal-integration-audit-v1', ...
                                'fallbackWingOnly',true, ...
                                'reason','nmpc_candidate_unavailable')));
                        end
                        Uinfo.output.dynamicNullspaceWingAllocation = ...
                            dynamicNullspaceInfo;
                        diag.dynamicNullspaceWingAllocation{iCtrl} = ...
                            dynamicNullspaceInfo;
                        diag.coupledRtiActive(iCtrl) = true;
                    end
                    if lexicographicSharedWingAllocationRequest.enabled
                        assert(~isempty(lexicographicSharedWingAllocator), ...
                            'sim_run:LexicographicSharedWingAllocator', ...
                            'The lexicographic shared-wing owner is unavailable.');
                        nmpcAcceptedForAllocation = logical(safeField( ...
                            Uinfo,'accepted',safeField(Uinfo,'exitflag',-1)>0));
                        if nmpcAcceptedForAllocation && ...
                                isfield(Uinfo,'uHorizon') && ...
                                all(isfinite(Uinfo.uHorizon(:,1:min(3, ...
                                size(Uinfo.uHorizon,2)))),"all")
                            [uMpcAppliedTarget,lexicographicInfo] = ...
                                lexicographicSharedWingAllocator. ...
                                computeLexicographic(plant,predictionPackage, ...
                                fuser,actuator,ctrl,xhat, ...
                                uMpcPreviousEndpoint,u_outer_hold, ...
                                rbCmd_hold,rigidReferenceHold, ...
                                coupledRtiGustHorizon,t_k,Uinfo.uHorizon);
                            u_inner = uMpcAppliedTarget;
                        else
                            uMpcAppliedTarget = uMpcPreviousEndpoint;
                            u_inner = uMpcAppliedTarget;
                            lexicographicInfo = struct('accepted',false, ...
                                'solveAttempted',false,'exitflag',0, ...
                                'output',struct('auditCapture',struct( ...
                                'schemaVersion', ...
                                'phase18c-v17a-lexicographic-shared-wing-allocation-v1', ...
                                'fallbackWingOnly',true, ...
                                'reason','nmpc_candidate_unavailable')));
                        end
                        Uinfo.output.lexicographicSharedWingAllocation = ...
                            lexicographicInfo;
                        diag.lexicographicSharedWingAllocation{iCtrl} = ...
                            lexicographicInfo;
                    end
                    if fullChannelLexicographicAllocationRequest.enabled
                        assert(~isempty(fullChannelLexicographicAllocator), ...
                            'sim_run:FullChannelLexicographicAllocator', ...
                            'The full-channel lexicographic owner is unavailable.');
                        nmpcAcceptedForAllocation = logical(safeField( ...
                            Uinfo,'accepted',safeField(Uinfo,'exitflag',-1)>0));
                        fullChannelReferenceDeparture = norm( ...
                            rigidReferenceHold-fullChannelTrimReference,inf);
                        % The full-channel allocator owns a declared
                        % finite-horizon Case-A gust preview.  It must arm
                        % before the instantaneous gust changes the plant:
                        % waiting for gk to become nonzero can make the
                        % nominal trajectory violate its clamp limits
                        % before the first constrained correction is
                        % attempted.  This consumes the same fixed
                        % gust_series values subsequently passed to the
                        % allocator; it does not introduce a new truth or
                        % measurement path.
                        fullChannelConstraintPreviewCount = ...
                            fullChannelLexicographicAllocator. ...
                            fullChannelPreviewIntervalCount;
                        % Activation belongs to the ten-interval decision
                        % horizon.  An optional feasibility tail may extend
                        % the constraint/replay horizon, but must not make
                        % the allocator act before the decision horizon
                        % contains a departure.
                        fullChannelActivationPreviewCount = ...
                            fullChannelLexicographicAllocator.nInterval;
                        % Case A retains the outer-command cadence.  The
                        % Case-B source-root discriminator is the native
                        % nMPC horizon and therefore advances at Ts.
                        fullChannelPreviewIntervalSeconds = cfg.ctrl.outerTs;
                        if fullChannelLexicographicAllocationRequest. ...
                                sourceRootCondensedMultiInputCoordination
                            fullChannelPreviewIntervalSeconds = cfg.ctrl.Ts;
                        end
                        fullChannelActivationPreviewTime = t_k + ...
                            (0:fullChannelActivationPreviewCount-1)* ...
                            fullChannelPreviewIntervalSeconds;
                        fullChannelActivationPreviewIndex = min(max(round( ...
                            fullChannelActivationPreviewTime/cfg.sim.dt)+1,1), ...
                            numel(gust_series));
                        fullChannelGustActive = norm( ...
                            gust_series(fullChannelActivationPreviewIndex),inf) > 1e-8;
                        if fullChannelLexicographicAllocationRequest. ...
                                sourceRootCondensedMultiInputCoordination
                            fullChannelGustActive = ...
                                norm(coupledRtiGustHorizon,inf)>1e-8;
                        end
                        fullChannelPredictiveRisk = struct('available',false, ...
                            'active',false,'minimumUnscaledSlack',nan, ...
                            'minimumUnscaledSlackLabel',"",'checks',struct());
                        fullChannelActivationRisk = fullChannelGustActive;
                        if fullChannelLexicographicAllocationRequest. ...
                                predictiveFeasibilityActivation.enabled && ...
                                isOuterUpdate && fullChannelGustActive && ...
                                nmpcAcceptedForAllocation && ...
                                isfield(Uinfo,'uHorizon') && ...
                                size(Uinfo.uHorizon,1)==cfg.nu && ...
                                all(isfinite(Uinfo.uHorizon),"all")
                            previewTime = t_k+(0:fullChannelConstraintPreviewCount-1)* ...
                                cfg.ctrl.outerTs;
                            previewIndex = min(max(round(previewTime/ ...
                                cfg.sim.dt)+1,1),numel(gust_series));
                            gustPreview = reshape(double(gust_series(previewIndex)), ...
                                1,[]);
                            fullChannelPredictiveRisk = ...
                                fullChannelLexicographicAllocator. ...
                                predictFullChannelHardConstraintRisk(plant, ...
                                predictionPackage,fuser,actuator,ctrl,xhat, ...
                                uMpcPreviousEndpoint,u_outer_hold,rbCmd_hold, ...
                                rigidReferenceHold,gustPreview,t_k,Uinfo.uHorizon);
                            fullChannelActivationRisk = ...
                                fullChannelPredictiveRisk.active;
                        end
                        fullChannelDeparture = max(fullChannelReferenceDeparture, ...
                            double(fullChannelActivationRisk));
                        if fullChannelLexicographicAllocationRequest. ...
                                sourceRootCondensedMultiInputCoordination && ...
                                fullChannelPersistentInWindow
                            fullChannelDeparture = max(fullChannelDeparture,1);
                        end
                        % The full-channel correction owns the same 25 Hz
                        % command frame as the outer reference.  nMPC still
                        % runs at every inner sample; accepted full endpoints
                        % are held between outer updates.
                        fullChannelActive = fullChannelTrimReferenceCaptured && ...
                            fullChannelDeparture > 1e-8 && isOuterUpdate;
                        if fullChannelLexicographicAllocationRequest. ...
                                sourceRootCondensedMultiInputCoordination
                            fullChannelActive = fullChannelTrimReferenceCaptured && ...
                                fullChannelPersistentInWindow;
                        end
                        if ~fullChannelActive
                            fullChannelAwaitingOuterUpdate = ...
                                fullChannelDeparture > 1e-8;
                            fullInfo = struct('accepted',true, ...
                                'solveAttempted',false,'exitflag',1, ...
                                'output',struct('auditCapture',struct( ...
                                'schemaVersion', ...
                                'phase18c-v17a-casea-full-channel-lexicographic-trajectory-allocation-v1', ...
                                'equilibriumHold',~fullChannelAwaitingOuterUpdate, ...
                                'holdReason',string( ...
                                ternary(fullChannelAwaitingOuterUpdate, ...
                                'awaiting_outer_update','equilibrium')), ...
                                'departureInfinity',fullChannelDeparture, ...
                                'referenceDepartureInfinity', ...
                                fullChannelReferenceDeparture, ...
                                'gustActive',fullChannelGustActive, ...
                                'predictiveRisk',fullChannelPredictiveRisk)));
                        elseif nmpcAcceptedForAllocation && ...
                                fullChannelFeasibilityTailAllocatorCalls < ...
                                min(fullChannelLexicographicAllocator. ...
                                fullChannelFeasibilityTailMaximumAllocatorCalls, ...
                                fullChannelLexicographicAllocator. ...
                                fullChannelMaximumAllocatorCalls) && ...
                                isfield(Uinfo,'uHorizon') && ...
                                size(Uinfo.uHorizon,1)==cfg.nu && ...
                                all(isfinite(Uinfo.uHorizon),"all")
                            previewCount = fullChannelConstraintPreviewCount;
                            previewTime = t_k+(0:previewCount-1)* ...
                                fullChannelPreviewIntervalSeconds;
                            previewIndex = min(max(round(previewTime/ ...
                                cfg.sim.dt)+1,1),numel(gust_series));
                            gustPreview = reshape(double(gust_series(previewIndex)), ...
                                1,[]);
                            if fullChannelLexicographicAllocationRequest. ...
                                    sourceRootCondensedMultiInputCoordination
                                gustPreview = coupledRtiGustHorizon(:,1:previewCount);
                            end
                            assert(isequal(size(gustPreview), ...
                                [cfg.nw,previewCount]) && ...
                                all(isfinite(gustPreview),"all"), ...
                                'sim_run:FullChannelGustPreview', ...
                                'The full-channel gust preview is invalid.');
                            nativeNmpcTarget = uMpcAppliedTarget;
                            [uMpcAppliedTarget,fullRigidCommand,fullInfo, ...
                                governedOuterReference,governedInnerTarget] = ...
                                fullChannelLexicographicAllocator. ...
                                computeFullChannelLexicographic(plant, ...
                                predictionPackage,fuser,actuator,ctrl,xhat, ...
                                uMpcPreviousEndpoint,u_outer_hold,rbCmd_hold, ...
                                rigidReferenceHold,gustPreview,t_k,Uinfo.uHorizon);
                            % A transparent nominal-safe preview is not an
                            % optimizer attempt.  The bounded snapshot study
                            % consumes its single call only when the allocator
                            % actually enters a constrained solve.
                            if logical(safeField(fullInfo,"solveAttempted",false))
                                fullChannelFeasibilityTailAllocatorCalls = ...
                                    fullChannelFeasibilityTailAllocatorCalls + 1;
                            end
                            if fullChannelLexicographicAllocationRequest. ...
                                    nonlinearOuterReferenceGovernor
                                % Governor ownership is the nominal outer reference;
                                % retain nMPC's independently solved inner command.
                                u_outer_hold = governedOuterReference;
                                uMpcAppliedTarget = nativeNmpcTarget;
                            end
                            if fullChannelLexicographicAllocationRequest. ...
                                    jointSharedSurfaceSafetyCoordination
                                % The joint coordinator owns the single applied
                                % endpoint passed through the existing fusion
                                % inverse/forward path; it is not a direct servo
                                % bypass or a second actuator command.
                                u_outer_hold = governedOuterReference;
                                uMpcAppliedTarget = governedInnerTarget;
                            end
                            u_inner = uMpcAppliedTarget;
                            rbCmd_hold = fullRigidCommand;
                            rigidIncrementHold = [rbCmd_hold.delta_e; ...
                                rbCmd_hold.delta_a;rbCmd_hold.delta_r; ...
                                rbCmd_hold.thrust];
                            rigidTotalHold = outerCtrl.uTrimRB(:)+rigidIncrementHold;
                        elseif fullChannelActive && ...
                                fullChannelFeasibilityTailAllocatorCalls >= ...
                                min(fullChannelLexicographicAllocator. ...
                                fullChannelFeasibilityTailMaximumAllocatorCalls, ...
                                fullChannelLexicographicAllocator. ...
                                fullChannelMaximumAllocatorCalls)
                            uMpcAppliedTarget = uMpcPreviousEndpoint;
                            u_inner = uMpcAppliedTarget;
                            fullInfo = struct('accepted',true, ...
                                'solveAttempted',false,'exitflag',1, ...
                                'output',struct('auditCapture',struct( ...
                                'schemaVersion', ...
                                'phase18c-v17a-casea-full-channel-feasibility-tail-audit-v1', ...
                                'allocatorCallLimitReached',true, ...
                                'allocatorCalls', ...
                                fullChannelFeasibilityTailAllocatorCalls)));
                        else
                            uMpcAppliedTarget = uMpcPreviousEndpoint;
                            u_inner = uMpcAppliedTarget;
                            fullInfo = struct('accepted',false, ...
                                'solveAttempted',false,'exitflag',0, ...
                                'output',struct('auditCapture',struct( ...
                                'schemaVersion', ...
                                'phase18c-v17a-casea-full-channel-lexicographic-trajectory-allocation-v1', ...
                                'fallbackFullEndpoint',true, ...
                                'reason','nmpc_candidate_unavailable')));
                        end
                        Uinfo.output.fullChannelLexicographicAllocation = fullInfo;
                        diag.fullChannelLexicographicAllocation{iCtrl} = fullInfo;
                    end
                    if isempty(uBaseHorizon)
                        uKnownOuterBase = zeros(cfg.nu,1);
                    else
                        uKnownOuterBase = uBaseHorizon(:,1);
                    end

                    %--------------------------------------------------------------
                    % 3. Store diagnostics
                    %--------------------------------------------------------------
                    diag.tCtrl(iCtrl)         = t_k;
                    diag.mheTime(iCtrl)       = mheSolveTime;
                    diag.mhePreparationUsed(iCtrl) = logical(safeField( ...
                        safeField(Ehe,'preparation',struct()),'used',false));
                    diag.mhePreparationDiscarded(iCtrl) = logical(safeField( ...
                        safeField(Ehe,'preparation',struct()),'discarded',false));
                    diag.mpcTime(iCtrl)       = mpcSolveTime;
                    diag.scheduleTime(iCtrl)  = scheduleTime;
                    if scheduleTimingTraceEnabled
                        diag.schedulePrepareTime(iCtrl) = schedulePrepareTime;
                        diag.schedulePacketBuildTime(iCtrl) = ...
                            schedulePacketBuildTime;
                        diag.schedulePacketAuditTime(iCtrl) = ...
                            schedulePacketAuditTime;
                        diag.schedulePacketInstallTime(iCtrl) = ...
                            schedulePacketInstallTime;
                        diag.scheduleModelSyncTime(iCtrl) = ...
                            scheduleModelSyncTime;
                    end
                    diag.modelLRelativeError(:,iCtrl) = ...
                        modelIdentity.lRelativeError(:);
                    diag.modelParConstMatch(:,iCtrl) = ...
                        modelIdentity.parConstMatch(:);

                    diag.mheCost(iCtrl)       = safeField(Ehe,'cost',nan);
                    diag.mpcCost(iCtrl)       = safeField(Uinfo,'cost',nan);
                    diag.mpcTerminalSetValue(iCtrl) = safeField( ...
                        Uinfo,'terminalSetValue',nan);
                    diag.mpcTerminalSetSatisfied(iCtrl) = logical( ...
                        safeField(Uinfo,'terminalSetSatisfied',false));

                    diag.mheCont(iCtrl)       = safeField(Ehe,'continuity',nan);
                    diag.mheConstraintViolationInf(iCtrl) = safeField( ...
                        Ehe,'constraintViolationInf',nan);
                    diag.mpcCont(iCtrl)       = safeField(Uinfo,'continuity',nan);
                    diag.mpcConstraintViolationInf(iCtrl) = safeField( ...
                        Uinfo,'constraintViolationInf',nan);

                    diag.mheFlag(iCtrl)       = safeField(Ehe,'exitflag',safeField(Ehe,'flag',nan));
                    diag.mpcFlag(iCtrl)       = safeField(Uinfo,'exitflag',safeField(Uinfo,'flag',nan));
                    mheOutput = safeField(Ehe,'output',struct());
                    diag.mheIterations(iCtrl) = safeField( ...
                        mheOutput,'iterations',nan);
                    diag.mheFirstOrderOptimality(iCtrl) = safeField( ...
                        mheOutput,'firstorderopt',nan);
                    diag.mheStepSize(iCtrl) = safeField( ...
                        mheOutput,'stepsize',nan);
                    diag.mheSolverMessage(iCtrl) = string(safeField( ...
                        mheOutput,'message',""));
                    diag.mheSolverUsed(iCtrl) = string(safeField( ...
                        Ehe,'solverUsed',""));
                    diag.mheAttempted(iCtrl)  = logical(safeField( ...
                        Ehe,'solveAttempted',true));
                    diag.mheAccepted(iCtrl)   = logical(safeField( ...
                        Ehe,'accepted',diag.mheFlag(iCtrl) > 0));
                    diag.mheHealthy(iCtrl) = mheHealthy;
                    diag.mpcAttempted(iCtrl) = logical(safeField( ...
                        Uinfo,'solveAttempted', ...
                        ~(cfg.ctrl.skipMPC || mpcHeldByEstimatorGate)));
                    diag.mpcSkippedByMheHealth(iCtrl) = mpcSkippedByMheHealth;
                    diag.coupledRtiEstimatorGateEnabled(iCtrl) = ...
                        coupledRtiEstimatorGateEnabled;
                    diag.coupledRtiEstimatorGateLatched(iCtrl) = ...
                        coupledRtiEstimatorGateLatched;
                    diag.coupledRtiSkippedByEstimatorGate(iCtrl) = ...
                        coupledRtiSkippedByEstimatorGate;
                    diag.coupledRtiGateGustEstimate(iCtrl) = ...
                        coupledRtiGateGustEstimate;
                    diag.coupledRtiEstimatorGateHealthyCount(iCtrl) = ...
                        coupledRtiEstimatorGateHealthyCount;
                    diag.mpcAccepted(iCtrl) = diag.mpcAttempted(iCtrl) && ...
                        diag.mpcFlag(iCtrl) > 0;
                    if reciprocalControllerRuntimeEnabled
                        mheKernel = est.reciprocalProvider. ...
                            fixedIntervalKernelAuditSnapshot();
                        mpcKernel = ctrl.reciprocalProvider. ...
                            fixedIntervalKernelAuditSnapshot();
                        diag.mheCompiledProviderCalls(iCtrl) = ...
                            mheKernel.compiledCallCount;
                        diag.mheCompiledProviderFallbacks(iCtrl) = ...
                            mheKernel.fallbackCount;
                        diag.mheCompiledProviderLastFallback{iCtrl} = ...
                            char(mheKernel.lastFallback);
                        diag.mheCompiledProviderActiveSources(iCtrl) = ...
                            mheKernel.activeSourceCount;
                        diag.mpcCompiledProviderCalls(iCtrl) = ...
                            mpcKernel.compiledCallCount;
                        diag.mpcCompiledProviderFallbacks(iCtrl) = ...
                            mpcKernel.fallbackCount;
                        diag.mpcCompiledProviderLastFallback{iCtrl} = ...
                            char(mpcKernel.lastFallback);
                        diag.mpcCompiledProviderActiveSources(iCtrl) = ...
                            mpcKernel.activeSourceCount;
                        if isa(est.reciprocalProvider, ...
                                ['AeroFlex.ctrl.', ...
                                'ScheduledReciprocalControllerModelProvider'])
                            mheAggregate = est.reciprocalProvider. ...
                                scheduledAggregateRuntimeSnapshot();
                            mpcAggregate = ctrl.reciprocalProvider. ...
                                scheduledAggregateRuntimeSnapshot();
                            diag.mheScheduledAggregateCalls(iCtrl) = ...
                                mheAggregate.callCount;
                            diag.mheScheduledAggregateFallbacks(iCtrl) = ...
                                mheAggregate.fallbackCount;
                            diag.mheScheduledAggregateParityChecks(iCtrl) = ...
                                mheAggregate.parityCount;
                            diag.mpcScheduledAggregateCalls(iCtrl) = ...
                                mpcAggregate.callCount;
                            diag.mpcScheduledAggregateFallbacks(iCtrl) = ...
                                mpcAggregate.fallbackCount;
                            diag.mpcScheduledAggregateParityChecks(iCtrl) = ...
                                mpcAggregate.parityCount;
                        end
                    end
                    if isfield(Uinfo,'output') && isfield(Uinfo.output,'auditCapture')
                        diag.mpcAuditCapture{iCtrl} = Uinfo.output.auditCapture;
                    end
                    if isfield(cfg.ctrl,'sqp') && ...
                            isfield(cfg.ctrl.sqp,'AuditCapture') && ...
                            logical(cfg.ctrl.sqp.AuditCapture) && ...
                            isfield(Uinfo,'output')
                        diag.mpcSolverOutput{iCtrl} = Uinfo.output;
                        diag.mheRealtimeRti{iCtrl} = safeField( ...
                            Ehe,'realtimeRti',struct());
                        diag.mpcRealtimeRti{iCtrl} = safeField( ...
                            Uinfo,'realtimeRti',struct());
                    end
                    if isfield(Uinfo,'priority')
                        diag.mpcPriority{iCtrl} = Uinfo.priority;
                    end

                    diag.wInf(iCtrl)          = norm(wMPC,inf);
                    if ((isstruct(trim) && isfield(trim,'states')) || ...
                            (isobject(trim) && isprop(trim,'states'))) && ...
                            ~isempty(trim.states)
                        diag.xErrInf(iCtrl) = norm(xhat(:)-trim.states(:),inf);
                    else
                        diag.xErrInf(iCtrl) = norm(xhat(:),inf);
                    end

                    % Failure counters.
                    if diag.mheAttempted(iCtrl) && ...
                            ~diag.mheAccepted(iCtrl)
                        diag.nMHEFail = diag.nMHEFail + 1;
                    end

                    if diag.mpcAttempted(iCtrl) && ~diag.mpcAccepted(iCtrl)
                        diag.nMPCFail = diag.nMPCFail + 1;
                    end
                    if mpcSkippedByMheHealth
                        diag.nMPCSkippedByMheHealth = ...
                            diag.nMPCSkippedByMheHealth + 1;
                    end
                    if coupledRtiSkippedByEstimatorGate
                        diag.nCoupledRtiSkippedByEstimatorGate = ...
                            diag.nCoupledRtiSkippedByEstimatorGate + 1;
                    end

                    % ==============================================================
                    % 4. Command fusion / saturation
                    % ==============================================================
                    fusionTimer = tic;
                    endpointRealizationInfo = struct( ...
                        'enabled',false,'accepted',false, ...
                        'fallback',false,'target',[], ...
                        'preActuatorTarget',[], ...
                        'realizationErrorInfinity',nan, ...
                        'preview',struct(),'fusionInverse',struct());
                    nMpcSolverRejectionSafeEndpointInfo = struct( ...
                        'enabled', ...
                        nMpcSolverRejectionSafeEndpointRequest.enabled, ...
                        'active',false,'target',[], ...
                        'preActuatorTarget',[],'preview',struct(), ...
                        'fusionInverse',struct(), ...
                        'realizationErrorInfinity',nan);
                    fullChannelEndpointRealizationInfo = struct( ...
                        'enabled',false,'target',[], ...
                        'preActuatorTarget',[],'preview',struct(), ...
                        'fusionInverse',struct(), ...
                        'realizationErrorInfinity',nan);
                    if fullChannelLexicographicAllocationRequest.enabled && ...
                            ~fullChannelLexicographicAllocationRequest. ...
                            nonlinearOuterReferenceGovernor && ...
                            isfield(fullInfo,'accepted') && ...
                            logical(fullInfo.accepted) && ...
                            isfield(fullInfo,'solveAttempted') && ...
                            logical(fullInfo.solveAttempted)
                        [preActuatorTarget,fullEndpointPreview] = ...
                            actuator.previewCommandForEndpoint( ...
                            uMpcAppliedTarget);
                        assert(fullEndpointPreview.accepted, ...
                            'sim_run:FullChannelEndpointRealization', ...
                            ['An accepted full-channel allocator endpoint ', ...
                            'must be realizable by the active actuator.']);
                        fullChannelEndpointRealizationInfo.enabled = true;
                        fullChannelEndpointRealizationInfo.target = ...
                            uMpcAppliedTarget;
                        fullChannelEndpointRealizationInfo. ...
                            preActuatorTarget = preActuatorTarget;
                        fullChannelEndpointRealizationInfo.preview = ...
                            fullEndpointPreview;
                    end
                    healthGateInfo = struct('enabled', ...
                        nMheHealthGateAuditRequest.enabled, ...
                        'active',mpcSkippedByMheHealth, ...
                        'target',[],'realizationErrorInfinity',nan);
                    estimatorConditionedRtiGateInfo = struct( ...
                        'enabled',coupledRtiEstimatorGateEnabled, ...
                        'latched',coupledRtiEstimatorGateLatched, ...
                        'active',coupledRtiSkippedByEstimatorGate, ...
                        'gustEstimate',coupledRtiGateGustEstimate, ...
                        'threshold',coupledRtiAllocatorAuditRequest. ...
                        gustActivationThreshold, ...
                        'healthyAboveThresholdCount', ...
                        coupledRtiEstimatorGateHealthyCount, ...
                        'minimumHealthyAboveThresholdSamples', ...
                        coupledRtiAllocatorAuditRequest. ...
                        minimumHealthyAboveThresholdSamples, ...
                        'target',[],'realizationErrorInfinity',nan);
                    switch body_case
                        case "wingonly"
                            if mpcHeldByEstimatorGate
                                u_inner = localNmpcSafeHoldEndpoint( ...
                                    uMpcPreviousEndpoint,actuator,cfg.ctrl.n_surf);
                                uMpcAppliedTarget = u_inner;
                                healthGateInfo.target = u_inner;
                            end
                            if benchmarkControlProfile.enabled
                                solverAccepted = logical(safeField(Uinfo, ...
                                    'accepted',safeField(Uinfo,'exitflag',-1) > 0));
                                [normalizedTarget,normalizationInfo] = ...
                                    localNormalizeEndpointRateTarget( ...
                                    u_inner,uMpcPreviousEndpoint,cfg, ...
                                    actuator,solverAccepted,true);
                                diag.endpointRateEqualityRawResidual(iCtrl) = ...
                                    normalizationInfo.rawResidual;
                                diag.endpointRateEqualityNormalizedResidual(iCtrl) = ...
                                    normalizationInfo.normalizedResidual;
                                diag.endpointRateEqualityNormalized(iCtrl) = ...
                                    normalizationInfo.applied;
                                if solverAccepted && normalizationInfo.applied
                                    endpointTarget = normalizedTarget;
                                else
                                    endpointTarget = [actuator.delta; ...
                                        zeros(cfg.ctrl.n_surf,1)];
                                    endpointRealizationInfo.fallback = true;
                                end
                                [preActuatorTarget,previewInfo] = ...
                                    actuator.previewCommandForEndpoint( ...
                                    endpointTarget);
                                if ~previewInfo.accepted
                                    endpointTarget = [actuator.delta; ...
                                        zeros(cfg.ctrl.n_surf,1)];
                                    [preActuatorTarget,previewInfo] = ...
                                        actuator.previewCommandForEndpoint( ...
                                        endpointTarget);
                                    endpointRealizationInfo.fallback = true;
                                end
                                assert(previewInfo.accepted, ...
                                    'sim_run:CaseAProfileSafeEndpoint', ...
                                    ['The preceding accepted actuator endpoint ', ...
                                    'must remain realizable.']);
                                endpointRealizationInfo.enabled = true;
                                endpointRealizationInfo.accepted = ...
                                    ~endpointRealizationInfo.fallback;
                                endpointRealizationInfo.target = endpointTarget;
                                endpointRealizationInfo.preActuatorTarget = ...
                                    preActuatorTarget;
                                endpointRealizationInfo.preview = previewInfo;
                                [u_inner,fusionInverseInfo] = ...
                                    fuser.rawInnerForApplied( ...
                                    preActuatorTarget,zeros(cfg.nu,1));
                                endpointRealizationInfo.fusionInverse = ...
                                    fusionInverseInfo;
                                [u_cmd_preAct,fusionInfo] = ...
                                    fuser.fuse(zeros(cfg.nu,1),u_inner);
                                preActuatorError = norm(u_cmd_preAct- ...
                                    preActuatorTarget,inf);
                                assert(preActuatorError <= 1e-11, ...
                                    'sim_run:CaseAProfileFusion', ...
                                    ['The Case-A fusion inverse/forward ', ...
                                    'contract failed.']);
                                endpointRealizationInfo. ...
                                    preActuatorErrorInfinity = preActuatorError;
                                fusionInfo.endpointRealization = ...
                                    endpointRealizationInfo;
                                fusionInfo.nmheHealthGate = healthGateInfo;
                                uMpcAppliedTarget = endpointTarget;
                                diag.endpointRealizationFallback(iCtrl) = ...
                                    endpointRealizationInfo.fallback;
                            else
                                u_cmd_preAct = saturateControl(u_inner,cfg);
                                fusionInfo = struct( ...
                                    'nmheHealthGate',healthGateInfo);
                            end

                        case "coupledfull"
                            if ~isempty(fuser)
                                if coordinateNmpcHorizon
                                    uInnerAppliedTarget = u_inner;
                                    fusionAppliedTarget = uInnerAppliedTarget;
                                    if fullChannelEndpointRealizationInfo.enabled
                                        fusionAppliedTarget = ...
                                            fullChannelEndpointRealizationInfo. ...
                                            preActuatorTarget;
                                    end
                                    [u_inner, coordinationInfo] = ...
                                        fuser.rawInnerForApplied( ...
                                        fusionAppliedTarget,u_outer_hold);
                                    if fullChannelEndpointRealizationInfo.enabled
                                        fullChannelEndpointRealizationInfo. ...
                                            fusionInverse = coordinationInfo;
                                    end
                                else
                                    coordinationInfo = struct();
                                end
                                if priorityNmpcReference
                                    % The outer wing value is a nonbinding nMPC
                                    % reference and must not bypass nMPC ownership.
                                    uOuterForFusion = zeros(size(u_outer_hold));
                                else
                                    uOuterForFusion = u_outer_hold;
                                end
                                if mpcHeldByEstimatorGate
                                    safeHoldEndpoint = localNmpcSafeHoldEndpoint( ...
                                        uMpcPreviousEndpoint,actuator,cfg.ctrl.n_surf);
                                    [u_inner,healthFusionInverseInfo] = ...
                                        fuser.rawInnerForApplied( ...
                                        safeHoldEndpoint,uOuterForFusion);
                                    uMpcAppliedTarget = safeHoldEndpoint;
                                    if coordinateNmpcHorizon
                                        uInnerAppliedTarget = safeHoldEndpoint;
                                    end
                                    healthGateInfo.target = safeHoldEndpoint;
                                    estimatorConditionedRtiGateInfo.target = ...
                                        safeHoldEndpoint;
                                    healthGateInfo.fusionInverse = ...
                                        healthFusionInverseInfo;
                                end
                                nmpcSolverAccepted = logical(safeField( ...
                                    Uinfo,'accepted', ...
                                    safeField(Uinfo,'exitflag',-1)>0));
                                if nMpcSolverRejectionSafeEndpointRequest.enabled && ...
                                        ~nmpcSolverAccepted && ...
                                        ~mpcHeldByEstimatorGate
                                    safeHoldEndpoint = localNmpcSafeHoldEndpoint( ...
                                        uMpcPreviousEndpoint,actuator, ...
                                        cfg.ctrl.n_surf);
                                    [safeHoldPreActuator,safeHoldPreview] = ...
                                        actuator.previewCommandForEndpoint( ...
                                        safeHoldEndpoint);
                                    assert(safeHoldPreview.accepted, ...
                                        'sim_run:nMpcSolverRejectionSafeEndpointPreview', ...
                                        ['The current-deflection, zero-rate ', ...
                                        'fallback endpoint is not realizable.']);
                                    [u_inner,safeHoldFusionInverse] = ...
                                        fuser.rawInnerForApplied( ...
                                        safeHoldPreActuator,uOuterForFusion);
                                    uMpcAppliedTarget = safeHoldEndpoint;
                                    nMpcSolverRejectionSafeEndpointInfo = struct( ...
                                        'enabled',true,'active',true, ...
                                        'target',safeHoldEndpoint, ...
                                        'preActuatorTarget',safeHoldPreActuator, ...
                                        'preview',safeHoldPreview, ...
                                        'fusionInverse',safeHoldFusionInverse, ...
                                        'realizationErrorInfinity',nan);
                                end
                                if realizeNmpcEndpoint
                                    assert(~isempty(actuator), ...
                                        'sim_run:EndpointRealizationActuator', ...
                                        ['The endpoint-realization audit ', ...
                                        'requires the active actuator chain.']);
                                    endpointRealizationInfo.enabled = true;
                                    endpointRealizationInfo.target = ...
                                        uMpcAppliedTarget;
                                    [preActuatorTarget,previewInfo] = ...
                                        actuator.previewCommandForEndpoint( ...
                                        uMpcAppliedTarget);
                                    endpointRealizationInfo.preview = previewInfo;
                                    if previewInfo.accepted
                                        endpointRealizationInfo.accepted = true;
                                    else
                                        endpointRealizationInfo.fallback = true;
                                        safeTarget = [actuator.delta; ...
                                            zeros(cfg.ctrl.n_surf,1)];
                                        [preActuatorTarget,safeInfo] = ...
                                            actuator.previewCommandForEndpoint( ...
                                            safeTarget);
                                        assert(safeInfo.accepted, ...
                                            'sim_run:EndpointRealizationFallback', ...
                                            ['The preceding actuator endpoint ', ...
                                            'must be realizable as a safe hold.']);
                                        endpointRealizationInfo.target = safeTarget;
                                        endpointRealizationInfo.preview = safeInfo;
                                    end
                                    endpointRealizationInfo.preActuatorTarget = ...
                                        preActuatorTarget;
                                    [u_inner,fusionInverseInfo] = ...
                                        fuser.rawInnerForApplied( ...
                                        preActuatorTarget,uOuterForFusion);
                                    endpointRealizationInfo.fusionInverse = ...
                                        fusionInverseInfo;
                                end
                                if correctedModelRigidResidualAllocationRequest.enabled
                                    assert(correctedRigidResidualNominalHold.valid && ...
                                        ~isempty(correctedRigidResidualPreview), ...
                                        'sim_run:CorrectedRigidResidualRuntime', ...
                                        ['The corrected residual allocator lacks its ', ...
                                        'held nominal command or preview owner.']);
                                    [rbCmd_hold,correctedRigidResidualRealizationHold, ...
                                        correctedRigidResidualPreviousTailThrust] = ...
                                        localEvaluateCorrectedRigidResidualAllocation( ...
                                        correctedRigidResidualModel, ...
                                        correctedModelRigidResidualAllocationRequest, ...
                                        correctedRigidResidualPreview,plant, ...
                                        predictionPackage,fuser,actuator, ...
                                        uMpcPreviousEndpoint,uOuterForFusion, ...
                                        correctedRigidResidualNominalHold, ...
                                        rbCmd_hold,gk,u_inner, ...
                                        uMpcAppliedTarget, ...
                                        correctedRigidResidualPreviousTailThrust);
                                    assert(plant.trimThrust+rbCmd_hold.thrust>=0, ...
                                        'sim_run:CorrectedRigidResidualThrust', ...
                                        'The corrected residual path violated T >= 0.');
                                    rigidIncrementHold(1) = rbCmd_hold.delta_e;
                                    rigidIncrementHold(4) = rbCmd_hold.thrust;
                                    rigidTotalHold = outerCtrl.uTrimRB(:)+ ...
                                        rigidIncrementHold;
                                    diag.correctedRigidResidualAllocation{iCtrl} = ...
                                        correctedRigidResidualRealizationHold;
                                end
                                if gustRigidResponseDomainAuditRequest.enabled && ...
                                        any(iCtrl == gustRigidResponseDomainAuditRequest.sampleIndices)
                                    % Capture all handle-owned states before the live
                                    % fusion/actuator update.  The diagnostic clone
                                    % advances one interval, so a post-fusion snapshot
                                    % would apply this command a second time.
                                    diag.gustRigidResponseDomain{iCtrl} = ...
                                        localGustRigidResponseDomainPreview( ...
                                        gustRigidResponseDomainPreview,plant, ...
                                        predictionPackage,fuser,actuator, ...
                                        uMpcPreviousEndpoint,uOuterForFusion, ...
                                        rbCmd_hold,gk,u_inner, ...
                                        gustRigidResponseDomainAuditRequest);
                                end
                                [u_cmd_preAct, fusionInfo] = fuser.fuse(uOuterForFusion, u_inner);
                                if outerWingFusionBypassAuditRequest.enabled
                                    % Audit-only discriminator: retain fusion-state evolution for
                                    % logging, but send the current outer wing request directly to
                                    % the existing rate- and position-limited actuator.  Polarity
                                    % is relative to the increment-chart trim command.
                                    nSurface = cfg.ctrl.n_surf;
                                    trimWing = fuser.uTrim(1:nSurface);
                                    requestedWing = u_outer_hold(1:nSurface);
                                    directWing = trimWing + ...
                                        outerWingFusionBypassAuditRequest.polarity * ...
                                        (requestedWing-trimWing);
                                    fusedWing = u_cmd_preAct(1:nSurface);
                                    u_cmd_preAct(1:nSurface) = directWing;
                                    fusionInfo.outerWingFusionBypass = struct( ...
                                        'enabled',true, ...
                                        'source',outerWingFusionBypassAuditRequest.source, ...
                                        'polarity',outerWingFusionBypassAuditRequest.polarityName, ...
                                        'requestedWing',requestedWing, ...
                                        'fusedWing',fusedWing, ...
                                        'directPreActuatorWing',directWing);
                                end
                                fusionInfo.nmheHealthGate = healthGateInfo;
                                fusionInfo.estimatorConditionedRtiGate = ...
                                    estimatorConditionedRtiGateInfo;
                                fusionInfo.nmpcSolverRejectionSafeEndpoint = ...
                                    nMpcSolverRejectionSafeEndpointInfo;
                                if realizeNmpcEndpoint
                                    preActuatorError = norm(u_cmd_preAct- ...
                                        endpointRealizationInfo.preActuatorTarget,inf);
                                    assert(preActuatorError <= 1e-11, ...
                                        'sim_run:EndpointRealizationFusion', ...
                                        ['The fusion inverse/forward endpoint ', ...
                                        'realization contract failed.']);
                                    endpointRealizationInfo.preActuatorErrorInfinity = ...
                                        preActuatorError;
                                    fusionInfo.endpointRealization = ...
                                        endpointRealizationInfo;
                                end
                                if coordinateNmpcHorizon
                                    coordinationError = norm( ...
                                        u_cmd_preAct-fusionAppliedTarget,inf);
                                    assert(coordinationError <= 1e-11, ...
                                        'sim_run:CoordinationContract', ...
                                        ['The fusion inverse/forward ', ...
                                        'shared-command contract failed.']);
                                    fusionInfo.coordination = coordinationInfo;
                                    fusionInfo.coordination.error = coordinationError;
                                end
                            else
                                if mpcHeldByEstimatorGate
                                    u_inner = localNmpcSafeHoldEndpoint( ...
                                        uMpcPreviousEndpoint,actuator,cfg.ctrl.n_surf);
                                    uMpcAppliedTarget = u_inner;
                                    healthGateInfo.target = u_inner;
                                    estimatorConditionedRtiGateInfo.target = u_inner;
                                end
                                u_cmd_preAct = saturateControl( ...
                                    fuseInnerOuterCommands( ...
                                    u_outer,u_inner,cfg),cfg);
                                fusionInfo = struct( ...
                                    'nmheHealthGate',healthGateInfo, ...
                                    'estimatorConditionedRtiGate', ...
                                    estimatorConditionedRtiGateInfo);
                            end
                    end
                    fusionTime = toc(fusionTimer);

                    %======================================================================
                    % 5. Actuator chain and interval-applied command
                    %======================================================================
                    actuatorTimer = tic;
                    if wingActuatorBypassAuditRequest.enabled
                        % Nonphysical audit discriminator: retain the
                        % active configuration bounds, but bypass the
                        % servo state update to isolate its causal role.
                        u_act = saturateControl(u_cmd_preAct,cfg);
                        actInfo = struct('auditBypass',true, ...
                            'uRequested',u_cmd_preAct(:), ...
                            'uApplied',u_act(:));
                    elseif ~isempty(actuator)
                        [u_act, actInfo] = actuator.step(u_cmd_preAct);
                    else
                        u_act = u_cmd_preAct;
                        actInfo = struct();
                    end
                    actuatorTime = toc(actuatorTimer);
                    assert(numel(u_act) == cfg.nu && all(isfinite(u_act)), ...
                        'sim_run:InvalidActuatorEndpoint', ...
                        'The actuator endpoint must contain %d finite values.', ...
                        cfg.nu);
                    localPhaseTrace(cfg,"after_actuator_realization", ...
                        struct('timeSeconds',t_k, ...
                        'innerRequested',u_inner(:), ...
                        'outerRequested',u_outer_hold(:), ...
                        'fusionRequested',u_cmd_preAct(:), ...
                        'actuatorEndpoint',u_act(:), ...
                        'previousEndpoint',uMpcPreviousEndpoint(:), ...
                        'endpointEqualityInf',norm( ...
                        u_act(1:cfg.ctrl.n_surf)- ...
                        uMpcPreviousEndpoint(1:cfg.ctrl.n_surf)- ...
                        TsCtrl*u_act(cfg.ctrl.n_surf+(1:cfg.ctrl.n_surf)), ...
                        inf)));
                    if healthGateInfo.active
                        healthGateInfo.realizationErrorInfinity = ...
                            norm(u_act-healthGateInfo.target,inf);
                        healthGateTolerance = 100*eps(max(1, ...
                            norm(healthGateInfo.target,inf)));
                        assert(healthGateInfo.realizationErrorInfinity <= ...
                            healthGateTolerance, ...
                            'sim_run:nMheHealthGateHold', ...
                            ['The nMHE-health fallback did not retain the ', ...
                            'current safe actuator endpoint.']);
                        fusionInfo.nmheHealthGate = healthGateInfo;
                    end
                    if exist('nMpcSolverRejectionSafeEndpointInfo','var') && ...
                            nMpcSolverRejectionSafeEndpointInfo.active
                        nMpcSolverRejectionSafeEndpointInfo. ...
                            realizationErrorInfinity = norm( ...
                            u_act-nMpcSolverRejectionSafeEndpointInfo.target,inf);
                        safeEndpointTolerance = 100*eps(max(1,norm( ...
                            nMpcSolverRejectionSafeEndpointInfo.target,inf)));
                        assert(nMpcSolverRejectionSafeEndpointInfo. ...
                            realizationErrorInfinity<=safeEndpointTolerance, ...
                            'sim_run:nMpcSolverRejectionSafeEndpoint', ...
                            ['The rejected-solve fallback did not realize ', ...
                            'the current-deflection, zero-rate endpoint.']);
                        fusionInfo.nmpcSolverRejectionSafeEndpoint = ...
                            nMpcSolverRejectionSafeEndpointInfo;
                    end
                    if exist('endpointRealizationInfo','var') && ...
                            endpointRealizationInfo.enabled
                        endpointRealizationInfo.realizationErrorInfinity = ...
                            norm(u_act-endpointRealizationInfo.target,inf);
                        assert(endpointRealizationInfo.realizationErrorInfinity <= ...
                            endpointRealizationInfo.preview.tolerance, ...
                            'sim_run:EndpointRealizationActuator', ...
                            ['The actuator did not realize the accepted ', ...
                            'endpoint target.']);
                        fusionInfo.endpointRealization = ...
                            endpointRealizationInfo;
                    end
                    if fullChannelEndpointRealizationInfo.enabled
                        fullChannelEndpointRealizationInfo. ...
                            realizationErrorInfinity = norm(u_act- ...
                            fullChannelEndpointRealizationInfo.target,inf);
                        assert(fullChannelEndpointRealizationInfo. ...
                            realizationErrorInfinity <= ...
                            fullChannelEndpointRealizationInfo.preview.tolerance, ...
                            'sim_run:FullChannelEndpointRealization', ...
                            ['The actuator did not realize the accepted ', ...
                            'full-channel endpoint.']);
                        fusionInfo.fullChannelEndpointRealization = ...
                            fullChannelEndpointRealizationInfo;
                    end
                    if fullChannelLexicographicAllocationRequest.enabled
                        % The input-cost reference includes actuator-rate
                        % coordinates.  Those coordinates continue to
                        % evolve between 25 Hz allocator updates, so the
                        % reference must follow the actual servo endpoint
                        % at every inner sample rather than retain the last
                        % requested allocation target.
                        assert(isequal(size(u_act),[cfg.nu,1]) && ...
                            all(isfinite(u_act)), ...
                            'sim_run:FullChannelReferenceEndpoint', ...
                            ['The full-channel inner reference must track ', ...
                            'the finite realized actuator endpoint.']);
                        fullChannelOuterEndpointReference = u_act;
                    end
                    fullChannelWarmStartSync = struct('enabled',false, ...
                        'applied',false,'offsetInfinity',nan, ...
                        'warmInputProjectionInfinity',nan, ...
                        'reason',"not_required");
                    if fullChannelEndpointRealizationInfo.enabled
                        % The allocation is applied after nMPC has shifted
                        % its persistent candidate horizon.  Translate
                        % that warm horizon into the realized endpoint
                        % frame before the next inner solve; otherwise the
                        % optimizer starts from a pre-allocation actuator
                        % trajectory even though uPrev is physical.
                        [ctrl,fullChannelWarmStartSync] = ...
                            localSynchronizeNmpcWarmStartToEndpoint( ...
                            ctrl,Uinfo,u_act);
                        fullInfo.output.auditCapture. ...
                            warmStartSynchronization = ...
                            fullChannelWarmStartSync;
                        fusionInfo.fullChannelWarmStartSynchronization = ...
                            fullChannelWarmStartSync;
                    end
                    if sourceCoordinateOuterEnabled && ...
                            mod(k,outerEvery)==0
                        realizedSourceDemand = [ ...
                            mean(u_act(1:cfg.ctrl.n_surf)); ...
                            rbCmd_hold.delta_e;rbCmd_hold.thrust];
                        sourceAdvance = ...
                            sourceCoordinateOuter.acceptRealizedDemand( ...
                            realizedSourceDemand, ...
                            sourceCoordinateOuterHeldGust);
                        sourceSnapshot = sourceCoordinateOuter.snapshot();
                        diag.sourceCoordinateOuterFeedback{iCtrl} = struct( ...
                            'update',sourceSnapshot.last, ...
                            'advance',sourceAdvance);
                    elseif sourceCoordinateOuterEnabled && isOuterUpdate
                        sourceSnapshot = sourceCoordinateOuter.snapshot();
                        diag.sourceCoordinateOuterFeedback{iCtrl} = struct( ...
                            'update',sourceSnapshot.last, ...
                            'advance',struct('accepted',false, ...
                            'reason',"awaiting_realized_outer_endpoint"));
                    end
                    uIntervalApplied = intervalAppliedCommand( ...
                        uMpcPreviousEndpoint,u_act, ...
                        cfg.ctrl.n_surf,ctrl.actuatorDeflectionAlpha);
                    assert(all(isfinite(uIntervalApplied)), ...
                        'sim_run:InvalidIntervalCommand', ...
                        'The interval-applied command contains NaN or Inf.');

                    nSurface = cfg.ctrl.n_surf;
                    endpointEquality = norm( ...
                        u_act(1:nSurface) - ...
                        uMpcPreviousEndpoint(1:nSurface) - ...
                        TsCtrl*u_act(nSurface+1:2*nSurface),inf);
                    totalCtrlTime = toc(tCtrlTimer);
                    diag.fusionTime(iCtrl) = fusionTime;
                    diag.actuatorTime(iCtrl) = actuatorTime;
                    diag.totalCtrlTime(iCtrl) = totalCtrlTime;
                    diag.actuatorEndpointEquality(iCtrl) = ...
                        endpointEquality;
                    diag.uInf(iCtrl) = norm( ...
                        uIntervalApplied(1:nSurface),inf);
                    diag.duInf(iCtrl) = norm( ...
                        uIntervalApplied-uDiagPrev,inf);

                    uInnerHist(:,iCtrl) = u_inner;
                    uMpcAppliedTargetHist(:,iCtrl) = uMpcAppliedTarget;
                    uKnownOuterBaseHist(:,iCtrl) = uKnownOuterBase;
                    if isfield(Uinfo,'uHorizon') && ...
                            isequal(size(Uinfo.uHorizon),[cfg.nu,ctrl.Nc])
                        uMpcAppliedHorizonHist(:,:,iCtrl) = ...
                            Uinfo.uHorizon;
                    end
                    if isfield(Uinfo,'uBaseHorizon') && ...
                            isequal(size(Uinfo.uBaseHorizon),[cfg.nu,ctrl.Nc])
                        uKnownOuterBaseHorizonHist(:,:,iCtrl) = ...
                            Uinfo.uBaseHorizon;
                    end
                    uOuterHist(:,iCtrl) = u_outer_hold;
                    uOuterRawHist(:,iCtrl) = u_outer_raw_hold;
                    uOuterRigidIncrementHist(:,iCtrl) = rigidIncrementHold;
                    uOuterRigidTotalHist(:,iCtrl) = rigidTotalHold;
                    uOuterRigidPositionHist(:,iCtrl) = plant.rb.r_I(:);
                    uOuterRigidStateHist(:,iCtrl) = rigidStateHold;
                    uOuterRigidReferenceHist(:,iCtrl) = rigidReferenceHold;
                    uFusedRequestedHist(:,iCtrl) = u_cmd_preAct;
                    uActuatorEndpointHist(:,iCtrl) = u_act;
                    Uhist(:,iCtrl) = uIntervalApplied;
                    % ==============================================================
                    % 6. Propagate plant
                    % ==============================================================
                    plantTimer = tic;
                    p1PlantIntervalApplied = false;
                    if benchmarkControlProfile.enabled
                        % The interval measurement at the next control
                        % sample must use the state and gust that owned
                        % this interval.  Capture the post-schedule,
                        % pre-propagation state for both plant paths.
                        benchmarkStateBeforePropagation = ...
                            xk(1:plant.nx);
                    end
                    switch lower(string(body_case))
                        case "wingonly"
                            cfg.sim.rigidToWingMode = "fixed";
                            assert(cfg.sim.commandsAreTrimIncrements, ...
                                'sim_run:WingOnlyControlledCommandFrame', ...
                                ['Wing-only controlled propagation requires ', ...
                                 'the trim-relative command contract.']);
                            wingPlantInput = plant.trimWingControl + ...
                                uIntervalApplied;
                            xk = plant.step(wingPlantInput,gk,"ROM");

                        case "coupledfull"
                            cfg.sim.rigidToWingMode = "alpha_gust";
                            coupledPlantTimeBefore = plant.t;
                            reciprocalSourceDomainRatio = nan;
                            reciprocalSourceDomainRejected = false;
                            reciprocalSourceStepAccepted = true;
                            if reciprocalControllerRuntimeEnabled
                                nextReciprocalMheContext = ...
                                    localReciprocalControllerIntervalContext( ...
                                    plant,uIntervalApplied,rbCmd_hold, ...
                                    coupledPlantStepsPerControlSample, ...
                                    scheduledReciprocalPacket, ...
                                    predictionPackage);
                                caseBParityNativeBefore = plant.xFlex;
                                caseBParityHiddenBefore = plant. ...
                                    reciprocalTangentCorrection.hiddenState;
                            end
                            p1PlantIntervalApplied = false;
                            p1PlantIntervalOutput = struct();
                            if p1PlantIntervalAuditEnabled && ...
                                    p1PlantIntervalPacketReady
                                p1StateBefore = [plant.xFlex(:); ...
                                    plant.rb.r_I(:);plant.rb.v_B(:); ...
                                    plant.rb.euler(:);plant.rb.omega_B(:); ...
                                    plant.reciprocalTangentCorrection. ...
                                    hiddenState(:)];
                                p1StepBefore = plant.k;
                                p1TimeBefore = plant.t;
                                p1HoldBefore = plant. ...
                                    controlSampleScheduleHoldStepsRemaining;
                                try
                                    [xk,p1PlantIntervalOutput] = ...
                                        plant.stepCoupledIntervalAudit( ...
                                        uIntervalApplied,gk,rbCmd_hold, ...
                                        p1PlantIntervalPacket);
                                    p1PlantIntervalApplied = true;
                                catch p1IntervalException
                                    p1StateAfterFailure = [plant.xFlex(:); ...
                                        plant.rb.r_I(:);plant.rb.v_B(:); ...
                                        plant.rb.euler(:);plant.rb.omega_B(:); ...
                                        plant.reciprocalTangentCorrection. ...
                                        hiddenState(:)];
                                    if ~isequaln(p1StateAfterFailure, ...
                                            p1StateBefore) || ...
                                            plant.k~=p1StepBefore || ...
                                            plant.t~=p1TimeBefore || ...
                                            plant. ...
                                            controlSampleScheduleHoldStepsRemaining~= ...
                                            p1HoldBefore
                                        rethrow(p1IntervalException)
                                    end
                                    p1PlantIntervalFallbackReason = ...
                                        "core:"+string( ...
                                        p1IntervalException.identifier);
                                end
                            end
                            if p1PlantIntervalApplied
                                rigidBefore = p1PlantIntervalOutput. ...
                                    rigidStateBeforeHistory;
                                nextReciprocalMheContext.rigidState = [ ...
                                    rigidBefore(4:6,:); ...
                                    rigidBefore(10:12,:); ...
                                    rigidBefore(7:9,:)];
                                nextReciprocalMheContext. ...
                                    reciprocalCorrectionAccepted = logical( ...
                                    p1PlantIntervalOutput.stepAccepted);
                                reciprocalSourceDomainRatio = max( ...
                                    p1PlantIntervalOutput.sourceRatios, ...
                                    [],'all');
                                reciprocalSourceDomainRejected = any( ...
                                    p1PlantIntervalOutput.domainRejected);
                                reciprocalSourceStepAccepted = all( ...
                                    p1PlantIntervalOutput.stepAccepted);
                            else
                                for coupledPlantStepIndex = ...
                                        1:coupledPlantStepsPerControlSample
                                    if reciprocalControllerRuntimeEnabled
                                        nextReciprocalMheContext.rigidState( ...
                                            :,coupledPlantStepIndex) = [ ...
                                            plant.rb.v_B(:); ...
                                            plant.rb.omega_B(:); ...
                                            plant.rb.euler(:)];
                                    end
                                    xk = plant.stepCoupled( ...
                                        uIntervalApplied,gk,rbCmd_hold);
                                    if reciprocalControllerRuntimeEnabled
                                        reciprocalStep = plant.last. ...
                                            reciprocalTangentCorrection;
                                        assert(isstruct(reciprocalStep) && ...
                                            isfield(reciprocalStep,'enabled') && ...
                                            logical(reciprocalStep.enabled) && ...
                                            isfield(reciprocalStep, ...
                                            'stepAccepted') && ...
                                            isscalar(reciprocalStep. ...
                                            stepAccepted), ...
                                            'sim_run:ReciprocalControllerGateHistory', ...
                                            ['The reciprocal controller history ', ...
                                            'requires the plant-owned realization ', ...
                                            'gate decision at every substep.']);
                                        reciprocalSourceDomainRatio = max( ...
                                            reciprocalSourceDomainRatio, ...
                                            localReciprocalSourceDomainRatio( ...
                                            reciprocalStep));
                                        reciprocalSourceDomainRejected = ...
                                            reciprocalSourceDomainRejected || ...
                                            logical(safeField(reciprocalStep, ...
                                            'domainRejected',false));
                                        reciprocalSourceStepAccepted = ...
                                            reciprocalSourceStepAccepted && ...
                                            logical(reciprocalStep.stepAccepted);
                                        nextReciprocalMheContext. ...
                                            reciprocalCorrectionAccepted( ...
                                            coupledPlantStepIndex) = logical( ...
                                            reciprocalStep.stepAccepted);
                                    end
                                end
                            end
                            coupledPlantElapsed = ...
                                plant.t - coupledPlantTimeBefore;
                            assert(abs(coupledPlantElapsed - TsCtrl) <= ...
                                coupledSampleTimeTolerance, ...
                                'sim_run:CoupledPhysicalTimeAdvance', ...
                                ['Coupled propagation advanced %.16g s; ', ...
                                'expected one controller sample %.16g s.'], ...
                                coupledPlantElapsed, TsCtrl);
                            if reciprocalControllerRuntimeEnabled
                                localCaseBScheduledIntervalParityTrace( ...
                                    cfg,ctrl,plant,nextReciprocalMheContext, ...
                                    uIntervalApplied,gk,iCtrl,t_k, ...
                                    caseBParityNativeBefore, ...
                                    caseBParityHiddenBefore);
                                mhePreviousReciprocalContext = ...
                                    nextReciprocalMheContext;
                                diag.reciprocalControllerModelProviderContext{ ...
                                    iCtrl} = struct( ...
                                    'substepCount', ...
                                    coupledPlantStepsPerControlSample, ...
                                    'maximumWingIncrementInfinityNorm', ...
                                    norm(nextReciprocalMheContext. ...
                                    wingIncrement,inf), ...
                                    'elevatorIncrement', ...
                                    rbCmd_hold.delta_e, ...
                                    'thrustIncrement',rbCmd_hold.thrust, ...
                                    'minimumTotalThrustN', ...
                                    plant.trimThrust+rbCmd_hold.thrust, ...
                                    'plantHiddenStateRead',false);
                                reciprocalSourceDomainRatioHist(k) = ...
                                    reciprocalSourceDomainRatio;
                                reciprocalSourceDomainRejectedHist(k) = ...
                                    reciprocalSourceDomainRejected;
                                reciprocalSourceStepAcceptedHist(k) = ...
                                    reciprocalSourceStepAccepted;
                            end
                            % xk = plant.stepCoupled(u_act, gk);

                        otherwise
                            error('Unknown cfg.sim.body_case = "%s".', cfg.sim.body_case);
                    end
                    if gustRigidResponseDomainAuditRequest.enabled && ...
                            ~isempty(diag.gustRigidResponseDomain{iCtrl})
                        diag.gustRigidResponseDomain{iCtrl} = ...
                            localFinalizeGustRigidResponseDomain( ...
                            diag.gustRigidResponseDomain{iCtrl},plant,u_act, ...
                            uIntervalApplied);
                    end
                    if coupledRtiAllocatorAuditRequest.enabled && ...
                            diag.coupledRtiActive(iCtrl)
                        diag.coupledRtiRealized{iCtrl} = ...
                            coupledRtiAllocator.recordRealized(plant);
                    end
                    if lexicographicSharedWingAllocationRequest.enabled
                        lexicographicInfo = diag. ...
                            lexicographicSharedWingAllocation{iCtrl};
                        if isstruct(lexicographicInfo) && ...
                                logical(safeField(lexicographicInfo, ...
                                'solveAttempted',false))
                            diag.lexicographicSharedWingAllocation{iCtrl}. ...
                                realized = lexicographicSharedWingAllocator. ...
                                recordRealized(plant);
                        end
                    end
                    if fullChannelLexicographicAllocationRequest.enabled
                        fullChannelInfo = diag. ...
                            fullChannelLexicographicAllocation{iCtrl};
                        if isstruct(fullChannelInfo) && ...
                                logical(safeField(fullChannelInfo, ...
                                'solveAttempted',false))
                            diag.fullChannelLexicographicAllocation{iCtrl}. ...
                                realized = fullChannelLexicographicAllocator. ...
                                recordRealized(plant);
                        end
                    end
                    if benchmarkControlProfile.enabled
                        benchmarkPreviousState = ...
                            benchmarkStateBeforePropagation;
                        benchmarkPreviousAppliedGust = gk;
                    end
                    diag.plantTime(iCtrl) = toc(plantTimer);
                    diag.p1PlantIntervalPacketBuildTime(iCtrl) = ...
                        p1PlantIntervalPacketBuildTime;
                    diag.p1PlantIntervalApplied(iCtrl) = ...
                        p1PlantIntervalAuditEnabled && ...
                        p1PlantIntervalApplied;
                    diag.p1PlantIntervalFallback(iCtrl) = ...
                        p1PlantIntervalAuditEnabled && ...
                        ~p1PlantIntervalApplied;
                    diag.p1PlantIntervalFallbackReason{iCtrl} = char( ...
                        p1PlantIntervalFallbackReason);

                    % The propagated interval becomes the known input
                    % for the next measurement. The actuator endpoint is
                    % retained separately for the next nMPC rate constraint.
                    uMhePreviousInterval = uIntervalApplied;
                    mhePreviousIntervalPackage = predictionPackage;
                    uMpcPreviousEndpoint = u_act;
                    uDiagPrev = uIntervalApplied;
                    if nMhePreparationFeedbackAuditRequest.enabled
                        mhePreparationInfo = est.prepareNextEstimate( ...
                            uMhePreviousInterval);
                        diag.mhePreparationTime(iCtrl) = ...
                            mhePreparationInfo.seconds;
                        diag.mhePreparationFeedbackTime(iCtrl) = ...
                            diag.mheTime(iCtrl) + mhePreparationInfo.seconds;
                        diag.mhePreparationPrepared(iCtrl) = ...
                            mhePreparationInfo.prepared;
                    end

                    %--------------------------------------------------------------
                    % 7. Runtime progress print
                    %--------------------------------------------------------------
                    isPrintStep = mod(iCtrl,diagPrintEvery) == 0;
                    isLastStep = k == Nctrl;
                    if isPrintStep || isLastStep
                        progressFrac = (iCtrl-1) / max(1,Nctrl-1);
                        elapsedWall = toc(simWallTimer);
                        etaWall = elapsedWall * ...
                            (1/max(progressFrac,eps)-1);
                        if elapsedWall > 0
                            rtFactor = t_k/elapsedWall;
                        else
                            rtFactor = nan;
                        end
                        flagStr = sprintf('%+d/%+d', ...
                            round(diag.mheFlag(iCtrl)), ...
                            round(diag.mpcFlag(iCtrl)));
                        fprintf(['  %7.2f | %9.4f | %9s | %7.2f | ', ...
                            '%8.2f | %8.2f | %8.1e | %8.1e | %7s | ', ...
                            '%8.2e | %8.2e | %8.2e'], ...
                            100*progressFrac,t_k,fmtDuration(elapsedWall), ...
                            rtFactor,1e3*mheSolveTime,1e3*mpcSolveTime, ...
                            diag.mheCont(iCtrl),diag.mpcCont(iCtrl), ...
                            flagStr,diag.wInf(iCtrl),diag.uInf(iCtrl), ...
                            diag.duInf(iCtrl));
                        fprintf('   ETA %s\n',fmtDuration(etaWall));
                    end
                    xk_full = xk;
                    % ---------------------------------------------------------------------
                    % Split plant state into flexible and rigid-body parts.
                    % ---------------------------------------------------------------------
                    [xFlex_k, rb_k] = splitFlexibleRigidState(xk_full,nxFlex);

                    % Store flexible part for legacy postProcess reconstruction.
                    x(:,k+1) = xFlex_k;
                    if ~isempty(benchmarkSignedWingtipContract)
                        signedWingtipHist(:,k+1) = ...
                            benchmarkSignedWingtipContract.measureAbsolute( ...
                            xFlex_k);
                    end

                    % Store appended rigid-body states separately.
                    if ~isempty(rb_k)
                        rbHist(:,k+1) = rb_k;
                    end

                    % ---------------------------------------------------------------------
                    % Store coupled force/moment terms if PlantRunTime.stepCoupled populated
                    % plant.last.
                    % ---------------------------------------------------------------------
                    if benchmarkControlProfile.enabled && ...
                            lower(string(body_case)) == "wingonly"
                        totalWingInput = plant.trimWingControl + ...
                            uIntervalApplied;
                        Clamp6Hist(:,k) = ...
                            localBenchmarkWingClampReaction( ...
                            plant,xFlex_k,totalWingInput,gk);
                    elseif isprop(plant,'last') && isstruct(plant.last)

                        if isfield(plant.last,'Clamp6')
                            Clamp6Hist(:,k) = plant.last.Clamp6(:);
                        end

                        if isfield(plant.last,'Fwing_B')
                            FwingHist(:,k) = plant.last.Fwing_B(:);
                        end

                        if isfield(plant.last,'Mwing_B')
                            MwingHist(:,k) = plant.last.Mwing_B(:);
                        end

                        if isfield(plant.last,'Ftot_B')
                            FtotHist(:,k) = plant.last.Ftot_B(:);
                        end

                        if isfield(plant.last,'Mtot_B')
                            MtotHist(:,k) = plant.last.Mtot_B(:);
                        end

                        if isfield(plant.last,'Fgrav_B')
                            FgravHist(:,k) = plant.last.Fgrav_B(:);
                        end

                        if isfield(plant.last,'Fthrust_B')
                            FthrustHist(:,k) = plant.last.Fthrust_B(:);
                        end
                        if isfield(plant.last, ...
                                'reciprocalTangentCorrection') && ...
                                isstruct(plant.last. ...
                                reciprocalTangentCorrection)
                            reciprocalOutput = plant.last. ...
                                reciprocalTangentCorrection;
                            if isfield(reciprocalOutput, ...
                                    'sourceRootWrench')
                                sourceRootWrenchHist(:,k) = ...
                                    reciprocalOutput.sourceRootWrench(:);
                            end
                            if isfield(reciprocalOutput, ...
                                    'loadOutputQualified')
                                sourceRootLoadQualifiedHist(k) = ...
                                    logical(reciprocalOutput. ...
                                    loadOutputQualified);
                            end
                        end
                    end
                    % figure;
                    % plot(estGust);
                    % Log
                    xhat_hist(:,k) = xhat;
                    if ~isempty(benchmarkSignedWingtipContract)
                        estimatedSignedWingtipHist(:,k) = ...
                            benchmarkSignedWingtipContract. ...
                            measureAbsolute(xhat(1:nxFlex));
                    end
                    if isnumeric(what)
                        wHorizon(1:min(end,numel(what)),k) = what(1:min(end,numel(what)));
                    end
                    if runtimeSegmentAuditRequest.enabled && ...
                            k==runtimeSegmentAuditRequest.stopSample && ...
                            k<Nctrl
                        checkpointCacheCompaction = struct( ...
                            'enabled',false,'estimatorEntriesBefore',0, ...
                            'controllerEntriesBefore',0, ...
                            'estimatorEntriesAfter',0, ...
                            'controllerEntriesAfter',0, ...
                            'activePacketsRetained',true);
                        if isa(est.reciprocalProvider, ...
                                ['AeroFlex.ctrl.', ...
                                'ScheduledReciprocalControllerModelProvider']) && ...
                                isa(ctrl.reciprocalProvider, ...
                                ['AeroFlex.ctrl.', ...
                                'ScheduledReciprocalControllerModelProvider'])
                            estimatorCacheBefore = est.reciprocalProvider. ...
                                validatedPacketCacheAuditSnapshot();
                            controllerCacheBefore = ctrl.reciprocalProvider. ...
                                validatedPacketCacheAuditSnapshot();
                            estimatorPacketBefore = est.reciprocalProvider. ...
                                scheduledAggregateRuntimeSnapshot();
                            controllerPacketBefore = ctrl.reciprocalProvider. ...
                                scheduledAggregateRuntimeSnapshot();
                            est.reciprocalProvider. ...
                                clearValidatedPacketCacheAudit();
                            ctrl.reciprocalProvider. ...
                                clearValidatedPacketCacheAudit();
                            estimatorCacheAfter = est.reciprocalProvider. ...
                                validatedPacketCacheAuditSnapshot();
                            controllerCacheAfter = ctrl.reciprocalProvider. ...
                                validatedPacketCacheAuditSnapshot();
                            estimatorPacketAfter = est.reciprocalProvider. ...
                                scheduledAggregateRuntimeSnapshot();
                            controllerPacketAfter = ctrl.reciprocalProvider. ...
                                scheduledAggregateRuntimeSnapshot();
                            activePacketsRetained = ...
                                estimatorPacketBefore.packetSignature== ...
                                estimatorPacketAfter.packetSignature && ...
                                controllerPacketBefore.packetSignature== ...
                                controllerPacketAfter.packetSignature && ...
                                estimatorPacketAfter.packetSynchronized && ...
                                controllerPacketAfter.packetSynchronized;
                            assert(estimatorCacheAfter.entryCount==0 && ...
                                controllerCacheAfter.entryCount==0 && ...
                                activePacketsRetained, ...
                                'sim_run:RuntimeSegmentCacheCompaction', ...
                                ['Checkpoint cache compaction changed the ', ...
                                'active scheduled packet.']);
                            checkpointCacheCompaction = struct( ...
                                'enabled',true, ...
                                'estimatorEntriesBefore', ...
                                estimatorCacheBefore.entryCount, ...
                                'controllerEntriesBefore', ...
                                controllerCacheBefore.entryCount, ...
                                'estimatorEntriesAfter', ...
                                estimatorCacheAfter.entryCount, ...
                                'controllerEntriesAfter', ...
                                controllerCacheAfter.entryCount, ...
                                'activePacketsRetained', ...
                                activePacketsRetained);
                        end
                        segmentState = struct( ...
                            'plant',plant,'estimator',est, ...
                            'controller',ctrl,'fuser',fuser, ...
                            'actuator',actuator, ...
                            'sourceCoordinateOuter', ...
                            sourceCoordinateOuter, ...
                            'outerController',outerCtrl, ...
                            'xk',xk, ...
                            'uMhePreviousInterval', ...
                            uMhePreviousInterval, ...
                            'mhePreviousReciprocalContext', ...
                            mhePreviousReciprocalContext, ...
                            'uMpcPreviousEndpoint', ...
                            uMpcPreviousEndpoint, ...
                            'fullChannelOuterEndpointReference', ...
                            fullChannelOuterEndpointReference, ...
                            'fullChannelTrimReference', ...
                            fullChannelTrimReference, ...
                            'fullChannelTrimReferenceCaptured', ...
                            fullChannelTrimReferenceCaptured, ...
                            'fullChannelFeasibilityTailAllocatorCalls', ...
                            fullChannelFeasibilityTailAllocatorCalls, ...
                            'outerAllocationPrevious', ...
                            outerAllocationPrevious, ...
                            'coupledRtiEstimatorGateLatched', ...
                            coupledRtiEstimatorGateLatched, ...
                            'coupledRtiEstimatorGateHealthyCount', ...
                            coupledRtiEstimatorGateHealthyCount, ...
                            'benchmarkPreviousState', ...
                            benchmarkPreviousState, ...
                            'benchmarkPreviousAppliedGust', ...
                            benchmarkPreviousAppliedGust, ...
                            'mhePreviousIntervalPackage', ...
                            mhePreviousIntervalPackage, ...
                            'dynamicEquilibriumReference', ...
                            dynamicEquilibriumReference, ...
                            'uDiagPrev',uDiagPrev, ...
                            'uOuterHold',u_outer_hold, ...
                            'uOuterRawHold',u_outer_raw_hold, ...
                            'rigidCommandHold',rbCmd_hold, ...
                            'rigidIncrementHold',rigidIncrementHold, ...
                            'rigidTotalHold',rigidTotalHold, ...
                            'rigidStateHold',rigidStateHold, ...
                            'rigidReferenceHold',rigidReferenceHold, ...
                            'sourceCoordinateOuterLatestGust', ...
                            sourceCoordinateOuterLatestGust, ...
                            'sourceCoordinateOuterHeldGust', ...
                            sourceCoordinateOuterHeldGust, ...
                            'checkpointCacheCompaction', ...
                            checkpointCacheCompaction);
                        segmentLog = struct( ...
                            'x',x,'signedWingtip',signedWingtipHist, ...
                            'estimatedSignedWingtip', ...
                            estimatedSignedWingtipHist, ...
                            'rigidState',rbHist,'clamp6',Clamp6Hist, ...
                            'sourceRootWrench',sourceRootWrenchHist, ...
                            'sourceRootLoadQualified', ...
                            sourceRootLoadQualifiedHist, ...
                            'reciprocalSourceDomainRatio', ...
                            reciprocalSourceDomainRatioHist, ...
                            'reciprocalSourceDomainRejected', ...
                            reciprocalSourceDomainRejectedHist, ...
                            'reciprocalSourceStepAccepted', ...
                            reciprocalSourceStepAcceptedHist, ...
                            'wingForce',FwingHist, ...
                            'wingMoment',MwingHist, ...
                            'totalForce',FtotHist, ...
                            'totalMoment',MtotHist, ...
                            'gravityForce',FgravHist, ...
                            'thrustForce',FthrustHist, ...
                            'estimatedState',xhat_hist, ...
                            'appliedInterval',Uhist, ...
                            'innerRequest',uInnerHist, ...
                            'mpcAppliedTarget',uMpcAppliedTargetHist, ...
                            'knownOuterBase',uKnownOuterBaseHist, ...
                            'mpcAppliedHorizon', ...
                            uMpcAppliedHorizonHist, ...
                            'knownOuterBaseHorizon', ...
                            uKnownOuterBaseHorizonHist, ...
                            'outerRequest',uOuterHist, ...
                            'outerRawRequest',uOuterRawHist, ...
                            'outerRigidIncrement', ...
                            uOuterRigidIncrementHist, ...
                            'outerRigidTotal',uOuterRigidTotalHist, ...
                            'outerRigidPosition', ...
                            uOuterRigidPositionHist, ...
                            'outerRigidState',uOuterRigidStateHist, ...
                            'outerRigidReference', ...
                            uOuterRigidReferenceHist, ...
                            'fusedRequest',uFusedRequestedHist, ...
                            'actuatorEndpoint',uActuatorEndpointHist, ...
                            'mhePreviousInterval', ...
                            uMhePreviousIntervalHist, ...
                            'mpcPreviousEndpoint', ...
                            uMpcPreviousEndpointHist, ...
                            'scheduleMu',scheduleMuHist, ...
                            'schedulePointIds',{schedulePointIds}, ...
                            'disturbanceHorizon',wHorizon, ...
                            'trueGust',trueGust, ...
                            'estimatorTruthGust',estimatorTruthGust, ...
                            'mheMeasurement',nMheMeasurementHist, ...
                            'reciprocalMheCompletedContext', ...
                            {reciprocalMheCompletedContextHist}, ...
                            'benchmarkMeasurementContext', ...
                            benchmarkMeasurementContextHist, ...
                            'knownMheChiContext', ...
                            knownMheChiContextHist, ...
                            'diagnostics',diag);
                        runtimeSegmentCheckpoint = struct( ...
                            'schemaVersion', ...
                            localRuntimeSegmentSchema( ...
                            runtimeSegmentAuditRequest.source), ...
                            'source',runtimeSegmentAuditRequest.source, ...
                            'completedSample',k, ...
                            'totalSamples',Nctrl, ...
                            'sourceSignature', ...
                            runtimeSegmentSourceSignature, ...
                            'state',segmentState,'log',segmentLog, ...
                            'createdUtc',string(datetime('now', ...
                            'TimeZone','UTC', ...
                            'Format', ...
                            "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'")));
                        checkpointParent = fileparts( ...
                            runtimeSegmentAuditRequest.checkpointPath);
                        if strlength(string(checkpointParent))>0 && ...
                                ~isfolder(checkpointParent)
                            mkdir(checkpointParent);
                        end
                        localSaveRuntimeSegmentCheckpoint( ...
                            runtimeSegmentAuditRequest.checkpointPath, ...
                            runtimeSegmentCheckpoint);
                        runtimeSegmentPaused = true;
                        fprintf(['Runtime segment checkpoint saved after ', ...
                            'S%d: %s\n'],k, ...
                            runtimeSegmentAuditRequest.checkpointPath);
                        break
                    end
                end

                % Pack outputs to match open-loop fields
                % x = []; sensEq = [];
                log = struct( ...
                    'xhat',xhat_hist, ...
                    'U',Uhist, ...
                    'uInnerRequested',uInnerHist, ...
                    'uMpcAppliedTarget',uMpcAppliedTargetHist, ...
                    'uKnownOuterBase',uKnownOuterBaseHist, ...
                    'uMpcAppliedHorizon',uMpcAppliedHorizonHist, ...
                    'uKnownOuterBaseHorizon', ...
                    uKnownOuterBaseHorizonHist, ...
                    'uOuterRequested',uOuterHist, ...
                    'uOuterRequestedRaw',uOuterRawHist, ...
                    'uOuterRigidIncrement',uOuterRigidIncrementHist, ...
                    'uOuterRigidTotal',uOuterRigidTotalHist, ...
                    'uOuterRigidPosition',uOuterRigidPositionHist, ...
                    'uOuterRigidState',uOuterRigidStateHist, ...
                    'uOuterRigidReference',uOuterRigidReferenceHist, ...
                    'uFusedRequested',uFusedRequestedHist, ...
                    'uActuatorEndpoint',uActuatorEndpointHist, ...
                    'uMhePreviousInterval', ...
                    uMhePreviousIntervalHist, ...
                    'uMpcPreviousEndpoint', ...
                    uMpcPreviousEndpointHist, ...
                    'solverSelection',runtimeSolverSelection, ...
                    'scheduleMu',scheduleMuHist, ...
                    'schedulePointIds',{schedulePointIds}, ...
                    'wHorizon',wHorizon, ...
                    'wTrue',trueGust, ...
                    'estimatorTruthGust',estimatorTruthGust, ...
                    'nMheMeasurement',nMheMeasurementHist, ...
                    'reciprocalMheCompletedContext', ...
                    {reciprocalMheCompletedContextHist}, ...
                    'benchmarkControlProfile',benchmarkControlProfile, ...
                    'benchmarkMeasurementContext', ...
                    benchmarkMeasurementContextHist, ...
                    'knownMheChiContext',knownMheChiContextHist, ...
                    'controlDiagnostics',diag, ...
                    'runtimeSegment',struct( ...
                    'enabled',runtimeSegmentAuditRequest.enabled, ...
                    'paused',runtimeSegmentPaused, ...
                    'resumed',runtimeSegmentResumed, ...
                    'sourceRebound',runtimeSegmentSourceRebound, ...
                    'sourceRebind',runtimeSegmentSourceRebind, ...
                    'completedSample',diag.iCtrl, ...
                    'checkpointPath', ...
                    runtimeSegmentAuditRequest.checkpointPath));
                if runtimeSegmentPaused
                    validNodes = 1:diag.iCtrl+1;
                    validIntervals = 1:diag.iCtrl;
                    partialLog = log;
                    partialLog.xhat = partialLog.xhat(:,validIntervals);
                    partialLog.U = partialLog.U(:,validIntervals);
                    sim_hist = struct('t',t(validNodes), ...
                        'x',x(:,validNodes),'cfg',cfg,'beam',beam, ...
                        'aero',aero,'base',base,'trim',trim, ...
                        'log',partialLog,'paths',paths);
                    success = true;
                    return
                end
                %======================================================================
                % Final diagnostic summary
                %======================================================================
                elapsedTotal = toc(simWallTimer);

                idxValid = 1:diag.iCtrl;

                mheTime_ms = 1e3*diag.mheTime(idxValid);
                mhePreparationTime_ms = ...
                    1e3*diag.mhePreparationTime(idxValid);
                mhePreparationFeedbackTime_ms = ...
                    1e3*diag.mhePreparationFeedbackTime(idxValid);
                mpcTime_ms = 1e3*diag.mpcTime(idxValid);
                scheduleTime_ms = 1e3*diag.scheduleTime(idxValid);
                fusionTime_ms = 1e3*diag.fusionTime(idxValid);
                actuatorTime_ms = 1e3*diag.actuatorTime(idxValid);
                plantTime_ms = 1e3*diag.plantTime(idxValid);
                totTime_ms = 1e3*diag.totalCtrlTime(idxValid);

                mheCont = diag.mheCont(idxValid);
                mpcCont = diag.mpcCont(idxValid);

                mheFlag = diag.mheFlag(idxValid);
                mpcFlag = diag.mpcFlag(idxValid);
                mheAttempted = diag.mheAttempted(idxValid);
                mheAccepted = diag.mheAccepted(idxValid);
                mpcAttempted = diag.mpcAttempted(idxValid);
                mpcAccepted = diag.mpcAccepted(idxValid);

                fprintf('\n');
                fprintf('======================================================================\n');
                fprintf(' SIMULATION COMPLETE\n');
                fprintf('======================================================================\n');
                fprintf('  Simulated duration      : %.6g s\n', t(end));
                fprintf('  Wall-clock duration     : %s\n', fmtDuration(elapsedTotal));
                fprintf('  Average real-time factor: %.3f x\n', t(end)/max(elapsedTotal,eps));
                fprintf('  Controller calls        : %d\n', diag.iCtrl);
                fprintf('----------------------------------------------------------------------\n');

                mheAttemptCount = sum(mheAttempted);
                if mheAttemptCount > 0
                    mheSuccessRate = ...
                        sum(mheAccepted & mheAttempted)/mheAttemptCount;
                else
                    mheSuccessRate = nan;
                end
                fprintf(['  nMHE success rate       : %6.2f %%  ', ...
                    '(%d fail / %d attempted; %d warmup)\n'], ...
                    100*mheSuccessRate,diag.nMHEFail,mheAttemptCount, ...
                    sum(~mheAttempted));

                mpcAttemptCount = sum(mpcAttempted);
                if mpcAttemptCount > 0
                    mpcSuccessRate = sum(mpcAccepted & mpcAttempted)/ ...
                        mpcAttemptCount;
                else
                    mpcSuccessRate = nan;
                end
                fprintf(['  nMPC success rate       : %6.2f %%  ', ...
                    '(%d fail / %d attempted; %d nMHE-health skips)\n'], ...
                    100*mpcSuccessRate,diag.nMPCFail,mpcAttemptCount, ...
                    diag.nMPCSkippedByMheHealth);

                fprintf('----------------------------------------------------------------------\n');
                fprintf('  nMHE solve time [ms]    : mean %8.3f | p95 %8.3f | max %8.3f\n', ...
                    mean(mheTime_ms,'omitnan'), localPercentile(mheTime_ms,95), max(mheTime_ms,[],'omitnan'));
                if nMhePreparationFeedbackAuditRequest.enabled
                    fprintf(['  nMHE preparation [ms]   : mean %8.3f | ', ...
                        'p95 %8.3f | max %8.3f\n'], ...
                        mean(mhePreparationTime_ms,'omitnan'), ...
                        localPercentile(mhePreparationTime_ms,95), ...
                        max(mhePreparationTime_ms,[],'omitnan'));
                    fprintf(['  nMHE prep+feedback [ms] : mean %8.3f | ', ...
                        'p95 %8.3f | max %8.3f\n'], ...
                        mean(mhePreparationFeedbackTime_ms,'omitnan'), ...
                        localPercentile(mhePreparationFeedbackTime_ms,95), ...
                        max(mhePreparationFeedbackTime_ms,[],'omitnan'));
                end

                fprintf('  nMPC solve time [ms]    : mean %8.3f | p95 %8.3f | max %8.3f\n', ...
                    mean(mpcTime_ms,'omitnan'), localPercentile(mpcTime_ms,95), max(mpcTime_ms,[],'omitnan'));

                fprintf('  Total ctrl time [ms]    : mean %8.3f | p95 %8.3f | max %8.3f\n', ...
                    mean(totTime_ms,'omitnan'), localPercentile(totTime_ms,95), max(totTime_ms,[],'omitnan'));
                fprintf('  Scheduling time [ms]    : mean %8.3f | p95 %8.3f | max %8.3f\n', ...
                    mean(scheduleTime_ms,'omitnan'),localPercentile(scheduleTime_ms,95),max(scheduleTime_ms,[],'omitnan'));
                fprintf('  Fusion time [ms]        : mean %8.3f | p95 %8.3f | max %8.3f\n', ...
                    mean(fusionTime_ms,'omitnan'),localPercentile(fusionTime_ms,95),max(fusionTime_ms,[],'omitnan'));
                fprintf('  Actuator time [ms]      : mean %8.3f | p95 %8.3f | max %8.3f\n', ...
                    mean(actuatorTime_ms,'omitnan'),localPercentile(actuatorTime_ms,95),max(actuatorTime_ms,[],'omitnan'));
                fprintf('  Plant time [ms]         : mean %8.3f | p95 %8.3f | max %8.3f\n', ...
                    mean(plantTime_ms,'omitnan'),localPercentile(plantTime_ms,95),max(plantTime_ms,[],'omitnan'));

                fprintf('----------------------------------------------------------------------\n');
                fprintf('  nMHE continuity norm    : mean %8.2e | p95 %8.2e | max %8.2e\n', ...
                    mean(mheCont,'omitnan'), localPercentile(mheCont,95), max(mheCont,[],'omitnan'));

                fprintf('  nMPC continuity norm    : mean %8.2e | p95 %8.2e | max %8.2e\n', ...
                    mean(mpcCont,'omitnan'), localPercentile(mpcCont,95), max(mpcCont,[],'omitnan'));

                fprintf('----------------------------------------------------------------------\n');
                fprintf('  |wHat|_inf              : mean %8.2e | max %8.2e\n', ...
                    mean(diag.wInf(idxValid),'omitnan'), max(diag.wInf(idxValid),[],'omitnan'));

                fprintf('  |u|_inf                 : mean %8.2e | max %8.2e\n', ...
                    mean(diag.uInf(idxValid),'omitnan'), max(diag.uInf(idxValid),[],'omitnan'));

                fprintf('  |du|_inf per ctrl step  : mean %8.2e | max %8.2e\n', ...
                    mean(diag.duInf(idxValid),'omitnan'), max(diag.duInf(idxValid),[],'omitnan'));

                fprintf('  |xhat-xTrim|_inf        : mean %8.2e | max %8.2e\n', ...
                    mean(diag.xErrInf(idxValid),'omitnan'), max(diag.xErrInf(idxValid),[],'omitnan'));

                fprintf('======================================================================\n\n');
                %% ---- 5. PLOT ----------------------------------------------------------
                tAxis = (0:Nt-1)*cfg.ctrl.Ts;
                % figure;
                % plot(tAxis,gust_series(1:end-1),'k--','LineWidth',1.4), hold on,
                % plot(tCtrlVec,wHorizon(1,:),'b','LineWidth',1.4), grid on
                % legend('true','estimated'), xlabel('time [s]'), ylabel('gust [m/s]')
                % title('MHE demo – ROM truth vs observer estimate')

                %                  figure; plot(t_vec, gust_series); title('True Gust Series');
                % xlabel('t (sec)'); ylabel('w true');
            otherwise
                error('Unknown runner="%s".', runner);
        end

    otherwise
        error('Unknown sim_case="%s".', sim_case);
end

% % Store results
% results.t = exist('t','var') * t;
% results.x = exist('x','var') * x;
% results.log = exist('log','var') * log;
% results.sensEq = exist('sensEq','var') * sensEq;
results.t      = assignIfExists('t',      []);
results.x      = assignIfExists('x',      []);
results.log    = assignIfExists('log',    struct());
results.sensEq = assignIfExists('sensEq', []);
% figure; plot(t_vec, gust_series); title('True Gust Series');
% xlabel('t (sec)'); ylabel('w true');
% catch ME
%     hadError = true; MEout = ME;
%     fprintf(2,'[sim_run] ERROR: %s\n', ME.message);
%     fprintf(2,'%s\n', getReport(ME,'extended','hyperlinks','off'));
% end
base.chi0 = trim.chi0;
%% ------------------------------------------------------------
% Post-processing (tip deflection, angles, energies, modal series)
% --------------------------------------------------------------
% try
% ---------------------------------------------------------------------
% Pack logs for postProcess
% ---------------------------------------------------------------------
log = assignIfExists('log', struct());

if sim_case ~= "openloop"
    log.xhat = xhat_hist;
    log.U    = Uhist;
end

if exist('wHorizon','var')
    log.wHorizon = wHorizon;
end

if exist('trueGust','var')
    log.wTrue = trueGust;
end

% If available, actuator chain:
if exist('uActuatorEndpointHist', 'var')
    log.u_act = uActuatorEndpointHist;
    log.actInfo = actInfo;
end

% Rigid-body states, if available.
if exist('rbHist','var') && any(isfinite(rbHist(:)))
    log.rb = struct();
    log.rb.state   = rbHist;
    log.rb.r_I     = rbHist(1:3,:);
    log.rb.v_B     = rbHist(4:6,:);
    log.rb.euler   = rbHist(7:9,:);
    log.rb.omega_B = rbHist(10:12,:);
end

% Coupled force/moment logs, if available.
if exist('Clamp6Hist','var')
    log.loads = struct();
    log.loads.Clamp6   = Clamp6Hist;
    log.loads.Fwing_B  = FwingHist;
    log.loads.Mwing_B  = MwingHist;
    log.loads.Ftot_B   = FtotHist;
    log.loads.Mtot_B   = MtotHist;
    log.loads.Fgrav_B  = FgravHist;
    log.loads.Fthrust_B = FthrustHist;
    if exist('sourceRootWrenchHist','var')
        log.loads.sourceRootWrench = sourceRootWrenchHist;
        log.loads.sourceRootLoadQualified = ...
            sourceRootLoadQualifiedHist;
        log.loads.reciprocalSourceDomainRatio = ...
            reciprocalSourceDomainRatioHist;
        log.loads.reciprocalSourceDomainRejected = ...
            reciprocalSourceDomainRejectedHist;
        log.loads.reciprocalSourceStepAccepted = ...
            reciprocalSourceStepAcceptedHist;
        log.loads.sourceRootWrenchOwner = ...
            'source wing dynamic equilibrium at root cut';
        log.loads.Clamp6Owner = ...
            'fixed-root structural diagnostic only';
    end
end

% Solver diagnostics, if available.
if exist('diag','var')
    log.diag = diag;
end
if exist('plant','var') && isprop(plant,'last') && ...
        isfield(plant.last,'exactPackageReuseAudit')
    cacheLog = plant.last.exactPackageReuseAudit;
    if isfield(cacheLog,'entries')
        cacheLog = rmfield(cacheLog,'entries');
    end
    log.exactPackageReuseAudit = cacheLog;
end
if exist('signedWingtipHist','var') && ...
        any(isfinite(signedWingtipHist),'all')
    log.physicalWingtip = struct( ...
        'ownerPolicy','package_owned_signed_mirrored_tip', ...
        'positiveTipAbsoluteMeters',signedWingtipHist(1,:), ...
        'negativeTipAbsoluteMeters',signedWingtipHist(2,:), ...
        'symmetricMeanAbsoluteMeters',signedWingtipHist(3,:), ...
        'estimatedPositiveTipAbsoluteMeters', ...
        estimatedSignedWingtipHist(1,:), ...
        'estimatedNegativeTipAbsoluteMeters', ...
        estimatedSignedWingtipHist(2,:), ...
        'estimatedSymmetricMeanAbsoluteMeters', ...
        estimatedSignedWingtipHist(3,:), ...
        'outputOrder',["positive_tip_z","negative_tip_z", ...
        "symmetric_mean_z"]);
end

% Store body case for post-processing.
log.body_case = body_case;
%Temp to run in RunBenchmark.m
sim_hist = struct('t',t,'x',x,'cfg',cfg,'beam',beam,'aero',aero, ...
    'base',base,'trim',trim,'log',log,'paths',paths);
deferredOutputAudit = localDeferredOutputAuditRequest(cfg);
if deferredOutputAudit.enabled
    % Keep the complete raw history; presentation output is regenerated explicitly.
    out = struct('deferred',true,'auditOnly',true, ...
        'source',deferredOutputAudit.source);
else
    out = AeroFlex.sim.postProcess(t, x, cfg, beam, aero, base, log);
end
%     warning('[postProcess] %s. Falling back to minimal outputs.', ME.message);
%     out = minimal_post(t, x, cfg, beam);   % helper below
% end
%%
if ~deferredOutputAudit.enabled
    % --- Ensure run root exists ---
    run_dir = paths.run_dir;        % already set earlier in your sim_run
    if ~exist(run_dir,'dir'), mkdir(run_dir); end

    % --- CSVs in the run root (what the notebook scans) ---
    writematrix(out.t(:),               fullfile(run_dir, 'time.csv'));
    writematrix(out.tip_z(:),           fullfile(run_dir, 'tip_z.csv'));
    writematrix(out.tip_z_norm_pct(:),  fullfile(run_dir, 'tip_z_norm_pct.csv'));

    % --- Also export a compact HDF5 in the run root (optional but nice) ---
    h5fn = fullfile(run_dir, 'sim_out.h5');
    if exist(h5fn,'file'), delete(h5fn); end
    h5create(h5fn,'/time',             [numel(out.t) 1]);         h5write(h5fn,'/time', out.t(:));
    h5create(h5fn,'/tip_z',            [numel(out.tip_z) 1]);     h5write(h5fn,'/tip_z', out.tip_z(:));
    h5create(h5fn,'/tip_z_norm_pct',   [numel(out.tip_z_norm_pct) 1]);  h5write(h5fn,'/tip_z_norm_pct', out.tip_z_norm_pct(:));

    % Save Euler angles, if you want them on disk too
    angles_deg = rad2deg(x(end-2:end,:)).';   % Nt x 3
    h5create(h5fn,'/angles_deg', [size(angles_deg,1) size(angles_deg,2)]);
    h5write(h5fn,'/angles_deg', angles_deg);

    % (Optional) Excel fallback the notebook can use if H5/CSV absent
    xcell_dir = fullfile(run_dir, 'xcell');
    if ~exist(xcell_dir,'dir'), mkdir(xcell_dir); end
    try
        T = table(out.t(:), out.tip_z(:), out.tip_z_norm_pct(:), ...
            angles_deg(:,1), angles_deg(:,2), angles_deg(:,3), ...
            'VariableNames', {'time','tip_z','tip_z_norm_pct','roll_deg','pitch_deg','yaw_deg'});
        writetable(T, fullfile(xcell_dir,'timeseries.xlsx'), 'Sheet','timeseries');
    catch ME
        warning('xcell Excel export skipped: %s', ME.message);
    end


    %%

    % ------- Exports (CSV + HDF5 + MAT) ---------------------------
    post_dir = fullfile(paths.run_dir, 'post');            if ~exist(post_dir,'dir'), mkdir(post_dir); end
    plots_dir = paths.plots;                               if ~exist(plots_dir,'dir'), mkdir(plots_dir); end
    sh_py_dir = paths.for_sharpy;                          if ~exist(sh_py_dir,'dir'), mkdir(sh_py_dir); end
    fm_dir    = paths.for_matlab;                          if ~exist(fm_dir,'dir'),    mkdir(fm_dir);    end

    % 1) MAT bundle for MATLAB analysis
    save(fullfile(fm_dir,'post_out.mat'), 'out','-v7');

    % 2) CSVs (time, tip, angles [deg], energies)
    writematrix(out.t,                       fullfile(post_dir,'time.csv'));
    writematrix(out.tip.xyz,                 fullfile(post_dir,'tip_xyz_m.csv'));            % [t x 3]
    writematrix(out.tip.z_norm_pct,          fullfile(post_dir,'tip_z_norm_pct.csv'));      % [% b/2]
    writematrix(out.angles.deg,              fullfile(post_dir,'angles_deg.csv'));          % [t x 3: roll,pitch,yaw]
    writematrix([out.energy.Tkin, out.energy.Vpot, out.energy.Etot], ...
        fullfile(post_dir,'energies.csv'));           % [t x 3]

    % 3) HDF5 for Python/SHARPy notebooks (simple, flat schema)
    h5post = fullfile(sh_py_dir,'post.h5');   if exist(h5post,'file'), delete(h5post); end
    h5create(h5post, '/time',                size(out.t));                     h5write(h5post,'/time', out.t);
    h5create(h5post, '/tip/xyz',            size(out.tip.xyz));               h5write(h5post,'/tip/xyz', out.tip.xyz);
    h5create(h5post, '/tip/z_norm_pct',     size(out.tip.z_norm_pct));        h5write(h5post,'/tip/z_norm_pct', out.tip.z_norm_pct);
    h5create(h5post, '/angles/deg',         size(out.angles.deg));            h5write(h5post,'/angles/deg', out.angles.deg);
    h5create(h5post, '/energy/Tkin',        size(out.energy.Tkin));           h5write(h5post,'/energy/Tkin', out.energy.Tkin);
    h5create(h5post, '/energy/Vpot',        size(out.energy.Vpot));           h5write(h5post,'/energy/Vpot', out.energy.Vpot);
    h5create(h5post, '/energy/Etot',        size(out.energy.Etot));           h5write(h5post,'/energy/Etot', out.energy.Etot);

    % optional modal series if you want them in H5 too (can be large)
    if isfield(out,'q') && isfield(out.q,'q0')
        h5create(h5post, '/modal/q0', size(out.q.q0));    h5write(h5post,'/modal/q0', out.q.q0);
        h5create(h5post, '/modal/q1', size(out.q.q1));    h5write(h5post,'/modal/q1', out.q.q1);
        h5create(h5post, '/modal/q2', size(out.q.q2));    h5write(h5post,'/modal/q2', out.q.q2);
    end

    % 4) Quick plots saved in /plots
    try
        % tip z (normalized) and angles
        f1 = figure('Color','w'); plot(out.t, out.tip.z_norm_pct); grid on
        xlabel('t [s]'); ylabel('Tip z [% b/2]'); title('Wing-tip heave (A-frame)')
        saveas(f1, fullfile(plots_dir,'tip_z_norm_pct.png')); close(f1);

        f2 = figure('Color','w'); plot(out.t, out.angles.deg); grid on
        xlabel('t [s]'); ylabel('Angle [deg]'); title('Euler angles (roll, pitch, yaw)')
        legend({'\phi','\theta','\psi'},'Location','best');
        saveas(f2, fullfile(plots_dir,'angles_deg.png')); close(f2);

        f3 = figure('Color','w'); plot(out.t, [out.energy.Tkin, out.energy.Vpot, out.energy.Etot]); grid on
        xlabel('t [s]'); ylabel('Energy [J]'); title('Modal energies')
        legend({'T','V','Total'},'Location','best');
        saveas(f3, fullfile(plots_dir,'energies.png')); close(f3);
    catch MEp
        warning('Plot save failed: %s', MEp.message);
    end

    % also tuck a tiny index yaml in run_dir so Python can locate post files
    yaml_fn = fullfile(paths.run_dir,'post_index.yaml');
    fid = fopen(yaml_fn,'w');  assert(fid~=-1);
    cleanupObj = onCleanup(@() fclose(fid));
    fprintf(fid, 'post:\n');
    fprintf(fid, '  mat:   %s\n', fullfile(relpath(paths.run_dir,fm_dir),'for_matlab/post_out.mat'));
    fprintf(fid, '  h5:    %s\n', fullfile(relpath(paths.run_dir,sh_py_dir),'for_sharpy/post.h5'));
    fprintf(fid, '  csv:\n');
    fprintf(fid, '    time:    %s\n', fullfile('post','time.csv'));
    fprintf(fid, '    tip_xyz: %s\n', fullfile('post','tip_xyz_m.csv'));
    fprintf(fid, '    tip_z%%:  %s\n', fullfile('post','tip_z_norm_pct.csv'));
    fprintf(fid, '    angles:  %s\n', fullfile('post','angles_deg.csv'));
    fprintf(fid, '    energy:  %s\n', fullfile('post','energies.csv'));


    % ------------------- Save run bundle -------------------
    try
        save(fullfile(paths.for_matlab,'run_bundle.mat'), ...
            'results','cfg','aero','beam','base','trim','idx', ...
            'run_settings','-v7');
    catch ME
        warning('[sim_run] Could not save run_bundle: %s', ME.message);
    end

    % Also drop a minimal H5 with time & (if present) a primary state trace
    try
        h5out = fullfile(paths.for_sharpy,'sim_run_out.h5');
        if exist(h5out,'file'), delete(h5out); end
        if exist('t','var') && ~isempty(t)
            h5create(h5out,'/time',[numel(t) 1]); h5write(h5out,'/time',t(:));
        end
        if exist('x','var') && ~isempty(x)
            h5create(h5out,'/x_shape',[2 1]); h5write(h5out,'/x_shape',[size(x,1); size(x,2)]);
            % write first modal velocity row if it exists
            row = min(size(x,1), 1);
            h5create(h5out,'/x_row1',[1 size(x,2)]); h5write(h5out,'/x_row1',x(row,:));
        end
    catch ME
        warning('[sim_run] H5 export skipped: %s', ME.message);
    end
end

% ------------------- finalize log -------------------
fprintf('=== sim_run finished %s (status: %s) ===\n', datestr(now,'yyyy-mm-dd HH:MM:SS'), ternary(~hadError,'OK','ERROR'));
try, copyfile(console_log, fullfile(paths.run_dir,'console.log')); catch, end

success = ~hadError;
if hadError
    % rethrow(MEout);  % uncomment if you want hard failure
end
end
% --------------- helpers ----------------
function A = safe_h5read(h5fn, dset, default)
A = default;
try
    A = h5read(h5fn, dset);
catch
    warning('Missing dataset %s in %s. Using default.', dset, h5fn);
end
end
function val = getOr(S, f, dflt)
if nargin<3, dflt = []; end
if isstruct(S) && isfield(S,f) && ~isempty(S.(f)), val = S.(f); else, val = dflt; end
end

function [run_dir, paths] = create_run_dirs(sim_root, case_name, body_case_dir, overwrite, date_only_runs)
if ~exist(sim_root,'dir'), mkdir(sim_root); end
case_dir = fullfile(sim_root, case_name); if ~exist(case_dir,'dir'), mkdir(case_dir); end
body_dir = fullfile(case_dir, body_case_dir); if ~exist(body_dir,'dir'), mkdir(body_dir); end
if date_only_runs
    stamp = datestr(now,'yyyymmdd');
else
    stamp = datestr(now,'yyyymmdd_HHMMSS');
end
run_dir = fullfile(body_dir, stamp);
if exist(run_dir,'dir')
    if ~overwrite, error('Run dir exists: %s', run_dir); end
else
    mkdir(run_dir);
end
paths.run_dir     = run_dir;
paths.from_sharpy = must_mkdir(fullfile(run_dir,'from_sharpy'));
paths.for_matlab  = must_mkdir(fullfile(run_dir,'for_matlab'));
paths.for_sharpy  = must_mkdir(fullfile(run_dir,'for_sharpy'));
paths.plots       = must_mkdir(fullfile(run_dir,'plots'));
paths.logs        = must_mkdir(fullfile(run_dir,'logs'));
end

function d = must_mkdir(d), if ~exist(d,'dir'), mkdir(d); end, end

function s = sanitize_bodycase(s)
s = lower(char(s)); s = strrep(s,' ','_');
if strcmp(s,'wingonly'),    s = 'wing_only';    end
if strcmp(s,'coupledfull'), s = 'coupled_full'; end
end

function list = discover_sim_setup_roots(research_root)
% Return a cell array of folders that contain a 'sim_setup' directory
list = {};
% 1) Direct child: Research/sim_setup
d1 = fullfile(research_root,'sim_setup');
if exist(d1,'dir')==7, list{end+1} = d1; end

% 2) One level below Research/*/sim_setup
kids = dir(research_root); kids = kids([kids.isdir]);
for i = 1:numel(kids)
    nm = kids(i).name;
    if strcmp(nm,'.')||strcmp(nm,'..'), continue; end
    p = fullfile(research_root, nm, 'sim_setup');
    if exist(p,'dir')==7
        list{end+1} = p;
    end
end

% 3) Two levels below Research/*/*/sim_setup (optional, helps in deep layouts)
grandkids = dir(fullfile(research_root,'*')); grandkids = grandkids([grandkids.isdir]);
for i = 1:numel(grandkids)
    nm = grandkids(i).name;
    if strcmp(nm,'.')||strcmp(nm,'..'), continue; end
    subkids = dir(fullfile(research_root, nm)); subkids = subkids([subkids.isdir]);
    for j = 1:numel(subkids)
        nm2 = subkids(j).name;
        if strcmp(nm2,'.')||strcmp(nm2,'..'), continue; end
        p = fullfile(research_root, nm, nm2, 'sim_setup');
        if exist(p,'dir')==7
            list{end+1} = p;
        end
    end
end

% Uniquify
list = unique(list);
end

function out = minimal_post(t, X, cfg, beam)
% Minimal fallback if full postProcess fails – returns time, tip z and angles only.
Nm = beam.Nm;
q2 = X(Nm+(1:Nm),:);
q0 = -beam.Omega \ q2;
x0 = beam.phi0 * q0;
Nnode = beam.fem.num_node - 1;            % last node is the "tip"
tip_idx = double((Nnode-1)*6) + (1:3);            % x,y,z translations of tip
tip_xyz = x0(tip_idx,:).';                % Nt x 3
tip_z_norm_pct = 100 * tip_xyz(:,3) / max(eps, cfg.debug.plt_scale); % % of b/2

chi = X(end-2:end,:).';                   % Nt x 3 (roll,pitch,yaw)
out.t = t(:);
out.tip.xyz = tip_xyz;
out.tip.z_norm_pct = tip_z_norm_pct;
out.angles.deg = rad2deg(chi);
out.energy.Tkin = 0.5*sum( X(1:Nm,:).^2 , 1 ).';
out.energy.Vpot = 0.5*sum( X(Nm+(1:Nm),:).^2 , 1 ).';
out.energy.Etot = out.energy.Tkin + out.energy.Vpot;
out.q.q0 = q0; out.q.q1 = X(1:Nm,:); out.q.q2 = q2;
end

function s = relpath(from, to)
% Return relative path of "to" with respect to "from" (best effort)
try
    s = char(java.nio.file.Paths.get(from).relativize(java.nio.file.Paths.get(to)).toString());
catch
    s = to;
end
end

function val = assignIfExists(varname, fallback)
if evalin('caller', sprintf('exist(''%s'',''var'') && ~isempty(%s)', varname, varname))
    val = evalin('caller', varname);
else
    val = fallback;
end
end

function setup_dir = find_latest_setup(sim_setup_root, case_name, body_case_dir)
base = fullfile(sim_setup_root, case_name, body_case_dir);
if exist(base,'dir')~=7, setup_dir = ''; return; end
dd = dir(base); dd = dd([dd.isdir]);
% keep only folders named yyyymmdd or yyyymmdd_HHMMSS
names = setdiff({dd.name},{'.','..'});
if isempty(names), setup_dir=''; return; end
% sort by datenum
[~,ix] = sort([dd.datenum],'descend');
setup_dir = fullfile(base, dd(ix(1)).name);
end

function out = ternary(cond, a, b), if cond, out=a; else, out=b; end, end
function val = safeField(S,fieldName,defaultVal)
%SAFEFIELD Safely read a field from a struct.
if isstruct(S) && isfield(S,fieldName) && ~isempty(S.(fieldName))
    val = S.(fieldName);
else
    val = defaultVal;
end

if numel(val) > 1
    val = val(1);
end
end

function str = fmtDuration(sec)
%FMTDURATION Format seconds as hh:mm:ss.s.
if ~isfinite(sec) || sec < 0
    str = '--:--:--';
    return
end

h = floor(sec/3600);
m = floor((sec - 3600*h)/60);
s = sec - 3600*h - 60*m;

if h > 0
    str = sprintf('%02d:%02d:%04.1f',h,m,s);
else
    str = sprintf('%02d:%04.1f',m,s);
end
end

function p = localPercentile(x,pct)
%LOCALPERCENTILE Percentile without requiring Statistics Toolbox.
x = x(:);
x = x(isfinite(x));

if isempty(x)
    p = nan;
    return
end

x = sort(x);

if numel(x) == 1
    p = x;
    return
end

q = pct/100;
pos = 1 + q*(numel(x)-1);

lo = floor(pos);
hi = ceil(pos);

if lo == hi
    p = x(lo);
else
    alpha = pos - lo;
    p = (1-alpha)*x(lo) + alpha*x(hi);
end
end

function value = localFirstColumnNorm(matrix)
%LOCALFIRSTCOLUMNNORM Return a finite trace scalar for an optional horizon.
if isempty(matrix)
    value = 0;
else
    value = norm(matrix(:,1),inf);
end
end

function value = localFusionOuterLowPassInf(fuser)
%LOCALFUSIONOUTERLOWPASSINF Report zero when fusion is not configured.

if isempty(fuser)
    value = 0;
else
    value = norm(fuser.yOuterLP,inf);
end
end

function clamp = localBenchmarkWingClampReaction( ...
    plant,state,totalWingInput,gust)
% Recover the physical trim-relative clamp reaction from the raw q1 equation.
% This is the same signed full-wing output used by the qualified Case-A
% benchmark runner. Propagation remains owned by the projected Ldyn operator.
parConst = plant.model.parConst;
parConst.u_ctrl = totalWingInput(:);
parConst.gust = gust(:);
parConst.N_Thrust = zeros(numel(plant.model.idx.q1),1);
stateDerivative = AeroFlex.sim.nonlinear_terms( ...
    state,parConst,plant.model.idx) + plant.model.L*state;
q1Derivative = stateDerivative(plant.model.idx.q1);
clamp = AeroFlex.beam.recoverRootWrench( ...
    plant.beam.red.phi1_sA,plant.beam.Pr, ...
    plant.beam.Pr*q1Derivative);
clamp = clamp(:);
assert(numel(clamp) == 6 && all(isfinite(clamp)), ...
    'sim_run:CaseAProfileClamp', ...
    'The named Case-A profile produced an invalid clamp wrench.');
end

function identity = synchronizePredictionModels( ...
    estimator,controller,package,cfg,plantModel,scheduledPacket,bodyCase)
%SYNCHRONIZEPREDICTIONMODELS Install the active plant package in both models.

if nargin < 6
    scheduledPacket = struct();
end
if nargin < 7
    bodyCase = "unspecified";
end

estimator.model = AeroFlex.sched.applyToROMIntegrator( ...
    estimator.model,package,cfg);
controller.model = AeroFlex.sched.applyToROMIntegrator( ...
    controller.model,package,cfg);
if ~isempty(fieldnames(scheduledPacket))
    estimator.applyScheduledReciprocalPacket(scheduledPacket);
    controller.applyScheduledReciprocalPacket(scheduledPacket);
elseif isprop(estimator,'reciprocalProvider') && ...
        ~isempty(estimator.reciprocalProvider)
    estimator.reciprocalProvider. ...
        synchronizeFixedIntervalKernelAuditPacket();
end
if isprop(controller,'reciprocalProvider') && ...
        ~isempty(controller.reciprocalProvider)
    controller.reciprocalProvider. ...
        synchronizeFixedIntervalKernelAuditPacket();
end
estimator.synchronizeTimingFromModel();
controller.synchronizeTimingFromModel();

predictionModels = {estimator.model,controller.model};
identity = struct();
identity.lRelativeError = zeros(2,1);
identity.parConstMatch = false(2,1);
identity.parConstDifferingFields = cell(2,1);
identity.rateProjection = strings(3,1);
identity.modelStepSeconds = [estimator.dt;controller.dt];
identity.substepsPerControlSample = round( ...
    [estimator.Ts/estimator.dt;controller.Ts/controller.dt]);
identity.coveredSeconds = identity.substepsPerControlSample .* ...
    identity.modelStepSeconds;
plantParConst = functionalParConst(plantModel.parConst);
identity.rateProjection(3) = localRateProjectionSummary(plantParConst);
for modelIndex = 1:2
    model = predictionModels{modelIndex};
    identity.lRelativeError(modelIndex) = norm( ...
        model.L-plantModel.L,'fro')/max(norm(plantModel.L,'fro'),eps);
    identity.parConstMatch(modelIndex) = isequaln( ...
        functionalParConst(model.parConst),plantParConst);
    identity.parConstDifferingFields{modelIndex} = ...
        localDifferingStructFields( ...
        functionalParConst(model.parConst),plantParConst);
    identity.rateProjection(modelIndex) = localRateProjectionSummary( ...
        functionalParConst(model.parConst));
end
assert(all(identity.lRelativeError == 0) && ...
    all(identity.parConstMatch), ...
    'sim_run:PredictionModelMismatch', ...
    ['The plant, nMHE, and nMPC must use the same active functional ', ...
    'package during each control sample. Body case: %s. Relative L ', ...
    'errors: [%g, %g]. Differing nMHE fields: %s. Differing nMPC ', ...
    'fields: %s. Rate projection [nMHE; nMPC; plant]: [%s; %s; %s].'], ...
    char(string(bodyCase)),identity.lRelativeError(1), ...
    identity.lRelativeError(2), ...
    strjoin(identity.parConstDifferingFields{1},', '), ...
    strjoin(identity.parConstDifferingFields{2},', '), ...
    identity.rateProjection(1),identity.rateProjection(2), ...
    identity.rateProjection(3));
timeTolerance = 100*eps(max([1,cfg.ctrl.Ts,plantModel.dt, ...
    identity.modelStepSeconds(:).']));
assert(all(identity.modelStepSeconds == plantModel.dt) && ...
    all(abs(identity.coveredSeconds-cfg.ctrl.Ts) <= timeTolerance), ...
    'sim_run:PredictionSampleTimeMismatch', ...
    ['The plant, nMHE, and nMPC must cover exactly one controller ', ...
    'sample using the same active scheduled-model step.']);
end

function summary = localRateProjectionSummary(parConst)
%LOCALRATEPROJECTIONSUMMARY Format the projection state for diagnostics.

if ~isfield(parConst,'RateProject') || ~isstruct(parConst.RateProject)
    summary = "missing";
    return
end
projection = parConst.RateProject;
enabled = isfield(projection,'projSet') && logical(projection.projSet);
if isfield(projection,'Pz')
    pzSize = size(projection.Pz);
    pzNorm = norm(projection.Pz,'fro');
else
    pzSize = [0 0];
    pzNorm = nan;
end
summary = sprintf('enabled=%d,size=%dx%d,norm=%.9g',enabled, ...
    pzSize(1),pzSize(2),pzNorm);
end

function differingFields = localDifferingStructFields(left,right)
%LOCALDIFFERINGSTRUCTFIELDS Name top-level fields that are not identical.

allFields = union(string(fieldnames(left)),string(fieldnames(right)), ...
    'stable');
isDifferent = false(size(allFields));
for fieldIndex = 1:numel(allFields)
    fieldName = char(allFields(fieldIndex));
    isDifferent(fieldIndex) = ~isfield(left,fieldName) || ...
        ~isfield(right,fieldName) || ...
        ~isequaln(left.(fieldName),right.(fieldName));
end
differingFields = cellstr(allFields(isDifferent));
if isempty(differingFields)
    differingFields = {'none'};
end
end

function [info,previousState,measurement,outputContract] = ...
    localTransportScheduledControlState(transition,package,cfg, ...
    estimator,controller,previousState,measurement,request)
%LOCALTRANSPORTSCHEDULEDCONTROLSTATE Change every persistent state owner.
assert(isfield(transition,'valid') && transition.valid && ...
    isfield(transition,'transform') && isfield(package,'x_eq'), ...
    'sim_run:ScheduledStateTransport', ...
    'Only a qualified atomic plant transition may reach the controllers.');
transform = transition.transform;
source = struct('beam',package.beam,'base',package.base, ...
    'trim',struct('states',package.x_eq(:)), ...
    'p5',package, ...
    'scheduleStateCoordinate',package.scheduleStateCoordinate);
[scheduledCfg,scheduledMeasurement] = ...
    AeroFlex.sensor.buildLongitudinalPhysicalOutputAudit( ...
    cfg,source,"imu_attitude_airdata_scheduled");
assert(isequaln(scheduledCfg.Qe,estimator.Qe), ...
    'sim_run:ScheduledMeasurementWeight', ...
    'Scheduling changed the declared physical measurement weights.');
outputContract = [];
if controller.wingtipOutputOwnerPolicy == ...
        "package_owned_signed_mirrored_tip"
    outputContract = ...
        AeroFlex.sensor.buildSignedWingtipOutput(source);
end
controllerReference = package.x_eq(:);
controlTargetHeld = isfield(request,'preserveNmpcControlTarget') && ...
    request.preserveNmpcControlTarget;
if controlTargetHeld
    controllerReference = transform*controller.xTrim(:);
end
estimatorInfo = estimator.transportScheduledState( ...
    transform,package.x_eq(:),scheduledCfg);
controllerInfo = controller.transportScheduledState( ...
    transform,controllerReference,package.beam,package.base,outputContract);
measurement = scheduledMeasurement;
previousState = transform*previousState(:);
info = struct('accepted',true,'estimator',estimatorInfo, ...
    'controller',controllerInfo, ...
    'controlTargetHeld',controlTargetHeld, ...
    'controllerReference',controllerReference, ...
    'previousStateFinite',all(isfinite(previousState)));
assert(info.previousStateFinite, ...
    'sim_run:ScheduledPreviousState', ...
    'The interval-measurement previous state failed chart transport.');
end

function parConst = functionalParConst(parConst)
%FUNCTIONALPARCONST Remove per-call input caches before package comparison.

runtimeFields = {'u_ctrl','gust'};
for fieldIndex = 1:numel(runtimeFields)
    if isfield(parConst,runtimeFields{fieldIndex})
        parConst = rmfield(parConst,runtimeFields{fieldIndex});
    end
end

% A dormant projection map does not participate in either the explicit
% nonlinear terms or the rebuilt implicit operator. Normalize its storage
% so fixed-wing models compare by functional behavior, while an enabled
% projection still requires exact Pz equality.
if isfield(parConst,'RateProject') && ...
        isstruct(parConst.RateProject) && ...
        isfield(parConst.RateProject,'projSet') && ...
        ~logical(parConst.RateProject.projSet)
    parConst.RateProject.Pz = [];
end
end

function intervalCommand = intervalAppliedCommand( ...
    previousEndpoint,currentEndpoint,nSurface,alpha)
%INTERVALAPPLIEDCOMMAND Represent a constant-rate actuator interval.

previousEndpoint = previousEndpoint(:);
currentEndpoint = currentEndpoint(:);
assert(numel(previousEndpoint) == 2*nSurface && ...
    numel(currentEndpoint) == 2*nSurface, ...
    'sim_run:ActuatorOrdering', ...
    'Actuator endpoints must use [position; rate] ordering.');
assert(isscalar(alpha) && isfinite(alpha) && alpha >= 0 && alpha <= 1, ...
    'sim_run:ActuatorDeflectionAlpha', ...
    'The interval deflection weight must lie in [0,1].');

intervalCommand = currentEndpoint;
intervalCommand(1:nSurface) = ...
    (1-alpha)*previousEndpoint(1:nSurface) + ...
    alpha*currentEndpoint(1:nSurface);
end

%% Coupling functions

function xk = stepPlant_case(plant, cfg, bodyCase, u_cmd, gk)
%STEPPLANT_CASE Unified plant propagation interface.

switch lower(string(bodyCase))

    case "wingonly"
        % Existing flexible-wing-only ROM propagation.
        assert(cfg.sim.commandsAreTrimIncrements, ...
            'sim_run:WingOnlyCommandFrame', ...
            ['Wing-only propagation requires the trim-relative command ', ...
             'contract.']);
        xk = plant.step(plant.trimWingControl+u_cmd,gk,"ROM");

    case "coupledfull"
        % Preferred future API:
        %
        cfg.sim.rigidToWingMode = "alpha_gust";
        xk = plant.stepCoupled(u_cmd, gk);
        %
        % Internally this should:
        %   1. propagate flexible wing ROM,
        %   2. compute Clamp6 = [Fwing; Mwing],
        %   3. compute tail/fin/thrust/weight terms,
        %   4. sum forces/moments,
        %   5. propagate rigid-body 6-DoF state,
        %   6. update local wing flight condition for next step.
        %
        % Temporary fallback:
        % warningOnce('stepPlant_case:coupledFallback', ...
        %     ['fully_coupled requested, but stepCoupled is not wired. ', ...
        %      'Using plant.step(...,"ROM") fallback.']);
        % xk = plant.step(u_cmd, gk, "ROM");

    otherwise
        error('Unknown bodyCase = "%s".', bodyCase);
end
end

function u = fuseInnerOuterCommands(u_outer, u_inner, cfg)
%FUSEINNEROUTERCOMMANDS Complementary command fusion.
%
% Placeholder implementation:
%   u = u_outer + u_inner
%
% Future implementation:
%   u = F_L(z) u_outer + F_H(z) u_inner
%
% where F_L is low-pass and F_H is high-pass/complementary.

u_outer = u_outer(:);
u_inner = u_inner(:);

if numel(u_outer) ~= numel(u_inner)
    error('Command dimension mismatch: outer has %d, inner has %d.', ...
        numel(u_outer), numel(u_inner));
end

% The active complementary implementation is owned by
% ComplementaryCommandFusion; this legacy helper remains a direct sum.
u = u_outer + u_inner;
end

function uSat = saturateControl(u, cfg)
%SATURATECONTROL Apply actuator deflection/rate limits.

u = u(:);

nSurf  = cfg.ctrl.n_surf;
varPer = cfg.ctrl.var_per;

if varPer == 1
    uL = expandBound(cfg.uL,nSurf);
    uU = expandBound(cfg.uU,nSurf);

elseif varPer == 2
    % Assumed ordering:
    %   u = [delta_1; ...; delta_n; rate_1; ...; rate_n]
    defL  = expandBound(cfg.uL,nSurf);
    defU  = expandBound(cfg.uU,nSurf);
    rateL = expandBound(cfg.urateL,nSurf);
    rateU = expandBound(cfg.urateU,nSurf);

    uL = [defL; rateL];
    uU = [defU; rateU];

else
    error('Unsupported cfg.ctrl.var_per = %d.', varPer);
end

if numel(u) ~= numel(uL)
    error('Control length mismatch: numel(u)=%d, expected %d.', ...
        numel(u), numel(uL));
end

uSat = min(max(u,uL),uU);
end

function b = expandBound(b,n)
%EXPANDBOUND Expand scalar bound to n-vector.
b = b(:);
if isscalar(b)
    b = repmat(b,n,1);
elseif numel(b) ~= n
    error('Bound must be scalar or length %d.', n);
end
end

function [cfg,trim,x0] = localInstallCorrectedNonwingTrimOwner( ...
    cfg,trim,x0,request,repositoryRoot)
% The public runtime binds the qualified bundle directly by content and hash.
bundlePath = string(request.bundleArtifactPath);
assert(isfile(bundlePath) && ...
    localStructuredVirtualPitchFileHash(bundlePath)== ...
    string(request.bundleArtifactSha256), ...
    'sim_run:CorrectedNonwingRuntimeArtifact', ...
    'The corrected non-wing controller bundle is unavailable or changed.');
saved = load(bundlePath,'bundle','source');
bundle = saved.bundle;
source = saved.source;
assert(string(bundle.status)== ...
    "PASS_CORRECTED_NONWING_SOURCE_CONTROLLER_BUILD" && ...
    all(structfun(@logical,bundle.checks)) && ...
    string(source.id)=="CASEA_U040_ALPHA_P01" && ...
    string(source.packageSha256)==bundle.sourcePackageSha256 && ...
    source.trim.thrust>=0, ...
    'sim_run:CorrectedNonwingRuntimeBundleGate', ...
    'The corrected non-wing controller bundle is not qualified.');
if isfield(cfg,'library') && isfield(cfg.library,'frozenPackage')
    assert(norm(double(cfg.library.frozenPackage.mu(:).')-[40,1],inf)<=1e-12, ...
        'sim_run:CorrectedNonwingRuntimeSource', ...
        'The setup is not bound to the exact Case-A source node.');
end
legacyTrim = trim;
legacyX0 = x0;
[cfg,massOwner] = RigidBody.methods.applyRuntimeMassOwner(cfg, ...
    "nonwing_source_owned_wing_reaction");
trim = source.trim;
x0 = trim.states(:);
alpha = deg2rad(trim.alphaDeg);
cfg.rigidEOMset.euler0 = [0;alpha;0];
cfg.rigidEOMset.vB0 = [cfg.flight.U_inf*cos(alpha);0; ...
    cfg.flight.U_inf*sin(alpha)];
cfg.sim.commandsAreTrimIncrements = true;
legacyInitialStateDifference = nan;
if ~isempty(legacyX0) && numel(legacyX0)==numel(x0)
    legacyInitialStateDifference = norm(legacyX0(:)-x0(:),inf);
end
cfg.outerLQR.correctedNonwingOwner = struct('enabled',true, ...
    'auditOnly',true,'defaultActive',false, ...
    'sourceId',string(source.id), ...
    'sourcePackageSha256',string(source.packageSha256), ...
    'bundleArtifactSha256',string(request.bundleArtifactSha256), ...
    'massOwnership',massOwner,'correctedTrimThrustNewtons',trim.thrust, ...
    'correctedTrimAlphaDegrees',trim.alphaDeg, ...
    'legacyTrimThrustNewtons',legacyTrim.thrust, ...
    'legacyInitialStateDifferenceInfinity', ...
    legacyInitialStateDifference, ...
    'rollback','legacy_setup_trim_and_lqr_bundle');
end

function warningOnce(id,msg)
%WARNINGONCE Print a warning only once.
persistent issued
if isempty(issued)
    issued = containers.Map();
end

if ~isKey(issued,id)
    warning(id,'%s',msg);
    issued(id) = true;
end
end

function request = localStructuredVirtualPitchRuntimeAuditRequest(value)
%LOCALSTRUCTUREDVIRTUALPITCHRUNTIMEAUDITREQUEST Validate the approved opt-in.
request = struct('enabled',false,'auditOnly',true);
if isempty(fieldnames(value))
    return
end
assert(isfield(value,'source'), ...
    'sim_run:StructuredVirtualPitchRuntimeRequest', ...
    'The structured virtual-pitch request requires source.');
source = string(value.source);
correctedSource = ...
    "phase18c-v17a-corrected-nonwing-trim-lqr-owner-integration-v1";
if source==correctedSource
    required = {'enable','auditOnly','source','bundleArtifactPath', ...
        'bundleArtifactSha256'};
    for index = 1:numel(required)
        assert(isfield(value,required{index}), ...
            'sim_run:CorrectedNonwingRuntimeRequest', ...
            'The corrected non-wing request requires %s.',required{index});
    end
    assert(isscalar(value.enable) && logical(value.enable) && ...
        isscalar(value.auditOnly) && logical(value.auditOnly) && ...
        string(value.bundleArtifactSha256)== ...
        "29f7bb6434bd34afd42ed18059b456223c0cd813c3c445ae9f8925f69b75d8ec", ...
        'sim_run:CorrectedNonwingRuntimeRequest', ...
        ['The corrected non-wing runtime request must be audit-only ', ...
        'and match the approved controller bundle.']);
    request = value;
    request.enabled = true;
    request.auditOnly = true;
    request.member = "structured_controlled";
    if isfield(value,'member')
        request.member = string(value.member);
    end
    assert(isscalar(request.member) && any(request.member== ...
        ["structured_controlled","zero_outer_baseline"]), ...
        'sim_run:CorrectedNonwingRuntimeMember', ...
        'The runtime member must be structured_controlled or zero_outer_baseline.');
    if isfield(value,'attributionSource')
        assert(isscalar(string(value.attributionSource)) && ...
            string(value.attributionSource)== ...
            "phase18c-v17a-casea-corrected-model-rigid-residual-allocation-integration-v1", ...
            'sim_run:CorrectedNonwingRuntimeAttributionSource', ...
            'The corrected non-wing attribution source is not approved.');
        request.attributionSource = string(value.attributionSource);
    end
    return
end
required = {'enable','auditOnly','source','linearArtifactPath', ...
    'linearArtifactSha256','linearJsonPath','linearJsonSha256', ...
    'nonlinearEntryJsonPath','nonlinearEntryJsonSha256', ...
    'seedArtifactPath','seedArtifactSha256'};
for index = 1:numel(required)
    assert(isfield(value,required{index}), ...
        'sim_run:StructuredVirtualPitchRuntimeRequest', ...
        'The structured virtual-pitch request requires %s.',required{index});
end
assert(isscalar(value.enable) && logical(value.enable) && ...
    isscalar(value.auditOnly) && logical(value.auditOnly) && ...
    source== ...
    "phase18c-v17a-casea-structured-virtual-pitch-runtime-integration-audit-v1", ...
    'sim_run:StructuredVirtualPitchRuntimeRequest', ...
    'The structured virtual-pitch request must be explicit and audit-only.');
assert(string(value.linearArtifactSha256)== ...
    "a8a62135e9cbb1f741ed1a896983668f07669c84ef2f75026f0ddd81b1920845" && ...
    string(value.linearJsonSha256)== ...
    "333a998e88b559daf524fa8b1ed5d39a4e8991b79e8a0df7298aa8ffff3d6383" && ...
    string(value.nonlinearEntryJsonSha256)== ...
    "c52d9a3c1f91e0a29298172ffa7317957b2c3157378591111eef55cd838880e5" && ...
    string(value.seedArtifactSha256)== ...
    "abc17545fa28a5ef189d2f142911b1feffe4f9457a7ba2891c949f50b985cbd5", ...
    'sim_run:StructuredVirtualPitchRuntimeApprovedHashes', ...
    'The request does not match the explicitly approved artifact hashes.');
request = value;
request.enabled = true;
request.auditOnly = true;
request.member = "structured_controlled";
if isfield(value,'member')
    request.member = string(value.member);
end
assert(isscalar(request.member) && any(request.member== ...
    ["structured_controlled","zero_outer_baseline"]), ...
    'sim_run:StructuredVirtualPitchRuntimeMember', ...
    'The runtime member must be structured_controlled or zero_outer_baseline.');
end

function [runtime,cfg] = localLoadStructuredVirtualPitchRuntime( ...
    request,matlabRoot,cfg,profileSource,plant,trim)
%LOCALLOADSTRUCTUREDVIRTUALPITCHRUNTIME Load only the hash-locked V2 artifacts.
% sim_run's historical matlabRoot variable already denotes the repository
% root; its MatlabFlex child contains this file.
repositoryRoot = matlabRoot;
if string(request.source)== ...
        "phase18c-v17a-corrected-nonwing-trim-lqr-owner-integration-v1"
    [runtime,cfg] = localLoadCorrectedNonwingControllerRuntime( ...
        request,repositoryRoot,cfg,profileSource,plant,trim);
    return
end
paths = [string(request.linearArtifactPath), ...
    string(request.linearJsonPath),string(request.nonlinearEntryJsonPath), ...
    string(request.seedArtifactPath)];
hashes = [string(request.linearArtifactSha256), ...
    string(request.linearJsonSha256), ...
    string(request.nonlinearEntryJsonSha256), ...
    string(request.seedArtifactSha256)];
for index = 1:numel(paths)
    assert(isfile(paths(index)) && ...
        localStructuredVirtualPitchFileHash(paths(index))==hashes(index), ...
        'sim_run:StructuredVirtualPitchRuntimeArtifact', ...
        'A structured virtual-pitch artifact is unavailable or changed: %s.', ...
        paths(index));
end

linearJson = jsondecode(fileread(request.linearJsonPath));
nonlinearJson = jsondecode(fileread(request.nonlinearEntryJsonPath));
assert(string(linearJson.status)== ...
    "PASS_LINEAR_STRUCTURED_VIRTUAL_PITCH_ENTRY_NONLINEAR_PENDING" && ...
    logical(linearJson.selectedCandidate.gatePassed) && ...
    string(nonlinearJson.status)== ...
    "PASS_NONLINEAR_COMMAND_NO_GUST_ENTRY_INTEGRATED_CASE_PENDING" && ...
    logical(nonlinearJson.gatePassed) && ...
    ~logical(linearJson.productionModified) && ...
    ~logical(linearJson.promotionApproved), ...
    'sim_run:StructuredVirtualPitchRuntimeEntryGate', ...
    'The certified linear or nonlinear entry gate is absent or stale.');
linear = load(request.linearArtifactPath,'artifact');
seed = load(request.seedArtifactPath,'source','layout','z0');
gain = linear.artifact.selectedGain;
candidate = linear.artifact.selectedCandidate;
assert(string(seed.source.id)=="CASEA_U040_ALPHA_P01" && ...
    string(seed.source.packageHash)==profileSource.packageSha256 && ...
    profileSource.packageSha256== ...
    "7c501bb9782332395b7be7d9f14aa310c17398b7640f565fcf51ce256f9dec02" && ...
    norm(plant.trimMu(:).'-[40,1],inf)<=1e-12, ...
    'sim_run:StructuredVirtualPitchRuntimeSource', ...
    'The runtime does not own the certified exact Case-A source.');
assert(isequal(size(gain.physicalStateGain),[2,numel(seed.z0)]) && ...
    isequal(size(gain.physicalReferenceGain),[2,1]) && ...
    numel(seed.z0)==94 && isfinite(candidate.crossoverRadPerSecond) && ...
    candidate.crossoverRadPerSecond>0, ...
    'sim_run:StructuredVirtualPitchRuntimeGain', ...
    'The selected structured gain has an incompatible state contract.');
assert(cfg.ctrl.outerTs==0.04 && cfg.ctrl.Ts==0.01 && ...
    cfg.sim.dt==0.000625 && cfg.ctrl.outerEvery==4 && ...
    string(cfg.ctrl.mheSolver)=="custom_sqp" && ...
    string(cfg.ctrl.mpcSolver)=="custom_sqp", ...
    'sim_run:StructuredVirtualPitchRuntimeCadence', ...
    'A cadence or solver owner differs from the approved integration.');
assert(isfinite(trim.thrust) && trim.thrust>=0, ...
    'sim_run:StructuredVirtualPitchRuntimeThrust', ...
    'The active trim violates T >= 0.');

cfg.fusion.omega_c = double(candidate.crossoverRadPerSecond);
runtime = struct('enabled',true,'source',string(request.source), ...
    'member',request.member, ...
    'gain',gain,'candidate',candidate,'layout',seed.layout, ...
    'z0',seed.z0(:),'sourceId',string(seed.source.id), ...
    'sourcePackageSha256',string(seed.source.packageHash), ...
    'linearArtifactPath',string(request.linearArtifactPath), ...
    'linearArtifactSha256',string(request.linearArtifactSha256), ...
    'linearJsonSha256',string(request.linearJsonSha256), ...
    'nonlinearEntryJsonSha256',string(request.nonlinearEntryJsonSha256), ...
    'seedArtifactSha256',string(request.seedArtifactSha256), ...
    'crossoverRadPerSecond',double(candidate.crossoverRadPerSecond));
end

function [runtime,cfg] = localLoadCorrectedNonwingControllerRuntime( ...
    request,repositoryRoot,cfg,profileSource,plant,trim)
%LOCALLOADCORRECTEDNONWINGCONTROLLERRUNTIME Load the hash-locked owner bundle.
bundlePath = string(request.bundleArtifactPath);
assert(isfile(bundlePath) && ...
    localStructuredVirtualPitchFileHash(bundlePath)== ...
    string(request.bundleArtifactSha256), ...
    'sim_run:CorrectedNonwingControllerArtifact', ...
    'The corrected non-wing controller bundle is unavailable or changed.');
saved = load(bundlePath,'bundle','source');
bundle = saved.bundle;
source = saved.source;
assert(string(bundle.status)== ...
    "PASS_CORRECTED_NONWING_SOURCE_CONTROLLER_BUILD" && ...
    all(structfun(@logical,bundle.checks)) && ...
    ~logical(bundle.productionModified) && ...
    string(source.id)=="CASEA_U040_ALPHA_P01" && ...
    string(source.packageSha256)==profileSource.packageSha256 && ...
    norm(plant.trimMu(:).'-[40,1],inf)<=1e-12 && ...
    norm(trim.states(:)-source.trim.states(:),inf)<=1e-12 && ...
    trim.thrust>=0 && ...
    string(cfg.rigidEOMset.massOwnership.owner)== ...
    "nonwing_source_owned_wing_reaction", ...
    'sim_run:CorrectedNonwingControllerSource', ...
    'The runtime does not own the corrected exact Case-A source and trim.');
gain = bundle.selectedGain;
candidate = bundle.selectedCandidate;
nx = plant.nx;
z0 = [plant.xFlex(:);plant.rb.r_I(:);plant.rb.v_B(:); ...
    plant.rb.euler(:);plant.rb.omega_B(:);0;0];
assert(isequal(size(gain.physicalStateGain),[2,numel(z0)]) && ...
    isequal(size(gain.physicalReferenceGain),[2,1]) && ...
    cfg.ctrl.outerTs==0.04 && cfg.ctrl.Ts==0.01 && ...
    cfg.sim.dt==0.000625, ...
    'sim_run:CorrectedNonwingControllerState', ...
    'The corrected controller state or cadence contract is incompatible.');
cfg.fusion.omega_c = double(candidate.crossoverRadPerSecond);
layout = struct('nf',nx,'rigidTheta',nx+8,'rigidQ',nx+11, ...
    'fusionSymmetric',nx+13,'actuatorSymmetric',nx+14);
runtime = struct('enabled',true,'schemaVersion', ...
    "corrected_nonwing_symmetric_scalar_v1", ...
    'source',string(request.source),'member',request.member, ...
    'gain',gain,'candidate',candidate,'layout',layout,'z0',z0, ...
    'sourceId',string(source.id), ...
    'sourcePackageSha256',string(source.packageSha256), ...
    'linearArtifactPath',bundlePath, ...
    'linearArtifactSha256',string(request.bundleArtifactSha256), ...
    'linearJsonSha256',"not_applicable_bundle_embedded", ...
    'nonlinearEntryJsonSha256',"not_applicable_separate_audit_artifact", ...
    'seedArtifactSha256',"not_applicable_corrected_bundle", ...
    'crossoverRadPerSecond',double(candidate.crossoverRadPerSecond), ...
    'trimThrustNewtons',double(source.trim.thrust), ...
    'equilibriumOwner',"corrected_nonwing_coupled_trim_states", ...
    'sourcePackageEquilibriumDifferenceInfinity', ...
    double(bundle.sourcePackageEquilibriumDifferenceInfinity));
end

function provenance = localStructuredVirtualPitchRuntimeProvenance(runtime)
%LOCALSTRUCTUREDVIRTUALPITCHRUNTIMEPROVENANCE Log bounded reproducibility data.
provenance = struct('enabled',logical(runtime.enabled), ...
    'source',runtime.source,'sourceId',runtime.sourceId, ...
    'member',runtime.member, ...
    'sourcePackageSha256',runtime.sourcePackageSha256, ...
    'linearArtifactPath',runtime.linearArtifactPath, ...
    'linearArtifactSha256',runtime.linearArtifactSha256, ...
    'linearJsonSha256',runtime.linearJsonSha256, ...
    'nonlinearEntryJsonSha256',runtime.nonlinearEntryJsonSha256, ...
    'seedArtifactSha256',runtime.seedArtifactSha256, ...
    'crossoverRadPerSecond',runtime.crossoverRadPerSecond, ...
    'outerControllerOutput',"finite_horizon_pitch_rate_change_demand", ...
    'outerControllerOutputUnit',"rad_per_second", ...
    'legacyCommandDiscarded',true,'onlineAllocatorUsed',false);
if isfield(runtime,'equilibriumOwner')
    provenance.equilibriumOwner = runtime.equilibriumOwner;
    provenance.trimThrustNewtons = runtime.trimThrustNewtons;
    provenance.sourcePackageEquilibriumDifferenceInfinity = ...
        runtime.sourcePackageEquilibriumDifferenceInfinity;
end
end

function [candidate,info] = localEvaluateStructuredVirtualPitchRuntime( ...
    runtime,xhat,mheHealthy,rb,fuser,actuator,referenceState, ...
    measuredState,previous,outerCtrl,sample,timeSeconds)
%LOCALEVALUATESTRUCTUREDVIRTUALPITCHRUNTIME Apply the certified algebraic law.
candidate = previous;
correctedContract = isfield(runtime,'schemaVersion') && ...
    string(runtime.schemaVersion)=="corrected_nonwing_symmetric_scalar_v1";
stateOrdering = ...
    "flex;r_I;v_B;euler;omega_B;fusionOuterLP;actuatorDelta;actuatorRate";
if correctedContract
    stateOrdering = ...
        "flex;r_I;v_B;euler;omega_B;fusionOuterLPSymmetric;actuatorDeltaSymmetric";
end
info = struct('enabled',true,'accepted',false,'fallback',true, ...
    'reason',"unavailable_current_estimate",'sample',sample, ...
    'timeSeconds',timeSeconds,'estimateAgeSamples',0, ...
    'stateOrdering',stateOrdering, ...
    'referenceDeltaRadians',nan,'virtualDemand',nan, ...
    'virtualDemandUnit',"rad_per_second", ...
    'physicalRequestRadians',[nan;nan], ...
    'legacyCommandUsed',false,'onlineAllocatorUsed',false);
if runtime.member=="zero_outer_baseline"
    candidate = previous;
    candidate.accepted = true;
    candidate.sample = sample;
    info.accepted = true;
    info.fallback = false;
    info.reason = "matched_zero_outer_baseline";
    info.referenceDeltaRadians = referenceState(5)- ...
        runtime.z0(runtime.layout.rigidTheta);
    info.virtualDemand = 0;
    info.physicalRequestRadians = [0;0];
    info.unsaturatedPhysicalRequestRadians = [0;0];
    return
end
if ~mheHealthy || any(~isfinite(xhat(:)))
    return
end
layout = runtime.layout;
if correctedContract
    fusionSymmetric = mean(fuser.yOuterLP(1:2));
    actuatorSymmetric = mean(actuator.delta(1:2));
    symmetryResidual = max(abs([fuser.yOuterLP(1)-fuser.yOuterLP(2); ...
        actuator.delta(1)-actuator.delta(2)]));
    assert(isfinite(symmetryResidual), ...
        'sim_run:CorrectedNonwingControllerSymmetry', ...
        'The symmetric-coordinate projection received a nonfinite state.');
    z = [xhat(:);rb.r_I(:);rb.v_B(:);rb.euler(:);rb.omega_B(:); ...
        fusionSymmetric;actuatorSymmetric];
else
    symmetryResidual = nan;
    z = [xhat(:);rb.r_I(:);rb.v_B(:);rb.euler(:);rb.omega_B(:); ...
        fuser.yOuterLP(:);actuator.delta(:);actuator.deltaDot(:)];
end
assert(numel(z)==numel(runtime.z0) && all(isfinite(z)), ...
    'sim_run:StructuredVirtualPitchRuntimeState', ...
    'The current estimator/runtime state does not match the certified order.');
assert(numel(referenceState)==9 && numel(measuredState)==9 && ...
    all(isfinite(referenceState)) && all(isfinite(measuredState)), ...
    'sim_run:StructuredVirtualPitchRuntimeReference', ...
    'The current rigid state/reference contract is invalid.');
referenceDelta = referenceState(5)-runtime.z0(layout.rigidTheta);
physicalRequest = -runtime.gain.physicalStateGain*(z-runtime.z0)+ ...
    runtime.gain.physicalReferenceGain*referenceDelta;
assert(isequal(size(physicalRequest),[2,1]) && ...
    all(isfinite(physicalRequest)), ...
    'sim_run:StructuredVirtualPitchRuntimeCommand', ...
    'The structured physical realization is nonfinite.');
physicalRequestUnsaturated = physicalRequest;
inputScale = [deg2rad(20);deg2rad(10)];
physicalRequest(1) = min(max(physicalRequest(1),-inputScale(1)),inputScale(1));
physicalRequest(2) = min(max(physicalRequest(2),-inputScale(2)),inputScale(2));
uOuter = zeros(actuator.nu,1);
uOuter(1:actuator.nSurf) = physicalRequest(1);
rigidIncrement = [physicalRequest(2);0;0;0];
rigidTotal = outerCtrl.uTrimRB(:)+rigidIncrement;
assert(rigidTotal(4)>=0, ...
    'sim_run:StructuredVirtualPitchRuntimeNegativeThrust', ...
    'The structured controller requested negative total thrust.');
rbCommand = struct('delta_e',physicalRequest(2),'delta_a',0, ...
    'delta_r',0,'thrust',0);
candidate = struct('uOuter',uOuter,'rigidIncrement',rigidIncrement, ...
    'rigidTotal',rigidTotal,'rbCmd',rbCommand,'accepted',true, ...
    'sample',sample);
info.accepted = true;
info.fallback = false;
info.reason = "accepted_current_estimate";
info.referenceDeltaRadians = referenceDelta;
stateSelection = runtime.gain.stateSelection;
qScaleRow = find(abs(stateSelection(:,layout.rigidQ)-1)<=1e-14,1,'first');
assert(~isempty(qScaleRow), ...
    'sim_run:StructuredVirtualPitchRuntimeDemandScale', ...
    'The certified pitch-rate state scale is unavailable.');
qScale = runtime.gain.stateScale(qScaleRow);
allocator = runtime.gain.normalizedAllocator(:);
normalizedPhysicalRequest = physicalRequestUnsaturated./inputScale;
info.virtualDemand = qScale*(allocator.'*normalizedPhysicalRequest)/ ...
    (allocator.'*allocator);
info.physicalRequestRadians = physicalRequest;
info.unsaturatedPhysicalRequestRadians = physicalRequestUnsaturated;
info.stateInfinityNorm = norm(z-runtime.z0,inf);
info.symmetryResidual = symmetryResidual;
info.measuredRigidState = measuredState(:);
info.referenceRigidState = referenceState(:);
end

function digest = localStructuredVirtualPitchFileHash(path)
%LOCALSTRUCTUREDVIRTUALPITCHFILEHASH Compute SHA-256 without changing a file.
engine = javaMethod('getInstance','java.security.MessageDigest','SHA-256');
file = fopen(path,'rb');
assert(file>=0,'sim_run:StructuredVirtualPitchHashOpen', ...
    'Cannot read %s.',path);
cleanup = onCleanup(@()fclose(file));
while ~feof(file)
    bytes = fread(file,1024*1024,'*uint8');
    if isempty(bytes), break, end
    engine.update(typecast(bytes(:),'int8'));
end
digest = lower(string(reshape(dec2hex( ...
    typecast(engine.digest(),'uint8'),2).',1,[])));
clear cleanup
end

function request = localFixedBasisIntrinsicPortAuditRequest(value)
%LOCALFIXEDBASISINTRINSICPORTAUDITREQUEST Validate exact Case-A opt-in.
request = struct('enabled',false,'auditOnly',false, ...
    'sourceId',"CASEA_U040_ALPHA_P01");
if isempty(fieldnames(value))
    return
end
assert(isfield(value,'enable') && isscalar(value.enable) && ...
    (islogical(value.enable) || isnumeric(value.enable)) && ...
    isfinite(double(value.enable)) && any(double(value.enable)==[0,1]), ...
    'sim_run:IntrinsicPortAuditRequest', ...
    'The fixed-basis/intrinsic-port enable field must be logical.');
request.enabled = logical(value.enable);
if ~request.enabled
    return
end
assert(isfield(value,'auditOnly') && isscalar(value.auditOnly) && ...
    (islogical(value.auditOnly) || isnumeric(value.auditOnly)) && ...
    isfinite(double(value.auditOnly)) && double(value.auditOnly)==1, ...
    'sim_run:IntrinsicPortAuditOnly', ...
    'The fixed-basis/intrinsic-port integration is audit-only.');
assert(isfield(value,'sourceId') && ...
    isscalar(string(value.sourceId)) && ...
    string(value.sourceId)=="CASEA_U040_ALPHA_P01", ...
    'sim_run:IntrinsicPortAuditSource', ...
    'The intrinsic-port integration requires the exact Case-A source ID.');
request.auditOnly = true;
request.sourceId = string(value.sourceId);
end

function request = localReciprocalTangentAuditRequest(value)
%LOCALRECIPROCALTANGENTAUDITREQUEST Validate the exact Case-A selector.
%   The public parameter name is retained for compatibility.  An enabled
%   production request must cite the approved V4 promotion; an explicit
%   disabled request preserves the prior fixed-root V17A rollback path.
request = struct('enabled',false,'auditOnly',false, ...
    'sourceId',"CASEA_U040_ALPHA_P01",'promotionId',"");
if isempty(fieldnames(value))
    return
end
assert(isfield(value,'enable') && isscalar(value.enable) && ...
    (islogical(value.enable) || isnumeric(value.enable)) && ...
    isfinite(double(value.enable)) && any(double(value.enable)==[0,1]), ...
    'sim_run:ReciprocalTangentAuditRequest', ...
    'The reciprocal-tangent enable field must be logical.');
request.enabled = logical(value.enable);
assert(isfield(value,'auditOnly') && isscalar(value.auditOnly) && ...
    (islogical(value.auditOnly) || isnumeric(value.auditOnly)) && ...
    isfinite(double(value.auditOnly)) && ...
    any(double(value.auditOnly)==[0,1]), ...
    'sim_run:ReciprocalTangentAuditOnly', ...
    'The reciprocal-reaction auditOnly field must be logical.');
assert(isfield(value,'sourceId') && isscalar(string(value.sourceId)) && ...
    string(value.sourceId)=="CASEA_U040_ALPHA_P01", ...
    'sim_run:ReciprocalTangentAuditSource', ...
    'The reciprocal-tangent integration requires the exact Case-A source.');
request.auditOnly = logical(value.auditOnly);
request.sourceId = string(value.sourceId);
if ~request.enabled
    return
end
if ~request.auditOnly
    expectedPromotion = ...
        "phase18c-v17a-casea-reciprocal-reaction-replacement-production-promotion-v1";
    assert(isfield(value,'promotionId') && ...
        isscalar(string(value.promotionId)) && ...
        string(value.promotionId)==expectedPromotion, ...
        'sim_run:ReciprocalReactionPromotion', ...
        ['The production reciprocal-reaction selector requires the ', ...
        'approved exact Case-A promotion identifier.']);
    request.promotionId = expectedPromotion;
end
end

