function request = localNmpcSolverRejectionSafeEndpointRequest(value)
%LOCALNMPCSOLVERREJECTIONSAFEENDPOINTREQUEST Validate Case-B fallback audit.
request = struct('enabled',false,'auditOnly',false, ...
    'changeId',"",'caseId',"");
if isempty(fieldnames(value))
    return
end
required = {'enable','auditOnly','changeId','caseId'};
assert(all(isfield(value,required)) && isscalar(value.enable) && ...
    isscalar(value.auditOnly), ...
    'sim_run:nMpcSolverRejectionSafeEndpointRequest', ...
    'The rejected-solve safe-endpoint request is incomplete.');
request.enabled = logical(value.enable);
if ~request.enabled
    return
end
assert(logical(value.auditOnly) && string(value.changeId)== ...
    "phase18c-v17a-caseb-solver-rejection-safe-endpoint-realization-audit-v1" && ...
    string(value.caseId)=="formal_case_b", ...
    'sim_run:nMpcSolverRejectionSafeEndpointScope', ...
    ['The rejected-solve safe-endpoint realization is restricted to ', ...
    'the approved formal Case-B audit.']);
request.auditOnly = true;
request.changeId = string(value.changeId);
request.caseId = string(value.caseId);
end

