function request = localRigidAttitudeChiAuditRequest(value)
%LOCALRIGIDATTITUDECHIAUDITREQUEST Validate the chi-owner discriminator.
request = struct('enable',false,'auditOnly',false,'mode',"profile");
if isempty(fieldnames(value))
    return
end
assert(isfield(value,'enable') && isscalar(value.enable) && ...
    (islogical(value.enable) || isnumeric(value.enable)) && ...
    isfinite(double(value.enable)) && any(double(value.enable) == [0,1]), ...
    'sim_run:RigidAttitudeChiAuditRequest', ...
    'The rigid-attitude chi audit enable field must be logical.');
request.enable = logical(value.enable);
if ~request.enable
    return
end
assert(isfield(value,'auditOnly') && isscalar(value.auditOnly) && ...
