    'sim_run:RigidAttitudeChiAuditMode', ...
    'The supported audit modes are disabled and plant_only.');
request.auditOnly = true;
request.mode = mode;
end

function request = localCoupledRtiAllocatorAuditRequest(value)
%LOCALCOUPLEDRTIALLOCATORAUDITREQUEST Validate the persistent audit window.
request = struct('enabled',false,'auditOnly',false, ...
    'startSample',inf,'endSample',-inf,'predictionIntervals',3, ...
    'source',"disabled", ...
    'finiteDifferenceStep',2.5e-3, ...
    'usePlantFlexibleStateOracle',false, ...
    'usePlantChiStateOracle',false, ...
    'estimatorConditionedSafetyGate',false, ...
    'gustActivationThreshold',nan, ...
    'protectedOutputEnvelope',struct(), ...
    'protectedOutputEnvelopeSha256',"", ...
    'rigidPreservationGuard',struct('enabled',false,'auditOnly',true), ...
    'minimumHealthyAboveThresholdSamples',1, ...
    'daisyChainOuterEndpointIntegration',false, ...
    'knownGustPreview',struct('enabled',false,'auditOnly',true, ...
    'source',"disabled"), ...
    'futureScheduledPackageSequence',struct( ...
    'enabled',false,'auditOnly',true), ...
    'coupledNmpcPredictor',struct( ...
    'enabled',false,'auditOnly',true,'source',"disabled"), ...
    'dynamicNullspaceWingOnly',false, ...
    'baselineRelativeRigidTube',struct('enabled',false,'auditOnly',true, ...
    'source',"disabled",'fractions',zeros(0,1)), ...
    'offlineFminconComparator',struct('enabled',false,'auditOnly',true, ...
    'source',"disabled"));
if isempty(fieldnames(value))
    return
end
assert(isfield(value,'enable') && isscalar(value.enable) && ...
    (islogical(value.enable) || isnumeric(value.enable)) && ...
    isfinite(double(value.enable)) && any(double(value.enable) == [0,1]), ...
    'sim_run:CoupledRtiAllocatorRequest', ...
    'The coupled RTI enable field must be a logical scalar.');
request.enabled = logical(value.enable);
if ~request.enabled
    return
end
assert(isfield(value,'auditOnly') && isscalar(value.auditOnly) && ...
    logical(value.auditOnly), ...
    'sim_run:CoupledRtiAllocatorAuditOnly', ...
    'The coupled RTI request requires auditOnly=true.');
required = {'startSample','endSample'};
for index = 1:numel(required)
    name = required{index};
    assert(isfield(value,name) && isscalar(value.(name)) && ...
        isfinite(value.(name)) && value.(name) >= 1 && ...
        value.(name) == round(value.(name)), ...
        'sim_run:CoupledRtiAllocatorWindow', ...
        '%s must be a positive integer.',name);
end
assert(value.startSample <= value.endSample, ...
    'sim_run:CoupledRtiAllocatorWindow', ...
    'The coupled RTI sample window is reversed.');
request.auditOnly = true;
request.startSample = double(value.startSample);
request.endSample = double(value.endSample);
if isfield(value,'predictionIntervals')
    request.predictionIntervals = double(value.predictionIntervals);
end
if isfield(value,'finiteDifferenceStep')
    request.finiteDifferenceStep = double(value.finiteDifferenceStep);
end
if isfield(value,'futureScheduledPackageSequence') && ...
        ~isempty(value.futureScheduledPackageSequence)
    sequence = value.futureScheduledPackageSequence;
    assert(isstruct(sequence) && isscalar(sequence) && ...
        isfield(sequence,'enabled') && isscalar(sequence.enabled) && ...
        (islogical(sequence.enabled) || isnumeric(sequence.enabled)) && ...
        isfinite(double(sequence.enabled)) && ...
        any(double(sequence.enabled) == [0,1]) && ...
        isfield(sequence,'auditOnly') && isscalar(sequence.auditOnly) && ...
        logical(sequence.auditOnly), ...
        'sim_run:CoupledRtiFuturePackageSequence', ...
        ['Future scheduled package prediction requires an explicit ', ...
        'audit-only logical request.']);
    request.futureScheduledPackageSequence = struct( ...
        'enabled',logical(sequence.enabled),'auditOnly',true);
end
if isfield(value,'coupledNmpcPredictor') && ...
        ~isempty(value.coupledNmpcPredictor)
    predictor = value.coupledNmpcPredictor;
    assert(isstruct(predictor) && isscalar(predictor) && ...
        isfield(predictor,'enabled') && isscalar(predictor.enabled) && ...
        (islogical(predictor.enabled) || isnumeric(predictor.enabled)) && ...
        isfinite(double(predictor.enabled)) && ...
        any(double(predictor.enabled) == [0,1]) && ...
        isfield(predictor,'auditOnly') && isscalar(predictor.auditOnly) && ...
        logical(predictor.auditOnly) && isfield(predictor,'source'), ...
        'sim_run:CoupledNmpcPredictorRequest', ...
        ['The coupled nMPC predictor requires an explicit audit-only ', ...
        'source-bound request.']);
    if logical(predictor.enabled)
        assert(string(predictor.source) == ...
            "phase18c-v17a-casea-coupled-nmpc-predictor-architecture-audit-v1", ...
            'sim_run:CoupledNmpcPredictorSource', ...
            'The coupled nMPC predictor source is not the approved audit.');
        request.coupledNmpcPredictor = struct('enabled',true, ...
            'auditOnly',true,'source',string(predictor.source));
    end
end
if isfield(value,'rigidPreservationGuard') && ...
        ~isempty(value.rigidPreservationGuard)
    guard = value.rigidPreservationGuard;
    assert(isstruct(guard) && isscalar(guard) && ...
        isfield(guard,'enabled') && isscalar(guard.enabled) && ...
        (islogical(guard.enabled) || isnumeric(guard.enabled)) && ...
        isfinite(double(guard.enabled)) && ...
        any(double(guard.enabled) == [0,1]) && ...
        isfield(guard,'auditOnly') && isscalar(guard.auditOnly) && ...
        logical(guard.auditOnly), ...
        'sim_run:CoupledRtiRigidPreservationGuard', ...
        ['The rigid-preservation guard requires an explicit audit-only ', ...
        'logical request.']);
    request.rigidPreservationGuard = struct( ...
        'enabled',logical(guard.enabled),'auditOnly',true);
end
if isfield(value,'usePlantFlexibleStateOracle')
    assert(isscalar(value.usePlantFlexibleStateOracle) && ...
        (islogical(value.usePlantFlexibleStateOracle) || ...
        isnumeric(value.usePlantFlexibleStateOracle)) && ...
        isfinite(double(value.usePlantFlexibleStateOracle)) && ...
        any(double(value.usePlantFlexibleStateOracle) == [0,1]), ...
        'sim_run:CoupledRtiAllocatorOracle', ...
        'The plant-state oracle field must be a logical scalar.');
    request.usePlantFlexibleStateOracle = ...
        logical(value.usePlantFlexibleStateOracle);
end
if isfield(value,'usePlantChiStateOracle')
    assert(isscalar(value.usePlantChiStateOracle) && ...
        (islogical(value.usePlantChiStateOracle) || ...
        isnumeric(value.usePlantChiStateOracle)) && ...
        isfinite(double(value.usePlantChiStateOracle)) && ...
        any(double(value.usePlantChiStateOracle) == [0,1]), ...
        'sim_run:CoupledRtiAllocatorChiOracle', ...
        'The plant chi-state oracle field must be a logical scalar.');
    request.usePlantChiStateOracle = ...
        logical(value.usePlantChiStateOracle);
end
if isfield(value,'daisyChainOuterEndpointIntegration')
    assert(isscalar(value.daisyChainOuterEndpointIntegration) && ...
        (islogical(value.daisyChainOuterEndpointIntegration) || ...
        isnumeric(value.daisyChainOuterEndpointIntegration)) && ...
        isfinite(double(value.daisyChainOuterEndpointIntegration)) && ...
        any(double(value.daisyChainOuterEndpointIntegration) == [0,1]), ...
        'sim_run:CoupledRtiDaisyChainIntegration', ...
        'The daisy-chain endpoint integration field must be logical.');
    request.daisyChainOuterEndpointIntegration = logical( ...
        value.daisyChainOuterEndpointIntegration);
end
if isfield(value,'knownGustPreview') && ~isempty(value.knownGustPreview)
    preview = value.knownGustPreview;
    assert(isstruct(preview) && isscalar(preview) && ...
        isfield(preview,'enabled') && isscalar(preview.enabled) && ...
        (islogical(preview.enabled) || isnumeric(preview.enabled)) && ...
        isfinite(double(preview.enabled)) && ...
        any(double(preview.enabled) == [0,1]) && ...
        isfield(preview,'auditOnly') && isscalar(preview.auditOnly) && ...
        logical(preview.auditOnly) && isfield(preview,'source'), ...
        'sim_run:CoupledRtiKnownGustPreview', ...
        ['Known gust preview requires an explicit audit-only request and ', ...
        'source identifier.']);
    if logical(preview.enabled)
        assert(string(preview.source) == ...
            "formal_casea_declared_one_minus_cosine", ...
            'sim_run:CoupledRtiKnownGustPreviewSource', ...
            ['Only the declared formal Case-A one-minus-cosine profile may ', ...
            'supply a known coupled-RTI gust preview.']);
        request.knownGustPreview = struct('enabled',true,'auditOnly',true, ...
            'source',"formal_casea_declared_one_minus_cosine");
    end
end
if isfield(value,'dynamicNullspaceWingOnly') && ...
        logical(value.dynamicNullspaceWingOnly)
    assert(isfield(value,'source') && string(value.source) == ...
        "phase18c-v17a-casea-baseline-relative-rigid-tube-formal-integration-audit-v1", ...
        'sim_run:DynamicNullspaceFormalIntegrationSource', ...
        ['The runtime dynamic-nullspace branch requires the approved ', ...
        'formal Case-A integration record.']);
    assert(request.predictionIntervals == 10 && ...
        isfield(value,'daisyChainOuterEndpointIntegration') && ...
        logical(value.daisyChainOuterEndpointIntegration), ...
        'sim_run:DynamicNullspaceFormalIntegrationContract', ...
        ['The formal integration requires ten intervals and the existing ', ...
        'daisy-chain endpoint realization contract.']);
    assert(isfield(value,'baselineRelativeRigidTube') && ...
        isstruct(value.baselineRelativeRigidTube), ...
        'sim_run:DynamicNullspaceRigidTubeRequest', ...
        'The formal integration requires the approved rigid-output tube.');
    tube = value.baselineRelativeRigidTube;
    assert(isfield(tube,'enabled') && logical(tube.enabled) && ...
        isfield(tube,'auditOnly') && logical(tube.auditOnly) && ...
        isfield(tube,'source') && string(tube.source) == ...
        "phase18c-v17a-casea-baseline-relative-rigid-output-tube-allocation-audit-v1" && ...
        isfield(tube,'fractions') && isequal(double(tube.fractions(:)), ...
        [0.001;0.01;0.05]), ...
        'sim_run:DynamicNullspaceRigidTubeRequest', ...
        'The formal integration must retain the approved rigid-output tube.');
    request.dynamicNullspaceWingOnly = true;
    request.source = string(value.source);
    request.baselineRelativeRigidTube = struct('enabled',true, ...
        'auditOnly',true,'source',string(tube.source), ...
        'fractions',double(tube.fractions(:)));
end
if isfield(value,'offlineFminconComparator') && ...
        ~isempty(value.offlineFminconComparator)
    comparator = value.offlineFminconComparator;
    assert(isstruct(comparator) && isscalar(comparator) && ...
        isfield(comparator,'enabled') && isscalar(comparator.enabled) && ...
        (islogical(comparator.enabled) || isnumeric(comparator.enabled)) && ...
        isfinite(double(comparator.enabled)) && ...
        any(double(comparator.enabled)==[0,1]) && ...
        isfield(comparator,'auditOnly') && isscalar(comparator.auditOnly) && ...
        logical(comparator.auditOnly) && isfield(comparator,'source'), ...
        'sim_run:DynamicNullspaceFminconComparatorRequest', ...
        ['The fmincon comparator requires an explicit source-bound ', ...
        'audit-only request.']);
    if logical(comparator.enabled)
        assert(request.dynamicNullspaceWingOnly && ...
            request.source == ...
            "phase18c-v17a-casea-baseline-relative-rigid-tube-formal-integration-audit-v1" && ...
            string(comparator.source) == ...
            "phase18c-v17a-casea-baseline-relative-rigid-tube-fmincon-comparator-audit-v1", ...
            'sim_run:DynamicNullspaceFminconComparatorSource', ...
            ['The fmincon comparator is limited to the named formal ', ...
            'baseline-relative rigid-tube integration.']);
        request.offlineFminconComparator = struct('enabled',true, ...
            'auditOnly',true,'source',string(comparator.source));
    end
end
if isfield(value,'estimatorConditionedSafetyGate')
    assert(isscalar(value.estimatorConditionedSafetyGate) && ...
        (islogical(value.estimatorConditionedSafetyGate) || ...
        isnumeric(value.estimatorConditionedSafetyGate)) && ...
        isfinite(double(value.estimatorConditionedSafetyGate)) && ...
        any(double(value.estimatorConditionedSafetyGate) == [0,1]), ...
        'sim_run:CoupledRtiEstimatorGate', ...
        'The estimator-conditioned safety gate field must be logical.');
    request.estimatorConditionedSafetyGate = ...
        logical(value.estimatorConditionedSafetyGate);
end
if request.estimatorConditionedSafetyGate
    assert(isfield(value,'gustActivationThreshold') && ...
        isscalar(value.gustActivationThreshold) && ...
        isnumeric(value.gustActivationThreshold) && ...
        isfinite(value.gustActivationThreshold) && ...
        abs(value.gustActivationThreshold-0.01) <= 10*eps(0.01), ...
        'sim_run:CoupledRtiEstimatorGateThreshold', ...
        ['The approved estimator-conditioned safety gate requires the ', ...
        'frozen 0.01 m/s activation threshold.']);
    request.gustActivationThreshold = double( ...
        value.gustActivationThreshold);
    assert(isfield(value,'minimumHealthyAboveThresholdSamples') && ...
        isscalar(value.minimumHealthyAboveThresholdSamples) && ...
        isnumeric(value.minimumHealthyAboveThresholdSamples) && ...
        isfinite(value.minimumHealthyAboveThresholdSamples) && ...
        value.minimumHealthyAboveThresholdSamples == 8, ...
        'sim_run:CoupledRtiEstimatorGateDwell', ...
        ['The approved readiness dwell is exactly eight healthy samples, ', ...
        'matching the unchanged nMHE horizon.']);
    request.minimumHealthyAboveThresholdSamples = 8;
    expectedEnvelope = struct( ...
        'wingtip',9.7048202807314965e-12, ...
        'clampFz',1.6309789935275987e-8, ...
        'clampMy',1.1907872021765797e-8, ...
        'totalFz',2.110087969420249e-5, ...
        'totalMy',1.117918893989156e-5, ...
        'speed',9.5892411344777884e-8, ...
        'pitchRate',5.4376625335805784e-7);
    expectedEnvelopeHash = ...
        "b41ee34804eaf80e2a90802069ac6f8e0b46db29b3f81b494f3c8021ebe4ca5d";
    assert(isfield(value,'protectedOutputEnvelope') && ...
        isstruct(value.protectedOutputEnvelope) && ...
        isequal(fieldnames(value.protectedOutputEnvelope), ...
        fieldnames(expectedEnvelope)), ...
        'sim_run:CoupledRtiProtectedOutputEnvelope', ...
        'The approved protected-output envelope is missing or malformed.');
    for name = string(fieldnames(expectedEnvelope)).'
        observed = value.protectedOutputEnvelope.(name);
        expected = expectedEnvelope.(name);
        assert(isscalar(observed) && isnumeric(observed) && ...
            isfinite(observed) && observed >= 0 && ...
            abs(observed-expected) <= 100*eps(max(1,expected)), ...
            'sim_run:CoupledRtiProtectedOutputEnvelope', ...
            'The frozen %s uncertainty margin changed.',name);
    end
    assert(isfield(value,'protectedOutputEnvelopeSha256') && ...
        isscalar(string(value.protectedOutputEnvelopeSha256)) && ...
        string(value.protectedOutputEnvelopeSha256) == ...
        expectedEnvelopeHash, ...
        'sim_run:CoupledRtiProtectedOutputEnvelopeHash', ...
        'The protected-output envelope artifact hash changed.');
    request.protectedOutputEnvelope = value.protectedOutputEnvelope;
    request.protectedOutputEnvelopeSha256 = expectedEnvelopeHash;
end
assert(~(request.usePlantFlexibleStateOracle && ...
    request.usePlantChiStateOracle), ...
    'sim_run:CoupledRtiAllocatorOracleConflict', ...
    'The full-state and chi-only plant oracles are mutually exclusive.');
assert(~request.estimatorConditionedSafetyGate || ...
    ~(request.usePlantFlexibleStateOracle || request.usePlantChiStateOracle), ...
    'sim_run:CoupledRtiEstimatorGateOracle', ...
    ['The estimator-conditioned gate cannot be combined with a plant-state ', ...
    'oracle.']);
assert((request.predictionIntervals == 3 || ...
    (request.dynamicNullspaceWingOnly && request.predictionIntervals == 10)) && ...
    isfinite(request.finiteDifferenceStep) && ...
    request.finiteDifferenceStep > 0 && ...
    request.finiteDifferenceStep <= 1e-2, ...
    'sim_run:CoupledRtiAllocatorConfiguration', ...
    'The first persistent coupled RTI configuration is not qualified.');
end

function request = localWingActuatorBypassAuditRequest(value)
%LOCALWINGACTUATORBYPASSAUDITREQUEST Validate the bounded identity audit.
