function uOuter = localScaleSymmetricOuterWingReference(uOuter,fuser,request, ...
    nSurface,varPer)
%LOCALSCALESYMMETRICOUTERWINGREFERENCE Scale only the nominal symmetric input.
assert(request.enabled && request.auditOnly && request.scale==25, ...
    'sim_run:SymmetricWingAuthorityDiscriminatorContract', ...
    'The authority-scale path requires its validated audit request.');
assert(~isempty(fuser) && nSurface==2 && any(varPer==[1,2]) && ...
    numel(uOuter)==nSurface*varPer && numel(fuser.uTrim)==numel(uOuter), ...
    'sim_run:SymmetricWingAuthorityDiscriminatorDimensions', ...
    'The authority discriminator requires the two-surface shared-wing contract.');
trimWing = fuser.uTrim(1:nSurface);
wingDeviation = uOuter(1:nSurface)-trimWing;
assert(norm(wingDeviation-wingDeviation(1),inf)<=1e-12, ...
    'sim_run:SymmetricWingAuthorityDiscriminatorSymmetry', ...
    'The authority discriminator may only scale an exactly symmetric wing request.');
uOuter(1:nSurface) = trimWing + request.scale*wingDeviation;
assert(all(isfinite(uOuter)), ...
    'sim_run:SymmetricWingAuthorityDiscriminatorFinite', ...
    'The scaled outer-wing reference must remain finite.');
end

