function model = localLoadVirtualDemandSharedSurfaceModel(request)
path = char(request.modelArtifactPath);
assert(isfile(path),'sim_run:VirtualDemandSharedSurfaceModel', ...
    'The bound virtual-demand model artifact is missing.');
assert(localVirtualDemandFileHash(path)==request.expectedModelSha256, ...
    'sim_run:VirtualDemandSharedSurfaceHash', ...
    'The bound virtual-demand model artifact hash changed.');
data = load(path,'Acompact','Brealized','artifact');
assert(isfield(data,'artifact') && string(data.artifact.status)== ...
    "PASS_AUDIT_ONLY_REALIZED_INPUT_MODEL" && ...
    isequal(size(data.Acompact),[6,6]) && isequal(size(data.Brealized),[6,3]), ...
    'sim_run:VirtualDemandSharedSurfaceContract', ...
    'The bound model is not the certified six-state realized input map.');
model = struct('A',double(data.Acompact),'B',double(data.Brealized), ...
    'stateScale',[2;1;deg2rad(8);deg2rad(20)], ...
    'inputScale',[deg2rad(10);deg2rad(10);0.5]);
end

function digest = localVirtualDemandFileHash(path)
engine = javaMethod('getInstance','java.security.MessageDigest','SHA-256');
file = fopen(path,'rb'); assert(file>=0,'sim_run:VirtualDemandHashOpen', ...
    'Cannot read %s.',path);
cleanup = onCleanup(@()fclose(file));
while ~feof(file)
    bytes = fread(file,1024*1024,'*uint8'); if isempty(bytes), break, end
    engine.update(typecast(bytes(:),'int8'));
end
digest = lower(string(reshape(dec2hex(typecast(engine.digest(),'uint8'),2).',1,[])));
clear cleanup
end

function request = localCorrectedModelRigidResidualAllocationRequest(value)
%LOCALCORRECTEDMODELRIGIDRESIDUALALLOCATIONREQUEST Bind the 100 Hz audit.
request = struct('enabled',false,'auditOnly',false,'source',"", ...
    'modelArtifactPath',"",'expectedModelSha256',"", ...
    'elevatorRateRadiansPerSecond',nan);
if isempty(fieldnames(value)), return, end
assert(isfield(value,'enable') && isscalar(value.enable) && ...
    (islogical(value.enable) || isnumeric(value.enable)) && ...
    isfinite(double(value.enable)) && any(double(value.enable)==[0,1]), ...
    'sim_run:CorrectedRigidResidualRequest', ...
    'The corrected residual enable must be a logical scalar.');
request.enabled = logical(value.enable);
if ~request.enabled, return, end
required = {'auditOnly','source','modelArtifactPath', ...
    'expectedModelSha256','elevatorRateRadiansPerSecond'};
for field = required
    assert(isfield(value,field{1}), ...
        'sim_run:CorrectedRigidResidualRequest', ...
        'The corrected residual request requires %s.',field{1});
end
assert(logical(value.auditOnly) && string(value.source)== ...
    "phase18c-v17a-casea-corrected-model-rigid-residual-allocation-integration-v1", ...
    'sim_run:CorrectedRigidResidualApproval', ...
    'The corrected residual allocator is audit-only and source-bound.');
rate = double(value.elevatorRateRadiansPerSecond);
assert(isscalar(rate) && isfinite(rate) && rate>0 && rate<=deg2rad(200), ...
    'sim_run:CorrectedRigidResidualRate', ...
    'The provisional elevator-rate bound is invalid.');
request.auditOnly = true;
request.source = string(value.source);
request.modelArtifactPath = string(value.modelArtifactPath);
request.expectedModelSha256 = lower(string(value.expectedModelSha256));
request.elevatorRateRadiansPerSecond = rate;
end

function model = localLoadCorrectedModelRigidResidualModel(request)
%LOCALLOADCORRECTEDMODELRIGIDRESIDUALMODEL Load the exact 100 Hz input map.
path = char(request.modelArtifactPath);
assert(isfile(path) && localVirtualDemandFileHash(path)== ...
    request.expectedModelSha256, ...
    'sim_run:CorrectedRigidResidualModelHash', ...
    'The corrected residual model artifact is missing or changed.');
data = load(path,'bundle','plant100','models','cfg','source');
assert(string(data.bundle.status)== ...
    "PASS_CORRECTED_NONWING_SOURCE_CONTROLLER_BUILD" && ...
    string(data.source.id)=="CASEA_U040_ALPHA_P01" && ...
    abs(double(data.cfg.ctrl.Ts)-0.01)<=10*eps(0.01), ...
    'sim_run:CorrectedRigidResidualModelOwner', ...
    'The corrected residual model does not own the exact 100 Hz source.');
modelIndex = find(abs([data.models.omegaRadPerSecond]- ...
    double(data.bundle.selectedCandidate.crossoverRadPerSecond))<=1e-14,1);
assert(isscalar(modelIndex) && ...
    isfield(data.models(modelIndex).lift,'innerA') && ...
    isfield(data.models(modelIndex).lift,'innerB') && ...
    isfield(data.plant100,'symmetricWingRateInput'), ...
    'sim_run:CorrectedRigidResidualInnerMap', ...
    'The selected controller bundle lacks its certified 100 Hz map.');
nx = size(data.plant100.Ad,1);
groups = data.plant100.stateGroups;
rows = [groups.bodyVelocity(1),groups.bodyVelocity(3), ...
    groups.euler(2),groups.bodyRate(2),nx+1,nx+2];
innerA = double(data.models(modelIndex).lift.innerA);
innerB = double(data.models(modelIndex).lift.innerB);
assert(isequal(size(innerA),[nx+2,nx+2]) && ...
    isequal(size(innerB),[nx+2,3]) && all(isfinite(innerA),'all') && ...
    all(isfinite(innerB),'all'), ...
    'sim_run:CorrectedRigidResidualInnerMap', ...
    'The certified 100 Hz realized map has invalid dimensions or values.');
physicalB = zeros(6,3);
physicalB(1:4,:) = double(data.plant100.Bd(rows(1:4),:));
wingRateB = zeros(6,1);
wingRateB(1:4) = double(data.plant100.symmetricWingRateInput(rows(1:4)));
model = struct('A',eye(6),'B',physicalB,'wingRateB',wingRateB, ...
    'stateScale',[2;1;deg2rad(8);deg2rad(20)], ...
    'inputScale',[deg2rad(10);deg2rad(10);0.5], ...
    'sampleTimeSeconds',double(data.cfg.ctrl.Ts), ...
    'sourcePackageSha256',string(data.source.packageSha256), ...
    'artifactSha256',request.expectedModelSha256, ...
    'stateRows',rows(:),'inputOrder',[ ...
    "physical_symmetric_wing_endpoint";"elevator";"thrust"], ...
    'wingRateInput',"physical_symmetric_wing_endpoint_rate");
end

