function request = localFullChannelLexicographicTrajectoryAllocationRequest(value)
%LOCALFULLCHANNELLEXICOGRAPHICTRAJECTORYALLOCATIONREQUEST Validate audit scope.
request = struct('enabled',false,'auditOnly',false,'source',"", ...
    'offlineFminconReferenceGovernor',false, ...
    'sourceRootCondensedMultiInputCoordination',false, ...
    'trajectoryMetricSharedAllocation',struct(), ...
    'normalizedRigidTrajectoryTube',struct(), ...
    'persistentSampleWindow',[inf,-inf]);
if isempty(fieldnames(value)), return, end
assert(isfield(value,'enable') && isscalar(value.enable) && ...
    (islogical(value.enable) || isnumeric(value.enable)) && ...
    isfinite(double(value.enable)) && any(double(value.enable)==[0,1]), ...
    'sim_run:FullChannelLexicographicRequest', ...
    'Full-channel lexicographic enable must be a logical scalar.');
request.enabled = logical(value.enable);
if ~request.enabled, return, end
assert(isfield(value,'auditOnly') && logical(value.auditOnly) && ...
    isfield(value,'source') && any(string(value.source)==[ ...
    "phase18c-v17a-casea-full-channel-lexicographic-trajectory-allocation-audit-v1", ...
    "phase18c-v17a-casea-nonlinear-outer-reference-governor-audit-v1", ...
    "phase18c-v17a-casea-joint-shared-surface-safety-coordination-audit-v1", ...
    "phase18c-v17a-casea-predictive-time-parameterized-joint-coordination-audit-v1", ...
    "phase18c-v17a-caseb-source-root-condensed-multi-input-coordination-discriminator-v1", ...
    "phase18c-v17a-caseb-trajectory-metric-shared-allocation-persistent-integration-v1"]), ...
    'sim_run:FullChannelLexicographicAuditOnly', ...
    'The full-channel allocation request is audit-only and source-bound.');
request.auditOnly = true;
request.source = string(value.source);
request.nonlinearOuterReferenceGovernor = request.source == ...
    "phase18c-v17a-casea-nonlinear-outer-reference-governor-audit-v1";
request.jointSharedSurfaceSafetyCoordination = request.source == ...
    "phase18c-v17a-casea-joint-shared-surface-safety-coordination-audit-v1";
request.timeParameterizedJointCoordination = request.source == ...
    "phase18c-v17a-casea-predictive-time-parameterized-joint-coordination-audit-v1";
request.sourceRootCondensedMultiInputCoordination = any(request.source == [ ...
    "phase18c-v17a-caseb-source-root-condensed-multi-input-coordination-discriminator-v1", ...
    "phase18c-v17a-caseb-trajectory-metric-shared-allocation-persistent-integration-v1"]);
trajectoryMetricSource = request.source == ...
    "phase18c-v17a-caseb-trajectory-metric-shared-allocation-persistent-integration-v1";
if request.sourceRootCondensedMultiInputCoordination
    request.jointSharedSurfaceSafetyCoordination = true;
    request.persistentSampleWindow = [141,150];
end
request.maximumAllocatorCalls = inf;
if isfield(value,'offlineFminconReferenceGovernor')
    assert(isscalar(value.offlineFminconReferenceGovernor) && ...
        (islogical(value.offlineFminconReferenceGovernor) || ...
        isnumeric(value.offlineFminconReferenceGovernor)) && ...
        isfinite(double(value.offlineFminconReferenceGovernor)) && ...
        any(double(value.offlineFminconReferenceGovernor)==[0,1]), ...
        'sim_run:FullChannelFminconReferenceGovernor', ...
        'The fmincon reference-governor marker must be a logical scalar.');
    request.offlineFminconReferenceGovernor = logical( ...
        value.offlineFminconReferenceGovernor);
end
if request.offlineFminconReferenceGovernor
    assert(request.auditOnly && request.source== ...
        "phase18c-v17a-casea-full-channel-lexicographic-trajectory-allocation-audit-v1", ...
        'sim_run:FullChannelFminconReferenceGovernor', ...
        ['The fmincon reference-governor is restricted to the approved ', ...
        'full-channel Case-A audit.']);
end
request.debug = struct('enabled',false,'printIterations',false);
request.solverAlgorithm = "sqp";
request.primarySolver = "fmincon-sqp";
request.primarySafeFallback = false;
request.condensedFirstMove = struct();
request.trustRegionContinuation = struct();
request.feasibilityTail = struct();
request.predictiveFeasibilityActivation = struct('enabled',false, ...
    'auditOnly',false,'source',"");
request.rowScaling = struct();
request.centeredRootWrenchGustRecovery = struct();
if request.nonlinearOuterReferenceGovernor || ...
        request.jointSharedSurfaceSafetyCoordination
    % Keep the governor bounded to its immediate physical correction.
    % The remaining preview intervals still enforce all replayed hard
    % constraints while the first move is the only decision variable.
    request.condensedFirstMove = struct('enabled',true,'auditOnly',true, ...
        'source',request.source);
end
if request.sourceRootCondensedMultiInputCoordination
    request.coupledNmpcPredictor = struct('enabled',true, ...
        'auditOnly',true,'source',request.source);
    request.futureScheduledPackageSequence = struct( ...
        'enabled',true,'auditOnly',true);
    request.sourceRootCoordination = struct('enabled',true, ...
        'auditOnly',true,'source',request.source);
    if trajectoryMetricSource
        request.trajectoryMetricSharedAllocation = struct( ...
            'enabled',true,'auditOnly',true,'source',request.source, ...
            'priority',"flexible_first_rigid_near_tie");
    end
end
if isfield(value,'normalizedRigidTrajectoryTube') && ...
        ~isempty(value.normalizedRigidTrajectoryTube)
    tube = value.normalizedRigidTrajectoryTube;
    assert(isstruct(tube) && isscalar(tube) && ...
        isfield(tube,'enable') && isscalar(tube.enable) && ...
        (islogical(tube.enable) || isnumeric(tube.enable)) && ...
        isfinite(double(tube.enable)) && any(double(tube.enable)==[0,1]), ...
        'sim_run:NormalizedRigidTrajectoryTubeEnable', ...
        'The normalized rigid-trajectory tube enable must be logical.');
    if ~logical(tube.enable)
        tube = struct();
    end
else
    tube = struct();
end
if ~isempty(fieldnames(tube))
    tubeSource = ...
        "phase18c-v17a-caseb-normalized-rigid-trajectory-tube-coordination-audit-v1";
    assert(trajectoryMetricSource && logical(tube.enable) && ...
        isfield(tube,'auditOnly') && logical(tube.auditOnly) && ...
        isfield(tube,'source') && string(tube.source)==tubeSource && ...
        isfield(tube,'fractions') && ...
        isequal(double(tube.fractions(:)),[0.001;0.01;0.05]) && ...
        isfield(tube,'auditFraction') && ...
        double(tube.auditFraction)==0.05, ...
        'sim_run:NormalizedRigidTrajectoryTube', ...
        ['The normalized rigid-trajectory tube requires the approved ', ...
        'Case-B trajectory-metric request and fixed tube contract.']);
    request.normalizedRigidTrajectoryTube = struct('enabled',true, ...
        'auditOnly',true,'source',tubeSource, ...
        'fractions',[0.001;0.01;0.05],'auditFraction',0.05);
    request.trajectoryMetricSharedAllocation. ...
        normalizedRigidTrajectoryTube = ...
        request.normalizedRigidTrajectoryTube;
end
if request.timeParameterizedJointCoordination
    request.jointSharedSurfaceSafetyCoordination = true;
    request.maximumAllocatorCalls = 1;
    request.condensedFirstMove = struct('enabled',false,'auditOnly',true, ...
        'source',request.source);
end
if isfield(value,'debug') && ~isempty(value.debug)
    assert(isstruct(value.debug) && isscalar(value.debug) && ...
        isfield(value.debug,'enabled') && isscalar(value.debug.enabled) && ...
        (islogical(value.debug.enabled) || isnumeric(value.debug.enabled)), ...
        'sim_run:FullChannelLexicographicDebug', ...
        'The audit-only debug request must contain a logical enabled flag.');
    request.debug.enabled = logical(value.debug.enabled);
    if isfield(value.debug,'printIterations')
        assert(isscalar(value.debug.printIterations) && ...
            (islogical(value.debug.printIterations) || ...
            isnumeric(value.debug.printIterations)), ...
            'sim_run:FullChannelLexicographicDebug', ...
            'printIterations must be a logical scalar.');
        request.debug.printIterations = logical(value.debug.printIterations);
    end
end
if isfield(value,'solverAlgorithm')
    request.solverAlgorithm = lower(string(value.solverAlgorithm));
    assert(isscalar(request.solverAlgorithm) && ...
        any(request.solverAlgorithm == ["sqp","interior-point"]), ...
        'sim_run:FullChannelLexicographicAlgorithm', ...
        'The audit-only full-channel solver must be sqp or interior-point.');
end
if isfield(value,'primarySolver')
    request.primarySolver = lower(string(value.primarySolver));
    assert(isscalar(request.primarySolver) && any( ...
        request.primarySolver == ["fmincon-sqp", ...
        "quadprog-interior-point-convex"]), ...
        'sim_run:FullChannelLexicographicPrimarySolver', ...
        'The full-channel primary solver request is invalid.');
end
if isfield(value,'primarySafeFallback')
    assert(isscalar(value.primarySafeFallback) && ...
        (islogical(value.primarySafeFallback) || ...
        isnumeric(value.primarySafeFallback)) && ...
        isfinite(double(value.primarySafeFallback)) && ...
        any(double(value.primarySafeFallback)==[0,1]), ...
        'sim_run:FullChannelLexicographicPrimarySafeFallback', ...
        'primarySafeFallback must be a logical scalar.');
    request.primarySafeFallback = logical(value.primarySafeFallback);
end
if isfield(value,'condensedFirstMove') && ~isempty(value.condensedFirstMove)
    condensed = value.condensedFirstMove;
    assert(isstruct(condensed) && isscalar(condensed) && ...
        isfield(condensed,'enable') && isfield(condensed,'auditOnly') && ...
        isfield(condensed,'source') && isscalar(condensed.enable) && ...
        logical(condensed.enable) && logical(condensed.auditOnly) && ...
        any(string(condensed.source) == [ ...
        "phase18c-v17a-casea-condensed-first-move-full-channel-allocation-audit-v1", ...
        "phase18c-v17a-casea-nonlinear-outer-reference-governor-audit-v1"]), ...
        'sim_run:FullChannelCondensedFirstMove', ...
        ['The condensed first-move parameterization requires an explicit ', ...
        'approved audit-only request.']);
    request.condensedFirstMove = struct('enabled',true,'auditOnly',true, ...
        'source',string(condensed.source));
end
if isfield(value,'trustRegionContinuation') && ...
        ~isempty(value.trustRegionContinuation)
    continuation = value.trustRegionContinuation;
    assert(isstruct(continuation) && isscalar(continuation) && ...
        isfield(continuation,'enable') && isfield(continuation,'auditOnly') && ...
        isfield(continuation,'source') && isfield(continuation,'candidateBounds') && ...
        isscalar(continuation.enable) && logical(continuation.enable) && ...
        logical(continuation.auditOnly) && string(continuation.source) == ...
        "phase18c-v17a-casea-full-channel-trust-region-continuation-audit-v1", ...
        'sim_run:FullChannelTrustRegionContinuation', ...
        'The continuation request must be explicitly approved and audit-only.');
    candidateBounds = double(continuation.candidateBounds(:).');
    assert(isequal(candidateBounds,[0.25,0.50,0.75,1.00]), ...
        'sim_run:FullChannelTrustRegionCandidates', ...
        'The continuation request requires [0.25 0.50 0.75 1.00].');
    request.trustRegionContinuation = struct('enabled',true,'auditOnly',true, ...
        'source',string(continuation.source),'candidateBounds',candidateBounds);
end
if isfield(value,'feasibilityTail') && ~isempty(value.feasibilityTail)
    tail = value.feasibilityTail;
    assert(isstruct(tail) && isscalar(tail) && isfield(tail,'enable') && ...
        isfield(tail,'auditOnly') && isfield(tail,'source') && ...
        isfield(tail,'intervals') && isscalar(tail.enable) && ...
        logical(tail.enable) && logical(tail.auditOnly) && ...
        string(tail.source) == ...
        "phase18c-v17a-casea-full-channel-feasibility-tail-audit-v1" && ...
        double(tail.intervals) == 10, ...
        'sim_run:FullChannelFeasibilityTail', ...
        'The feasibility tail must match its approved audit-only request.');
    request.feasibilityTail = struct('enabled',true,'auditOnly',true, ...
        'source',string(tail.source),'intervals',10);
    if isfield(tail,'maximumAllocatorCalls')
        maximumCalls = double(tail.maximumAllocatorCalls);
        assert(isscalar(maximumCalls) && isfinite(maximumCalls) && ...
            maximumCalls >= 1 && maximumCalls == round(maximumCalls), ...
            'sim_run:FullChannelFeasibilityTailCallLimit', ...
            'maximumAllocatorCalls must be a positive integer.');
        request.feasibilityTail.maximumAllocatorCalls = maximumCalls;
    end
end
if isfield(value,'predictiveFeasibilityActivation') && ...
        ~isempty(value.predictiveFeasibilityActivation)
    activation = value.predictiveFeasibilityActivation;
    assert(isstruct(activation) && isscalar(activation) && ...
        isfield(activation,'enable') && isscalar(activation.enable) && ...
        logical(activation.enable) && isfield(activation,'auditOnly') && ...
        logical(activation.auditOnly) && isfield(activation,'source') && ...
        string(activation.source) == ...
        "phase18c-v17a-casea-predictive-feasibility-tail-activation-audit-v1", ...
        'sim_run:PredictiveFeasibilityActivation', ...
        ['Predictive feasibility activation requires its explicit ', ...
        'approved audit-only source.']);
    request.predictiveFeasibilityActivation = struct('enabled',true, ...
        'auditOnly',true,'source',string(activation.source));
end
if isfield(value,'rowScaling') && ~isempty(value.rowScaling)
    scaling = value.rowScaling;
    assert(isstruct(scaling) && isscalar(scaling) && ...
        isfield(scaling,'enable') && isscalar(scaling.enable) && ...
        (islogical(scaling.enable) || isnumeric(scaling.enable)) && ...
        isfinite(double(scaling.enable)) && any(double(scaling.enable)==[0,1]) && ...
        isfield(scaling,'auditOnly') && isscalar(scaling.auditOnly) && ...
        logical(scaling.auditOnly) && isfield(scaling,'source') && ...
        string(scaling.source) == ...
        "phase18c-v17a-casea-full-channel-row-scaling-equivalence-audit-v1", ...
        'sim_run:FullChannelRowScaling', ...
        'The full-channel row scaling request must match its approved audit-only source.');
    request.rowScaling = struct('enabled',logical(scaling.enable), ...
        'auditOnly',true,'source',string(scaling.source));
end
if isfield(value,'centeredRootWrenchGustRecovery') && ...
        ~isempty(value.centeredRootWrenchGustRecovery)
    recovery = value.centeredRootWrenchGustRecovery;
    assert(isstruct(recovery) && isscalar(recovery) && ...
        isfield(recovery,'enable') && logical(recovery.enable) && ...
        isfield(recovery,'auditOnly') && logical(recovery.auditOnly) && ...
        isfield(recovery,'source') && string(recovery.source) == ...
        "phase18c-v17a-centered-root-wrench-gust-recovery-audit-v1", ...
        'sim_run:CenteredRootWrenchGustRecovery', ...
        'Centered root-wrench gust recovery requires its audit-only request.');
    request.centeredRootWrenchGustRecovery = struct('enabled',true, ...
        'auditOnly',true,'source',string(recovery.source));
end
end

function [uOuter,rigidIncrement,info] = localRealizedOuterAllocation( ...
    preview,plant,package,fusion,actuator,controller,xFlexible, ...
    uPrevious,uCandidate,rigidCandidate,rigidReference,gust,previous)
%LOCALREALIZEDOUTERALLOCATION Backtrack against preceding nonlinear endpoint.
alphaGrid = [1,0.5,0.25,0.125,0.0625,0];
gustHorizon = repmat(gust(:),1,3);
baselineRigid = localRigidCommandFromIncrement(previous.rigidIncrement);
baseline = preview.previewFirstInterval(plant,package,fusion,actuator, ...
    xFlexible,uPrevious,previous.uOuter,baselineRigid,gustHorizon,zeros(2,3));
baselineError = localOuterPreviewError(baseline,rigidReference);
accepted = false; selected = 0; candidate = baseline;
for alpha = alphaGrid
    uTry = previous.uOuter + alpha*(uCandidate-previous.uOuter);
    rTry = previous.rigidIncrement + alpha*(rigidCandidate-previous.rigidIncrement);
    assert(plant.trimThrust+rTry(4)>=0, ...
        'sim_run:RealizedOuterAllocationThrust','Backtracking violated T >= 0.');
    trajectory = preview.previewFirstInterval(plant,package,fusion,actuator, ...
        xFlexible,uPrevious,uTry,localRigidCommandFromIncrement(rTry), ...
        gustHorizon,zeros(2,3));
    error = localOuterPreviewError(trajectory,rigidReference);
    sameOrBetter = all(abs(error) <= abs(baselineError)+1e-10,"all");
    loadSafe = max(abs(trajectory.wingtip)) <= max(abs(baseline.wingtip))+1e-10 && ...
        max(abs(trajectory.clampFz)) <= max(abs(baseline.clampFz))+1e-8 && ...
        max(abs(trajectory.clampMy)) <= max(abs(baseline.clampMy))+1e-8;
    if all(isfinite([error(:);trajectory.wingtip(:);trajectory.clampFz(:); ...
            trajectory.clampMy(:)])) && sameOrBetter && loadSafe
        accepted = true; selected = alpha; candidate = trajectory; break
    end
end
uOuter = previous.uOuter + selected*(uCandidate-previous.uOuter);
rigidIncrement = previous.rigidIncrement + selected*(rigidCandidate-previous.rigidIncrement);
info = struct('enabled',true,'accepted',accepted,'alpha',selected, ...
    'fallback',~accepted || selected==0,'baselineError',baselineError, ...
    'candidateError',localOuterPreviewError(candidate,rigidReference));
end

function command = localRigidCommandFromIncrement(increment)
increment = increment(:);
assert(isequal(size(increment),[4,1]) && all(isfinite(increment)), ...
    'sim_run:RealizedOuterAllocationIncrement','Rigid increment is invalid.');
command = struct('delta_e',increment(1),'delta_a',increment(2), ...
    'delta_r',increment(3),'thrust',increment(4));
end

function error = localOuterPreviewError(trajectory,reference)
reference = reference(:);
assert(isequal(size(reference),[9,1]), ...
    'sim_run:RealizedOuterAllocationReference','Rigid reference is invalid.');
error = [trajectory.uBody-reference(1),trajectory.wBody-reference(3), ...
    atan2(sin(trajectory.theta-reference(5)),cos(trajectory.theta-reference(5))), ...
    trajectory.pitchRate-reference(8)];
end

function request = localRuntimeCheckpointAuditRequest(value)
%LOCALRUNTIMECHECKPOINTAUDITREQUEST Validate exact-runtime capture request.
request = struct('enabled',false,'auditOnly',false,'sampleIndices',[]);
if isempty(fieldnames(value))
    return
end
assert(isfield(value,'enable') && isscalar(value.enable) && ...
    (islogical(value.enable) || isnumeric(value.enable)) && ...
    isfinite(double(value.enable)) && any(double(value.enable) == [0,1]), ...
    'sim_run:RuntimeCheckpointRequest', ...
    'Runtime-checkpoint enable must be a logical scalar.');
request.enabled = logical(value.enable);
if ~request.enabled
    return
end
assert(isfield(value,'auditOnly') && isscalar(value.auditOnly) && ...
    (islogical(value.auditOnly) || isnumeric(value.auditOnly)) && ...
    isfinite(double(value.auditOnly)) && double(value.auditOnly) == 1, ...
    'sim_run:RuntimeCheckpointAuditOnly', ...
    'An enabled runtime-checkpoint request is audit-only.');
assert(isfield(value,'sampleIndices') && isnumeric(value.sampleIndices) && ...
    isreal(value.sampleIndices) && isvector(value.sampleIndices) && ...
    ~isempty(value.sampleIndices) && all(isfinite(value.sampleIndices)) && ...
    all(value.sampleIndices >= 1) && ...
    all(value.sampleIndices == round(value.sampleIndices)), ...
    'sim_run:RuntimeCheckpointSamples', ...
    'Runtime-checkpoint sampleIndices must be positive integers.');
request.auditOnly = true;
request.sampleIndices = unique(double(value.sampleIndices(:).'));
end

function request = localDeferredOutputAuditRequest(cfg)
%LOCALDEFERREDOUTPUTAUDITREQUEST Guard the approved Case-B diagnostic switch.
request = struct('enabled',false,'auditOnly',false,'source',"disabled");
if ~isfield(cfg,'sim') || ~isfield(cfg.sim,'deferredOutputAudit') || ...
        isempty(cfg.sim.deferredOutputAudit)
    return
end
value = cfg.sim.deferredOutputAudit;
assert(isstruct(value) && isscalar(value) && isfield(value,'enabled') && ...
    isscalar(value.enabled) && logical(value.enabled) && ...
    isfield(value,'auditOnly') && logical(value.auditOnly) && ...
    isfield(value,'source') && string(value.source)== ...
    "phase18c-v17a-caseb-exact-package-reuse-output-decoupling-audit-v1", ...
    'sim_run:DeferredOutputAuditScope', ...
    'Deferred output is restricted to the approved Case-B audit.');
request.enabled = true;
request.auditOnly = true;
request.source = string(value.source);
end

function request = localRuntimeSegmentAuditRequest(value)
%LOCALRUNTIMESEGMENTAUDITREQUEST Validate an approved stop/resume request.
request = struct('enabled',false,'auditOnly',false, ...
    'source',"disabled",'checkpointPath',"", ...
    'stopSample',inf,'resume',false,'sourceRebind',struct());
if isempty(fieldnames(value))
    return
end
assert(isfield(value,'enable') && isscalar(value.enable) && ...
    (islogical(value.enable) || isnumeric(value.enable)) && ...
    isfinite(double(value.enable)) && any(double(value.enable)==[0,1]), ...
    'sim_run:RuntimeSegmentEnable', ...
    'Runtime-segment enable must be a logical scalar.');
request.enabled = logical(value.enable);
if ~request.enabled
    return
end
allowedSources = [ ...
    "phase18c-v17a-formal-casea-integrated-resumable-execution-v1", ...
    "phase18c-v17a-casebc-integrated-resumable-execution-v1"];
assert(isfield(value,'auditOnly') && isscalar(value.auditOnly) && ...
    logical(value.auditOnly) && isfield(value,'source') && ...
    any(string(value.source)==allowedSources), ...
    'sim_run:RuntimeSegmentApproval', ...
    ['Runtime segmentation requires the approved audit-only ', ...
    'Case-A or Case-B/C source.']);
assert(isfield(value,'checkpointPath') && ...
    (ischar(value.checkpointPath) || isstring(value.checkpointPath)) && ...
    strlength(string(value.checkpointPath))>0, ...
    'sim_run:RuntimeSegmentCheckpointPath', ...
    'Runtime segmentation requires a nonempty checkpoint path.');
assert(isfield(value,'stopSample') && isscalar(value.stopSample) && ...
    isnumeric(value.stopSample) && isfinite(value.stopSample) && ...
    value.stopSample>=1 && value.stopSample==round(value.stopSample), ...
    'sim_run:RuntimeSegmentStopSample', ...
    'Runtime-segment stopSample must be a positive integer.');
request.auditOnly = true;
request.source = string(value.source);
request.checkpointPath = string(value.checkpointPath);
request.stopSample = double(value.stopSample);
if isfield(value,'resume')
    assert(isscalar(value.resume) && ...
        (islogical(value.resume) || isnumeric(value.resume)) && ...
        isfinite(double(value.resume)) && any(double(value.resume)==[0,1]), ...
        'sim_run:RuntimeSegmentResume', ...
        'Runtime-segment resume must be a logical scalar.');
    request.resume = logical(value.resume);
end
if request.resume
    assert(isfile(request.checkpointPath), ...
        'sim_run:RuntimeSegmentMissingCheckpoint', ...
        'The requested runtime-segment checkpoint does not exist.');
else
    assert(~isfile(request.checkpointPath), ...
        'sim_run:RuntimeSegmentExistingCheckpoint', ...
        ['A fresh segmented run cannot overwrite an existing ', ...
        'checkpoint.']);
end
if isfield(value,'sourceRebind') && ~isempty(value.sourceRebind)
    rebind = value.sourceRebind;
    rebindSources = [ ...
        "phase18c-v17a-caseb-trajectory-metric-shared-allocation-persistent-integration-v1"; ...
        "phase18c-v17a-casebc-resumed-debug-trace-owner-correction-v1"];
    assert(request.resume && request.source== ...
        "phase18c-v17a-casebc-integrated-resumable-execution-v1" && ...
        isstruct(rebind) && isscalar(rebind) && ...
        isfield(rebind,'enabled') && logical(rebind.enabled) && ...
        isfield(rebind,'auditOnly') && logical(rebind.auditOnly) && ...
        isfield(rebind,'source') && any(string(rebind.source)==rebindSources), ...
        'sim_run:RuntimeSegmentSourceRebind', ...
        ['A source rebind is restricted to the approved trajectory-metric ', ...
        'Case-B continuation.']);
    request.sourceRebind = struct('enabled',true,'auditOnly',true, ...
        'source',string(rebind.source));
end
end

function signature = localRuntimeSegmentSourceSignature( ...
    repositoryRoot,source)
%LOCALRUNTIMESEGMENTSOURCESIGNATURE Bind a resume to its executable owners.
relativePaths = [ ...
    "MatlabFlex/sim_run.m"; ...
    "MatlabFlex/+AeroFlex/+sim/PlantRunTime.m"; ...
    "MatlabFlex/+AeroFlex/+ctrl/@nMHEv2/nMHEv2.m"; ...
    "MatlabFlex/+AeroFlex/+ctrl/@nMPC/nMPC.m"; ...
    "MatlabFlex/+AeroFlex/+ctrl/SourceCoordinateOuterFeedback.m"; ...
    "MatlabFlex/+AeroFlex/+ctrl/ComplementaryCommandFusion.m"; ...
    "MatlabFlex/+AeroFlex/+ctrl/ActuatorChain.m"];
if string(source)== ...
        "phase18c-v17a-casebc-integrated-resumable-execution-v1"
    relativePaths = [relativePaths; ...
        "MatlabFlex/+AeroFlex/+ctrl/ScheduledReciprocalControllerModelProvider.m"; ...
        "MatlabFlex/+AeroFlex/+ctrl/CoupledRtiAllocatorAudit.m"; ...
        "MatlabFlex/+AeroFlex/+sched/evalLibrary.m"; ...
        "MatlabFlex/+AeroFlex/+sched/buildPhysicalChartPackage.m"; ...
        "MatlabFlex/+AeroFlex/+sched/buildFullCoordinateQueryRealization.m"; ...
        "MatlabFlex/+AeroFlex/+sched/buildScheduledReciprocalPacket.m"; ...
        "MatlabFlex/+AeroFlex/+benchmark/+runtime/run_phase18c_v17a_caseb_integrated_profile_v1.m"];
end
hashes = strings(size(relativePaths));
for index = 1:numel(relativePaths)
    path = fullfile(repositoryRoot,relativePaths(index));
    assert(isfile(path),'sim_run:RuntimeSegmentSource', ...
        'A runtime-segment source is unavailable: %s.',path);
    hashes(index) = localStructuredVirtualPitchFileHash(path);
end
signature = struct('relativePaths',relativePaths, ...
    'sha256',hashes);
end

function info = localRuntimeSegmentSourceRebind(previous,current,request)
%LOCALRUNTIMESEGMENTSOURCEREBIND Permit only approved allocator-source changes.
info = struct('enabled',false,'applied',false,'source',"", ...
    'changedPaths',strings(0,1),'previousSha256',strings(0,1), ...
    'currentSha256',strings(0,1));
if ~isfield(request,'sourceRebind') || ...
        isempty(fieldnames(request.sourceRebind))
    return
end
rebind = request.sourceRebind;
trajectoryRebindSource = ...
    "phase18c-v17a-caseb-trajectory-metric-shared-allocation-persistent-integration-v1";
debugTraceRebindSource = ...
    "phase18c-v17a-casebc-resumed-debug-trace-owner-correction-v1";
assert(logical(rebind.enabled) && logical(rebind.auditOnly) && ...
    any(string(rebind.source)==[trajectoryRebindSource;debugTraceRebindSource]), ...
    'sim_run:RuntimeSegmentSourceRebind', ...
    'The runtime source-rebind request is not approved.');
[previousPaths,currentPaths] = ...
    AeroFlex.benchmark.internal.canonicalizeRuntimeSegmentSignaturePaths( ...
    previous,current);
previousHashes = string(previous.sha256);
currentHashes = string(current.sha256);
cacheOwners = [ ...
    "MatlabFlex/sim_run.m"; ...
    "MatlabFlex/+AeroFlex/+sim/PlantRunTime.m"; ...
    "MatlabFlex/+AeroFlex/+sched/buildPhysicalChartPackage.m"; ...
    "MatlabFlex/+AeroFlex/+sched/buildFullCoordinateQueryRealization.m"];
compatibleLayout = isequal(previousPaths,currentPaths) || ...
    isequal(previousPaths,currentPaths(~ismember(currentPaths,cacheOwners)));
assert(compatibleLayout && all(ismember(previousPaths,currentPaths)), ...
    'sim_run:RuntimeSegmentSourceRebindLayout', ...
    ['The runtime source-signature layout changed outside the approved ', ...
    'immutable-metadata cache owners.']);
info.enabled = true;
info.source = string(rebind.source);
if isequal(previousPaths,currentPaths) && ...
        isequal(string(previous.sha256),string(current.sha256))
    return
end
changedPaths = strings(0,1);
for index = 1:numel(currentPaths)
    previousIndex = find(previousPaths==currentPaths(index),1,'first');
    if isempty(previousIndex) || ...
            previousHashes(previousIndex)~=currentHashes(index)
        changedPaths(end+1,1) = currentPaths(index); %#ok<AGROW>
    end
end
if string(rebind.source)==debugTraceRebindSource
    permitted = "MatlabFlex/sim_run.m";
else
    permitted = [ ...
        "MatlabFlex/sim_run.m"; ...
        "MatlabFlex/+AeroFlex/+sim/PlantRunTime.m"; ...
        "MatlabFlex/+AeroFlex/+ctrl/CoupledRtiAllocatorAudit.m"; ...
        "MatlabFlex/+AeroFlex/+sched/evalLibrary.m"; ...
        "MatlabFlex/+AeroFlex/+sched/buildPhysicalChartPackage.m"; ...
        "MatlabFlex/+AeroFlex/+sched/buildFullCoordinateQueryRealization.m"; ...
        "MatlabFlex/+AeroFlex/+benchmark/+runtime/run_phase18c_v17a_caseb_integrated_profile_v1.m"];
end
assert(~isempty(changedPaths) && all(ismember(changedPaths,permitted)), ...
    'sim_run:RuntimeSegmentSourceRebindFiles', ...
    ['Only the approved trajectory-metric allocator, request plumbing, ', ...
    'and bounded runner may differ from the S140 checkpoint signature.']);
info = struct('enabled',true,'applied',true, ...
    'source',string(rebind.source),'changedPaths',changedPaths, ...
    'previousSha256',previousHashes(ismember(previousPaths,changedPaths)), ...
    'currentSha256',currentHashes(ismember(currentPaths,changedPaths)));
end

function schema = localRuntimeSegmentSchema(source)
%LOCALRUNTIMESEGMENTSCHEMA Keep each approved checkpoint family distinct.
if string(source)== ...
        "phase18c-v17a-formal-casea-integrated-resumable-execution-v1"
    schema = ...
        "phase18c-v17a-formal-casea-integrated-runtime-segment-v1";
    return
end
assert(string(source)== ...
    "phase18c-v17a-casebc-integrated-resumable-execution-v1", ...
    'sim_run:RuntimeSegmentSchemaSource', ...
    'The runtime-segment source has no checkpoint schema.');
schema = ...
    "phase18c-v17a-casebc-scheduled-reciprocal-runtime-segment-v1";
end

function localSaveRuntimeSegmentCheckpoint(path,runtimeSegmentCheckpoint)
%LOCALSAVERUNTIMESEGMENTCHECKPOINT Complete locally before UNC transfer.
temporaryPath = string(tempname)+".mat";
cleanup = onCleanup(@()localDeleteTemporaryCheckpoint(temporaryPath));
save(temporaryPath,'runtimeSegmentCheckpoint','-v7');
[copied,message] = copyfile(temporaryPath,path,'f');
assert(copied,'sim_run:RuntimeSegmentCheckpointCopy', ...
    'Unable to copy the completed runtime checkpoint: %s',message);
clear cleanup
localDeleteTemporaryCheckpoint(temporaryPath);
end

function runtimeSegmentCheckpoint = ...
    localLoadRuntimeSegmentCheckpoint(path)
%LOCALLOADRUNTIMESEGMENTCHECKPOINT Avoid direct HDF5 access across UNC.
temporaryPath = string(tempname)+".mat";
cleanup = onCleanup(@()localDeleteTemporaryCheckpoint(temporaryPath));
[copied,message] = copyfile(path,temporaryPath,'f');
assert(copied,'sim_run:RuntimeSegmentCheckpointLocalCopy', ...
    'Unable to copy the runtime checkpoint locally: %s',message);
loaded = load(temporaryPath,'runtimeSegmentCheckpoint');
assert(isfield(loaded,'runtimeSegmentCheckpoint'), ...
    'sim_run:RuntimeSegmentCheckpointVariable', ...
    'The runtime-segment checkpoint variable is missing.');
runtimeSegmentCheckpoint = loaded.runtimeSegmentCheckpoint;
clear cleanup
localDeleteTemporaryCheckpoint(temporaryPath);
end

function localDeleteTemporaryCheckpoint(path)
%LOCALDELETETEMPORARYCHECKPOINT Remove only this call's local temporary file.
if isfile(path)
    delete(path);
end
end

function request = localGustRigidResponseDomainAuditRequest(value)
%LOCALGUSTRIGIDRESPONSEDOMAINAUDITREQUEST Validate the approved Case-A probe.
request = struct('enabled',false,'auditOnly',false,'sampleIndices',[], ...
    'finiteDifferenceStep',2.5e-3,'wingStepsRadians',deg2rad([0.25,0.5]), ...
    'elevatorStepsRadians',deg2rad([0.25,0.5]), ...
    'thrustStepsNewtons',[0.0025,0.005], ...
    'source',"disabled");
if isempty(fieldnames(value))
    return
end
assert(isfield(value,'enable') && isscalar(value.enable) && ...
    (islogical(value.enable) || isnumeric(value.enable)) && ...
    isfinite(double(value.enable)) && any(double(value.enable)==[0,1]), ...
    'sim_run:GustRigidResponseDomainEnable', ...
    'The gust rigid-response diagnostic enable field must be logical.');
request.enabled = logical(value.enable);
if ~request.enabled
    return
end
assert(isfield(value,'auditOnly') && isscalar(value.auditOnly) && ...
    logical(value.auditOnly) && isfield(value,'source') && ...
    string(value.source)== ...
    "phase18c-v17a-casea-gust-rigid-response-domain-discriminator-v1", ...
    'sim_run:GustRigidResponseDomainApproval', ...
    'The gust rigid-response diagnostic requires its approved audit source.');
assert(isfield(value,'sampleIndices') && isnumeric(value.sampleIndices) && ...
    isvector(value.sampleIndices) && ~isempty(value.sampleIndices) && ...
    all(isfinite(value.sampleIndices)) && all(value.sampleIndices>=1) && ...
    all(value.sampleIndices==round(value.sampleIndices)), ...
    'sim_run:GustRigidResponseDomainSamples', ...
    'The gust rigid-response diagnostic requires positive integer samples.');
request.auditOnly = true;
request.source = string(value.source);
request.sampleIndices = unique(double(value.sampleIndices(:).'));
if isfield(value,'finiteDifferenceStep')
    request.finiteDifferenceStep = double(value.finiteDifferenceStep);
end
for name = ["wingStepsRadians","elevatorStepsRadians","thrustStepsNewtons"]
    field = char(name);
    if isfield(value,field)
        request.(field) = double(value.(field)(:).');
    end
    assert(isequal(size(request.(field)),[1,2]) && ...
        all(isfinite(request.(field))) && all(request.(field)>0), ...
        'sim_run:GustRigidResponseDomainSteps', ...
        'The %s diagnostic steps must be two positive finite values.',field);
end
assert(isfinite(request.finiteDifferenceStep) && ...
    request.finiteDifferenceStep>0 && request.finiteDifferenceStep<=1e-2, ...
    'sim_run:GustRigidResponseDomainDifferenceStep', ...
    'The diagnostic finite-difference step is invalid.');
end

function record = localGustRigidResponseDomainPreview(preview,plant, ...
    package,fusion,actuator,uPrevious,uOuter,rigidCommand,gust, ...
    rawInnerCommand,request)
%LOCALGUSTRIGIDRESPONSEDOMAINPREVIEW Clone-only nonlinear input probe.
assert(~isempty(preview) && plant.trimThrust+rigidCommand.thrust>=0, ...
    'sim_run:GustRigidResponseDomainRuntime', ...
    'The diagnostic runtime owner or thrust command is invalid.');
nSurface = numel(actuator.delta);
assert(nSurface==2 && numel(uOuter)==2*nSurface, ...
    'sim_run:GustRigidResponseDomainWingOrder', ...
    'The diagnostic requires two [deflection; rate] wing channels.');
assert(isequal(size(rawInnerCommand),[2*nSurface,1]) && ...
    all(isfinite(rawInnerCommand)), ...
    'sim_run:GustRigidResponseDomainRawInner', ...
    'The diagnostic requires the finite realized raw inner command.');
rates = zeros(nSurface,3);
gustHorizon = repmat(gust(:),1,3);
nominal = preview.previewFirstIntervalWithRawInner( ...
    plant,package,fusion,actuator,plant.xFlex,uPrevious,uOuter, ...
    rigidCommand,gustHorizon,rates,rawInnerCommand);
channels = struct('name',{'symmetric_wing','elevator','thrust'}, ...
    'steps',{request.wingStepsRadians,request.elevatorStepsRadians, ...
    request.thrustStepsNewtons},'derivative',cell(1,3), ...
    'positive',cell(1,3),'negative',cell(1,3));
for channelIndex = 1:numel(channels)
    derivative = nan(7,2);
    positive = cell(1,2); negative = cell(1,2);
    for stepIndex = 1:2
        step = channels(channelIndex).steps(stepIndex);
        uPlus = uOuter; uMinus = uOuter;
        rPlus = rigidCommand; rMinus = rigidCommand;
        switch channels(channelIndex).name
            case 'symmetric_wing'
                uPlus(1:nSurface) = uPlus(1:nSurface)+step;
                uMinus(1:nSurface) = uMinus(1:nSurface)-step;
            case 'elevator'
                rPlus.delta_e = rPlus.delta_e+step;
                rMinus.delta_e = rMinus.delta_e-step;
            case 'thrust'
                rPlus.thrust = rPlus.thrust+step;
                rMinus.thrust = rMinus.thrust-step;
        end
        assert(plant.trimThrust+rPlus.thrust>=0 && ...
            plant.trimThrust+rMinus.thrust>=0, ...
            'sim_run:GustRigidResponseDomainThrust', ...
            'The bounded diagnostic attempted negative total thrust.');
        positive{stepIndex} = preview.previewFirstIntervalWithRawInner( ...
            plant,package,fusion,actuator,plant.xFlex,uPrevious,uPlus, ...
            rPlus,gustHorizon,rates,rawInnerCommand);
        negative{stepIndex} = preview.previewFirstIntervalWithRawInner( ...
            plant,package,fusion,actuator,plant.xFlex,uPrevious,uMinus, ...
            rMinus,gustHorizon,rates,rawInnerCommand);
        derivative(:,stepIndex) = (localGustRigidResponseOutput( ...
            positive{stepIndex})-localGustRigidResponseOutput( ...
            negative{stepIndex}))/(2*step);
    end
    channels(channelIndex).derivative = derivative;
    channels(channelIndex).positive = positive;
    channels(channelIndex).negative = negative;
end
record = struct('schemaVersion', ...
    'phase18c-v17a-casea-gust-rigid-response-domain-discriminator-v1', ...
    'source',request.source,'timeSeconds',plant.t, ...
    'sampleIndex',plant.controlSampleIndex,'gust',gust(:), ...
    'nominal',nominal,'channels',channels, ...
    'appliedIntervalCommand',nan(2*nSurface,1), ...
    'outerWingCommand',uOuter(:),'rawInnerCommand',rawInnerCommand(:), ...
    'rigidCommand',rigidCommand, ...
    'centralDifferenceContract',"captured_raw_inner_held", ...
    'outputNames',{{'u','w','theta','q','clampFz','clampMy','totalFz'}}, ...
    'actual',struct());
end

function [rigidCommand,record,previousTailThrust] = ...
    localEvaluateCorrectedRigidResidualAllocation(model,request,preview, ...
    plant,package,fusion,actuator,uPrevious,uOuter,nominalHold, ...
    rigidCommand,gust,rawInnerCommand,appliedTarget,previousTailThrust)
%LOCALEVALUATECORRECTEDRIGIDRESIDUALALLOCATION Coordinate shared-wing demand.
% The nMPC wing endpoint remains fixed. Elevator and thrust are solved by
% explicit active-set enumeration, then accepted only if a one-interval
% nonlinear clone reduces departure from the outer-only rigid trajectory.
nSurface = numel(actuator.delta);
assert(nSurface==2 && numel(previousTailThrust)==2 && ...
    all(isfinite(previousTailThrust)) && ...
    isequal(size(rawInnerCommand),[2*nSurface,1]) && ...
    numel(appliedTarget)>=nSurface && all(isfinite(appliedTarget)), ...
    'sim_run:CorrectedRigidResidualInputs', ...
    'The corrected residual runtime inputs are invalid.');
wingTarget = mean(appliedTarget(1:nSurface));
wingTargetRate = mean(appliedTarget(nSurface+(1:nSurface)));
[nominalWingEndpoint,nominalWingRate,nominalRawInner] = ...
    localPredictOuterOnlyWingEndpoint(fusion,actuator,uOuter);
nominalCommand = [nominalWingEndpoint;nominalHold.elevator;nominalHold.thrust];
previousInput = previousTailThrust;
nominalRigid = rigidCommand;
nominalRigid.delta_e = nominalHold.elevator;
nominalRigid.thrust = nominalHold.thrust;
if max(abs([wingTarget-nominalWingEndpoint; ...
        wingTargetRate-nominalWingRate]))<=1e-12
    rigidCommand = nominalRigid;
    previousTailThrust = nominalCommand(2:3);
    record = struct('accepted',true,'reason',"zero_residual_identity", ...
        'solver',"explicit_two_variable_active_set", ...
        'nominalCommand',nominalCommand,'realizedCommand',nominalCommand, ...
        'wingCorrection',0,'wingRateCorrection',0, ...
        'sampleTimeSeconds',model.sampleTimeSeconds, ...
        'allocationRateHz',1/model.sampleTimeSeconds, ...
        'wingTarget',wingTarget,'elevatorRateStepRadians', ...
        request.elevatorRateRadiansPerSecond*model.sampleTimeSeconds, ...
        'previousTailThrust',previousInput, ...
        'appliedTailThrust',nominalCommand(2:3), ...
        'uncoordinatedRigidMetric',0,'coordinatedRigidMetric',0, ...
        'rigidMetricReductionPercent',0,'protectedOutputs',struct(), ...
        'endpointEqualityInfinity',0,'nonlinearPreviewAccepted',true, ...
        'totalThrustLowerSatisfied', ...
        plant.trimThrust+nominalHold.thrust>=0);
    return
end
rateStep = request.elevatorRateRadiansPerSecond*model.sampleTimeSeconds;
bounds = struct( ...
    'elevatorLower',max(-deg2rad(10),previousTailThrust(1)-rateStep), ...
    'elevatorUpper',min(deg2rad(10),previousTailThrust(1)+rateStep), ...
    'thrustLower',-double(plant.trimThrust), ...
    'thrustUpper',0.5,'trimThrust',double(plant.trimThrust));
algebraic = AeroFlex.ctrl.realizeVirtualDemandAudit( ...
    model,zeros(6,1),nominalCommand,wingTarget,bounds, ...
    struct('nominal',nominalWingRate,'realized',wingTargetRate));
candidateRigid = nominalRigid;
candidateRigid.delta_e = algebraic.realizedCommand(2);
candidateRigid.thrust = algebraic.realizedCommand(3);
assert(plant.trimThrust+candidateRigid.thrust>=0, ...
    'sim_run:CorrectedRigidResidualCandidateThrust', ...
    'The algebraic candidate attempted negative total thrust.');

rates = zeros(nSurface,3);
gustHorizon = repmat(gust(:),1,3);
reference = preview.previewFirstIntervalWithRawInner( ...
    plant,package,fusion,actuator,plant.xFlex,uPrevious,uOuter, ...
    nominalRigid,gustHorizon,rates,nominalRawInner);
uncoordinated = preview.previewFirstIntervalWithRawInner( ...
    plant,package,fusion,actuator,plant.xFlex,uPrevious,uOuter, ...
    nominalRigid,gustHorizon,rates,rawInnerCommand);
coordinated = preview.previewFirstIntervalWithRawInner( ...
    plant,package,fusion,actuator,plant.xFlex,uPrevious,uOuter, ...
    candidateRigid,gustHorizon,rates,rawInnerCommand);

scale = [2;1;deg2rad(8);deg2rad(20)];
referenceRigid = localCorrectedRigidResidualTrajectory(reference)./scale;
uncoordinatedRigid = ...
    localCorrectedRigidResidualTrajectory(uncoordinated)./scale;
coordinatedRigid = ...
    localCorrectedRigidResidualTrajectory(coordinated)./scale;
uncoordinatedMetric = norm(uncoordinatedRigid-referenceRigid,inf);
coordinatedMetric = norm(coordinatedRigid-referenceRigid,inf);
rigidImproved = coordinatedMetric <= uncoordinatedMetric- ...
    1e-12*max(1,uncoordinatedMetric);
if uncoordinatedMetric<=1e-12 && coordinatedMetric<=1e-12
    rigidImproved = true;
end

protectedNames = ["wingtip","clampFz","clampMy"];
protectedNotWorse = true;
protected = struct();
for name = protectedNames
    baselineMaximum = max(abs(uncoordinated.(name)));
    candidateMaximum = max(abs(coordinated.(name)));
    tolerance = 1e-6*max(1,baselineMaximum);
    channelPassed = candidateMaximum<=baselineMaximum+tolerance;
    protectedNotWorse = protectedNotWorse && channelPassed;
    protected.(name) = struct('uncoordinatedMaximum',baselineMaximum, ...
        'coordinatedMaximum',candidateMaximum,'tolerance',tolerance, ...
        'passed',channelPassed);
end
endpointEquality = norm(coordinated.actuatorEndpoint- ...
    uncoordinated.actuatorEndpoint,inf);
finiteGate = all(isfinite([referenceRigid;uncoordinatedRigid; ...
    coordinatedRigid]),'all') && all(isfinite([ ...
    coordinated.wingtip;coordinated.clampFz;coordinated.clampMy]));
accepted = algebraic.totalThrustLowerSatisfied && finiteGate && ...
    rigidImproved && protectedNotWorse && endpointEquality<=1e-12;
if accepted
    rigidCommand = candidateRigid;
    previousTailThrust = algebraic.realizedCommand(2:3);
    reason = "accepted_nonlinear_rigid_improvement";
else
    rigidCommand.delta_e = previousTailThrust(1);
    rigidCommand.thrust = previousTailThrust(2);
    reason = "fallback_previous_safe_tail_thrust";
end
assert(plant.trimThrust+rigidCommand.thrust>=0, ...
    'sim_run:CorrectedRigidResidualFallbackThrust', ...
    'The residual fallback violated T >= 0.');
record = algebraic;
record.accepted = accepted;
record.reason = reason;
record.sampleTimeSeconds = model.sampleTimeSeconds;
record.allocationRateHz = 1/model.sampleTimeSeconds;
record.wingTarget = wingTarget;
record.wingRateTarget = wingTargetRate;
record.nominalWingEndpoint = nominalWingEndpoint;
record.nominalWingRate = nominalWingRate;
record.elevatorRateStepRadians = rateStep;
record.previousTailThrust = previousInput;
record.appliedTailThrust = [rigidCommand.delta_e;rigidCommand.thrust];
record.uncoordinatedRigidMetric = uncoordinatedMetric;
record.coordinatedRigidMetric = coordinatedMetric;
record.rigidMetricReductionPercent = 100*(1-coordinatedMetric/ ...
    max(uncoordinatedMetric,eps));
record.protectedOutputs = protected;
record.endpointEqualityInfinity = endpointEquality;
record.nonlinearPreviewAccepted = accepted;
end

function [endpoint,rate,rawInner] = ...
    localPredictOuterOnlyWingEndpoint(fusion,actuator,uOuter)
%LOCALPREDICTOUTERONLYWINGENDPOINT Non-mutating fusion/servo prediction.
uOuter = uOuter(:);
assert(numel(uOuter)==numel(fusion.uTrim) && ...
    numel(actuator.delta)*2==numel(uOuter), ...
    'sim_run:CorrectedRigidResidualOuterPrediction', ...
    'The outer-only wing prediction received an invalid command order.');
if fusion.innerIsDeviation
    rawInner = zeros(size(fusion.uTrim));
    dInner = rawInner;
else
    rawInner = fusion.uTrim(:);
    dInner = zeros(size(fusion.uTrim));
end
dOuter = uOuter-fusion.uTrim(:);
yOuter = fusion.a*fusion.yOuterLP+(1-fusion.a)*dOuter;
yInner = fusion.a*fusion.yInnerLP+(1-fusion.a)*dInner;
preActuator = fusion.uTrim(:)+yOuter+(dInner-yInner);
nSurface = numel(actuator.delta);
deltaCommand = min(max(preActuator(1:nSurface), ...
    actuator.deltaL),actuator.deltaU);
rateVector = min(max(actuator.omega*(deltaCommand-actuator.delta), ...
    actuator.rateL),actuator.rateU);
endpointVector = min(max(actuator.delta+actuator.Ts*rateVector, ...
    actuator.deltaL),actuator.deltaU);
endpoint = mean(endpointVector);
rate = mean(rateVector);
assert(all(isfinite([endpoint;rate;rawInner])), ...
    'sim_run:CorrectedRigidResidualOuterPrediction', ...
    'The outer-only wing endpoint prediction is nonfinite.');
end

function values = localCorrectedRigidResidualTrajectory(trajectory)
%LOCALCORRECTEDRIGIDRESIDUALTRAJECTORY Four normalized rigid output rows.
values = [trajectory.uBody(:).';trajectory.wBody(:).'; ...
    trajectory.theta(:).';trajectory.pitchRate(:).'];
end

function record = localFinalizeGustRigidResponseDomain(record,plant,uAct, ...
    uIntervalApplied)
%LOCALFINALIZEGUSTRIGIDRESPONSEDOMAIN Compare zero-perturbation clone endpoint.
actualRigid = [plant.rb.r_I(:);plant.rb.v_B(:);plant.rb.euler(:); ...
    plant.rb.omega_B(:)];
actualOutput = [plant.rb.v_B(1);plant.rb.v_B(3);plant.rb.euler(2); ...
    plant.rb.omega_B(2);plant.last.Clamp6(3);plant.last.Clamp6(5); ...
    plant.last.Ftot_B(3)];
record.actual = struct('flexibleState',plant.xFlex(:), ...
    'rigidState',actualRigid,'actuatorEndpoint',uAct(:), ...
    'output',actualOutput,'flexibleInfinity',norm(plant.xFlex(:)- ...
    record.nominal.flexibleState(:),inf),'rigidInfinity',norm( ...
    actualRigid-record.nominal.rigidState(:),inf), ...
    'actuatorInfinity',norm(uAct(:)-record.nominal.actuatorEndpoint(:),inf), ...
    'outputInfinity',norm(actualOutput-localGustRigidResponseOutput( ...
    record.nominal),inf));
record.appliedIntervalCommand = uIntervalApplied(:);
end

function output = localGustRigidResponseOutput(trajectory)
%LOCALGUSTRIGIDRESPONSEOUTPUT Ordered endpoint outputs for central differences.
output = [trajectory.uBody(end);trajectory.wBody(end);trajectory.theta(end); ...
    trajectory.pitchRate(end);trajectory.clampFz(end); ...
    trajectory.clampMy(end);trajectory.totalFz(end)];
end

function record = localCaptureRuntimeCheckpoint(plant,predictionPackage, ...
    scheduleInfo,modelIdentity,scheduledReciprocalPacket, ...
    fuser,actuator,controller, ...
    uMhePreviousInterval, ...
    uMpcPreviousEndpoint,uOuter,rbCommand,gust,sampleIndex,timeSeconds)
%LOCALCAPTURERUNTIMECHECKPOINT Snapshot the active owner without mutation.
assert(~isempty(fuser) && ~isempty(actuator), ...
    'sim_run:RuntimeCheckpointControlChain', ...
    ['The exact runtime checkpoint requires the active fusion and ', ...
    'actuator owners.']);
assert(plant.trimThrust + safeField(rbCommand,'thrust',0) >= 0, ...
    'sim_run:RuntimeCheckpointNegativeThrust', ...
    'The checkpoint rigid command must preserve nonnegative thrust.');
plantState = struct( ...
    'cfg',plant.cfg,'trim',plant.trim,'xFlex',plant.xFlex(:), ...
    'xFlex0',plant.xFlex0(:),'dt',plant.dt,'idx',plant.idx, ...
    'nx',plant.nx,'nu',plant.nu,'nw',plant.nw, ...
    'rb',plant.rb,'t',plant.t,'k',plant.k, ...
    'flightCond',plant.flightCond,'last',plant.last, ...
    'lastWingControl',plant.lastWingControl(:), ...
    'trimWingControl',plant.trimWingControl(:), ...
    'trimMu',plant.trimMu(:).', ...
    'scheduleEnabled',plant.scheduleEnabled, ...
    'controlSampleScheduleHoldStepsRemaining', ...
    plant.controlSampleScheduleHoldStepsRemaining, ...
    'controlSampleIndex',plant.controlSampleIndex, ...
    'sched',plant.sched,'trimThrust',plant.trimThrust, ...
    'trimTailDelta',plant.trimTailDelta,'bodyCase',plant.bodyCase, ...
    'useRigidBody',plant.useRigidBody,'rbParams',plant.rbParams, ...
    'reciprocalTangentCorrection', ...
    plant.reciprocalTangentCorrection, ...
    'modelSnapshot',struct('L',plant.model.L, ...
    'Ldyn',plant.model.Ldyn,'dt',plant.model.dt, ...
    'idx',plant.model.idx,'parConst',plant.model.parConst, ...
    'internalCoupledCoordinate', ...
    plant.model.internalCoupledCoordinate));
fusionState = struct('Ts',fuser.Ts,'wc',fuser.wc,'a',fuser.a, ...
    'uTrim',fuser.uTrim(:),'yOuterLP',fuser.yOuterLP(:), ...
    'yInnerLP',fuser.yInnerLP(:),'initialized',fuser.initialized, ...
    'innerIsDeviation',fuser.innerIsDeviation);
actuatorState = struct('Ts',actuator.Ts,'omega',actuator.omega, ...
    'nSurf',actuator.nSurf,'varPer',actuator.varPer,'nu',actuator.nu, ...
    'delta',actuator.delta(:),'deltaDot',actuator.deltaDot(:), ...
    'deltaL',actuator.deltaL(:),'deltaU',actuator.deltaU(:), ...
    'rateL',actuator.rateL(:),'rateU',actuator.rateU(:));
controllerState = struct('Ts',controller.Ts,'dt',controller.dt, ...
    'Nc',controller.Nc,'nx',controller.nx,'nu',controller.nu, ...
    'nw',controller.nw,'nSurface',controller.n_surf, ...
    'xTrim',controller.xTrim(:),'uTrim',controller.uTrim(:), ...
    'uModelTrim',controller.uModelTrim(:), ...
    'Qc',controller.Qc,'Rc',controller.Rc,'Pc',controller.Pc, ...
    'uPrevious',controller.uPrev(:), ...
    'actuatorDeflectionAlpha',controller.actuatorDeflectionAlpha);
reciprocalPacket = struct();
if isstruct(scheduledReciprocalPacket) && ...
        isfield(scheduledReciprocalPacket,'schemaVersion') && ...
        string(scheduledReciprocalPacket.schemaVersion)== ...
        "phase18c-v17a-scheduled-reciprocal-packet-v1"
    packetFields = {'schemaVersion','plantCandidate','queryTrim', ...
        'queryNativeEquilibrium','sourceIds','schedule'};
    reciprocalPacket = cell2struct(cellfun( ...
        @(name)scheduledReciprocalPacket.(name),packetFields, ...
        'UniformOutput',false),packetFields,2);
end
record = struct( ...
    'schemaVersion','phase18c-v17a-runtime-checkpoint-v1', ...
    'phase','post_schedule_transport_and_equilibrium_rebase_pre_solve', ...
    'sampleIndex',sampleIndex,'timeSeconds',timeSeconds, ...
    'predictionPackage',predictionPackage,'scheduleInfo',scheduleInfo, ...
    'modelIdentity',modelIdentity, ...
    'scheduledReciprocalPacket',reciprocalPacket,'plant',plantState, ...
    'fusion',fusionState,'actuator',actuatorState, ...
    'controller',controllerState, ...
    'uMhePreviousInterval',uMhePreviousInterval(:), ...
    'uMpcPreviousEndpoint',uMpcPreviousEndpoint(:), ...
    'uOuterWing',uOuter(:),'rigidCommand',rbCommand, ...
    'gust',gust(:));
end

function request = localDynamicEquilibriumRecenteringAuditRequest(cfg)
%LOCALDYNAMICEQUILIBRIUMRECENTERINGAUDITREQUEST Validate Case-B audit opt-in.
request = struct('enabled',false,'auditOnly',false, ...
    'suppressSolvesAfterInitialization',false, ...
    'preserveNmpcControlTarget',false);
if ~isfield(cfg,'ctrl') || ~isstruct(cfg.ctrl) || ...
        ~isfield(cfg.ctrl,'dynamicEquilibriumRecenteringAudit') || ...
        isempty(cfg.ctrl.dynamicEquilibriumRecenteringAudit)
    return
end
value = cfg.ctrl.dynamicEquilibriumRecenteringAudit;
assert(isstruct(value) && isfield(value,'enable') && ...
    isscalar(value.enable) && (islogical(value.enable) || isnumeric(value.enable)) && ...
    isfinite(double(value.enable)) && any(double(value.enable) == [0,1]), ...
    'sim_run:DynamicEquilibriumRecenteringRequest', ...
    'Dynamic equilibrium recentering enable must be a logical scalar.');
request.enabled = logical(value.enable);
if ~request.enabled
    return
end
assert(isfield(value,'auditOnly') && isscalar(value.auditOnly) && ...
    (islogical(value.auditOnly) || isnumeric(value.auditOnly)) && ...
    isfinite(double(value.auditOnly)) && double(value.auditOnly) == 1, ...
    'sim_run:DynamicEquilibriumRecenteringAuditOnly', ...
    'An enabled dynamic-equilibrium recentering request is audit-only.');
request.auditOnly = true;
if isfield(value,'preserveNmpcControlTarget') && ...
        ~isempty(value.preserveNmpcControlTarget)
    preserve = value.preserveNmpcControlTarget;
    assert(isscalar(preserve) && ...
        (islogical(preserve) || isnumeric(preserve)) && ...
        isfinite(double(preserve)) && any(double(preserve) == [0,1]), ...
        'sim_run:DynamicEquilibriumControlTarget', ...
        'nMPC control-target preservation must be a logical scalar.');
    request.preserveNmpcControlTarget = logical(preserve);
end
if isfield(value,'suppressSolvesAfterInitialization') && ...
        ~isempty(value.suppressSolvesAfterInitialization)
    suppress = value.suppressSolvesAfterInitialization;
    assert(isscalar(suppress) && (islogical(suppress) || isnumeric(suppress)) && ...
        isfinite(double(suppress)) && any(double(suppress) == [0,1]), ...
        'sim_run:DynamicEquilibriumRecenteringSuppression', ...
        'Solver suppression must be a logical scalar.');
    request.suppressSolvesAfterInitialization = logical(suppress);
end
end

function [reference,uMhePreviousInterval,uMpcPreviousEndpoint,info] = ...
    localRebaseDynamicEquilibriumReference(request,plant,estimator, ...
    controller,fuser,actuator,package,reference,uMhePreviousInterval, ...
    uMpcPreviousEndpoint)
%LOCALREBASEDYNAMICEQUILIBRIUMREFERENCE Preserve total commands on a trim shift.
%
% The plant, nMHE, and nMPC store surface commands as increments about one
% total wing reference.  During the default-disabled Case-B audit, an active
% package may carry a different total equilibrium input.  Translate all
% local command histories by oldReference-newReference so their physical
% total inputs are invariant.  Flexible states remain in the locked common
% coordinate and are therefore not translated.

reference = reference(:);
uMhePreviousInterval = uMhePreviousInterval(:);
uMpcPreviousEndpoint = uMpcPreviousEndpoint(:);
info = struct('attempted',false,'accepted',false, ...
    'referenceChangeInfinityNorm',0, ...
    'endpointPreservationInfinityNorm',0, ...
    'stateTargetPreservationInfinityNorm',0, ...
    'inputTargetPreservationInfinityNorm',0, ...
    'controlTargetHeld',false,'reason',"disabled");
if ~request.enabled
    return
end
info.attempted = true;
info.controlTargetHeld = request.preserveNmpcControlTarget;
origin = "legacy_dynamic_equilibrium_audit";
if isfield(request,'origin') && strlength(string(request.origin)) > 0
    origin = string(request.origin);
end
info.reason = "unchanged_reference";
if ~isfield(package,'u_eq') || ~isfield(package,'x_eq') || ...
        isempty(package.u_eq) || isempty(package.x_eq)
    info.reason = "missing_package_equilibrium";
    return
end
newReference = package.u_eq(:);
newStateReference = package.x_eq(:);
if numel(newReference) ~= numel(reference) || ...
        numel(newStateReference) ~= controller.nx || ...
        any(~isfinite(newReference)) || any(~isfinite(newStateReference))
    info.reason = "invalid_package_equilibrium";
    return
end
nSurface = controller.n_surf;
if nSurface <= 0 || nSurface > numel(reference) || ...
        any(abs(newReference(nSurface+1:end)) > 100*eps)
    info.reason = "unsupported_equilibrium_input_order";
    return
end
offset = reference-newReference;
info.referenceChangeInfinityNorm = norm(offset,inf);
estimatorReferenceError = norm(estimator.uModelTrim-reference,inf);
controllerReferenceError = norm(controller.uModelTrim-reference,inf);
if info.referenceChangeInfinityNorm <= 100*eps(max(1,norm(reference,inf))) && ...
        estimatorReferenceError <= 1e-11 && controllerReferenceError <= 1e-11
    info.accepted = true;
    return
end

% Validate every owner before mutating any persistent runtime state.
if numel(uMhePreviousInterval) ~= controller.nu || ...
        numel(uMpcPreviousEndpoint) ~= controller.nu
    info.reason = "external_endpoint_dimension_mismatch";
    return
end
if numel(estimator.uModelTrim) ~= controller.nu || ...
        numel(controller.uModelTrim) ~= controller.nu || ...
        numel(controller.uTrim) ~= controller.nu
    info.reason = "prediction_reference_dimension_mismatch";
    return
end
if ~isequal(size(estimator.Uhist),[controller.nu,estimator.Ne]) || ...
        ~isequal(size(controller.Uhist),[controller.nu,controller.Nc]) || ...
        numel(controller.uPrev) ~= controller.nu
    info.reason = "controller_history_layout_mismatch";
    return
end
if isempty(fuser) || isempty(actuator) || ...
        numel(actuator.delta) ~= nSurface || ...
        numel(fuser.yInnerLP) ~= controller.nu
    info.reason = "fusion_actuator_owner_mismatch";
    return
end
if any(actuator.delta + offset(1:nSurface) < actuator.deltaL) || ...
        any(actuator.delta + offset(1:nSurface) > actuator.deltaU)
    info.reason = "actuator_rebase_outside_position_limits";
    return
end

oldPhysicalEndpoint = reference + uMpcPreviousEndpoint;
oldPhysicalInputTarget = reference + controller.uTrim(:);
oldStateTarget = controller.xTrim(:);
newMhePreviousInterval = uMhePreviousInterval + offset;
newMpcPreviousEndpoint = uMpcPreviousEndpoint + offset;
newPhysicalEndpoint = newReference + newMpcPreviousEndpoint;
endpointError = norm(newPhysicalEndpoint-oldPhysicalEndpoint,inf);
tolerance = 100*eps(max(1,norm(oldPhysicalEndpoint,inf)));
if endpointError > tolerance
    info.reason = "endpoint_translation_failure";
    return
end
inputStart = (controller.Nc+1)*controller.nx + 1;
inputStop = inputStart + controller.Nc*controller.nu - 1;
if numel(controller.z0) < inputStop
    info.reason = "controller_warm_start_layout_mismatch";
    return
end

% Histories and warm starts are local command coordinates.  Shift them
% before changing the model reference so u_eq+u_local remains physical.
estimator.Uhist = estimator.Uhist + offset;
estimator.uModelTrim = newReference;
estimator.stateModelTrim = newStateReference;
estimator.preparedFeedback = struct();

controller.Uhist = controller.Uhist + offset;
controller.uPrev = controller.uPrev + offset;
warmInput = reshape(controller.z0(inputStart:inputStop), ...
    controller.nu,controller.Nc);
warmInput = warmInput + offset;
controller.z0(inputStart:inputStop) = warmInput(:);
controller.uL(1:nSurface) = controller.uL(1:nSurface) + ...
    controller.uModelTrim(1:nSurface)-newReference(1:nSurface);
controller.uU(1:nSurface) = controller.uU(1:nSurface) + ...
    controller.uModelTrim(1:nSurface)-newReference(1:nSurface);
controller.uModelTrim = newReference;
if request.preserveNmpcControlTarget
    controller.uTrim = controller.uTrim + offset;
else
    controller.xTrim = newStateReference;
end

newPhysicalInputTarget = newReference + controller.uTrim(:);
info.inputTargetPreservationInfinityNorm = ...
    norm(newPhysicalInputTarget-oldPhysicalInputTarget,inf);
if request.preserveNmpcControlTarget
    info.stateTargetPreservationInfinityNorm = ...
        norm(controller.xTrim-oldStateTarget,inf);
end
if request.preserveNmpcControlTarget && ...
        (info.inputTargetPreservationInfinityNorm > tolerance || ...
        info.stateTargetPreservationInfinityNorm > tolerance)
    error('sim_run:NmpcControlTargetPreservation', ...
        ['The model schedule transition changed the physical nMPC ', ...
        'state or input control target.']);
end

% The actuator and fusion states are held in the same increment frame.
% Shift their position/filter memories to avoid a false command jump.
actuator.delta = actuator.delta + offset(1:nSurface);
fuser.yInnerLP = fuser.yInnerLP + offset;
plant.trimWingControl = newReference;
reference = newReference;
uMhePreviousInterval = newMhePreviousInterval;
uMpcPreviousEndpoint = newMpcPreviousEndpoint;
info.accepted = true;
if estimatorReferenceError > 1e-11 || controllerReferenceError > 1e-11
    info.reason = "accepted_" + origin + ...
        "_preexisting_reference_owner_mismatch";
else
    info.reason = "accepted_" + origin;
end
info.endpointPreservationInfinityNorm = endpointError;
end

function [controller,info] = localSynchronizeNmpcWarmStartToEndpoint( ...
    controller,Uinfo,uApplied)
%LOCALSYNC... Translate an audit-only nMPC warm start after allocation.
%   Full-channel allocation is applied after nMPC has accepted and shifted
%   its candidate.  Preserve that candidate's local trajectory while making
%   its endpoint frame consistent with the realized actuator state.
info = struct('enabled',true,'applied',false,'offsetInfinity',nan, ...
    'warmInputProjectionInfinity',nan,'reason',"unavailable");
candidate = safeField(Uinfo,'candidateFirstCommand',[]);
if ~isnumeric(candidate) || numel(candidate) ~= controller.nu || ...
        ~all(isfinite(candidate(:)))
    info.reason = "candidate_first_command_unavailable";
    return
end
uApplied = uApplied(:);
assert(numel(uApplied)==controller.nu && all(isfinite(uApplied)), ...
    'sim_run:FullChannelWarmStartEndpoint', ...
    'The realized full-channel endpoint is invalid.');
inputStart = (controller.Nc+1)*controller.nx + 1;
inputStop = inputStart + controller.Nc*controller.nu - 1;
assert(numel(controller.z0) >= inputStop, ...
    'sim_run:FullChannelWarmStartLayout', ...
    'The nMPC warm-start layout is incompatible with its horizon.');
offset = uApplied-candidate(:);
warmInput = reshape(controller.z0(inputStart:inputStop), ...
    controller.nu,controller.Nc);
translatedWarmInput = warmInput + offset;
projectedWarmInput = min(max(translatedWarmInput,controller.uL(:)), ...
    controller.uU(:));
translatedHistory = controller.Uhist + offset;
controller.Uhist = min(max(translatedHistory,controller.uL(:)), ...
    controller.uU(:));
controller.z0(inputStart:inputStop) = projectedWarmInput(:);
controller.uPrev = uApplied;
info.applied = true;
info.offsetInfinity = norm(offset,inf);
info.warmInputProjectionInfinity = norm( ...
    projectedWarmInput-translatedWarmInput,inf);
info.reason = "realized_endpoint_translation";
end

function healthy = localNmpcMheHealth(info,xhat,what)
%LOCALNMPCMHEHEALTH Accept only a current finite, accepted nMHE result.
attempted = logical(safeField(info,'solveAttempted',true));
accepted = logical(safeField(info,'accepted', ...
    safeField(info,'exitflag',-inf) > 0));
continuity = safeField(info,'continuity',nan);
healthy = attempted && accepted && isfinite(continuity) && ...
    isnumeric(xhat) && isnumeric(what) && all(isfinite(xhat(:))) && ...
    all(isfinite(what(:)));
end

function [uHold,info] = localNmpcMheHealthHold(uPreviousEndpoint,nSurf)
%LOCALNMPCMHEHEALTHHOLD Return nMPC-shaped audit diagnostics without a solve.
uHold = localNmpcSafeHoldEndpoint(uPreviousEndpoint,[],nSurf);
info = struct('cost',nan,'exitflag',nan,'continuity',nan, ...
    'uHorizon',uHold,'output',struct(), ...
    'status',"skipped_nMHE_health_gate");
end

function uHold = localNmpcSafeHoldEndpoint(uPreviousEndpoint,actuator,nSurf)
%LOCALNMPCSAFEHOLDENDPOINT Preserve deflection and command zero wing rate.
if ~isempty(actuator)
    if actuator.varPer == 1
        uHold = actuator.delta(:);
    elseif actuator.varPer == 2
        uHold = [actuator.delta(:); zeros(actuator.nSurf,1)];
    else
        error('sim_run:nMheHealthGateActuator', ...
            'Unsupported actuator varPer=%d.',actuator.varPer);
    end
else
    uHold = uPreviousEndpoint(:);
    assert(numel(uHold) == nSurf || numel(uHold) == 2*nSurf, ...
        'sim_run:nMheHealthGateEndpoint', ...
        'The prior actuator endpoint has an incompatible length.');
    if numel(uHold) == 2*nSurf
        uHold(nSurf+1:end) = 0;
    end
end
assert(all(isfinite(uHold)), 'sim_run:nMheHealthGateEndpoint', ...
    'The nMHE-health safe endpoint must be finite.');
end

function ref = localOuterAuditReference(cfg,t,rb)
%LOCALOUTERAUDITREFERENCE Return an explicitly enabled rigid reference.
% The production and retained audit providers share the same evaluated
% reference contract. Their selectors are mutually exclusive at entry.
ref = struct();
if ~isfield(cfg,'outerLQR')
    return
end
production = isfield(cfg.outerLQR,'referenceProvider') && ...
    isstruct(cfg.outerLQR.referenceProvider) && ...
    isfield(cfg.outerLQR.referenceProvider,'enable') && ...
    logical(cfg.outerLQR.referenceProvider.enable);
audit = isfield(cfg.outerLQR,'auditReferenceProvider') && ...
    isstruct(cfg.outerLQR.auditReferenceProvider) && ...
    isfield(cfg.outerLQR.auditReferenceProvider,'enable') && ...
    logical(cfg.outerLQR.auditReferenceProvider.enable);
assert(~(production && audit), ...
    'sim_run:OuterReferenceProviderConflict', ...
    'The production and audit reference providers are mutually exclusive.');
if production
    request = cfg.outerLQR.referenceProvider;
elseif audit
    request = cfg.outerLQR.auditReferenceProvider;
else
    return
end
if ~isfield(request,'enable') || ~logical(request.enable)
    return
end
if audit
    assert(isfield(request,'auditOnly') && logical(request.auditOnly), ...
        'sim_run:AuditReferenceOnly', ...
        'The audit reference provider requires auditOnly=true.');
end
assert(isfield(request,'provider') && isa(request.provider,'function_handle'), ...
    'sim_run:AuditReferenceProvider', ...
    'An enabled outer reference request requires a function-handle provider.');
ref = request.provider(t,rb);
assert(isstruct(ref) && isscalar(ref), 'sim_run:AuditReferenceType', ...
    'The outer reference provider must return a scalar struct.');
fields = {'v_B_ref','euler_ref','omega_B_ref'};
for index = 1:numel(fields)
    field = fields{index};
    if isfield(ref,field)
        value = ref.(field);
        assert(isnumeric(value) && isreal(value) && numel(value) == 3 && ...
            all(isfinite(value(:))), 'sim_run:AuditReferenceValue', ...
            'Reference field %s must be a finite real three-vector.',field);
        ref.(field) = value(:);
    end
end
scalarFields = {'scheduleUInfMps','scheduleAlphaDeg'};
for index = 1:numel(scalarFields)
    field = scalarFields{index};
    if isfield(ref,field)
        value = ref.(field);
        assert(isnumeric(value) && isreal(value) && isscalar(value) && ...
            isfinite(value), 'sim_run:AuditScheduleReferenceValue', ...
            'Reference field %s must be a finite real scalar.',field);
        ref.(field) = double(value);
    end
end
end

function request = localProductionOuterReferenceProvider(raw)
%LOCALPRODUCTIONOUTERREFERENCEPROVIDER Validate the custom guidance owner.
request = struct();
if isempty(fieldnames(raw))
    return
end
assert(isfield(raw,'enable') && isscalar(raw.enable) && ...
    logical(raw.enable) && isfield(raw,'schemaVersion') && ...
    string(raw.schemaVersion)== ...
    "pazy-production-reference-provider-v1" && ...
    isfield(raw,'source') && string(raw.source)== ...
    "phase18c-v17a-custom-continuous-guidance-runtime-adapter-v1" && ...
    isfield(raw,'provider') && isa(raw.provider,'function_handle'), ...
    'sim_run:ProductionReferenceProvider', ...
    ['The production reference provider must match the approved ', ...
    'custom continuous-guidance contract.']);
request = raw;
request.enable = true;
end

function value = localSourceCoordinateOuterMeasurement( ...
    physicalMeasurement,xFlex,rb,baseline)
%LOCALSOURCECOORDINATEOUTERMEASUREMENT Recover the qualified six outputs.
node = physicalMeasurement.measure(xFlex(:));
assert(isfield(physicalMeasurement,'groups') && ...
    isfield(physicalMeasurement.groups,'gyro'), ...
    'sim_run:SourceCoordinateOuterMeasurementContract', ...
    'The Case-A physical measurement does not expose wing gyro rows.');
gyro = node(physicalMeasurement.groups.gyro);
assert(numel(gyro)>=14 && numel(baseline.velocity)==3 && ...
    all(isfinite([node(:);rb.v_B(:);rb.euler(:);rb.omega_B(:)])), ...
    'sim_run:SourceCoordinateOuterMeasurementFinite', ...
    'The source-coordinate outer measurement is incomplete or nonfinite.');
value = [rb.v_B(1)-baseline.velocity(1); ...
    rb.v_B(3)-baseline.velocity(3); ...
    rb.euler(2)-baseline.theta;rb.omega_B(2); ...
    mean(gyro([8,11]));mean(gyro([5,14]))];
end

function localPhaseTrace(cfg,phase,payload)
%LOCALPHASETRACE Append explicitly requested audit-only runtime phase stamps.
if nargin < 3 || isempty(payload)
    payload = struct();
end
if ~isfield(cfg,'debug') || ~isstruct(cfg.debug) || ...
        ~isfield(cfg.debug,'phase18TracePath') || ...
        strlength(string(cfg.debug.phase18TracePath)) == 0
    return
end
path = char(string(cfg.debug.phase18TracePath));
fileId = fopen(path,'a');
assert(fileId >= 0,'sim_run:PhaseTraceOpen', ...
    'Cannot append the requested Phase 18 runtime trace: %s',path);
cleanup = onCleanup(@() fclose(fileId));
entry = struct('utc',char(datetime('now','TimeZone','UTC', ...
    'Format',"yyyy-MM-dd'T'HH:mm:ss.SSS'Z'")), 'phase',char(phase), ...
    'payload',payload);
fprintf(fileId,'%s\n',jsonencode(entry));
clear cleanup
end

function payload = localSolverTracePayload(info,timeSeconds,elapsedSeconds)
%LOCALSOLVERTRACEPAYLOAD Emit compact solver progress without changing state.
payload = struct('timeSeconds',timeSeconds,'elapsedSeconds',elapsedSeconds, ...
    'accepted',logical(safeField(info,'accepted', ...
    safeField(info,'exitflag',-inf)>0)), ...
    'exitflag',safeField(info,'exitflag',nan), ...
    'continuity',safeField(info,'continuity',nan), ...
    'cost',safeField(info,'cost',nan));
end

function payload = localNmpcTracePayload(info,timeSeconds,elapsedSeconds)
%LOCALNMPCTRACEPAYLOAD Emit the accepted or rejected nMPC command horizon.
payload = localSolverTracePayload(info,timeSeconds,elapsedSeconds);
payload.realtimeRti = safeField(info,'realtimeRti',struct());
payload.firstCommand = safeField(info,'candidateFirstCommand', ...
    safeField(info,'uHorizon',nan));
payload.appliedHorizon = safeField(info,'uHorizon',nan);
payload.candidateHorizon = safeField(info,'candidateUHorizon',nan);
payload.constraintViolationInf = safeField(info, ...
    'constraintViolationInf',nan);
payload.surfaceSubspace = safeField(info,'surfaceSubspace',struct());
end

function localCaseBInnerFixedPointTrace(cfg,plant,ctrl,est,xhat,wForMpc,iCtrl,t_k)
%LOCALCASEBINNERFIXEDPOINTTRACE Record the scheduled nMPC seed, read-only.
if ~isfield(cfg,'debug') || ~isstruct(cfg.debug) || ...
        ~isfield(cfg.debug,'caseBInnerFixedPointTrace') || ...
        ~isstruct(cfg.debug.caseBInnerFixedPointTrace)
    return
end
request = cfg.debug.caseBInnerFixedPointTrace;
if ~isfield(request,'enabled') || ~logical(request.enabled)
    return
end
assert(isfield(request,'auditOnly') && logical(request.auditOnly) && ...
    isfield(request,'maximumControlSamples'), ...
    'sim_run:CaseBInnerFixedPointTraceRequest', ...
    'The Case-B nMPC seed trace must remain bounded and audit-only.');
if ~localCaseBTraceRequested(request,iCtrl)
    return
end

try
    audit = ctrl.evaluateReciprocalProviderConstraintAudit(xhat,wForMpc);
    zeroControl = ctrl.evaluateReciprocalProviderZeroControlAudit( ...
        xhat,wForMpc);
    sourceDomain = ctrl.evaluateReciprocalProviderSourceDomainAudit( ...
        xhat,wForMpc,audit.z);
catch auditException
    localPhaseTrace(cfg,"nmpc_warm_seed_fixed_point_failure",struct( ...
        'timeSeconds',t_k,'controlSample',iCtrl, ...
        'xhatTrimInfinity',norm(xhat-ctrl.xTrim,inf), ...
        'gustInfinity',norm(wForMpc,inf), ...
        'identifier',string(auditException.identifier), ...
        'message',string(auditException.message)));
    return
end
stateIndex = ctrl.model.idx;
stateDelta = zeroControl.stateHorizon-ctrl.xTrim;
stateGroups = struct('q1',max(abs(stateDelta(stateIndex.q1,:)),[],"all"), ...
    'q2',max(abs(stateDelta(stateIndex.q2,:)),[],"all"), ...
    'qxi',max(abs(stateDelta(stateIndex.qxi,:)),[],"all"), ...
    'qGam',max(abs(stateDelta(stateIndex.qGam,:)),[],"all"), ...
    'chi',max(abs(stateDelta(stateIndex.chi,:)),[],"all"));
estimatorLatent = est.reciprocalInternalMemoryEndpoint();
memoryAudit = est.reciprocalInternalMemoryAudit();
plantMemory = localCaseBPlantReciprocalMemory(plant,estimatorLatent);
intervalContext = struct( ...
    'modelTrim',memoryAudit.modelTrim(:), ...
    'wingTotalFirst',memoryAudit.wingTotal(:,1), ...
    'wingTotalLast',memoryAudit.wingTotal(:,end), ...
    'wingIncrementFirst',memoryAudit.wingIncrement(:,1), ...
    'wingIncrementLast',memoryAudit.wingIncrement(:,end), ...
    'elevatorIncrementFirst',memoryAudit.elevatorIncrement(1), ...
    'elevatorIncrementLast',memoryAudit.elevatorIncrement(end), ...
    'thrustIncrementFirst',memoryAudit.thrustIncrement(1), ...
    'thrustIncrementLast',memoryAudit.thrustIncrement(end), ...
    'rigidStateFirst',memoryAudit.rigidState(:,1), ...
    'rigidStateLast',memoryAudit.rigidState(:,end), ...
    'rigidStateSubstepRange',max(memoryAudit.rigidState,[],2)- ...
    min(memoryAudit.rigidState,[],2), ...
    'wingTrimMismatchInfinity',norm(memoryAudit.wingTotal(:,1)- ...
    memoryAudit.modelTrim,inf));
stateDecisionCount = ctrl.nx*(ctrl.Nc + 1);
controlDecisionCount = ctrl.nu*ctrl.Nc;
assert(numel(audit.z) == stateDecisionCount + controlDecisionCount, ...
    'sim_run:CaseBInnerFixedPointTraceLayout', ...
    'The nMPC audit decision layout differs from the native state/control chart.');
controlSeed = reshape(audit.z(stateDecisionCount + ...
    (1:controlDecisionCount)),ctrl.nu,ctrl.Nc);
payload = struct('timeSeconds',t_k,'controlSample',iCtrl, ...
    'decisionCount',audit.decisionCount,'cost',audit.cost, ...
    'gradientInfinity',norm(audit.gradient,inf), ...
    'equalityInfinity',norm(audit.equality,inf), ...
    'inequalityMaximum',max([0;audit.inequality(:)]), ...
    'estimatorLatentInfinity',norm(estimatorLatent,inf), ...
    'plantReciprocalMemory',plantMemory, ...
    'estimatorIntervalContext',intervalContext, ...
    'trimLatentInfinity',norm(zeroControl.trimLatentState,inf), ...
    'latentTrimMismatchInfinity',norm( ...
    zeroControl.initialLatentState-zeroControl.trimLatentState,inf), ...
    'zeroControlFirstDepartureInfinity',norm( ...
    zeroControl.firstDeparture,inf), ...
    'zeroControlTerminalDepartureInfinity',norm( ...
    zeroControl.terminalDeparture,inf), ...
    'zeroControlStateGroupDepartureInfinity',stateGroups, ...
    'seedStateDepartureInfinity',norm(audit.z(1:stateDecisionCount) - ...
    repmat(xhat(:),ctrl.Nc + 1,1),inf), ...
    'controlHorizon',controlSeed,'controlInfinity', ...
    norm(controlSeed,inf),'deflectionSymmetryInfinity', ...
    norm(controlSeed(1,:) - controlSeed(2,:),inf), ...
    'rateSymmetryInfinity',norm(controlSeed(3,:) - controlSeed(4,:),inf), ...
    'sourceDomain',localCaseBSourceDomainSummary(sourceDomain));
localPhaseTrace(cfg,"nmpc_warm_seed_fixed_point",payload);
end

function summary = localCaseBSourceDomainSummary(audit)
%LOCALCASEBSOURCEDOMAINSUMMARY Keep bounded trace records compact.
summary = struct('accepted',audit.accepted, ...
    'firstRejectedInterval',audit.firstRejectedInterval, ...
    'maximumInputRatio',0,'maximumVisibleRatio',0, ...
    'maximumHiddenRatio',0,'maximumRootWrenchRatio',0);
for intervalIndex = 1:numel(audit.interval)
    interval = audit.interval{intervalIndex};
    for substepIndex = 1:numel(interval.substeps)
        details = interval.substeps(substepIndex).details;
        if isempty(details)
            continue
        end
        summary.maximumInputRatio = max(summary.maximumInputRatio, ...
            max([details.inputRatio]));
        summary.maximumVisibleRatio = max(summary.maximumVisibleRatio, ...
            max([details.visibleRatio]));
        summary.maximumHiddenRatio = max(summary.maximumHiddenRatio, ...
            max([details.hiddenRatio]));
        summary.maximumRootWrenchRatio = max( ...
            summary.maximumRootWrenchRatio, ...
            max([details.rootWrenchRatio]));
    end
end
end

function localCaseBPostNmpcSourceDomainTrace(cfg,ctrl,xhat,wForMpc, ...
    info,iCtrl,t_k)
%LOCALCASEBPOSTNMPCSOURCEDOMAINTRACE Inspect the accepted candidate only.
if ~isfield(cfg,'debug') || ~isstruct(cfg.debug) || ...
        ~isfield(cfg.debug,'caseBInnerFixedPointTrace') || ...
        ~isstruct(cfg.debug.caseBInnerFixedPointTrace)
    return
end
request = cfg.debug.caseBInnerFixedPointTrace;
accepted = logical(safeField(info,'accepted', ...
    safeField(info,'exitflag',-1) > 0));
if ~isfield(request,'enabled') || ~logical(request.enabled) || ...
        ~localCaseBTraceRequested(request,iCtrl) || ~accepted
    return
end
audit = ctrl.evaluateReciprocalProviderSourceDomainAudit(xhat,wForMpc,[]);
localPhaseTrace(cfg,"nmpc_candidate_source_domain",struct( ...
    'timeSeconds',t_k,'controlSample',iCtrl, ...
    'sourceDomain',localCaseBSourceDomainSummary(audit)));
end

function ratio = localReciprocalSourceDomainRatio(step)
%LOCALRECIPROCALSOURCEDOMAINRATIO Report the worst plant-owned source ratio.
ratio = 0;
details = safeField(step,'domainDetails',struct([]));
if isempty(details)
    return
end
required = {'inputRatio','visibleRatio','hiddenRatio','rootWrenchRatio'};
assert(all(isfield(details,required)), ...
    'sim_run:ReciprocalSourceDomainDetail', ...
    'The reciprocal runtime source-domain detail is incomplete.');
for index = 1:numel(details)
    values = [details(index).inputRatio,details(index).visibleRatio, ...
        details(index).hiddenRatio,details(index).rootWrenchRatio];
    assert(all(isfinite(values)), ...
        'sim_run:ReciprocalSourceDomainFinite', ...
        'The reciprocal runtime source-domain ratio is nonfinite.');
    ratio = max(ratio,max(values));
end
end

function audit = localCaseBPlantReciprocalMemory(plant,estimatorLatent)
%LOCALCASEBPLANTRECIPROCALMEMORY Compare causal plant and estimator memory.
audit = struct('enabled',false,'hiddenStateCount',0, ...
    'hiddenStateInfinity',nan,'dimensionMatchesEstimator',false, ...
    'estimatorDifferenceInfinity',nan,'lastInputInfinity',nan, ...
    'lastVisibleCorrectionInfinity',nan,'lastStepAccepted',false, ...
    'lastDomainRejected',false,'lastDomainReason',"", ...
    'scheduledQueryWingInfinity',nan);
runtime = plant.reciprocalTangentCorrection;
if ~isstruct(runtime) || ~isfield(runtime,'enabled') || ...
        ~logical(runtime.enabled) || ~isfield(runtime,'hiddenState')
    return
end
hiddenState = runtime.hiddenState(:);
audit.enabled = true;
audit.hiddenStateCount = numel(hiddenState);
audit.hiddenStateInfinity = norm(hiddenState,inf);
audit.dimensionMatchesEstimator = numel(hiddenState)==numel(estimatorLatent);
if audit.dimensionMatchesEstimator
    audit.estimatorDifferenceInfinity = norm(hiddenState-estimatorLatent,inf);
end
if isfield(runtime,'lastInput')
    audit.lastInputInfinity = norm(runtime.lastInput(:),inf);
end
if isfield(runtime,'lastVisibleCorrection')
    audit.lastVisibleCorrectionInfinity = norm( ...
        runtime.lastVisibleCorrection(:),inf);
end
if isfield(runtime,'lastStepAccepted')
    audit.lastStepAccepted = logical(runtime.lastStepAccepted);
end
if isfield(runtime,'lastDomainRejected')
    audit.lastDomainRejected = logical(runtime.lastDomainRejected);
end
if isfield(runtime,'lastDomainReason')
    audit.lastDomainReason = string(runtime.lastDomainReason);
end
if isfield(runtime,'scheduledQueryTrim') && ...
        isfield(runtime.scheduledQueryTrim,'wing')
    audit.scheduledQueryWingInfinity = norm( ...
        runtime.scheduledQueryTrim.wing(:),inf);
end
end

function localCaseBScheduledIntervalParityTrace(cfg,ctrl,plant,context, ...
    wingIncrement,gust,iCtrl,t_k,nativeBefore,hiddenBefore)
%LOCALCASEBSCHEDULEDINTERVALPARITYTRACE Compare held context with plant step.
if ~isfield(cfg,'debug') || ~isstruct(cfg.debug) || ...
        ~isfield(cfg.debug,'caseBInnerFixedPointTrace') || ...
        ~isstruct(cfg.debug.caseBInnerFixedPointTrace)
    return
end
request = cfg.debug.caseBInnerFixedPointTrace;
if ~isfield(request,'enabled') || ~logical(request.enabled) || ...
        ~localCaseBTraceRequested(request,iCtrl) || ...
        ~isfield(context,'scheduledPacket') || ...
        isempty(fieldnames(context.scheduledPacket))
    return
end
packet = context.scheduledPacket;
package = context.scheduledPackage;
integrator = ctrl.cfg.modelHandle( ...
    ctrl.cfg,package.beam,package.aero,package.base);
context.scheduledModel = AeroFlex.sched.applyToROMIntegrator( ...
    integrator,package,ctrl.cfg);
provider = AeroFlex.ctrl.ScheduledReciprocalControllerModelProvider( ...
    context.scheduledModel,packet.members,packet.queryTrim);
provider.applyScheduledPacket(context.scheduledModel,packet);
providerState = [nativeBefore(:);hiddenBefore(:)];
providerNext = provider.propagateControlInterval( ...
    providerState,gust,wingIncrement,context,false);
nativeCount = provider.nativeStateCount;
runtime = plant.reciprocalTangentCorrection;
payload = struct('timeSeconds',t_k,'controlSample',iCtrl, ...
    'nativeStateDifferenceInfinity',norm( ...
    providerNext(1:nativeCount)-plant.xFlex(:),inf), ...
    'hiddenStateDifferenceInfinity',norm( ...
    providerNext(nativeCount+1:end)-runtime.hiddenState(:),inf), ...
    'plantHiddenStateInfinity',norm(runtime.hiddenState(:),inf), ...
    'providerHiddenStateInfinity',norm( ...
    providerNext(nativeCount+1:end),inf), ...
    'substepCount',size(context.rigidState,2), ...
    'wingIncrementInfinity',norm(wingIncrement(:),inf), ...
    'rigidHistoryRangeInfinity',norm( ...
    max(context.rigidState,[],2)-min(context.rigidState,[],2),inf), ...
    'plantStepAccepted',logical(runtime.lastStepAccepted), ...
    'plantDomainRejected',logical(runtime.lastDomainRejected), ...
    'plantDomainReason',string(runtime.lastDomainReason));
localPhaseTrace(cfg,"caseb_scheduled_interval_provider_parity",payload);
end

function tf = localCaseBTraceRequested(request,iCtrl)
%LOCALCASEBTRACEREQUESTED Select bounded Case-B diagnostic samples.
if isfield(request,'sampleIndices') && ~isempty(request.sampleIndices)
    tf = any(iCtrl == request.sampleIndices);
    return
end
tf = iCtrl <= request.maximumControlSamples;
end

function source = localCaseAProfileSource( ...
    repositoryRoot,beam,base,trim,plant,intrinsicPortRequest, ...
    correctedNonwingRequest)
%LOCALCASEAPROFILESOURCE Resolve and verify the exact V17A Case-A source.
if nargin < 6 || isempty(intrinsicPortRequest)
    intrinsicPortRequest = struct('enabled',false,'auditOnly',false, ...
        'sourceId',"CASEA_U040_ALPHA_P01");
end
if nargin < 7
    correctedNonwingRequest = struct('enabled',false);
end
registryPath = fullfile(repositoryRoot,'context','audits', ...
    'phase18c-control-validation','plant', ...
    'V17A_DIMENSIONAL_STEADY_FORCE_PRODUCTION_SOURCE_REGISTRY_V1.json');
assert(isfile(registryPath),'sim_run:CaseAProfileRegistry', ...
    'The V17A production registry is unavailable.');
registry = jsondecode(fileread(registryPath));
sourceIds = string({registry.sources.sourceId});
entry = registry.sources(sourceIds == "CASEA_U040_ALPHA_P01");
assert(isscalar(entry),'sim_run:CaseAProfileSource', ...
    'The V17A registry must contain exactly one Case-A source.');
packagePath = fullfile(repositoryRoot, ...
    entry.acceptedMatlabPackage.path);
certificatePath = fullfile(repositoryRoot,entry.certification.path);
assert(isfile(packagePath) && isfile(certificatePath), ...
    'sim_run:CaseAProfileArtifacts', ...
    'The V17A Case-A package or certificate is unavailable.');
assert(localIntrinsicPortFileHash(packagePath)== ...
    string(entry.acceptedMatlabPackage.sha256) && ...
    localIntrinsicPortFileHash(certificatePath)== ...
    string(entry.certification.sha256), ...
    'sim_run:CaseAProfileArtifactHash', ...
    'The registry-bound Case-A package or certificate hash changed.');
data = load(packagePath,'beam','base','trim','p5');
contractPath = fullfile(repositoryRoot,entry.selectedContract.path);
assert(isfile(contractPath) && localIntrinsicPortFileHash(contractPath)== ...
    string(entry.selectedContract.sha256), ...
    'sim_run:CaseAProfileSelectedContract', ...
    'The registry-bound Case-A physical-coordinate contract is unavailable or changed.');
assert(isfield(data.p5,'p5') && isstruct(data.p5.p5) && ...
    isfield(data.p5.p5,'artifactPath'), ...
    'sim_run:CaseAProfileSelectedContract', ...
    'The Case-A package does not expose its selected-contract path.');
data.p5.p5.artifactPath = char(contractPath);
assert(norm(data.p5.mu(:).'-[40,1],inf) <= 1e-12 && ...
    norm(plant.trimMu(:).'-[40,1],inf) <= 1e-12, ...
    'sim_run:CaseAProfileCoordinate', ...
    'The active scheduler must own the exact [40 m/s, 1 deg] source.');
assert(isequal(size(plant.model.L),size(data.p5.L)) && ...
    norm(plant.model.L-data.p5.L,'fro') <= ...
    1e-14*max(1,norm(data.p5.L,'fro')), ...
    'sim_run:CaseAProfilePackage', ...
    'The installed runtime model is not the registry-bound V17A package.');
assert(isequal(size(beam.phi1),size(data.beam.phi1)) && ...
    norm(beam.phi1-data.beam.phi1,'fro') <= ...
    1e-14*max(1,norm(data.beam.phi1,'fro')) && ...
    isequal(size(base.phi_xi_modes),size(data.base.phi_xi_modes)) && ...
    norm(base.phi_xi_modes-data.base.phi_xi_modes,'fro') <= ...
    1e-14*max(1,norm(data.base.phi_xi_modes,'fro')), ...
    'sim_run:CaseAProfileRecovery', ...
    'The setup recovery maps differ from the registry-bound Case-A source.');
correctedNonwingRequestActive = ...
    isfield(correctedNonwingRequest,'enabled') && ...
    logical(correctedNonwingRequest.enabled) && ...
    isfield(correctedNonwingRequest,'source') && ...
    string(correctedNonwingRequest.source)== ...
    "phase18c-v17a-corrected-nonwing-trim-lqr-owner-integration-v1";
reciprocalMassOwnerActive = isfield(plant.cfg,'rigidEOMset') && ...
    isfield(plant.cfg.rigidEOMset,'massOwnership') && ...
    string(plant.cfg.rigidEOMset.massOwnership.owner)== ...
    "nonwing_source_owned_wing_reaction";
correctedNonwingActive = correctedNonwingRequestActive || ...
    reciprocalMassOwnerActive;
correctedNonwingOwner = struct('enabled',false);
if correctedNonwingActive
    if correctedNonwingRequestActive
        bundlePath = string(correctedNonwingRequest.bundleArtifactPath);
        expectedBundleHash = ...
            string(correctedNonwingRequest.bundleArtifactSha256);
    else
        bundlePath = fullfile(repositoryRoot,'context','audits', ...
            'phase18c-control-validation','lqr', ...
            'v17a-casea-corrected-nonwing-trim-lqr-owner-v1', ...
            'PHASE18C_V17A_CASEA_CORRECTED_NONWING_LQR_BUNDLE_V1.mat');
        expectedBundleHash = ...
            "29f7bb6434bd34afd42ed18059b456223c0cd813c3c445ae9f8925f69b75d8ec";
    end
    assert(isfile(bundlePath) && ...
        localStructuredVirtualPitchFileHash(bundlePath)==expectedBundleHash, ...
        'sim_run:CaseAProfileCorrectedTrimArtifact', ...
        'The corrected non-wing bundle is unavailable or changed.');
    corrected = load(bundlePath,'bundle','source');
    assert(string(corrected.bundle.status)== ...
        "PASS_CORRECTED_NONWING_SOURCE_CONTROLLER_BUILD" && ...
        all(structfun(@logical,corrected.bundle.checks)) && ...
        norm(trim.states(:)-corrected.source.trim.states(:),inf)<=1e-12 && ...
        trim.thrust>=0, ...
        'sim_run:CaseAProfileCorrectedTrim', ...
        'The active trim does not match the approved corrected owner.');
    data.trim = corrected.source.trim;
    correctedNonwingOwner = struct('enabled',true, ...
        'auditOnly',true,'defaultActive',false, ...
        'sourceId',"CASEA_U040_ALPHA_P01", ...
        'sourcePackageSha256', ...
        string(entry.acceptedMatlabPackage.sha256), ...
        'bundleArtifactSha256',string(expectedBundleHash), ...
        'correctedTrimThrustNewtons',trim.thrust, ...
        'correctedTrimAlphaDegrees',trim.alphaDeg);
else
    assert(norm(trim.states(:)-data.trim.states(:),inf) <= 1e-12, ...
        'sim_run:CaseAProfileTrim', ...
        'The setup trim state differs from the registry-bound Case-A source.');
end
intrinsicPortInfo = struct('enabled',false,'auditOnly',false, ...
    'sourceId',"CASEA_U040_ALPHA_P01", ...
    'acceptedEquilibriumState',data.p5.x_eq(:));
if intrinsicPortRequest.enabled
    assert(intrinsicPortRequest.auditOnly && ...
        string(intrinsicPortRequest.sourceId)=="CASEA_U040_ALPHA_P01", ...
        'sim_run:IntrinsicPortRuntimeContract', ...
        'The intrinsic-port request must remain the exact Case-A audit path.');
    [candidate,contract] = ...
        AeroFlex.sched.buildExactSourceIntrinsicPortPackage( ...
        data.p5,plant.cfg,data.beam.phi1);
    data.p5 = candidate;
    data.trim.states = candidate.x_eq(:);
    intrinsicPortInfo = struct('enabled',true,'auditOnly',true, ...
        'sourceId',string(intrinsicPortRequest.sourceId), ...
        'acceptedPackageSha256', ...
        string(entry.acceptedMatlabPackage.sha256), ...
        'acceptedEquilibriumState', ...
        intrinsicPortInfo.acceptedEquilibriumState, ...
        'candidatePackageHash',string(candidate.p5.packageHash), ...
        'contract',contract,'fallback', ...
        'accepted_registry_bound_casea_package');
end
physicalChart = AeroFlex.sched.buildPhysicalStructuralChart( ...
    data.p5,1,"fixed_physical_svd",true);
packageOwnedScheduleStateCoordinate = struct( ...
    'schemaVersion',1, ...
    'owner','exact_source_physical_coordinate', ...
    'query',double(data.p5.mu(:).'), ...
    'q1ToPhysical',physicalChart.H1, ...
    'q1CenterToPhysical',data.p5.beam.red.phi1_sA, ...
    'q2ToPhysical',physicalChart.H2, ...
    'qxiToPhysical',physicalChart.Hxi, ...
    'qxiCenterToPhysical',data.p5.base.phiXi_sA, ...
    'equilibriumState',data.trim.states(:), ...
    'validationTruthUsedForConstruction',false);
projectionEnabled = isfield(plant.model.parConst,'RateProject') && ...
    isstruct(plant.model.parConst.RateProject) && ...
    isfield(plant.model.parConst.RateProject,'projSet') && ...
    logical(plant.model.parConst.RateProject.projSet);
runtimeBodyCase = lower(erase(string(plant.cfg.sim.bodyCase),"_"));
if runtimeBodyCase == "wingonly"
    assert(~projectionEnabled,'sim_run:CaseAProfileRateProjection', ...
        'Rate projection must remain off for wing-only Case A.');
end

source = struct('beam',data.beam,'base',data.base,'trim',data.trim, ...
    'p5',data.p5,'sourceId',"CASEA_U040_ALPHA_P01", ...
    'packageOwnedScheduleStateCoordinate', ...
    packageOwnedScheduleStateCoordinate, ...
    'registryPath',registryPath,'packagePath',packagePath, ...
    'certificatePath',certificatePath, ...
    'packageSha256',string(entry.acceptedMatlabPackage.sha256), ...
    'certificateSha256',string(entry.certification.sha256), ...
    'intrinsicPortRuntimeIntegration',intrinsicPortInfo, ...
    'correctedNonwingOwner',correctedNonwingOwner);
end

function [plant,cfg,trim,source] = ...
    localInstallCaseAIntrinsicPortPackage(plant,cfg,trim,source)
%LOCALINSTALLCASEAINTRINSICPORTPACKAGE Atomically install the audit package.
info = source.intrinsicPortRuntimeIntegration;
assert(isstruct(info) && isfield(info,'enabled') && info.enabled && ...
    info.auditOnly && string(info.sourceId)=="CASEA_U040_ALPHA_P01", ...
    'sim_run:IntrinsicPortInstallRequest', ...
    'Only the approved exact Case-A audit candidate may be installed.');
acceptedState = info.acceptedEquilibriumState(:);
assert(numel(acceptedState)==plant.nx && ...
    norm(plant.xFlex(:)-acceptedState,inf)<=1e-12 && ...
    norm(plant.model.L-source.p5.L,'fro')> ...
    1e-8*max(1,norm(source.p5.L,'fro')), ...
    'sim_run:IntrinsicPortInstallEntry', ...
    ['The runtime must enter from the unchanged accepted Case-A ', ...
    'equilibrium and must not already contain the candidate operator.']);

candidate = source.p5;
plant = AeroFlex.sched.applyToPlant(plant,candidate);
plant.xFlex = candidate.x_eq(:);
plant.xFlex0 = candidate.x_eq(:);
plant.x(1:plant.nx) = candidate.x_eq(:);
plant.trim.states = candidate.x_eq(:);
plant.last.sched_x_eq = candidate.x_eq(:);
plant.last.intrinsicPortRuntimeIntegration = struct( ...
    'enabled',true,'sourceId',string(info.sourceId), ...
    'candidatePackageHash',string(candidate.p5.packageHash), ...
    'fallback',string(info.fallback));

trim.states = candidate.x_eq(:);
source.trim = trim;
source.packageOwnedScheduleStateCoordinate.equilibriumState = ...
    candidate.x_eq(:);

cfg.library.frozenPackage = candidate;
predictionPackage = candidate;
cfg.modelHandle = @(runtimeCfg,beamModel,aeroModel,baseModel) ...
    AeroFlex.sim.ROMIntegrator(runtimeCfg,beamModel,aeroModel, ...
    baseModel,predictionPackage);
plant.cfg.library.frozenPackage = candidate;
plantParConst = plant.model.parConst;
candidateParConst = candidate.parConst;
plantRateProject = plantParConst.RateProject;
plantParConst = rmfield(plantParConst,'RateProject');
candidateParConst = rmfield(candidateParConst,'RateProject');
assert(norm(plant.model.L-candidate.L,'fro')==0 && ...
    isequaln(plantParConst,candidateParConst) && ...
    isstruct(plantRateProject) && plantRateProject.projSet && ...
    isequaln(plantRateProject.Pz,candidate.beam.Pz), ...
    'sim_run:IntrinsicPortPlantIdentity', ...
    ['The installed plant does not own the complete candidate package ', ...
    'and coupled-full rate projector.']);
source.intrinsicPortRuntimeIntegration.runtimeRateProjectionEnabled = ...
    logical(plantRateProject.projSet);
end

function [plant,source] = localInstallCaseAReciprocalTangent( ...
    plant,source,repositoryRoot,request)
%LOCALINSTALLCASEARECIPROCALTANGENT Install the promoted V4 reaction owner.
expectedPromotion = ...
    "phase18c-v17a-casea-reciprocal-reaction-replacement-production-promotion-v1";
assert(request.enabled && ...
    string(request.sourceId)=="CASEA_U040_ALPHA_P01", ...
    'sim_run:ReciprocalTangentInstallRequest', ...
    'Only the approved exact Case-A reciprocal tangent may be installed.');
candidatePath = fullfile(repositoryRoot,'context','audits', ...
    'phase18c-control-validation','plant', ...
    'v17a-casea-reciprocal-gust-path-discriminator-v1', ...
    'PHASE18C_V17A_CASEA_RECIPROCAL_REACTION_REPLACEMENT_CANDIDATE_V1.mat');
expectedCandidateHash = ...
    "1911b6f2ea775a9bb6ecb6461aff37fe69524acea49d910991968d4445fff96a";
assert(isfile(candidatePath), ...
    'sim_run:ReciprocalTangentArtifacts', ...
    'The reciprocal-tangent candidate artifact is unavailable.');
assert(~request.auditOnly && string(request.promotionId)==expectedPromotion, ...
    'sim_run:ReciprocalTangentRuntimeContract', ...
    'The exact Case-A reciprocal-reaction production profile is required.');
assert(localIntrinsicPortFileHash(candidatePath)==expectedCandidateHash, ...
    'sim_run:ReciprocalTangentCandidateHash', ...
    'The qualified reciprocal-tangent candidate artifact changed.');
loaded = load(candidatePath,'candidate');
assert(isfield(loaded,'candidate'), ...
    'sim_run:ReciprocalTangentCandidate', ...
    'The candidate artifact does not contain candidate.');
candidate = loaded.candidate;
assert(candidate.runtimeEligible && candidate.auditOnly && ...
    ~candidate.defaultActive && ...
    string(candidate.schemaVersion)== ...
    "phase18c-v17a-exact-casea-reciprocal-tangent-v4" && ...
    string(candidate.rigidReactionOwner)== ...
    "source_reciprocal_replaces_fixed_root_increment" && ...
    isfield(candidate,'rootWrenchOutput') && ...
    string(candidate.rootWrenchOutput.owner)== ...
    "source_wing_dynamic_equilibrium_at_root_cut" && ...
    all(size(candidate.rootWrenchOutput.runtimeStateMap)==[6,130]) && ...
    all(size(candidate.rootWrenchOutput.runtimeInputMap)==[6,7]) && ...
    string(candidate.source.acceptedPackageSha256)== ...
    string(source.packageSha256) && ...
    isfield(plant.cfg,'rigidEOMset') && ...
    isfield(plant.cfg.rigidEOMset,'massOwnership') && ...
    string(plant.cfg.rigidEOMset.massOwnership.owner)== ...
    "nonwing_source_owned_wing_reaction" && ...
    isfield(plant.cfg.sim,'shiftWingMomentToCG') && ...
    logical(plant.cfg.sim.shiftWingMomentToCG) && ...
    localIntrinsicPortFileHash(source.packagePath)== ...
    string(source.packageSha256), ...
    'sim_run:ReciprocalTangentContract', ...
    ['The reciprocal tangent is not runtime-qualified or does not bind ', ...
    'the active accepted Case-A package.']);
plant.installReciprocalTangentCorrection(candidate);
source.reciprocalTangentRuntimeIntegration = struct( ...
    'enabled',true,'auditOnly',false,'productionProfile',true, ...
    'defaultActive',true, ...
    'sourceId',string(request.sourceId), ...
    'promotionId',expectedPromotion, ...
    'candidatePath',candidatePath, ...
    'candidateSha256',expectedCandidateHash, ...
    'acceptedPackageSha256',string(source.packageSha256), ...
    'rigidReactionOwner',string(candidate.rigidReactionOwner), ...
    'rootWrenchOutputOwner',string(candidate.rootWrenchOutput.owner), ...
    'visibleStateCount',double(candidate.visible.count), ...
    'hiddenStateCount',double(candidate.hidden.count), ...
    'fallback','accepted_registry_bound_casea_fixed_root_package');
plant.last.reciprocalTangentRuntimeIntegration = ...
    source.reciprocalTangentRuntimeIntegration;
end

function digest = localIntrinsicPortFileHash(path)
%LOCALINTRINSICPORTFILEHASH Compute SHA-256 for bound audit inputs.
engine = javaMethod('getInstance','java.security.MessageDigest','SHA-256');
fileId = fopen(path,'rb');
assert(fileId>=0,'sim_run:IntrinsicPortHashOpen', ...
    'Cannot read %s.',path);
cleanup = onCleanup(@() fclose(fileId));
while ~feof(fileId)
    bytes = fread(fileId,1024*1024,'*uint8');
    if isempty(bytes), break, end
    engine.update(typecast(bytes(:),'int8'));
end
digest = lower(string(reshape(dec2hex( ...
    typecast(engine.digest(),'uint8'),2).',1,[])));
clear cleanup
end

function source = localCaseBProfileSource(repositoryRoot,beam,base,trim,plant)
%LOCALCASEBPROFILESOURCE Resolve and verify the exact V17A Case-B start.
registryPath = fullfile(repositoryRoot,'context','audits', ...
    'phase18c-control-validation','plant', ...
    'V17A_DIMENSIONAL_STEADY_FORCE_PRODUCTION_SOURCE_REGISTRY_V1.json');
assert(isfile(registryPath),'sim_run:CaseBProfileRegistry', ...
    'The V17A production registry is unavailable.');
registry = jsondecode(fileread(registryPath));
sourceIds = string({registry.sources.sourceId});
entry = registry.sources(sourceIds == "OPS_U015_ALPHA_P10");
assert(isscalar(entry),'sim_run:CaseBProfileSource', ...
    'The V17A registry must contain exactly one Case-B start source.');
packagePath = fullfile(repositoryRoot, ...
    entry.acceptedMatlabPackage.path);
certificatePath = fullfile(repositoryRoot,entry.certification.path);
assert(isfile(packagePath) && isfile(certificatePath), ...
    'sim_run:CaseBProfileArtifacts', ...
    'The V17A Case-B package or certificate is unavailable.');
data = load(packagePath,'beam','base','trim','p5');

assert(norm(data.p5.mu(:).'-[15,10],inf) <= 1e-12 && ...
    norm(plant.trimMu(:).'-[15,10],inf) <= 1e-12, ...
    'sim_run:CaseBProfileCoordinate', ...
    'The active scheduler must start at the exact [15 m/s, 10 deg] source.');
assert(isstruct(plant.ROMlib) && ...
    isfield(plant.ROMlib,'compatibleCoordinates') && ...
    logical(plant.ROMlib.compatibleCoordinates), ...
    'sim_run:CaseBProfileLibrary', ...
    'The Case-B profile requires the certified compatible library.');
expectedPackage = AeroFlex.sched.evalLibrary(plant.ROMlib,[15,10], ...
    plant.cfg.library);
assert(isfield(expectedPackage,'scheduleStateCoordinate') && ...
    numel(expectedPackage.pointIds) == 1 && ...
    string(plant.ROMlib.points(expectedPackage.pointIds).name) == ...
    "OPS_U015_ALPHA_P10" && ...
    isequal(size(plant.model.L),size(expectedPackage.L)) && ...
    norm(plant.model.L-expectedPackage.L,'fro') <= ...
    1e-14*max(1,norm(expectedPackage.L,'fro')), ...
    'sim_run:CaseBProfilePackage', ...
    ['The installed runtime model is not the exact source-bound Case-B ', ...
    'package under the active full-coordinate installation policy.']);
assert(isequal(size(beam.phi1),size(data.beam.phi1)) && ...
    norm(beam.phi1-data.beam.phi1,'fro') <= ...
    1e-14*max(1,norm(data.beam.phi1,'fro')) && ...
    isequal(size(base.phi_xi_modes),size(data.base.phi_xi_modes)) && ...
    norm(base.phi_xi_modes-data.base.phi_xi_modes,'fro') <= ...
    1e-14*max(1,norm(data.base.phi_xi_modes,'fro')), ...
    'sim_run:CaseBProfileRecovery', ...
    'The setup recovery maps differ from the registry-bound Case-B source.');
numberPositions = numel(expectedPackage.u_eq)/2;
assert(numberPositions == round(numberPositions) && ...
    isfield(trim,'deltaWing') && ...
    norm(trim.deltaWing(:)- ...
    expectedPackage.u_eq(1:numberPositions),inf) <= 1e-12 && ...
    norm(trim.states(:)-expectedPackage.x_eq(:),inf) <= 1e-12 && ...
    isfinite(trim.thrust) && trim.thrust >= 0, ...
    'sim_run:CaseBProfileTrim', ...
    ['The setup state or wing endpoint differs from the exact ', ...
    'source-bound Case-B runtime equilibrium.']);

sourceTrim = data.trim;
sourceTrim.states = expectedPackage.x_eq(:);
sourceTrim.u_ctrl = expectedPackage.u_eq(:);
sourceTrim.Uinpt = expectedPackage.u_eq(:);
sourceTrim.deltaWing = expectedPackage.u_eq(1:numberPositions);
sourceTrim.deltaWingDeg = rad2deg(sourceTrim.deltaWing);
sourceTrim.deltaDeg = sourceTrim.deltaWingDeg;
sourceTrim.uWingTrim = expectedPackage.u_eq(:);

source = struct('beam',data.beam,'base',data.base,'trim',sourceTrim, ...
    'p5',expectedPackage,'sourceId',"OPS_U015_ALPHA_P10", ...
    'scheduleStateCoordinate', ...
    expectedPackage.scheduleStateCoordinate, ...
    'registryPath',registryPath,'packagePath',packagePath, ...
    'certificatePath',certificatePath, ...
    'packageSha256',string(entry.acceptedMatlabPackage.sha256), ...
    'certificateSha256',string(entry.certification.sha256));
end

function cfg = localCorrectedOutputRetainedSocRequest(cfg)
% Bind the approved corrected-output profile without changing global defaults.
cfg.ctrl.packageOwnedPhysicalOutputs = struct( ...
    'enabled',true, ...
    'policy',"package_owned_signed_mirrored_tip", ...
    'fallback',"phase18c_v17a_casea_integrated_control_v1", ...
    'candidateMpcMaxIterations',10, ...
    'candidateLineSearchStrategy',"filter", ...
    'candidateLineSearchUpdate',"fixed_beta", ...
    'candidateAuditCapture',true, ...
    'candidateSecondOrderCorrection',true);
end

function [cfg,profile] = ...
    localFinalizeCorrectedOutputRetainedSocProfile(cfg,profile,name)
% Enforce the approved named-profile solver and output contract.
assert(string(profile.physicalOutputOwnerPolicy) == ...
    "package_owned_signed_mirrored_tip", ...
    'sim_run:CorrectedOutputOwner', ...
    'The corrected profile requires the package-owned signed tip output.');
cfg.ctrl.sqp.HessianMode = "gauss_newton";
cfg.ctrl.sqp.MaxIterations = 10;
cfg.ctrl.sqp.LineSearchStrategy = "filter";
cfg.ctrl.sqp.LineSearchUpdate = "fixed_beta";
cfg.ctrl.sqp.UseValueOnlyMeritEvaluation = false;
cfg.ctrl.sqp.SecondOrderCorrectionEnabled = true;
cfg.ctrl.sqp.AuditCapture = true;
cfg.ctrl.nmpcWingtipOutput.profile = string(name);
profile.name = string(name);
profile.nmpcLineSearchStrategy = "filter";
profile.nmpcLineSearchUpdate = "fixed_beta";
profile.nmpcMaximumIterations = 10;
profile.nmpcSecondOrderCorrectionEnabled = true;
profile.closedCheckpointFallback = ...
    "phase18c_v17a_casea_integrated_control_v1";
profile.promotionChangeId = ...
    "phase18c-v17a-corrected-output-retained-soc-production-promotion-v1";
end

function context = localBenchmarkMeasurementContext(measurement,rb)
%LOCALBENCHMARKMEASUREMENTCONTEXT Recover declared measured exogenous data.
assert(measurement.contextWidth == 1 && isstruct(rb) && ...
    isfield(rb,'v_B'), ...
    'sim_run:BenchmarkMeasurementContext', ...
    'The scheduled air-data contract requires measured rigid-body velocity.');
velocity = rb.v_B(:);
assert(numel(velocity) == 3 && all(isfinite(velocity)), ...
    'sim_run:BenchmarkMeasurementContext', ...
    'Measured rigid-body velocity must be a finite three-vector.');
context = norm(velocity);
measurement.validateContext(context);
end

function request = localReciprocalControllerModelProviderAuditRequest( ...
    rawRequest,repositoryRoot)
%LOCALRECIPROCALCONTROLLERMODELPROVIDERAUDITREQUEST Bind approved source.
request = struct('enabled',false,'auditOnly',true, ...
    'changeId', ...
    "phase18c-v17a-casea-reciprocal-controller-model-provider-audit-v1", ...
    'formulation',"augmented_reference", ...
    'estimatorActivationSeconds',0, ...
    'disturbanceWarmStart',"hold_last", ...
    'unboundedAerodynamicLagStates',false, ...
    'futureRigidPolicy',"held_measured", ...
    'mheSolver',"fmincon",'mpcSolver',"", ...
    'runtimeAcceleration',struct('enabled',false, ...
    'changeId', ...
    "phase18c-v17a-condensed-rti-compiled-runtime-owner-promotion-v1", ...
    'nmheIterationCount',3,'nmpcIterationCount',2, ...
    'compiledKernel',true));
if isempty(fieldnames(rawRequest))
    return
end
required = {'enabled','auditOnly','changeId'};
allowed = [string(required),"formulation", ...
    "estimatorActivationSeconds","disturbanceWarmStart", ...
    "unboundedAerodynamicLagStates","futureRigidPolicy", ...
    "mheSolver","mpcSolver","runtimeAcceleration"];
assert(all(isfield(rawRequest,required)) && ...
    all(ismember(string(fieldnames(rawRequest)),allowed)) && ...
    isscalar(rawRequest.enabled) && isscalar(rawRequest.auditOnly) && ...
    logical(rawRequest.auditOnly) && ...
    string(rawRequest.changeId)==string(request.changeId), ...
    'sim_run:ReciprocalControllerProviderRequest', ...
    ['The reciprocal controller-model provider requires its exact ', ...
    'approved audit-only request.']);
request.enabled = logical(rawRequest.enabled);
if isfield(rawRequest,'formulation') && ~isempty(rawRequest.formulation)
    request.formulation = lower(string(rawRequest.formulation));
end
assert(isscalar(request.formulation) && ismember( ...
    request.formulation, ...
    ["augmented_reference","condensed_internal_memory"]), ...
    'sim_run:ReciprocalControllerProviderFormulation', ...
    'The reciprocal controller-model formulation is unsupported.');
if isfield(rawRequest,'estimatorActivationSeconds') && ...
        ~isempty(rawRequest.estimatorActivationSeconds)
    request.estimatorActivationSeconds = double( ...
        rawRequest.estimatorActivationSeconds);
end
assert(isscalar(request.estimatorActivationSeconds) && ...
    isfinite(request.estimatorActivationSeconds) && ...
    request.estimatorActivationSeconds>=0, ...
    'sim_run:ReciprocalControllerProviderActivation', ...
    'Estimator activation time must be a finite nonnegative scalar.');
if isfield(rawRequest,'disturbanceWarmStart') && ...
        ~isempty(rawRequest.disturbanceWarmStart)
    request.disturbanceWarmStart = lower(string( ...
        rawRequest.disturbanceWarmStart));
end
assert(isscalar(request.disturbanceWarmStart) && ...
    ismember(request.disturbanceWarmStart, ...
    ["hold_last","bounded_secant"]), ...
    'sim_run:ReciprocalControllerProviderWarmStart', ...
    'The reciprocal disturbance warm-start selector is unsupported.');
if isfield(rawRequest,'unboundedAerodynamicLagStates') && ...
        ~isempty(rawRequest.unboundedAerodynamicLagStates)
    selector = rawRequest.unboundedAerodynamicLagStates;
    assert(isscalar(selector) && (islogical(selector) || ...
        (isnumeric(selector) && isfinite(selector) && ...
        ismember(selector,[0 1]))), ...
        'sim_run:ReciprocalControllerProviderLagBounds', ...
        'The reciprocal aerodynamic-lag selector must be logical.');
    request.unboundedAerodynamicLagStates = logical(selector);
end
if isfield(rawRequest,'futureRigidPolicy') && ...
        ~isempty(rawRequest.futureRigidPolicy)
    request.futureRigidPolicy = lower(string( ...
        rawRequest.futureRigidPolicy));
end
assert(isscalar(request.futureRigidPolicy) && ...
    request.futureRigidPolicy=="held_measured", ...
    'sim_run:ReciprocalControllerProviderFutureRigidPolicy', ...
    ['The current reciprocal nMPC audit supports only an explicit ', ...
    'held-measured future rigid discriminator.']);
if isfield(rawRequest,'mheSolver') && ~isempty(rawRequest.mheSolver)
    request.mheSolver = lower(string(rawRequest.mheSolver));
end
if isfield(rawRequest,'mpcSolver') && ~isempty(rawRequest.mpcSolver)
    request.mpcSolver = lower(string(rawRequest.mpcSolver));
end
assert(isscalar(request.mheSolver) && ismember( ...
    request.mheSolver,["fmincon","custom_sqp"]) && ...
    isscalar(request.mpcSolver) && ismember( ...
    request.mpcSolver,["","fmincon","custom_sqp"]), ...
    'sim_run:ReciprocalControllerProviderSolver', ...
    'The reciprocal controller-model solver selector is unsupported.');
if isfield(rawRequest,'runtimeAcceleration') && ...
        ~isempty(rawRequest.runtimeAcceleration)
    acceleration = rawRequest.runtimeAcceleration;
    requiredAcceleration = {'enabled','changeId', ...
        'nmheIterationCount','nmpcIterationCount','compiledKernel'};
    assert(isstruct(acceleration) && isscalar(acceleration) && ...
        all(isfield(acceleration,requiredAcceleration)) && ...
        all(ismember(string(fieldnames(acceleration)), ...
        string(requiredAcceleration))) && ...
        isscalar(acceleration.enabled) && ...
        isscalar(acceleration.compiledKernel) && ...
        string(acceleration.changeId)== ...
        "phase18c-v17a-condensed-rti-compiled-runtime-owner-promotion-v1", ...
        'sim_run:ReciprocalRuntimeAccelerationRequest', ...
        'The reciprocal runtime-acceleration request is unauthorized.');
    acceleration.enabled = logical(acceleration.enabled);
    acceleration.compiledKernel = logical(acceleration.compiledKernel);
    acceleration.nmheIterationCount = ...
        double(acceleration.nmheIterationCount);
    acceleration.nmpcIterationCount = ...
        double(acceleration.nmpcIterationCount);
    assert(all(isfinite([acceleration.nmheIterationCount, ...
        acceleration.nmpcIterationCount])) && ...
        all([acceleration.nmheIterationCount, ...
        acceleration.nmpcIterationCount]==fix([ ...
        acceleration.nmheIterationCount, ...
        acceleration.nmpcIterationCount])) && ...
        all([acceleration.nmheIterationCount, ...
        acceleration.nmpcIterationCount]>=1) && ...
        all([acceleration.nmheIterationCount, ...
        acceleration.nmpcIterationCount]<=3), ...
        'sim_run:ReciprocalRuntimeAccelerationIterations', ...
        'The RTI iteration counts must be integers in [1,3].');
    request.runtimeAcceleration = acceleration;
end
assert(~request.runtimeAcceleration.enabled || ...
    (request.formulation=="condensed_internal_memory" && ...
    request.mheSolver=="fmincon" && request.mpcSolver=="fmincon"), ...
    'sim_run:ReciprocalRuntimeAccelerationScope', ...
    ['The promoted RTI owner requires the condensed reciprocal ', ...
    'formulation and fmincon-configured offline references.']);
if request.mheSolver=="custom_sqp" || request.mpcSolver=="fmincon"
    assert(request.formulation=="condensed_internal_memory", ...
        'sim_run:ReciprocalControllerProviderSolverScope', ...
        ['The qualified custom-nMHE/fmincon-nMPC combination requires ', ...
        'the condensed reciprocal formulation.']);
end
if ~request.enabled
    return
end
candidatePath = fullfile(repositoryRoot,'context','audits', ...
    'phase18c-control-validation','plant', ...
    'v17a-casea-reciprocal-gust-path-discriminator-v1', ...
    'PHASE18C_V17A_CASEA_RECIPROCAL_REACTION_REPLACEMENT_CANDIDATE_V1.mat');
candidateHash = ...
    "1911b6f2ea775a9bb6ecb6461aff37fe69524acea49d910991968d4445fff96a";
assert(isfile(candidatePath), ...
    'sim_run:ReciprocalControllerProviderArtifacts', ...
    'The exact reciprocal candidate is unavailable.');
assert(string(request.changeId)== ...
    "phase18c-v17a-casea-reciprocal-controller-model-provider-audit-v1" && ...
    localIntrinsicPortFileHash(candidatePath)==candidateHash, ...
    'sim_run:ReciprocalControllerProviderContract', ...
    'The reciprocal controller-model provider is not bound to its exact source candidate.');
request.candidatePath = candidatePath;
request.candidateSha256 = candidateHash;
end

function context = localReciprocalControllerIntervalContext( ...
    plant,wingIncrement,rigidCommand,substepCount, ...
    scheduledPacket,scheduledPackage)
%LOCALRECIPROCALCONTROLLERINTERVALCONTEXT Build causal completed history.
if nargin < 5, scheduledPacket = struct(); end
if nargin < 6, scheduledPackage = struct(); end
wingIncrement = wingIncrement(:);
assert(numel(wingIncrement)==4 && all(isfinite(wingIncrement)) && ...
    isstruct(rigidCommand) && isfield(rigidCommand,'delta_e') && ...
    isfield(rigidCommand,'thrust') && ...
    all(isfinite([rigidCommand.delta_e,rigidCommand.thrust])) && ...
    isscalar(substepCount) && substepCount>=1 && ...
    substepCount==round(substepCount) && ...
    plant.trimThrust+rigidCommand.thrust>=0, ...
    'sim_run:ReciprocalControllerIntervalContext', ...
    ['The reciprocal completed-interval command context is invalid ', ...
    'or violates T >= 0.']);
rigidState = [plant.rb.v_B(:);plant.rb.omega_B(:);plant.rb.euler(:)];
assert(numel(rigidState)==9 && all(isfinite(rigidState)), ...
    'sim_run:ReciprocalControllerRigidContext', ...
    'The measured rigid-state context must contain nine finite values.');
context = struct( ...
    'wingTotal',repmat( ...
    plant.trimWingControl(:)+wingIncrement,1,substepCount), ...
    'wingIncrement',repmat(wingIncrement,1,substepCount), ...
    'elevatorIncrement',repmat( ...
    double(rigidCommand.delta_e),1,substepCount), ...
    'thrustIncrement',repmat( ...
    double(rigidCommand.thrust),1,substepCount), ...
    'rigidState',repmat(rigidState,1,substepCount), ...
    'reciprocalCorrectionAccepted',false(1,substepCount));
if ~isempty(fieldnames(scheduledPacket))
    context.scheduledReciprocal = repmat( ...
        {scheduledPacket.schedule},1,substepCount);
    context.scheduledPacket = scheduledPacket;
    context.scheduledPackage = scheduledPackage;
end
end

function horizon = localReciprocalControllerFutureContextHorizon( ...
    plant,rigidCommand,intervalCount,substepCount, ...
    scheduledPacket,scheduledPackage)
%LOCALRECIPROCALCONTROLLERFUTURECONTEXTHORIZON Held-rigid discriminator.
if nargin < 5, scheduledPacket = struct(); end
if nargin < 6, scheduledPackage = struct(); end
assert(isstruct(rigidCommand) && ...
    isfield(rigidCommand,'delta_e') && ...
    isfield(rigidCommand,'thrust') && ...
    all(isfinite([rigidCommand.delta_e,rigidCommand.thrust])) && ...
    isscalar(intervalCount) && intervalCount>=1 && ...
    intervalCount==round(intervalCount) && ...
    isscalar(substepCount) && substepCount>=1 && ...
    substepCount==round(substepCount) && ...
    plant.trimThrust+rigidCommand.thrust>=0, ...
    'sim_run:ReciprocalControllerFutureContext', ...
    ['The reciprocal nMPC future context is invalid or violates ', ...
    'T >= 0.']);
rigidState = [plant.rb.v_B(:);plant.rb.omega_B(:);plant.rb.euler(:)];
assert(numel(rigidState)==9 && all(isfinite(rigidState)), ...
    'sim_run:ReciprocalControllerFutureRigidState', ...
    'The held measured rigid state must contain nine finite values.');
context = struct( ...
    'elevatorIncrement',repmat( ...
    double(rigidCommand.delta_e),1,substepCount), ...
    'thrustIncrement',repmat( ...
    double(rigidCommand.thrust),1,substepCount), ...
    'rigidState',repmat(rigidState,1,substepCount), ...
    'ownerPolicy',"held_measured_rigid_and_held_outer_tail_thrust");
if ~isempty(fieldnames(scheduledPacket))
    context.scheduledReciprocal = repmat( ...
        {scheduledPacket.schedule},1,substepCount);
    context.scheduledPacket = scheduledPacket;
    context.scheduledPackage = scheduledPackage;
end
horizon = repmat({context},1,intervalCount);
end

function record = localReciprocalContextLogRecord(context)
%LOCALRECIPROCALCONTEXTLOGRECORD Remove runtime-only scheduled model data.
record = context;
if ~isstruct(record) || ~isscalar(record) || ...
        ~isfield(record,'scheduledPacket')
    return
end
packet = record.scheduledPacket;
required = {'schemaVersion','query','queryPackageHash', ...
    'queryNativeEquilibrium','queryTrim','schedule','mapConditions', ...
    'bankManifestSha256','sourceIds','hiddenStateCount'};
assert(isstruct(packet) && isscalar(packet) && ...
    all(isfield(packet,required)), ...
    'sim_run:ScheduledReciprocalLogRecord', ...
    'The scheduled reciprocal context cannot be compactly logged.');
record.scheduledPacketSummary = struct( ...
    'schemaVersion',string(packet.schemaVersion), ...
    'query',double(packet.query), ...
    'queryPackageHash',string(packet.queryPackageHash), ...
    'queryNativeEquilibrium',double( ...
    packet.queryNativeEquilibrium(:)), ...
    'queryTrim',packet.queryTrim, ...
    'schedule',packet.schedule, ...
    'mapConditions',packet.mapConditions, ...
    'bankManifestSha256',string(packet.bankManifestSha256), ...
    'sourceIds',string(packet.sourceIds(:)), ...
    'hiddenStateCount',double(packet.hiddenStateCount));
removable = intersect(fieldnames(record), ...
    {'scheduledPacket','scheduledPackage','scheduledModel'},'stable');
if ~isempty(removable)
    record = rmfield(record,removable);
end
end

function [xhat,what,info] = localEstimateWithContexts( ...
    estimator,measurement,input,time,measurementContext,knownChi, ...
    intervalPackage)
%LOCALESTIMATEWITHCONTEXTS Preserve the ordered optional nMHE context API.
usePackage = isprop(estimator,'scheduledPackageHistoryEnabled') && ...
    estimator.scheduledPackageHistoryEnabled;
if usePackage
    assert(nargin == 7 && isstruct(intervalPackage) && ...
        isscalar(intervalPackage), ...
        'sim_run:ScheduledMhePackageHistory', ...
        'The active scheduled-horizon nMHE requires one interval package.');
end
if ~isempty(measurementContext) && ~isempty(knownChi)
    if usePackage
        [xhat,what,info] = estimator.estimate( ...
            measurement,input,time,measurementContext,knownChi, ...
            intervalPackage);
    else
        [xhat,what,info] = estimator.estimate( ...
            measurement,input,time,measurementContext,knownChi);
    end
elseif ~isempty(measurementContext)
    if usePackage
        [xhat,what,info] = estimator.estimate( ...
            measurement,input,time,measurementContext,intervalPackage);
    else
        [xhat,what,info] = estimator.estimate( ...
            measurement,input,time,measurementContext);
    end
elseif ~isempty(knownChi)
    if usePackage
        [xhat,what,info] = estimator.estimate( ...
            measurement,input,time,knownChi,intervalPackage);
    else
        [xhat,what,info] = estimator.estimate( ...
            measurement,input,time,knownChi);
    end
else
    if usePackage
        [xhat,what,info] = estimator.estimate( ...
            measurement,input,time,intervalPackage);
    else
        [xhat,what,info] = estimator.estimate(measurement,input,time);
    end
end
end

function [target,info] = localNormalizeEndpointRateTarget( ...
    rawTarget,previousEndpoint,cfg,actuator,solverAccepted,enabled)
%LOCALNORMALIZEENDPOINTRATETARGET Enforce the existing endpoint identity.
target = rawTarget(:);
previousEndpoint = previousEndpoint(:);
nSurface = cfg.ctrl.n_surf;
assert(numel(target) == 2*nSurface && ...
    numel(previousEndpoint) == 2*nSurface, ...
    'sim_run:EndpointNormalizationDimension', ...
    'Endpoint histories must use [deflection; rate] ordering.');
delta = target(1:nSurface);
deltaDot = target(nSurface+1:end);
previousDelta = previousEndpoint(1:nSurface);
rawResidual = norm(delta-previousDelta-cfg.ctrl.Ts*deltaDot,inf);
guard = cfg.ctrl.sqp.ConstraintTolerance;
assert(isfinite(guard) && guard > 0, ...
    'sim_run:EndpointNormalizationTolerance', ...
    'The nMPC constraint tolerance must be finite and positive.');
candidate = [previousDelta+cfg.ctrl.Ts*deltaDot;deltaDot];
applied = enabled && solverAccepted && all(isfinite(target)) && ...
    rawResidual <= guard && all(isfinite(candidate)) && ...
    all(candidate(1:nSurface) >= actuator.deltaL) && ...
    all(candidate(1:nSurface) <= actuator.deltaU) && ...
    all(deltaDot >= actuator.rateL) && all(deltaDot <= actuator.rateU);
if applied
    target = candidate;
end
info = struct('applied',applied,'guard',guard, ...
    'rawResidual',rawResidual, ...
    'normalizedResidual',norm(target(1:nSurface)-previousDelta- ...
    cfg.ctrl.Ts*target(nSurface+1:end),inf), ...
    'correctionInfinity',norm(candidate(1:nSurface)-delta,inf));
end

function request = localScheduledEquilibriumFeedforwardAuditRequest(raw)
%LOCALSCHEDULEDEQUILIBRIUMFEEDFORWARDAUDITREQUEST Validate opt-in Case-B audit.
request = struct('enable',false);
if isempty(fieldnames(raw))
    return
end
assert(isfield(raw,'enable') && isscalar(raw.enable), ...
    'sim_run:ScheduledEquilibriumFeedforwardEnable', ...
    'The scheduled-equilibrium request requires a scalar enable field.');
if ~logical(raw.enable)
    return
end
assert(isfield(raw,'auditOnly') && logical(raw.auditOnly) && ...
    isfield(raw,'source') && string(raw.source)== ...
    "phase18c-v17a-caseb-scheduled-virtual-longitudinal-guidance-allocation-audit-v1", ...
    'sim_run:ScheduledEquilibriumFeedforwardScope', ...
    ['The scheduled-equilibrium feedforward request must remain bound ', ...
    'to the approved Case-B audit.']);
request = raw;
request.enable = true;
request.auditOnly = true;
end

function [xFlex, rb] = splitFlexibleRigidState(xFull,nxFlex)
%SPLITFLEXIBLERIGIDSTATE Split plant state into flexible ROM and appended RB state.
%
% Expected coupled state:
%   xFull = [xFlex; r_I(3); v_B(3); euler(3); omega_B(3)]
%
% For wing-only:
%   xFull = xFlex

xFull = xFull(:);

if numel(xFull) < nxFlex
    error('splitFlexibleRigidState:Dimension', ...
        'xFull length %d is smaller than nxFlex %d.', ...
        numel(xFull), nxFlex);
end

xFlex = xFull(1:nxFlex);

tail = xFull(nxFlex+1:end);

if isempty(tail)
    rb = [];
    return
end

if numel(tail) ~= 12
    error('splitFlexibleRigidState:RigidTail', ...
        ['Coupled state tail should have length 12: ', ...
        '[r_I(3); v_B(3); euler(3); omega_B(3)]. Got %d.'], ...
        numel(tail));
end

rb = tail;
end

function state = localRigidStateVector(plant)
%LOCALRIGIDSTATEVECTOR Return the current inertial/body rigid state.
required = {'r_I','v_B','euler','omega_B'};
assert(isprop(plant,'rb') && isstruct(plant.rb) && ...
    all(isfield(plant.rb,required)), ...
    'sim_run:RigidInitialState', ...
    'The coupled plant did not expose a complete rigid initial state.');
state = [plant.rb.r_I(:);plant.rb.v_B(:); ...
    plant.rb.euler(:);plant.rb.omega_B(:)];
assert(numel(state)==12 && all(isfinite(state)), ...
    'sim_run:RigidInitialState', ...
    'The coupled rigid initial state must be finite and 12-dimensional.');
end
